INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (1, '桂枝汤', 0, 5, 10001, '1、$f{桂枝汤} 5味\n$u{桂枝}$w{三两。去皮}    $u{芍药}$w{三两}    $u{甘草}$w{二两。炙}    $u{生姜}$w{三两。切}    $u{大枣}$w{十二枚。擘}\n	上五味。㕮咀三味。以水七升。微火煮取三升。去滓。适寒温。服一升。服已。须臾啜热稀粥一升余。以助药力。温覆令一时许。遍身漐漐。微似有汗者益佳。不可令如水流漓。病必不除。若一服汗出病差。停后服。不必尽剂。若不汗。更服依前法。又不汗。后服小促其间。半日许。令三服尽。若病重者。一日一夜服。周时观之。服一剂尽。病证犹在者。更作服。若汗不出。乃服至二三剂。禁生冷粘滑肉面五辛酒酪臭恶等物。', 3, '', '桂枝,芍药,甘草,生姜,大枣', 600025450844229, '7B37D4BA2D23C597FD0433082583358A', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:43', 1, '超级管理员', '2024-10-22 22:18:52');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (2, '桂枝加葛根汤', 1, 7, 10001, '2、$f{桂枝加葛根汤} 7味 \n$u{葛根}$w{四两}    $u{麻黄}$w{三两。去节}    $u{芍药}$w{二两}    $u{生姜}$w{三两。切}    $u{甘草}$w{二两。炙}    $u{大枣}$w{十二枚。擘}    $u{桂枝}$w{二两。去皮}\n	上七味。以水一斗。先煮麻黄葛根。减二升。去上沫。内诸药。煮取三升。去滓。温服一升。覆取微似汗。不须啜粥。余如桂枝法。将息及禁忌。$a{臣亿等谨按仲景本论。太阳中风自汗用桂枝。伤寒无汗用麻黄。今证云汗出恶风而方中有麻黄。恐非本意也。第三卷有葛根汤证云。无汗恶风。正与此方同。是合用麻黄也。此云桂枝加葛根汤。恐是桂枝中但加葛根耳。}', 3, '123', '桂枝,大枣,甘草,生姜,芍药,麻黄,葛根', 600025451450437, '88198AB7EE560E2891088A3D6F074204', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:43', 1, 'admin', '2025-11-10 16:14:51');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (3, '桂枝加厚朴杏子汤', 2, 7, 10001, '3、$f{桂枝加厚朴杏子汤} 7味 \n$u{桂枝}$w{三两。去皮}    $u{甘草}$w{二两。炙}    $u{生姜}$w{三两。切}    $u{芍药}$w{三两}    $u{大枣}$w{十二枚。擘}    $u{厚朴}$w{二两。炙去皮}    $u{杏仁}$w{五十枚。去皮尖}\n	上七味。以水七升。微火煮取三升。去滓。温服一升。覆取微似汗。', 3, '', '桂枝,甘草,生姜,芍药,大枣,厚朴,杏仁', 600025451884613, 'F9236D60A55268E5C46F88FB5AFEB8A4', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:43', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4, '桂枝加附子汤', 3, 6, 10001, '4、$f{桂枝加附子汤} 6味 \n$u{桂枝}$w{三两。去皮}    $u{芍药}$w{三两}    $u{甘草}$w{三两。炙}    $u{生姜}$w{三两。切}    $u{大枣}$w{十二枚。擘}    $u{附子}$w{一枚。炮去皮破八片}\n	上六味。以水七升。煮取三升。去滓。温服一升。【本云桂枝汤。今加附子。将息如前法。】', 3, '', '桂枝,芍药,甘草,生姜,大枣,附子', 600025452310597, '02953A141FBB4A5533FC2A6AB3AAB7C1', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:43', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5, '桂枝去芍药汤', 4, 4, 10001, '5、$f{桂枝去芍药汤} 4味 \n$u{桂枝}$w{三两。去皮}    $u{甘草}$w{二两。炙}    $u{生姜}$w{三两。切}    $u{大枣}$w{十二枚。擘}\n	上四味。以水七升。煮取三升。去滓。温服一升。【本云桂枝汤。今去芍药。将息如前法】', 3, '', '桂枝,甘草,生姜,大枣', 600025452752965, '696A1ED2B8B6217F3176B1DD7A250DC0', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:43', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6, '桂枝去芍药加附子汤', 5, 5, 10001, '6、$f{桂枝去芍药加附子汤} 5味 \n$u{桂枝}$w{三两。去皮}    $u{甘草}$w{二两。炙}    $u{生姜}$w{三两。切}    $u{大枣}$w{十二枚。擘}    $u{附子}$w{一枚。炮去皮破八片}\n	上五味。以水七升。煮取三升。去滓。温服一升。【本云桂枝汤。今去芍药。加附子。将息如前法。】', 3, '', '桂枝,甘草,生姜,大枣,附子', 600025453174853, '3A45B249FE98DC742E1085DAB561D74B', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:43', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7, '桂枝麻黄各半汤', 6, 7, 10001, '7、$f{桂枝麻黄各半汤} 7味 \n$u{桂枝}$w{一两十六铢。去皮}    $u{芍药}    $u{生姜}$w{切}    $u{甘草}$w{炙}    $u{麻黄}$w{各一两。去节}    $u{大枣}$w{四枚。擘}    $u{杏仁}$w{二十四枚。汤浸去皮尖及两仁者}\n	上七味。以水五升。先煮麻黄一二沸。去上沫。内诸药。煮取一升八合。去滓。温服六合。【本云桂枝汤三合。麻黄汤三合。并为六合。顿服。将息如上法。】$a{臣亿等谨按桂枝汤方。桂枝芍药生姜各三两。甘草二两。大枣十二枚。麻黄汤方麻黄三两。桂枝二两。甘草一两。杏仁七十个。今以算法约之。二汤各取三分之一。即得桂枝一两十六铢。芍药生姜甘草各一两。大枣四枚。杏仁二十三个。零三分枚之一。收之得二十四个。合方。详此方乃三分之一。非各半也。宜云合半汤。}', 3, '', '桂枝,芍药,生姜,甘草,麻黄,大枣,杏仁', 600025453596741, 'FBDC1B5FAD16EF2421F1B7A67EF21945', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:43', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8, '桂枝二麻黄一汤', 7, 7, 10001, '8、$f{桂枝二麻黄一汤} 7味 \n$u{桂枝}$w{一两十七铢。去皮}    $u{芍药}$w{一两六铢}    $u{麻黄}$w{十六铢。去节}    $u{生姜}$w{一两六铢。切}    $u{杏仁}$w{十六个。去皮尖}    $u{甘草}$w{一两二铢。炙}    $u{大枣}$w{五枚。擘}\n	上七味。以水五升。先煮麻黄一二沸。去上沫。内诸药。煮取二升。去滓。温服一升。日再服。【本云桂枝汤二分。麻黄汤一分。合为二升。分再服。今合为一方。将息如前法。】$a{臣亿等谨按桂枝汤方。桂枝芍药生姜各三两。甘草二两大枣十二枚。麻黄汤方。麻黄三两。桂枝二两。甘草一两。杏仁七十个。今以算法约之。桂枝汤取十二分之五。即得桂枝芍药生姜各一两六铢。甘草二十铢。大枣五枚。麻黄汤取九分之二。即得麻黄十六铢。桂枝十铢三分铢之二。收之得十一铢。甘草五铢三分铢之一。收之得六铢。杏仁十五个九分枚之四。收之得十六个。二汤所取相合。即共得桂枝一两十七铢。麻黄十六铢。生姜芍药各一两六铢。甘草一两二铢。大枣五枚。杏仁十六个。合方。}', 2, '', '桂枝,芍药,麻黄,生姜,杏仁,甘草,大枣', 600025454018629, '319C7329BA20C811464776176122CA5A', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:43', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (9, '白虎加人参汤', 8, 5, 10001, '9、$f{白虎加人参汤} 5味 \n$u{知母}$w{六两}    $u{石膏}$w{一斤。碎绵裹}    $u{甘草}$w{炙。二两}    $u{粳米}$w{六合}    $u{人参}$w{三两}\n	上五味。以水一斗。煮米熟汤成。去滓。温服一升。日三服。', 3, '', '知母,石膏,甘草,粳米,人参', 600025454428229, 'AEEF82412A804D5833D28C5DDF1D5289', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:43', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (10, '桂枝二越婢一汤', 9, 7, 10001, '10、$f{桂枝二越婢一汤} 7味 \n$u{桂枝}$w{去皮}    $u{芍药}    $u{麻黄}    $u{甘草}$w{各十八铢。炙}    $u{大枣}$w{四枚。擘}    $u{生姜}$w{一两二铢。切}    $u{石膏}$w{二十四铢。碎绵裹}\n	上七味。以水五升。煮麻黄一二沸。去上沫。内诸药。煮取二升。去滓。温服一升。【本云当裁为越婢汤桂枝汤。合之饮一升。今合为一方。桂枝汤二分。越婢汤一分。】$a{臣亿等谨按桂枝汤方。桂枝芍药生姜各三两。甘草二两。大枣十二枚。越婢汤方麻黄二两。生姜三两。甘草二两。石膏半斤。大枣十五枚。今以算法约之。桂枝汤取四分之一。即得桂枝芍药生姜各十八铢。甘草十二铢。大枣三枚。越婢汤取八分之一。即得麻黄十八铢。生姜九铢。甘草六铢。石膏二十四铢。大枣一枚八分之七。弃之。二汤所取相合。即共得桂枝芍药甘草麻黄各十八铢。生姜一两三铢。石膏二十四铢。大枣四枚。合方。旧云。桂枝三。今取四分之一。即当云桂枝二也。越婢汤方。见仲景杂方中。外台秘要。一云起脾汤。}', 2, '', '桂枝,芍药,麻黄,甘草,大枣,生姜,石膏', 600025454825541, '2D6D43BF6949C424766F0885B9ABBEBF', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:43', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (11, '桂枝去桂加茯苓白术汤', 10, 6, 10001, '11、$f{桂枝去桂加茯苓白术汤} 6味 \n$u{芍药}$w{三两}    $u{甘草}$w{二两。炙}    $u{生姜}$w{切}    $u{白术}    $u{茯苓}$w{各三两}    $u{大枣}$w{十二枚。擘}\n	上六味。以水八升。煮取三升。去滓。温服一升。小便利则愈。【本云桂枝汤。今去桂枝加茯苓白术。】', 3, '', '芍药,甘草,生姜,白术,茯苓,大枣', 600025455259717, '06A8E348B280B73AD4939C8C1C3483C7', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:43', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (12, '甘草干姜汤', 11, 2, 10001, '12、$f{甘草干姜汤} 2味 \n$u{甘草}$w{四两。炙}    $u{干姜}$w{二两}\n	上二味。以水三升。煮取一升五合。去滓。分温再服。', 2, '', '甘草,干姜', 600025455685701, '7A44A21BEEBEF4E5EEE2E470AD9A8E4C', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:43', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (13, '芍药甘草汤', 12, 2, 10001, '13、$f{芍药甘草汤} 2味 \n$u{白芍药}    $u{甘草}$w{各四两。炙}\n	上二味。以水三升。煮取一升五合。去滓。分温再服。', 2, '', '白芍药,甘草', 600025456103493, 'A78A11B98F53D8B6D3C7E4D90260C08B', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:43', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (14, '调胃承气汤', 13, 4, 10001, '14、$f{调胃承气汤} 3味 \n$u{大黄}$w{四两。去皮$u{清酒}洗}    $u{甘草}$w{二两。炙}    $u{芒硝}$w{半升}\n	上三味。以水三升。煮取一升。去滓。内芒硝。更上火微煮令沸。少少温服之。', 1, '', '大黄,清酒,甘草,芒硝', 600025456508997, '3C28A002BFF608335BC28935C26F4964', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:43', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (15, '葛根汤', 14, 7, 10001, '15、$f{葛根汤} 7味 \n$u{葛根}$w{四两}    $u{麻黄}$w{三两。去节}    $u{桂枝}$w{二两。去皮}    $u{生姜}$w{三两。切}    $u{甘草}$w{二两。炙}    $u{芍药}$w{二两}    $u{大枣}$w{十二枚。擘}\n	上七味。以水一斗。先煮麻黄葛根。减二升。去白沫。内诸药。煮取三升。去滓。温服一升。覆取微似汗。余如桂枝法。将息及禁忌。诸汤皆仿此。', 3, '', '葛根,麻黄,桂枝,生姜,甘草,芍药,大枣', 600025456943173, '3105BFDC06C2F61A7C4039080CEA8D9A', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:44', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (16, '葛根加半夏汤', 15, 8, 10001, '16、$f{葛根加半夏汤} 8味 \n$u{葛根}$w{四两}    $u{麻黄}$w{三两。去节}    $u{甘草}$w{二两。炙}    $u{芍药}$w{二两}    $u{桂枝}$w{二两。去皮}    $u{生姜}$w{二两。切}    $u{半夏}$w{半升(洗)}    $u{大枣}$w{十二枚。擘}\n	上八味。以水一斗。先煮葛根麻黄。减二升。去白沫。内诸药。煮取三升。去滓。温服一升。覆取微似汗。', 3, '', '葛根,麻黄,甘草,芍药,桂枝,生姜,半夏,大枣', 600025457340485, 'F421B854191229D1166D66568E2AF8DA', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:44', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (17, '葛根黄芩黄连汤', 16, 4, 10001, '17、$f{葛根黄芩黄连汤} 4味 \n$u{葛根}$w{半斤}    $u{甘草}$w{二两。炙}    $u{黄芩}$w{三两}    $u{黄连}$w{三两}\n	上四味。以水八升。先煮葛根。减二升。内诸药。煮取二升。去滓。分温再服。', 2, '', '葛根,甘草,黄芩,黄连', 600025457741893, 'D57D1547C06179613431D0805AC1C4B5', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:44', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (18, '麻黄汤', 17, 4, 10001, '18、$f{麻黄汤} 4味 \n$u{麻黄}$w{三两。去节}    $u{桂枝}$w{二两。去皮}    $u{甘草}$w{一两。炙}    $u{杏仁}$w{七十个。去皮尖}\n	上四味。以水九升。先煮麻黄。减二升。去上沫。内诸药。煮取二升半。去滓。温服八合。覆取微似汗。不须啜粥。余如桂枝法将息。', 3, '', '麻黄,桂枝,甘草,杏仁', 600025458204741, '0F9EBEF8AA54DBCC42D5DCB3290978F7', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:44', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (19, '小柴胡汤', 18, 15, 10001, '19、$f{小柴胡汤} 7味 \n$u{柴胡}$w{半斤}    $u{黄芩}    $u{人参}    $u{甘草}$w{炙}    $u{生姜}$w{各三两（切）}    $u{大枣}$w{十二枚。擘}    $u{半夏}$w{半升(洗)}\n	上七味。以水一斗二升。煮取六升。去滓。再煎取三升。温服一升。日三服。若胸中烦而不呕者。去$u{半夏}、$u{人参}。加$u{栝楼实}$w{一枚}。若渴。去$u{半夏}。加$u{人参}。$w{合前成四两半}    $u{栝楼根}$w{四两}。若腹中痛者。去$u{黄芩}。加$u{芍药}$w{三两}。若胁下痞硬。去$u{大枣}。加$u{牡蛎}$w{四两}。若心下悸、小便不利者。去$u{黄芩}。加$u{茯苓}$w{四两}。若不渴。外有微热者。去$u{人参}。加$u{桂枝}$w{三两}。温覆微汗愈。若咳者。去$u{人参}、$u{大枣}、$u{生姜}。加$u{五味子}$w{半升}    $u{干姜}$w{二两}。', 3, '', '柴胡,黄芩,人参,甘草,生姜,大枣,半夏,栝楼实,栝楼根,芍药,牡蛎,茯苓,桂枝,五味子,干姜', 600025458647109, 'D5C3ED8A177DCBC4B377854D478948CD', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:44', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (20, '大青龙汤', 19, 7, 10001, '20、$f{大青龙汤} 7味 \n$u{麻黄}$w{六两。去节}    $u{桂枝}$w{二两。去皮}    $u{甘草}$w{二两。炙}    $u{杏仁}$w{四十枚。去皮尖}    $u{生姜}$w{三两。切}    $u{大枣}$w{十枚。擘}    $u{石膏}$w{如鸡子大(碎)}\n	上七味。以水九升。先煮麻黄。减二升。去上沫。内诸药。煮取三升。去滓。温服一升。取微似汗。汗出多者。温粉扑之。一服汗者。停后服。若复服。汗多亡阳。遂$a{一作逆}虚。恶风烦躁。不得眠也。', 3, '', '麻黄,桂枝,甘草,杏仁,生姜,大枣,石膏', 600025459048517, '8569049F782FB669B59D28702B5FF1A7', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:44', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (21, '小青龙汤', 20, 13, 10001, '21、$f{小青龙汤} 8味 \n$u{麻黄}$w{去节}    $u{芍药}    $u{细辛}    $u{干姜}    $u{甘草}$w{炙}    $u{桂枝}$w{各三两。去皮}    $u{五味子}$w{半升}    $u{半夏}$w{半升(洗)}\n	上八味。以水一斗。先煮麻黄。减二升。去上沫。内诸药。煮取三升。去滓。温服一升。若渴。去$u{半夏}。加$u{栝楼根}$w{三两}。若微利。去$u{麻黄}。加$u{荛花}。$w{如一鸡子。熬令赤色}。若噎者。去$u{麻黄}。加$u{附子}$w{一枚。炮}。若小便不利。少腹满者。去$u{麻黄}。加$u{茯苓}$w{四两}。若喘。去$u{麻黄}。加$u{杏仁}$w{半升。去皮尖。}【且荛花不治利。麻黄主喘。今此语反之。疑非仲景意。】$a{臣亿等谨按小青龙汤。大要治水。又按本草荛花下十二水。若水去。利则止也。又按千金。形肿者应内麻黄。乃内杏仁者。以麻黄发其阳故也。以此证之。岂非仲景意也。}', 3, '', '麻黄,芍药,细辛,干姜,甘草,桂枝,五味子,半夏,栝楼根,荛花,附子,茯苓,杏仁', 600025459474501, '6F31A5C30F3CE21754F96B150C83A308', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:44', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (22, '干姜附子汤', 21, 2, 10001, '22、$f{干姜附子汤} 2味 \n$u{干姜}$w{一两}    $u{附子}$w{一枚(生用。去皮。切八片)}\n	上二味。以水三升。煮取一升。去滓。顿服。', 1, '', '干姜,附子', 600025459875909, 'A2AE2452F28F994CD7FBAF593AAE180D', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:44', NULL, NULL, NULL);
