INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (38, '真武汤', 37, 8, 10001, '38、$f{真武汤} 5味 \n$u{茯苓}    $u{芍药}    $u{生姜}$w{各三两(切)}    $u{白术}$w{二两}    $u{附子}$w{一枚(炮。去皮。破八片)}\n	上五味。以水八升。煮取三升。去滓。温服七合。日三服。若咳者。加$u{五味子}$w{半升}    $u{细辛}$w{一两}    $u{干姜}$w{一两}。若小便利者。去$u{茯苓}。若下利者。去$u{芍药}。加$u{干姜}$w{二两}。若呕者。去$u{附子}。加$u{生姜}。$w{足前为半斤。}', 4, '', '茯苓,芍药,生姜,白术,附子,五味子,细辛,干姜', 600025466679365, 'FEECD663E097579D3441141DBB021B64', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:45', NULL, NULL, NULL);
