INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (40, '小建中汤', 39, 6, 10001, '40、$f{小建中汤} 6味 \n$u{桂枝}$w{三两。去皮}    $u{甘草}$w{二两。炙}    $u{大枣}$w{十二枚。擘}    $u{芍药}$w{六两}    $u{生姜}$w{三两。切}    $u{胶饴}$w{一升}\n	上六味。以水七升。煮取三升。去滓。内饴。更上微火消解。温服一升。日三服。呕家不可用建中汤。以甜故也。', 3, '', '桂枝,甘草,大枣,芍药,生姜,胶饴', 600025467289669, '4D2DB2BB0BCFD7E0C0851D9D41641772', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:46', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (41, '大柴胡汤', 40, 8, 10001, '41、$f{大柴胡汤} 7味 \n$u{柴胡}$w{半斤}    $u{黄芩}$w{三两}    $u{芍药}$w{三两}    $u{半夏}$w{半升(洗)}    $u{生姜}$w{五两。切}    $u{枳实}$w{四枚。炙}    $u{大枣}$w{十二枚。擘}\n	上七味。以水一斗二升。煮取六升。去滓。再煎。温服一升。日三服。【一方。加$u{大黄}$w{二两}。若不加。恐不为大柴胡汤。】', 3, '', '柴胡,黄芩,芍药,半夏,生姜,枳实,大枣,大黄', 600025467699269, 'D3A96872B1863E52CCD3A26D71CE1DF0', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:46', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (42, '柴胡加芒硝汤', 41, 8, 10001, '42、$f{柴胡加芒硝汤} 8味 \n$u{柴胡}$w{二两十六铢}    $u{黄芩}$w{一两}    $u{人参}$w{一两}    $u{甘草}$w{一两。炙}    $u{生姜}$w{一两。切}    $u{半夏}$w{二十铢(本云五枚。洗)}    $u{大枣}$w{四枚。擘}    $u{芒硝}$w{二两}\n	上八味。以水四升。煮取二升。去滓。内芒硝。更微煮沸。分温再服。不解更作。$a{臣亿等谨按金匮玉函方中。无芒消。别一方云。以水七升。下芒消二合。大黄四两。桑螵蛸五枚。煮取一升半。服五合。微下即愈。本云柴胡再服以解其外。余二升加芒消大黄桑螵蛸也。}', 2, '', '柴胡,黄芩,人参,甘草,生姜,半夏,大枣,芒硝', 600025468137541, '7B0DA32F6A0DFB8E675A240AAAE5FF9C', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:46', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (43, '桃核承气汤', 42, 5, 10001, '43、$f{桃核承气汤} 5味 \n$u{桃仁}$w{五十个。去皮尖}     $u{桂枝}$w{二两。去皮}  $u{大黄}$w{四两}     $u{甘草}$w{二两。炙}    $u{芒硝}$w{二两}\n	上五味。以水七升。煮取二升半。去滓。内芒硝。更上火。微沸下火。先食。温服五合。日三服。当微利。', 5, '', '芒硝,甘草,桂枝,大黄,桃仁', 600025468608581, '30A7673EF74B87E68A6ED44DB87CFF67', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:46', 1, '超级管理员', '2024-11-25 09:59:01');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (44, '柴胡加龙骨牡蛎汤', 43, 12, 10001, '44、$f{柴胡加龙骨牡蛎汤} 12味 \n$u{柴胡}$w{四两}    $u{龙骨}    $u{黄芩}    $u{生姜}$w{切}    $u{铅丹}    $u{人参}    $u{桂枝}$w{去皮}    $u{茯苓}$w{各一两半}    $u{半夏}$w{二合半(洗)}    $u{大黄}$w{二两}    $u{牡蛎}$w{一两半(熬)}    $u{大枣}$w{六枚。擘}\n	上十二味。以水八升。煮取四升。内大黄。切如棋子。更煮一两沸。去滓。温服一升。【本云柴胡汤。今加龙骨等。】', 4, '', '柴胡,龙骨,黄芩,生姜,铅丹,人参,桂枝,茯苓,半夏,大黄,牡蛎,大枣', 600025469087813, '2281837766333DBE81063653077B4424', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:46', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (45, '桂枝去芍药加蜀漆牡蛎龙骨救逆汤', 44, 7, 10001, '45、$f{桂枝去芍药加蜀漆牡蛎龙骨救逆汤} 7味 \n$u{桂枝}$w{三两。去皮}    $u{甘草}$w{二两。炙}    $u{生姜}$w{三两。切}    $u{大枣}$w{十二枚。擘}    $u{牡蛎}$w{五两(熬)}    $u{蜀漆}$w{三两(洗去腥)}    $u{龙骨}$w{四两}\n	上七味。以水一斗二升。先煮蜀漆。减二升。内诸药。煮取三升。去滓。温服一升。【本云桂枝汤。今去芍药。加蜀漆牡蛎龙骨。】', 3, '', '桂枝,甘草,生姜,大枣,牡蛎,蜀漆,龙骨', 600025469509701, '33CC4F94390C2991579EB10A11003343', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:46', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (46, '桂枝加桂汤', 45, 5, 10001, '46、$f{桂枝加桂汤} 5味 \n$u{桂枝}$w{五两。去皮}    $u{芍药}$w{三两}    $u{生姜}$w{三两。切}    $u{甘草}$w{二两。炙}    $u{大枣}$w{十二枚。擘}\n	上五味。以水七升。煮取三升。去滓。温服一升。【本云桂枝汤。今加桂满五两所以加桂者。以能泄奔豚气也。】', 3, '', '桂枝,芍药,生姜,甘草,大枣', 600025469919301, '698295B2F89A22211F2371AFE50A0E62', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:46', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (47, '桂枝甘草龙骨牡蛎汤', 46, 4, 10001, '47、$f{桂枝甘草龙骨牡蛎汤} 4味 \n$u{桂枝}$w{一两。去皮}    $u{甘草}$w{二两。炙}    $u{牡蛎}$w{二两(熬)}    $u{龙骨}$w{二两}\n	上四味。以水五升。煮取二升半。去滓。温服八合。日三服。', 3, '', '龙骨,牡蛎,甘草,桂枝', 600025470308421, 'E9646481628717680898C61D7E0A4527', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:46', 1, '超级管理员', '2024-11-25 14:21:20');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (48, '抵当汤', 47, 5, 10001, '48、$f{抵当汤} 4味 \n$u{水蛭}$w{(熬)}    $u{虻虫}$w{各三十个(去翅足。熬)}    $u{桃仁}$w{二十个。去皮尖}    $u{大黄}$w{三两($u{酒}洗)}\n	上四味。以水五升。煮取三升。去滓。温服一升。不下。更服。', 3, '', '水蛭,虻虫,桃仁,大黄,酒', 600025470693445, 'CEAABB9C8F305458F799EF27C4AC190E', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:46', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (49, '抵当丸', 48, 4, 10001, '49、$f{抵当丸} 4味 \n$u{水蛭}$w{二十个(熬)}    $u{虻虫}$w{二十个(去翅足。熬)}    $u{桃仁}$w{二十五个。去皮尖}    $u{大黄}$w{三两}\n	上四味。捣分四丸。以水一升。煮一丸。取七合。服之。晬时当下血。若不下者。更服。', 4, '', '水蛭,虻虫,桃仁,大黄', 600025471111237, '8BD78A4CDB13BDA2CD0C50B82F4CEBEF', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:46', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (50, '大陷胸丸', 49, 6, 10001, '50、$f{大陷胸丸} 6味 \n$u{大黄}$w{半斤}    $u{葶苈子}$w{半升(熬)}    $u{芒硝}$w{半升}    $u{杏仁}$w{半升(去皮尖,熬黑)}\n	上四味。捣筛二味。内杏仁。芒硝。合研如脂。和散。取如弹丸一枚。别捣$u{甘遂末}$w{末一钱匕}    $u{白蜜}$w{二合}。水二升。煮取一升。温顿服之。一宿乃下。如不下。更服。取下为效。禁如药法。', 50, '', '大黄,葶苈子,芒硝,杏仁,甘遂末,白蜜', 600025471516741, '75F7F123301567F5189B2D8F495B33E1', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:46', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (51, '大陷胸汤', 50, 3, 10001, '51、$f{大陷胸汤} 3味 \n$u{大黄}$w{六两。去皮}    $u{芒硝}$w{一升}    $u{甘遂}$w{一钱匕}\n	上三味。以水六升。先煮大黄取二升。去滓。内芒硝。煮一两沸。内甘遂末。温服一升。得快利。止后服。', 2, '', '大黄,芒硝,甘遂', 600025471926341, '2E0E31B4E8ED4DF41BC62DED7390E4E1', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:46', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (52, '小陷胸汤', 51, 3, 10001, '52、$f{小陷胸汤} 3味 \n$u{黄连}$w{一两}    $u{半夏}$w{半升(洗)}    $u{栝楼实}$w{大者一枚}\n	上三味。以水六升。先煮栝楼。取三升。去滓。内诸药。煮取二升。去滓。分温三服。', 3, '', '黄连,半夏,栝楼实', 600025472352325, '943E55311EDD90F87EFA126DE67B3E98', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:47', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (53, '文蛤散', 52, 1, 10001, '53、$f{文蛤散} 1味 \n$u{文蛤}$w{五两}\n	上一味。为散。以沸汤和一方寸匕服。汤用五合。', 3, '', '文蛤', 600025472790597, 'AAC7C511E3D73E4B254071D19EE8A55A', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:47', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (54, '三物小白散', 53, 4, 10001, '54、$f{三物小白散} 3味 \n$u{桔梗}$w{三分}    $u{巴豆}$w{一分(去皮心。熬黑。研如脂)}    $u{贝母}$w{三分}\n	上三味为散。内巴豆。更于臼中杵之。以白饮和服。强人半钱匕。羸者减之。病在膈上必吐。在膈下必利。不利。进热粥一杯。利过不止。进冷粥一杯。身热皮粟不解。欲引衣自覆。若以水潠之、洗之。益令热却不得出。当汗而不汗则烦。假令汗出已。腹中痛。与$u{芍药}$w{三两}。如上法。', 10, '', '桔梗,巴豆,贝母,芍药', 600025473212485, '6235D0DCC49A8CE31F572E895D3A8E59', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:47', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (55, '柴胡桂枝汤', 54, 9, 10001, '55、$f{柴胡桂枝汤} 9味 \n$u{桂枝}$w{去皮}    $u{芍药}$w{一两半}    $u{黄芩}$w{一两半}    $u{人参}$w{一两半}    $u{甘草}$w{一两。炙}    $u{半夏}$w{二合半(洗)}    $u{生姜}$w{一两半。切}    $u{大枣}$w{六枚。擘}    $u{柴胡}$w{四两}\n	上九味。以水七升。煮取三升。去滓。温服一升。', 3, '', '桂枝,芍药,黄芩,人参,甘草,半夏,生姜,大枣,柴胡', 600025473638469, '5A0123D54CC4FC528FB8C56C3E458137', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:47', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (56, '柴胡桂枝干姜汤', 55, 7, 10001, '56、$f{柴胡桂枝干姜汤} 7味 \n$u{柴胡}$w{半斤}    $u{桂枝}$w{三两。去皮}    $u{干姜}$w{二两}    $u{栝楼根}$w{四两}    $u{黄芩}$w{三两}    $u{牡蛎}$w{二两(熬)}    $u{甘草}$w{二两。炙}\n	上七味。以水一斗二升。煮取六升。去滓。再煎取三升。温服一升。日三服。初服微烦。复服汗出便愈。', 3, '', '柴胡,桂枝,干姜,栝楼根,黄芩,牡蛎,甘草', 600025474113605, 'B63A51F17A632DBA13830DA305A1E2F9', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:47', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (57, '半夏泻心汤', 56, 7, 10001, '57、$f{半夏泻心汤} 7味 \n$u{半夏}$w{半升(洗)}    $u{黄芩}    $u{干姜}    $u{人参}    $u{甘草}$w{炙各三两}    $u{黄连}$w{一两}    $u{大枣}$w{十二枚。擘}\n	上七味。以水一斗。煮取六升。去滓。再煎取三升。温服一升。日三服。', 3, '', '半夏,黄芩,干姜,人参,甘草,黄连,大枣', 600025474531397, 'C28460088BAACC06BF8A9DF8DA20320E', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:47', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (58, '十枣汤', 57, 4, 10001, '58、$f{十枣汤} 4味 \n$u{芫花}$w{(熬)}    $u{甘遂}    $u{大戟}    $u{大枣}$w{十枚(先煮)}\n	上三味等分。各别捣为散。以水一升半。先煮大枣肥大者十枚。取八合。去滓。内药末。$a{强人服一钱匕。羸人服半钱。}温服之。$a{平旦服。}若下少病不除者。明日更服。$a{加半钱。}得快下利后。糜粥自养。', 1, '', '芫花,甘遂,大戟,大枣', 600025474953285, 'D3F171BE5BEFF62BA4C17FD487302AD3', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:47', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (59, '大黄黄连泻心汤', 58, 2, 10001, '59、$f{大黄黄连泻心汤} 2味 \n$u{大黄}$w{二两}    $u{黄连}$w{一两(麻过滤绞之)}\n	上二味。以麻沸汤二升渍之。须臾绞去滓。分温再服。', 2, '', '大黄,黄连', 600025475366981, 'CA53CBC29B02393E8A7F5EC3CB30848C', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:47', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (60, '附子泻心汤', 59, 4, 10001, '60、$f{附子泻心汤} 4味 \n$u{大黄}$w{二两}    $u{黄连}$w{一两}    $u{黄芩}$w{一两}    $u{附子}$w{一枚(炮。去皮。破。别煮取汁)}\n	上四味。切三味。以麻沸汤二升渍之。须臾绞去滓。内附子汁。分温再服。', 2, '', '大黄,黄连,黄芩,附子', 600025475797061, '9BF9A471D89F1DB4D9A5C719F05FCB68', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:47', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (61, '生姜泻心汤', 60, 8, 10001, '61、$f{生姜泻心汤} 8味 \n$u{生姜}$w{四两。切}    $u{甘草}$w{三两。炙}    $u{人参}$w{三两}    $u{干姜}$w{一两}    $u{黄芩}$w{三两}    $u{半夏}$w{半升(洗)}    $u{黄连}$w{一两}    $u{大枣}$w{十二枚。擘}\n	上八味。以水一斗。煮取六升。去滓。再煎取三升。温服一升。日三服。', 3, '', '生姜,甘草,人参,干姜,黄芩,半夏,黄连,大枣', 600025476251717, '2FBF7CC1216227803C3430E517BB8B58', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:47', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (62, '甘草泻心汤', 61, 6, 10001, '62、$f{甘草泻心汤} 6味 \n$u{甘草}$w{四两。炙}    $u{干姜}$w{三两}    $u{黄芩}$w{三两}    $u{半夏}$w{半升(洗)}    $u{黄连}$w{一两}    $u{大枣}$w{十二枚。擘}\n	上六味。以水一斗。煮取六升。去滓。再煎取三升。温服一升。日三服。$a{按：上生姜泻心汤法。本云理中人参黄芩汤。今详泻心以疗痞。痞气因发阴而生。是半夏、生姜、甘草泻心汤三方皆本于理中也。其方必各有人参。今甘草泻心汤中无者。脱落之也。又按《千金》并《外台秘要》。治伤寒食用此方。皆有人参。知脱落无疑。}', 3, '', '甘草,干姜,黄芩,半夏,黄连,大枣', 600025476726853, '7A5E5888416C3F125ABFCFCD6382447D', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:47', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (63, '赤石脂禹余粮汤', 62, 2, 10001, '63、$f{赤石脂禹余粮汤} 2味 \n$u{赤石脂}$w{一斤(碎)}    $u{太一禹余粮}$w{一斤(碎)}\n	上二味。以水六升。煮取二升。去滓。分温三服。', 3, '', '赤石脂,太一禹余粮', 600025477156933, '039C2CC2C51F481D5AF02ED83FB28617', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:48', NULL, NULL, NULL);
