INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (65, '桂枝人参汤', 64, 5, 10001, '65、$f{桂枝人参汤} 5味 \n$u{桂枝}$w{四两(别切)}    $u{甘草}$w{四两。炙}    $u{白术}$w{三两}    $u{人参}$w{三两}    $u{干姜}$w{三两}\n	上五味。以水九升。先煮四味。取五升。内桂。更煮取三升。去滓。温服一升。日再夜一服。', 3, '', '桂枝,甘草,白术,人参,干姜', 600025478041669, 'E54DC5F9001E477B72B4F2DFA1F36F23', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:48', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (66, '瓜蒂散', 65, 3, 10001, '66、$f{瓜蒂散} 2味 \n$u{瓜蒂}$w{一分(熬黄)}    $u{赤小豆}$w{一分}($u{香豉}$w{热汤合之})。\n	上二味。各别捣筛。为散已。合治之。取一钱匕。以香豉一合。用热汤七合。煮作稀糜。去滓。取汁和散。温顿服之。不吐者。少少加。得快吐乃止。$a{诸亡血虚家。不可与瓜蒂散。}', 1, '', '瓜蒂,赤小豆,香豉', 600025478496325, 'AB429E44EFB743ADAEBE44CD0F91C48A', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:48', NULL, NULL, NULL);
