INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (68, '黄芩加半夏生姜汤', 67, 6, 10001, '68、$f{黄芩加半夏生姜汤} 6味 \n$u{黄芩}$w{三两}    $u{芍药}$w{二两}    $u{甘草}$w{二两。炙}    $u{大枣}$w{十二枚。擘}    $u{半夏}$w{半升(洗)}    $u{生姜}$w{一两半。一方三两。切}\n	上六味。以水一斗。煮取三升。去滓。温服一升。日再夜一服。', 3, '', '黄芩,芍药,甘草,大枣,半夏,生姜', 600025479336005, '60CDEF4D4566492AD5A3AC8255BBC7F8', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:48', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (69, '黄连汤', 68, 7, 10001, '69、$f{黄连汤} 7味 \n$u{黄连}$w{三两}    $u{甘草}$w{三两。炙}    $u{干姜}$w{三两}    $u{桂枝}$w{三两。去皮}    $u{人参}$w{二两}    $u{半夏}$w{半升(洗)}    $u{大枣}$w{十二枚。擘}\n	上七味。以水一斗。煮取六升。去滓。温服。昼三夜二。$a{疑非仲景方。（康平本作“疑非仲景法“）}', 5, '', '黄连,甘草,干姜,桂枝,人参,半夏,大枣', 600025479766085, '637675BD14982B1B4ABBFA30DCC734FF', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:48', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (70, '桂枝附子汤', 69, 5, 10001, '70、$f{桂枝附子汤} 5味 \n$u{桂枝}$w{四两。去皮}    $u{附子}$w{三枚(炮。去皮。破)}    $u{生姜}$w{三两。切}    $u{大枣}$w{十二枚。擘}    $u{甘草}$w{二两。炙}\n	上五味。以水六升。煮取二升。去滓。分温三服。', 3, '', '桂枝,附子,生姜,大枣,甘草', 600025480183877, '7E21972CB7ED8B7E5AF57346E48FED66', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:48', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (71, '去桂加白术汤', 70, 5, 10001, '71、$f{去桂加白术汤} 5味 \n$u{附子}$w{三枚(炮。去皮。破)}    $u{白术}$w{四两}    $u{生姜}$w{三两。切}    $u{大枣}$w{十二枚。擘}    $u{甘草}$w{二两。炙}\n	上五味。以水六升。煮取二升。去滓。分温三服。初一服。其人身如痹。半日许复服之。三服都尽。其人如冒状。勿怪。此以附子、术。并走皮内。逐水气未得除。故使之耳。法当加桂四两。$a{此本一方二法：以大便硬。小便自利。去桂也。以大不便硬。小便不利。当加桂。附子三枚恐多也。虚弱及产妇宜减之。}', 3, '', '附子,白术,生姜,大枣,甘草', 600025480585285, 'CF4C9BB6622FDF577A8D1AD1B82A909E', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:48', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (72, '甘草附子汤', 71, 4, 10001, '72、$f{甘草附子汤} 4味 \n$u{甘草}$w{二两。炙}    $u{附子}$w{二枚(炮。去皮。破)}    $u{白术}$w{二两}    $u{桂枝}$w{四两。去皮}\n	上四味。以水六升。煮取三升。去滓。温服一升。日三服。$a{初服得微汗则解。能食。汗止复烦者。将服五合。恐一升多者。宜服六七合为始。}', 3, '', '甘草,附子,白术,桂枝', 600025480994885, 'B35F996E5404090A9C623275F3D905AA', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:48', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (73, '白虎汤', 72, 4, 10001, '73、$f{白虎汤} 4味 \n$u{知母}$w{六两}    $u{石膏}$w{一斤(碎)}    $u{甘草}$w{二两。炙}    $u{粳米}$w{六合}\n	上四味。以水一斗。煮米熟汤成。去滓。温服一升。日三服。', 3, '', '知母,石膏,甘草,粳米', 600025481404485, 'F5B17EF23E949EBCCAA978D070A17F49', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:48', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (74, '大承气汤', 73, 4, 10001, '74、$f{大承气汤} 4味 \n$u{大黄}$w{四两($u{酒}洗)}    $u{厚朴}$w{半斤(炙。去皮)}    $u{枳实}$w{五枚。炙}    $u{芒硝}$w{三合}\n	上四味。以水一斗。先煮二物。取五升。去滓。内大黄。更煮取二升。去滓。内芒硝。更上微火一两沸。分温再服。$a{得下。余勿服。}', 2, '', '大黄,酒,厚朴,枳实,芒硝', 600025481801797, '7B096EC84497EFDBAA2B3CF4DDBB18A3', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:48', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (75, '小承气汤', 74, 3, 10001, '75、$f{小承气汤} 3味 \n$u{大黄}$w{四两($u{酒}洗)}    $u{厚朴}$w{二两(炙。去皮)}    $u{枳实}$w{三枚(大者。炙)}\n	上三味。以水四升。煮取一升二合。去滓。分温二服。$a{初服汤当更衣。不尔者。尽饮之。若更衣者。勿服之。}', 2, '', '大黄,酒,厚朴,枳实', 600025482182725, 'AD73630FC3F0FA43C303C74196C8AF21', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:48', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (76, '猪苓汤', 75, 5, 10001, '76、$f{猪苓汤} 5味 \n$u{猪苓}$w{去皮}    $u{茯苓}    $u{泽泻}    $u{阿胶}    $u{滑石}$w{(碎)各一两}\n	上五味。以水四升。先煮四味。取二升。去滓。内阿胶烊消。温服七合。日三服。', 3, '', '猪苓,茯苓,泽泻,阿胶,滑石', 600025482666053, '08ADB02ABB98E1116B44490CB2AFC52D', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:49', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (77, '蜜煎导', 76, 3, 10001, '77、$f{蜜煎导} 1味 \n$u{食蜜}$w{七合}\n	上一味。于铜器内。微火煎。当须凝如饴状。搅之勿令焦着。欲可丸。并手捻作挺。令头锐。大如指。长二寸许。当热时急作。冷则硬。以内谷道中．以手急抱。欲大便时乃去之。又$u{大猪胆}$w{一枚。泻汁}。和少许$u{法醋}。以灌谷道内。如一食顷。当大便出宿食恶物。甚效。', 1, '', '食蜜,大猪胆,法醋', 600025483079749, '1824E56F6E1498F703CCFA912E092C05', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:49', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (78, '茵陈蒿汤', 77, 3, 10001, '78、$f{茵陈蒿汤} 3味 \n$u{茵陈蒿}$w{六两}    $u{栀子}$w{十四枚。擘}    $u{大黄}$w{二两。去皮}\n	上三味。以水一斗二升。先煮茵陈。减六升。内二味。煮取三升。去滓。分三服。小便当利。$a{尿如皂荚汁状。色正赤。一宿腹减。黄从小便去也。}', 3, '', '茵陈蒿,栀子,大黄', 600025483477061, 'FD3843DB4F67A2987A1253E4E930B2CD', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:49', NULL, NULL, NULL);
