INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (87, '桃花汤', 86, 3, 10001, '87、$f{桃花汤} 3味 \n$u{赤石脂}$w{一斤(一半全用。一半筛末)}    $u{干姜}$w{一两}    $u{粳米}$w{一升}\n	上三味。以水七升。煮米令熟。去滓。温服七合。内赤石脂末方寸匕。日三服。若一服愈。余勿服。', 3, '', '赤石脂,干姜,粳米', 600025487380549, '4220346E8C4A47D202D335C2C3C3BCD0', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:49', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (88, '猪肤汤', 87, 3, 10001, '88、$f{猪肤汤} 1味 \n$u{猪肤}$w{一斤}    $u{白蜜}、$u{白粉}$w{(即大米粉)}\n	上一味。以水一斗。煮取五升。去滓。加$u{白蜜}$w{一升}    $u{白粉}$w{五合}。熬香。和令相得。温分六服。', 6, '', '猪肤,白蜜,白粉', 600025487814725, 'E0D4D13FE3D3FC11EDD0614DDD57447F', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:49', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (89, '甘草汤', 88, 1, 10001, '89、$f{甘草汤} 1味 \n$u{甘草}$w{二两}\n	上一味。以水三升。煮取一升半。去滓。温服七合。日二服。', 2, '', '甘草', 600025488252997, '2E9CCC243CE6484F2D5ECFC504E57052', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:50', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (90, '桔梗汤', 89, 2, 10001, '90、$f{桔梗汤} 2味 \n$u{桔梗}$w{一两}    $u{甘草}$w{二两}\n	上二味。以水三升。煮取一升。去滓。温分再服。', 2, '', '桔梗,甘草', 600025488678981, '59A24772170BA7B5977FD005A8663482', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:50', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (91, '苦酒汤', 90, 3, 10001, '91、$f{苦酒汤} 3味 \n$u{半夏}$w{十四枚(洗。破如枣核)}    $u{鸡子}$w{一枚(去黄)。内上}$u{苦酒}$w{着鸡子壳中}\n	上二味。内半夏著苦酒中。以鸡子壳置刀环中。安火上。令三沸。去滓。少少含咽之。不差。更作三剂。', 1, '', '半夏,鸡子,苦酒', 600025489100869, '74D976C95CB45F197CDA62DFF819D8F2', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:50', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (92, '半夏散及汤', 91, 3, 10001, '92、$f{半夏散及汤} 3味 \n$u{半夏}$w{(洗)}    $u{桂枝}$w{去皮}    $u{甘草}$w{炙}\n	上三味。等分。个别捣筛已。合治之。白饮和。服方寸匕。日三服。若不能服散者。以水一升。煎七沸。内散两方寸匕。更煮三沸。下火令小冷。少少咽之。$a{半夏有毒。不当散服。}', 1, '', '半夏,桂枝,甘草', 600025489502277, '5214CC377ADEE1AFB4E6D26DA15EBE59', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:50', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (93, '白通汤', 92, 3, 10001, '93、$f{白通汤} 3味 \n$u{葱白}$w{四茎}    $u{干姜}$w{一两}    $u{附子}$w{一枚(生。去皮。破八片)}\n	上三味。以水三升。煮取一升。去滓。分温再服。', 2, '', '葱白,干姜,附子', 600025489899589, 'C9A302E4616DB47C4B8F2C6A0E445289', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:50', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (94, '白通加猪胆汁汤', 93, 5, 10001, '94、$f{白通加猪胆汁汤} 5味 \n$u{葱白}$w{四茎}    $u{干姜}$w{一两}    $u{附子}$w{一枚(生。去皮。破八片)}    $u{人尿}$w{五合}    $u{猪胆汁}$w{一合}\n	上五味。以水三升。煮取一升。去滓。内胆汁、人尿。和令相得。分温再服。$a{若无胆。亦可用。}', 2, '', '葱白,干姜,附子,人尿,猪胆汁', 600025490292805, '81DF3408F2681D58DE47BA3E75A59940', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:50', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (95, '通脉四逆汤', 94, 8, 10001, '95、$f{通脉四逆汤} 3味 \n$u{甘草}$w{二两。炙}    $u{附子}$w{大者一枚(生用。去皮。破八片)}    $u{干姜}$w{三两。强人可四两}\n	上三味。以水三升。煮取一升二合。去滓。分温再服。其脉即出者愈。面色赤者。加$u{葱}$w{九茎}。腹中痛者。去$u{葱}。加$u{芍药}$w{二两}。呕者。加$u{生姜}$w{二两}。咽痛者。去$u{芍药}。加$u{桔梗}$w{一两}。利止脉不出者。去$u{桔梗}。加$u{人参}$w{二两}。$a{病皆与方相应者。乃服之。}', 2, '', '甘草,附子,干姜,葱,芍药,生姜,桔梗,人参', 600025490673733, 'CE0BFE44DC0CDE6EFFA083AA40B06F03', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:50', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (96, '乌梅丸', 95, 12, 10001, '96、$f{乌梅丸} 10味 \n$u{乌梅}$w{三百枚}    $u{细辛}$w{六两}    $u{干姜}$w{十两}    $u{黄连}$w{十六两}    $u{附子}$w{六两(炮。去皮)}    $u{当归}$w{四两}    $u{蜀椒}$w{四两(出汗)}    $u{桂枝}$w{六两。去皮}    $u{人参}$w{六两}    $u{黄柏}$w{六两}\n	上十味。异捣筛。合治之。以$u{苦酒}（即酸醋）渍乌梅一宿。去核。蒸之五斗米下。饭熟。捣成泥。和药令相得。内臼中。与$u{蜜}杵二千下。丸如梧桐子大。先食。饮服十丸。日三服。稍加至二十丸。禁生冷。滑物。臭食等。', 30, '', '乌梅,细辛,干姜,黄连,附子,当归,蜀椒,桂枝,人参,黄柏,苦酒,蜜', 600025491107909, 'B2A68280C79870BB15875174FDF132B0', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:50', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (97, '当归四逆汤', 96, 7, 10001, '97、$f{当归四逆汤} 7味 \n$u{当归}$w{三两}    $u{桂枝}$w{三两。去皮}    $u{芍药}$w{三两}    $u{细辛}$w{三两}    $u{甘草}$w{二两。炙}    $u{通草}$w{二两}    $u{大枣}$w{二十五枚(擘。一法十二枚)}\n	上七味。以水八升。煮取三升。去滓。温服一升。日三服。', 3, '', '当归,桂枝,芍药,细辛,甘草,通草,大枣', 600025491550277, '82527E07F7CC6C0EA052A75871ED77A4', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:50', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (98, '当归四逆加吴茱萸生姜汤', 97, 10, 10001, '98、$f{当归四逆加吴茱萸生姜汤} 9味 \n$u{当归}$w{三两}    $u{桂枝}$w{三两。去皮}    $u{芍药}$w{三两}    $u{细辛}$w{三两}    $u{甘草}$w{二两。炙}    $u{通草}$w{二两}    $u{大枣}$w{二十五枚。擘}    $u{生姜}$w{半斤}    $u{吴茱萸}$w{二升}\n	上九味。以水六升、$u{清酒}$w{六升}和。煮取五升。去滓。温分五服。一方。水、酒各四升。', 5, '', '当归,桂枝,芍药,细辛,甘草,通草,大枣,生姜,吴茱萸,清酒', 600025492009029, 'B17A2392AADB56FFF2C5737AD6C6561E', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:50', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (99, '麻黄升麻汤', 98, 14, 10001, '99、$f{麻黄升麻汤} 14味 \n$u{麻黄}$w{二两半。去节}    $u{升麻}$w{一两一分}    $u{当归}$w{一两一分}    $u{知母}$w{十八铢}    $u{黄芩}$w{十八铢}    $u{葳蕤}$w{十八铢(一作菖蒲)}    $u{芍药}$w{六铢}    $u{天门冬}$w{六铢(去心)}    $u{桂枝}$w{六铢。去皮}    $u{茯苓}$w{六铢}    $u{甘草}$w{六铢。炙}    $u{石膏}$w{六铢(碎。绵裹)}    $u{白术}$w{六铢}    $u{干姜}$w{六铢}\n	上十四味。以水一斗。先煮麻黄一两沸。去上沫。内诸药。煮取三升。去滓。分温三服。相去如炊三斗米顷。令尽。汗出愈。', 3, '', '麻黄,升麻,当归,知母,黄芩,葳蕤,芍药,天门冬,桂枝,茯苓,甘草,石膏,白术,干姜', 600025492414533, '69A75094943A97B8085CBFB9A2A4D67E', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:50', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (100, '干姜黄芩黄连人参汤', 99, 4, 10001, '100、$f{干姜黄芩黄连人参汤} 4味 \n$u{干姜}    $u{黄芩}    $u{黄连}    $u{人参}$w{各三两}\n	上四味。以水六升。煮取二升。去滓。分温再服。', 2, '', '干姜,黄芩,黄连,人参', 600025492824133, '1003F91CA89C0159B7E94281606D691E', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:50', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (101, '四逆加人参汤', 100, 4, 10001, '101、$f{四逆加人参汤} 4味 \n$u{甘草}$w{二两。炙}    $u{附子}$w{一枚(生。去皮。破八片)}    $u{干姜}$w{一两半}    $u{人参}$w{一两}\n	上四味。以水三升。煮取一升二合。去滓。分温再服。', 2, '', '甘草,附子,干姜,人参', 600025493241925, '9B74A4D0083FF0A57626A1F1C95DF5D4', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:51', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (102, '理中丸', 101, 4, 10001, '102、$f{理中丸} 4味 \n$u{人参}    $u{干姜}    $u{甘草}$w{炙}    $u{白术}$w{各三两}\n	上四味。捣筛。$u{蜜}合为丸。如鸡子黄大。以沸汤数合。和一丸。研碎。温服之。$a{日三四、夜二服。}腹中未热。益至三四丸。然不及汤。汤法：以四物依两数切。用水八升。煮取三升。去滓。温服一升。日三服。若脐上筑者。肾气动也。去$u{术}加$u{桂}$w{四两}。吐多者。去$u{术}加$u{生姜}$w{三两}。下多者还用$u{术}。悸者。加$u{茯苓}$w{二两}。渴欲得水者。加$u{术}。$w{足前成四两半}。腹中痛者。加$u{人参}。$w{足前成四两半}。寒者。加$u{干姜}。$w{足前成四两半}。腹满者。去$u{术}。加$u{附子}$w{一枚}。服汤后。如食顷。饮热粥一升许。微自温。勿发揭衣被。', 3, '', '人参,干姜,甘草,白术,蜜,术,桂,生姜,茯苓,附子', 600025493667909, 'C65C5F61F9E2E1ADC7973ABD7EC3635A', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:51', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (103, '烧裈散', 102, 1, 10001, '103、$f{烧裈散} 1味 \n$u{妇人中裈近隐处取烧作灰}\n	上一味。水服方寸匕。日三服。小便即利。阴头微肿。$a{此为愈矣。妇人病取男子裈烧服。}', 3, '', '妇人中裈近隐处取烧作灰', 600025494085701, '876070808E2622E64862DFB52F577601', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:51', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (104, '牡蛎泽泻散', 103, 7, 10001, '104、$f{牡蛎泽泻散} 7味 \n$u{牡蛎}$w{(熬)}    $u{泽泻}    $u{蜀漆}$w{(煖水洗。去腥)}    $u{葶苈子}$w{(熬)}    $u{商陆根}$w{(熬)}    $u{海藻}$w{(洗。去咸)}    $u{栝楼根}$w{各等分}\n	上七味。异捣。下筛为散。更于臼中治之。白饮和服方寸匕。日三服。小便利。止后服。', 1, '', '牡蛎,泽泻,蜀漆,葶苈子,商陆根,海藻,栝楼根', 600025494470725, 'FF52DA91D8DF7BB050256FFF619534CF', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:51', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (105, '四逆散', 104, 10, 10001, '105、$f{四逆散} 4味 \n$u{甘草}$w{炙}    $u{枳实}$w{(破。水渍。炙干)}    $u{芍药}    $u{柴胡}\n	上四味。各十分。捣筛。白饮和服方寸匕。日三服。咳者。加$u{五味子}、$u{干姜}$w{各五分}。并主下利。悸者。加$u{桂枝}$w{五分}。小便不利者。加$u{茯苓}$w{五分}。腹中痛者。加$u{附子}$w{一枚。炮令坼}。泄利下重者。先以水五升。煮$u{薤白}$w{三升}。去滓。以散三方寸匕。内汤中。煮取一升半。分温再服。', 50, '', '甘草,枳实,芍药,柴胡,五味子,干姜,桂枝,茯苓,附子,薤白', 600025494933573, '3C17FEF5EAAA4C3AACF75A1BA0EDBF8C', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:51', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (106, '白头翁汤', 105, 4, 10001, '106、$f{白头翁汤} 4味 \n$u{白头翁}$w{二两}    $u{黄柏}$w{三两}    $u{黄连}$w{三两}    $u{秦皮}$w{三两}\n	上四味。以水七升。煮取二升。去滓。温服一升。不愈。更服一升。', 2, '', '白头翁,黄柏,黄连,秦皮', 600025495355461, '649E62DBF7251BB5F7DB387E37C7D0D1', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:51', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (107, '通脉四逆加猪胆汁汤', 106, 4, 10001, '107、$f{通脉四逆加猪胆汁汤} 4味 \n$u{甘草}$w{二两。炙}    $u{附子}$w{大者一枚(生。去皮。破八片)}    $u{干姜}$w{三两。强人可四两}    $u{猪胆汁}$w{半合}\n	上四味。以水三升。煮取一升二合。去滓。内猪胆汁。分温再服。$a{其脉即来。无猪胆。以羊胆代之。}', 2, '', '甘草,附子,干姜,猪胆汁', 600025495801925, '1893EF6887D3F39D2A512E16D0713CBF', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:51', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (108, '竹叶石膏汤', 107, 7, 10001, '108、$f{竹叶石膏汤} 7味 \n$u{竹叶}$w{二把}    $u{石膏}$w{一斤}    $u{半夏}$w{半升(洗)}    $u{麦门冬}$w{一斤(去心)}    $u{人参}$w{二两}    $u{甘草}$w{二两。炙}    $u{粳米}$w{半斤}\n	上七味。以水一斗。煮取六升。去滓。内粳米。煮米熟汤成。去米。温服一升。日三服。', 3, '', '竹叶,石膏,半夏,麦门冬,人参,甘草,粳米', 600025496199237, 'B6B1CCD9ACEB0078E4C4AC1DC277959F', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:51', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (109, '四逆汤', 108, 3, 10001, '109、$f{四逆汤} 3味 \n$u{甘草}$w{二两。炙}    $u{干姜}$w{一两半}    $u{附子}$w{一枚。生用去皮破八片}\n	上三味。以水三升。煮取一升二合。去滓。分温再服。强人可$u{大附子}$w{一枚}    $u{干姜}$w{三两}。', 2, '', '附子,干姜,甘草', 600025496666181, '367054CCCB97864AF6022C63AFFE7D7C', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:51', 1, '超级管理员', '2024-11-22 08:31:54');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (110, '炙甘草汤', 109, 10, 10001, '110、$f{炙甘草汤} 9味 \n$u{甘草}$w{四两。炙}    $u{生姜}$w{三两。切}    $u{人参}$w{二两}    $u{桂枝}$w{三两。去皮}    $u{生地黄}$w{一斤}    $u{阿胶}$w{二两}    $u{麦门冬}$w{半升(去心)}    $u{麻子仁}$w{半升}    $u{大枣}$w{三十枚。擘}\n	上九味。以$u{清酒}$w{七升}。水八升。先煮八味。取三升。去滓。内胶烊消尽。温服一升。日三服。$a{一名复脉汤。}', 3, '', '甘草,生姜,人参,桂枝,生地黄,阿胶,麦门冬,麻子仁,大枣,清酒', 600025497100357, 'AAF846DEF4912851D3E2CE08D2D59F72', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:51', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (111, '枳实栀子豉汤', 110, 5, 10001, '111、$f{枳实栀子豉汤} 3味 \n$u{枳实}$w{三枚。炙}    $u{栀子}$w{十四个。擘}    $u{豉}$w{一升(绵裹)}\n	上三味。以$u{清浆水}$w{七升}。空煮取四升。内枳实、栀子。煮取二升。下豉。更煮五六沸。去滓。温分再服。覆令微似汗。若有宿食者。内$u{大黄}$w{如博棋子大五六枚}。服之愈。', 2, '', '枳实,栀子,豉,清浆水,大黄', 600025497555013, '7CAFEF518DB678D3855D1C6BB8291022', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:51', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (112, '麻黄连轺赤小豆汤', 111, 9, 10001, '112、$f{麻黄连轺赤小豆汤} 8味 \n$u{麻黄}$w{二两。去节}    $u{连轺}$w{二两(连翘根)}    $u{杏仁}$w{四十个。去皮尖}    $u{赤小豆}$w{一升}    $u{大枣}$w{十二枚。擘}    $u{生梓白皮}$w{一升。切}    $u{生姜}$w{二两。切}    $u{甘草}$w{二两。炙}\n	上八味。以$u{潦水}$w{一斗}。先煮麻黄。再沸。去上沫。内诸药。煮取三升。分温三服。$a{半日服尽。}', 3, '', '麻黄,连轺,杏仁,赤小豆,大枣,生梓白皮,生姜,甘草,潦水', 600025497993285, '4F45BF4E4E663013AC5C2DE45B8FE046', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:51', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (113, '桂枝加大黄汤', 112, 6, 10001, '113、$f{桂枝加大黄汤} 6味 \n$u{桂枝}$w{三两。去皮}    $u{大黄}$w{二两}    $u{芍药}$w{六两}    $u{甘草}$w{二两。炙}    $u{生姜}$w{三两。切}    $u{大枣}$w{十二枚。擘}\n	上六味。以水七升。煮取三升。去滓。温服一升。日三服。', 3, '', '桂枝,大黄,芍药,甘草,生姜,大枣', 600025498431557, '1FC348195B2F9185F057A0FA3AB4A1E4', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:51', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (114, '栝楼桂枝汤', 0, 6, 10002, '1、$f{栝楼桂枝汤} $m{6味} $u{栝楼根}$w{二两}，$u{桂枝}$w{三两}，$u{芍药}$w{三两}，$u{甘草}$w{二两}，$u{生姜}$w{三两}，$u{大枣}$w{十二枚}\n	$s{右六味}，以水九升，煮取三升。分温三服，取微汗。汗不出，食顷，啜热粥发之。', 3, '', '栝楼根,桂枝,芍药,甘草,生姜,大枣', 600025498882117, '2A90A9051BA07C018A5F743107377614', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:51', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (115, '葛根汤', 1, 7, 10002, '2、$f{葛根汤} $m{7味} $u{葛根}$w{四两}，$u{麻黄}$w{三两，去节}，$u{桂枝}$w{三两，去皮}，$u{芍药}$w{二两}，$u{甘草}$w{二两，炙}，$u{生姜}$w{三两}，$u{大枣}$w{十二枚}\n	$s{右七味}，㕮咀，以水七升，先煮麻黄、葛根，减二升，去沫，内诸药，煮取三升，去滓。温服一升，覆取微似汗，不须啜粥，余如桂枝汤法将息及禁忌。', 3, '', '葛根,麻黄,桂枝,芍药,甘草,生姜,大枣', 600025499320389, '37FD5492A542FEBB6E432C7D6182B477', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:52', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (116, '大承气汤', 2, 5, 10002, '3、$f{大承气汤} $m{4味} $u{大黄}$w{四两，$u{酒}洗}，$u{厚朴}$w{半斤，炙，去皮}，$u{枳实}$w{五枚，炙}，$u{芒硝}$w{三合}\n	$s{右四味}，以水一斗，先煮二物，取五升，去滓，内大黄，煮取二升，去滓，内芒硝，更上火微一二沸。分温再服，得下止服。', 2, '', '大黄,酒,厚朴,枳实,芒硝', 600025539010629, '6333ACCF07261490F18A1096A00D1387', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:52', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (117, '麻黄加术汤', 3, 5, 10002, '4、$f{麻黄加术汤} $m{5味} $u{麻黄}$w{三两，去节}，$u{桂枝}$w{二两，去皮}，$u{甘草}$w{一两，炙}，$u{杏仁}$w{七十个，去皮尖}，$u{白术}$w{四两}\n	$s{右五味}，以水九升，先煮麻黄，减二升，去上沫，内诸药，煮取二升半，去滓。温服八合，覆取微似汗。', 3, '', '麻黄,桂枝,甘草,杏仁,白术', 600025539358789, '567EF546C53D95486F14D95FD46FE7BE', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:52', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (118, '麻黄杏仁薏苡甘草汤', 4, 4, 10002, '5、$f{麻黄杏仁薏苡甘草汤} $m{4味} $u{麻黄}$w{去节，半两，汤泡}，$u{甘草}$w{一两，炙}，$u{薏苡仁}$w{半两}，$u{杏仁}$w{十个，去皮尖，炒}\n	$s{右四味}，剉麻豆大，每服四钱匕，水盏半，煮八分，去滓。温服，有微汗，避风。', 3, '', '麻黄,甘草,薏苡仁,杏仁', 600025539694661, '691316346662F0935C372999BD088556', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:52', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (119, '防己黄芪汤', 5, 10, 10002, '6、$f{防己黄芪汤} $m{6味} $u{防己}$w{一两}，$u{甘草}$w{半两，炒}，$u{白术}$w{七钱半}，$u{黄芪}$w{一两一分，去芦}\n	$s{右四味}，剉麻豆大，每抄五钱匕，$u{生姜}$w{四片}，$u{大枣}$w{一枚}，水盏半，煎八分，去滓。温服，良久再服。喘者，加$u{麻黄}$w{半两}；胃中不和者，加$u{芍药}$w{三分}；气上冲者，加$u{桂枝}$w{三分}；下有陈寒者，加$u{细辛}$w{三分}。服后当如虫行皮中，从腰下如冰，后坐被上，又以一被绕腰以下，温，令微汗，差。$q{《外台》}：治风水。脉浮为在表，其人或头汗出，表无他病，病者但下重，从腰以上为和，腰以下当肿及阴，难以屈伸。', 3, '', '防己,甘草,白术,黄芪,生姜,大枣,麻黄,芍药,桂枝,细辛', 600025540026437, '498227F319FFEA068703A078DAFA06C2', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:52', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (120, '桂枝附子汤', 6, 5, 10002, '7、$f{桂枝附子汤} $m{5味} $u{桂枝}$w{四两，去皮}，$u{生姜}$w{三两，切}，$u{附子}$w{三枚，炮，去皮，破八片}，$u{甘草}$w{二两，炙}，$u{大枣}$w{十二枚，擘}\n	$s{右五味}，以水六升，煮取二升，去滓，分温三服。', 3, '', '桂枝,生姜,附子,甘草,大枣', 600025540440133, '250C2851506C8AAC861D8B6EF5DD500B', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:52', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (121, '白术附子汤', 7, 5, 10002, '8、$f{白术附子汤} $m{5味} $u{白术}$w{二两}，$u{附子}$w{一枚半，炮，去皮}，$u{甘草}$w{一两，炙}，$u{生姜}$w{一两半，切}，$u{大枣}$w{六枚}\n	$s{右五味}，以水三升，煮取一升，去滓，分温三服。一服觉身痹，半日许再服，三服都尽，其人如冒状，勿怪，即是术、附并走皮中逐水气，未得除故耳。', 3, '', '白术,附子,甘草,生姜,大枣', 600025540821061, '7B55B5FD4472097403C807D54D870B11', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:52', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (122, '甘草附子汤', 8, 4, 10002, '9、$f{甘草附子汤} $m{4味} $u{甘草}$w{二两，炙}，$u{附子}$w{二枚，炮，去皮}，$u{白术}$w{二两}，$u{桂枝}$w{四两，去皮}\n	$s{右四味}，以水六升，煮取三升，去滓。温服一升，日三服。初服得微汗则解。能食，汗出复烦者，服五合。恐一升多者，服六七合为妙。', 3, '', '甘草,附子,白术,桂枝', 600025541181509, '624D32B52AE8281E36C0697B59FECF14', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:52', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (123, '白虎加人参汤', 9, 5, 10002, '10、$f{白虎加人参汤} $m{5味} $u{知母}$w{六两}，$u{石膏}$w{一斤，碎}，$u{甘草}$w{二两}，$u{粳米}$w{六合}，$u{人参}$w{三两}\n	$s{右五味}，以水一斗，煮米熟汤成，去滓。温服一升，日三服。', 3, '', '知母,石膏,甘草,粳米,人参', 600025541513285, 'A49D25C7A6C544DFAC1887B15082FD41', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:52', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (124, '一物瓜蒂汤', 10, 1, 10002, '11、$f{一物瓜蒂汤} $m{1味} $u{瓜蒂}$w{二七个}\n	$s{右剉}，以水一升，煮取五合，去滓，顿服。又治诸黄。', 1, '', '瓜蒂', 600025541849157, '236C190459A6CF1E85F7536FA8149358', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:52', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (125, '百合知母汤', 11, 2, 10002, '12、$f{百合知母汤} $m{2味} $u{百合}$w{七枚，擘}，$u{知母}$w{三两，切}\n	$s{右先以水洗百合}，渍一宿，当白沫出，去其水，更以泉水二升，煎取一升，去滓；别以泉水二升煎知母，取一升，去滓；后合和煎，取一升五合。分温再服。', 2, '', '百合,知母', 600025542221893, '5ACF6937AC41FEA5F25876A75CB3AE87', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:52', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (126, '滑石代赭汤', 12, 3, 10002, '13、$f{滑石代赭汤} $m{3味} $u{百合}$w{七枚，擘}，$u{滑石}$w{三两，碎，绵裹}，$u{代赭石}$w{如弹丸大一枚，碎，绵裹}\n	$s{右先以水洗百合}，渍一宿，当白沫出，去其水，更以泉水二升，煎取一升，去滓；别以泉水二升煎滑石、代赭，取一升，去滓；后合和重煎，取一升五合，分温服。', 2, '', '百合,滑石,代赭石', 600025542553669, '519EBDB87627DD10AE1E9570B89EFA80', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:52', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (127, '百合鸡子汤', 13, 2, 10002, '14、$f{百合鸡子汤} $m{2味} $u{百合}$w{七枚，擘}，$u{鸡子黄}$w{一枚}\n	$s{右先以水洗百合}，渍一宿，当白沫出，去其水，更以泉水二升，煎取一升，去滓，内鸡子黄，搅匀，煎五分，温服。', 1, '', '百合,鸡子黄', 600025542881349, 'C3B08FE59461B81DA7131EC64E0ABE7C', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:53', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (128, '百合地黄汤', 14, 2, 10002, '15、$f{百合地黄汤} $m{2味} $u{百合}$w{七枚，擘}，$u{生地黄}$w{汁一升}\n	$s{右以水洗百合}，渍一宿，当白沫出，出其水，更以泉水二升，煎取一升，去滓，内地黄汁，煎取一升五合，分温再服。中病，勿更服，大便当如漆。', 3, '', '百合,生地黄', 600025543233605, '253097BBBA2D265CEC89B0C6DA46E78E', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:53', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (129, '百合洗', 15, 1, 10002, '16、$f{百合洗} $m{1味} $u{百合}$w{一升}\n	$s{右以百合一升}，以水一斗，渍之一宿，以洗身。洗已，食煮饼，勿以盐豉也。', 1, '', '百合', 600025543544901, '72999B0D88C27F271D750BAB49F73BFF', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:53', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (130, '栝楼牡蛎散', 16, 2, 10002, '17、$f{栝楼牡蛎散} $m{2味} $u{栝楼根}，$u{牡蛎}$w{熬，等分}\n	$s{右为细末}，饮服方寸匕，日三服。', 1, '', '栝楼根,牡蛎', 600025543843909, '6A20ED652CAD00002E6B265AF5EFAAB1', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:53', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (131, '百合滑石散', 17, 2, 10002, '18、$f{百合滑石散} $m{2味} $u{百合}$w{一两，炙}，$u{滑石}$w{三两}\n	$s{右为散}，饮服方寸匕，日三服。当微利者，止服，热则除。', 20, '', '百合,滑石', 600025544183877, 'FDC4251305B1D77A768B4A16354C21CF', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:53', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (132, '甘草泻心汤', 18, 7, 10002, '19、$f{甘草泻心汤} $m{7味} $u{甘草}$w{四两}，$u{黄芩}，$u{人参}，$u{干姜}$w{各三两}，$u{黄连}$w{一两}，$u{大枣}$w{十二枚}，$u{半夏}$w{半斤}\n	$s{右七味}，水一斗，煮取六升，去滓，再煎。温服一升，日三服。', 3, '', '甘草,黄芩,人参,干姜,黄连,大枣,半夏', 600025544503365, '6AB68794393C4C31263E8776F86657A8', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:53', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (133, '苦参汤', 19, 1, 10002, '20、$f{苦参汤} $m{1味} $u{苦参}$w{一升}\n	$s{以水一斗}，煎取七升，去滓，熏洗，日三服。', 3, '', '苦参', 600025544855621, '1445A93D67A08FC15B4371AA514F3AAE', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:53', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (134, '雄黄', 20, 1, 10002, '21、$f{雄黄} $m{1味} $u{雄黄}\n	$s{右一味为末}，筒瓦二枚合之，烧，向肛熏之。$a{$q{《脉经》}云：病人或从呼吸上蚀其咽，或从下焦蚀其肛阴，蚀上为惑，蚀下为狐，狐惑病者，$f{猪苓散}主之。}', 1, '', '雄黄', 600025545216069, 'E24A821F71B800DD0F9C18DD221B57C9', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:53', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (135, '赤豆当归散', 21, 2, 10002, '22、$f{赤豆当归散} $m{2味} $u{赤小豆}$w{三升，浸令芽出，曝干}，$u{当归}$w{三两}\n	$s{右二味}，杵为散，浆水服方寸匕，日三服。', 180, '', '赤小豆,当归', 600025545580613, '9ECD8C49101A9FB36F63EF06229729B8', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:53', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (136, '升麻鳖甲汤', 22, 6, 10002, '23、$f{升麻鳖甲汤} $m{6味} $u{升麻}$w{二两}，$u{当归}$w{一两}，$u{蜀椒}$w{炒去汗，一两}，$u{甘草}$w{二两}，$u{鳖甲}$w{手指大一片，炙}，$u{雄黄}$w{半两，研}\n	$s{右六味}，以水四升，煮取一升，顿服之。老少再服，取汗。$a{$q{《肘后》}、$q{《千金方》}：阳毒用升麻汤，无鳖甲，有桂；阴毒用甘草汤，无雄黄。}', 1, '', '升麻,当归,蜀椒,甘草,鳖甲,雄黄', 600025545977925, '424252E396E104C7E495F27C19653415', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:53', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (137, '鳖甲煎丸', 23, 25, 10002, '24、$f{鳖甲煎丸} $m{23味} $u{鳖甲}$w{十二分，炙}，$u{乌扇}$w{三分，烧}，$u{黄芩}$w{三分}，$u{柴胡}$w{六分}，$u{鼠妇}$w{三分，熬}，$u{干姜}$w{三分}，$u{大黄}$w{三分}，$u{芍药}$w{五分}，$u{桂枝}$w{三分}，$u{葶苈}$w{一分，熬}，$u{石苇}$w{三分，去毛}，$u{厚朴}$w{三分}，$u{牡丹}$w{五分，去心}，$u{瞿麦}$w{二分}，$u{紫葳}$w{三分}，$u{半夏}$w{一分}，$u{人参}$w{一分}，$u{䗪虫}$w{五分，熬}，$u{阿胶}$w{三分，炙}，$u{蜂窠}$w{四分，熬}，$u{赤硝}$w{十二分}，$u{蜣螂}$w{六分，熬}，$u{桃仁}$w{二分}\n	$s{右二十三味为末}，取$u{煅灶下灰}$w{一斗}，$u{清酒}$w{一斛五斗}，浸灰，候酒尽一半，着鳖甲于中，煮令泛烂如胶漆，绞取汁，内诸药，煎为丸，如梧子大。空心服七丸，日三服。$a{$q{《千金方》}鳖甲片十二片，又有海藻三分，大戟一分，䗪虫五分，无鼠妇、赤硝二味，以鳖甲和诸药为丸。}', 50, '', '鳖甲,乌扇,黄芩,柴胡,鼠妇,干姜,大黄,芍药,桂枝,葶苈,石苇,厚朴,牡丹,瞿麦,紫葳,半夏,人参,䗪虫,阿胶,蜂窠,赤硝,蜣螂,桃仁,煅灶下灰,清酒', 600025546408005, '97DB38246116AAD0CE9FBA8589E97D4B', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:53', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (138, '白虎加桂枝汤', 24, 5, 10002, '25、$f{白虎加桂枝汤} $m{5味} $u{知母}$w{六两}，$u{甘草}$w{二两，炙}，$u{石膏}$w{一斤}，$u{粳米}$w{二合}，$u{桂枝}$w{去皮，三两}\n	$s{右剉}，每五钱，水一盏半，煎至八分，去滓。温服，汗出愈。', 2, NULL, '桂枝,粳米,石膏,甘草,知母', 600025546850373, '7A239DBEEC640467B0A53E933783FF0F', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:53', 1, 'admin', '2025-03-06 17:22:14');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (139, '蜀漆散', 25, 3, 10002, '26、$f{蜀漆散} $m{3味} $u{蜀漆}$w{烧去腥}，$u{云母}$w{烧二日夜}，$u{龙骨}$w{等分}\n	$s{右三味}，杵为散，未发前，以浆水服半钱。温疟加$u{蜀漆}$w{半分}，临发时，服一钱匕。$a{一方云母作云实。}', 1, '', '蜀漆,云母,龙骨', 600025547259973, '7F8F806C9F7716625F12A7797C8A0143', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:53', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (140, '牡蛎汤', 26, 4, 10002, '27、$q{附《外台秘要》}$f{牡蛎汤} $m{4味} 治牡疟。\n	$u{牡蛎}$w{四两，熬}，$u{麻黄}$w{四两，去节}，$u{甘草}$w{二两}，$u{蜀漆}$w{三两}\n	$s{右四味}，以水八升，先煮蜀漆、麻黄，去上沫，得六升，内诸药，煮取二升，温服一升。若吐，则勿更服。', 2, '', '牡蛎,麻黄,甘草,蜀漆', 600025547698245, 'E8B227A3A551C49B3EE1CA92B0051CDE', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:53', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (141, '柴胡去半夏加栝楼汤', 27, 7, 10002, '28、$q{附《外台秘要》}$f{柴胡去半夏加栝楼汤} $m{7味} 治疟病发渴者，亦治劳疟。\n	$u{柴胡}$w{八两}，$u{人参}，$u{黄芩}，$u{甘草}$w{各三两}，$u{栝楼根}$w{四两}，$u{生姜}$w{二两}，$u{大枣}$w{十二枚}\n	$s{右七味}，以水一斗二升，煮取六升，去滓，再煎取三升。温服一升，日二服。', 3, '', '柴胡,人参,黄芩,甘草,栝楼根,生姜,大枣', 600025548132421, 'F25B4DCF56DFE7DA4B30BE332E930D73', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:54', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (142, '柴胡桂枝干姜汤', 28, 7, 10002, '29、$q{附《外台秘要》}$f{柴胡桂枝干姜汤} $m{7味} 治疟寒多，微有热，或但寒不热。\n	$u{柴胡}$w{半斤}，$u{桂枝}$w{三两，去皮}，$u{干姜}$w{二两}，$u{栝楼根}$w{四两}，$u{黄芩}$w{三两}，$u{牡蛎}$w{三两，熬}，$u{甘草}$w{二两，炙}\n	$s{右七味}，以水一斗二升，煮取六升，去滓，再煎取三升。温服一升，日三服。初服微烦，复服汗出便愈。', 3, '', '柴胡,桂枝,干姜,栝楼根,黄芩,牡蛎,甘草', 600025548582981, '8DE0D13FFCDB624BED5694B57A40CF53', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:54', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (143, '侯氏黑散', 29, 15, 10002, '30、$f{侯氏黑散} $m{14味} 治大风，四肢烦重，心中恶寒不足者。$q{《外台》}治风癫。\n	$u{菊花}$w{四十分}，$u{白术}$w{十分}，$u{细辛}$w{三分}，$u{茯苓}$w{三分}，$u{牡蛎}$w{三分}，$u{桔梗}$w{八分}，$u{防风}$w{十分}，$u{人参}$w{三分}，$u{矾石}$w{三分}，$u{黄芩}$w{五分}，$u{当归}$w{三分}，$u{干姜}$w{三分}，$u{芎䓖}$w{三分}，$u{桂枝}$w{三分}。\n	$s{上十四味}，杵为散，$u{酒}服方寸匕，日一服。初服二十日，温酒调服，禁一切鱼、肉、大蒜，常宜冷食，六十日止，即药积在腹中不下也，热食即下矣，冷食自能助药力。', 60, '', '菊花,白术,细辛,茯苓,牡蛎,桔梗,防风,人参,矾石,黄芩,当归,干姜,芎䓖,桂枝,酒', 600025548963909, 'B1FDE518A6029727C0FDD05AB3F399A3', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:54', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (144, '风引汤', 30, 12, 10002, '31、$f{风引汤} $m{12味} 除热瘫癎。\n	$u{大黄}，$u{干姜}，$u{龙骨}$w{各四两}，$u{桂枝}$w{三两}，$u{甘草}，$u{牡蛎}$w{各二两}，$u{寒水石}，$u{滑石}，$u{赤石脂}，$u{白石脂}，$u{紫石英}，$u{石膏}$w{各六两}。\n	$s{上十二味}，杵，粗筛，以韦囊盛之。取三指撮，井花水三升，煮三沸，温服一升。$a{治打人风引，少小惊痫瘈疭，日数十发，医所不能疗，除热方。巢氏云：脚气宜风引汤。}', 60, '', '大黄,干姜,龙骨,桂枝,甘草,牡蛎,寒水石,滑石,赤石脂,白石脂,紫石英,石膏', 600025549422661, '67C01FA1E20D6E9EC837C5660EB9D753', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:54', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (145, '防己地黄汤', 31, 6, 10002, '32、$f{防己地黄汤} $m{5味} 治病如狂状，妄行，独语不休，无寒热，其脉浮。\n	$u{防己}$w{一分}，$u{桂枝}$w{三分}，$u{防风}$w{三分}，$u{甘草}$w{一分}。\n	$s{上四味}，以$u{酒}$w{一杯}，渍之一宿，绞取汁。$u{生地黄}$w{二斤}，㕮咀，蒸之如斗米饭久，以铜器盛其汁，更绞地黄汁，和分再服。', 2, '', '防己,桂枝,防风,甘草,酒,生地黄', 600025549914181, '86A58A863BE6F143BFA60357123F6D86', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:54', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (146, '头风摩散方', 32, 2, 10002, '33、$f{头风摩散方} $m{2味} $u{大附子}$w{一枚，炮}，$u{盐}$w{等分}\n	$s{上二味}，为散，沐了，以方寸匕，已摩疢上，令药力行。', 10, '', '大附子,盐', 600025550360645, 'E6D5431FA041836F01D34069C544B798', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:54', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (147, '桂枝芍药知母汤', 33, 9, 10002, '34、$f{桂枝芍药知母汤} $m{9味} $u{桂枝}$w{四两}，$u{芍药}$w{三两}，$u{甘草}$w{二两}，$u{麻黄}$w{二两}，$u{生姜}$w{五两}，$u{白术}$w{五两}，$u{知母}$w{四两}，$u{防风}$w{四两}，$u{附子}$w{二枚，炮}\n	$s{右九味}，以水七升，煮取二升，温服七合，日三服。', 3, '', '桂枝,芍药,甘草,麻黄,生姜,白术,知母,防风,附子', 600025550786629, 'F65DA5B6CD0636E60D9731B8E8E11998', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:54', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (148, '乌头汤', 34, 6, 10002, '35、$f{乌头汤} $m{5味} 治脚气疼痛，不可屈伸。\n	$u{麻黄}，$u{芍药}，$u{黄芪}$w{各三两}，$u{甘草}$w{三两，炙}，$u{川乌}$w{五枚，㕮咀，以$u{蜜}二升，煎取一升，即出乌头}\n	$s{右五味}，㕮咀四味，以水三升，煮取一升，去滓，内$u{蜜}煎中，更煎之。服七合，不知，尽服之。', 3, '', '麻黄,芍药,黄芪,甘草,川乌,蜜', 600025551220805, 'B75180B06147BF287C594433F078C656', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:54', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (149, '矾石汤', 35, 1, 10002, '36、$f{矾石汤} $m{1味} 治脚气冲心\n	$u{矾石}\n	$s{上一味}，以浆水一斗五升，煎三、五沸，浸脚良。', 1, '', '矾石', 600025551663173, 'A39F6CD1C27C517FCFE253C97BECDE40', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:54', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (150, '续命汤', 36, 9, 10002, '37、$q{附方《古今录验》}$f{续命汤} $m{9味} 治中风痱，身体不能自收，口不能言，冒昧不知痛处，或拘急不得转侧。\n	$u{麻黄}，$u{桂枝}，$u{当归}，$u{人参}，$u{石膏}，$u{干姜}，$u{甘草}$w{各三两}，$u{芎䓖}$w{一两}，$u{杏仁}$w{四十枚}\n	$s{右九味}，以水一斗，煮取四升，温服一升，当小汗，薄覆脊，凭几坐，汗出则愈。不汗更服，无所禁，勿当风。并治但伏不得卧，咳逆上气，面目浮肿。', 4, '', '麻黄,桂枝,当归,人参,石膏,干姜,甘草,芎䓖,杏仁', 600025552072773, 'B519527F75CBBD62028A0BBDC6655F91', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:54', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (151, '三黄汤', 37, 11, 10002, '38、$q{《千金》}$f{三黄汤} $m{5味} 治中风手足拘急，百节疼痛，烦热心乱，恶寒，经日不欲饮食。\n	$u{麻黄}$w{五分}，$u{独活}$w{四分}，$u{细辛}$w{二分}，$u{黄芪}$w{二分}，$u{黄芩}$w{三分}\n	$s{右五味}，以水六升，煮取二升。分温三服，一服小汗，二服大汗。心热加$u{大黄}$w{二分}，腹满加$u{枳实}$w{一枚}，气逆加$u{人参}$w{三分}，悸加$u{牡蛎}$w{三分}，渴加$u{栝楼根}$w{三分}，先有寒加$u{附子}$w{一枚}。', 3, '', '麻黄,独活,细辛,黄芪,黄芩,大黄,枳实,人参,牡蛎,栝楼根,附子', 600025552482373, '866E10CF496D000D42CD37DB575126C2', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:54', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (152, '术附子汤', 38, 3, 10002, '39、$q{《近效方》}$f{术附子汤} $m{3味} 治风虚头重眩，苦极，不知食味，暖肌补中，益精气。\n	$u{白术}$w{二两}，$u{附子}$w{一枚半，炮，去皮}，$u{甘草}$w{一两，炙}\n	$s{右三味}，剉，每五钱匕，$u{姜}$w{五片}，$u{枣}$w{一枚}，水盏半，煎七分，去滓，温服。', 3, '', '白术,附子,甘草', 600025552916549, 'AD143EF5B112D028A1AF9938CAAF4E0A', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:54', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (153, '八味丸', 39, 10, 10002, '40、$q{崔氏}$f{八味丸} $m{8味} 治脚气上入，少腹不仁。\n	$u{干地黄}$w{八两}，$u{山茱萸}，$u{薯蓣}$w{各四两}，$u{泽泻}，$u{茯苓}，$u{牡丹皮}$w{各三两}，$u{桂枝}，$u{附子}$w{炮，各一两}\n	$s{右八味}，末之，炼$u{蜜}和丸梧子大。$u{酒}下十五丸，日再服。', 20, '', '干地黄,山茱萸,薯蓣,泽泻,茯苓,牡丹皮,桂枝,附子,蜜,酒', 600025553350725, 'A10CF1DE3C93A4D195EBD3393A4E7CE9', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:54', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (154, '越婢加术汤', 40, 6, 10002, '41、$q{《千金方》}$f{越婢加术汤} $m{6味} 治肉极热，则身体津脱，腠理开，汗大泄，厉风气，下焦脚弱。\n	$u{麻黄}$w{六两}，$u{石膏}$w{半斤}，$u{生姜}$w{三两}，$u{甘草}$w{二两}，$u{白术}$w{四两}，$u{大枣}$w{十五枚}\n	$s{右六味}，以水六升，先煮麻黄，去上沫，内诸药，煮取三升，分温三服。恶风加$u{附子}$w{一枚，炮}。', 3, '', '麻黄,石膏,生姜,甘草,白术,大枣,附子', 600025553752133, 'D507388D09C38115717EF570A5AD87F1', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:55', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (155, '黄芪桂枝五物汤', 41, 5, 10002, '42、$f{黄芪桂枝五物汤} $m{5味} $u{黄芪}$w{三两}，$u{芍药}$w{三两}，$u{桂枝}$w{三两}，$u{生姜}$w{六两}，$u{大枣}$w{十二枚}\n	$s{右五味}，以水六升，煮取二升。温服七合，日三服。$a{一方有人参}', 3, '', '黄芪,芍药,桂枝,生姜,大枣', 600025554186309, '68BC21D5A5E926D4962DF376A13ADF95', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:55', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (156, '桂枝加龙骨牡蛎汤', 42, 7, 10002, '43、$f{桂枝加龙骨牡蛎汤} $m{7味} $a{《小品》云：虚弱浮热汗出者，除桂，加白薇、附子各三分，故曰二加龙骨汤。}\n	$u{桂枝}，$u{芍药}，$u{生姜}$w{各三两}，$u{甘草}$w{二两}，$u{大枣}$w{十二枚}，$u{龙骨}，$u{牡蛎}$w{各三两}\n	$s{右七味}，以水七升，煮取三升，分温三服。', 3, '', '桂枝,芍药,生姜,甘草,大枣,龙骨,牡蛎', 600025554600005, '051696449ED52E71AB173EE723D1B7BB', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:55', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (157, '天雄散', 43, 5, 10002, '44、$f{天雄散} $m{4味} $u{天雄}$w{三两，炮}，$u{白术}$w{八两}，$u{桂枝}$w{六两}，$u{龙骨}$w{三两}\n	$s{右四味}，杵为散，$u{酒}服半钱匕，日三服，不知，稍增之。', 60, '', '天雄,白术,桂枝,龙骨,酒', 600025555017797, '0BC8DCD2A8A052C0F0E36FD794CDDDD7', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:55', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (158, '小建中汤', 44, 6, 10002, '45、$f{小建中汤} $m{6味} $u{桂枝}$w{三两，去皮}，$u{甘草}$w{三两，炙}，$u{大枣}$w{十二枚}，$u{芍药}$w{六两}，$u{生姜}$w{二两}，$u{胶饴}$w{一升}\n	$s{右六味}，以水七升，煮取三升，去滓，内胶饴，更上微火消解。温服一升，日三服。$a{呕家，不可用小建中汤，以甜故也。}', 3, '', '桂枝,甘草,大枣,芍药,生姜,胶饴', 600025555431493, '8ED9B4CFF9EC67B167401676724AF7A6', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:55', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (159, '黄芪建中汤', 45, 7, 10002, '46、$f{黄芪建中汤} $m{7味} $u{桂枝}$w{三两，去皮}，$u{甘草}$w{三两，炙}，$u{大枣}$w{十二枚}，$u{芍药}$w{六两}，$u{生姜}$w{二两}，$u{胶饴}$w{一升}，$u{黄芪}$w{一两半}。\n	$s{上七味}，以水七升，煮取三升，去滓，内胶饴，更上微火消解。温服一升，日三服。气短胸满者，加$u{生姜}；腹满者，去$u{枣}加$u{茯苓}$w{一两半}。及疗肺虚损不足，补气，加$u{半夏}$w{三两}。', 3, '', '桂枝,甘草,大枣,芍药,生姜,胶饴,黄芪,茯苓,半夏', 600025555890245, 'B63C6551C2F04249AD02CF1B809B7FD6', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:55', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (160, '薯蓣丸', 46, 23, 10002, '47、$f{薯蓣丸} $m{21味} $u{薯蓣}$w{三十分}，$u{当归}，$u{桂枝}，$u{曲}，$u{干地黄}，$u{豆黄卷}$w{各十分}，$u{甘草}$w{二十八分}，$u{人参}$w{七分}，$u{芎䓖}，$u{芍药}，$u{白术}，$u{麦门冬}，$u{杏仁}$w{各六分}，$u{柴胡}，$u{桔梗}，$u{茯苓}$w{各五分}，$u{阿胶}$w{七分}，$u{干姜}$w{三分}，$u{白敛}$w{二分}，$u{防风}$w{六分}，$u{大枣}$w{百枚，为膏}\n	$s{右二十一味}，末之，炼$u{蜜}和丸，如弹子大。空腹$u{酒}服一丸，一百丸为剂。', 100, '', '薯蓣,当归,桂枝,曲,干地黄,豆黄卷,甘草,人参,芎䓖,芍药,白术,麦门冬,杏仁,柴胡,桔梗,茯苓,阿胶,干姜,白敛,防风,大枣,蜜,酒', 600025556344901, '6619981BF6EE85E1D0EE50064E1F1DAB', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:55', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (161, '酸枣仁汤', 47, 5, 10002, '48、$f{酸枣仁汤} $m{5味} $u{酸枣仁}$w{二升}，$u{甘草}$w{一两}，$u{知母}$w{二两}，$u{茯苓}$w{二两}，$u{芎䓖}$w{二两} $a{深师有生姜二两。}\n	$s{右五味}，以水八升，煮酸枣仁，得六升，内诸药，煮取三升，分温三服。', 3, '', '酸枣仁,甘草,知母,茯苓,芎䓖', 600025556824133, 'B8B5CB4FBCAD492E1AD7CB2114345F75', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:55', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (162, '大黄䗪虫丸', 48, 14, 10002, '49、$f{大黄䗪虫丸} $m{12味} $u{大黄}$w{十分，蒸}，$u{黄芩}$w{二两}，$u{甘草}$w{三两}，$u{桃仁}$w{一升}，$u{杏仁}$w{一升}，$u{芍药}$w{四两}，$u{干地黄}$w{十两}，$u{干漆}$w{一两}，$u{虻虫}$w{一升}，$u{水蛭}$w{百枚}，$u{蛴螬}$w{一升}，$u{䗪虫}$w{半升}。\n	$s{右十二味}，末之，炼$u{蜜}和丸小豆大。$u{酒}饮服五丸，日三服。', 100, '', '大黄,黄芩,甘草,桃仁,杏仁,芍药,干地黄,干漆,虻虫,水蛭,蛴螬,䗪虫,蜜,酒', 600025557258309, 'B3FD272DE3B0BACCA0AF5A5DFC1ADFCF', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:55', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (163, '炙甘草汤', 49, 10, 10002, '50、$q{附方《千金翼》}$f{炙甘草汤} $m{9味} $a{一云复脉汤。}治虚劳不足，汗出而闷，脉结悸，行动如常，不出百日，危急者，十一日死。另有$q{《外台》}炙甘草汤，治肺痿涎唾多，心中温温液液者。\n	$u{甘草}$w{四两，炙}，$u{桂枝}，$u{生姜}$w{各三两}，$u{麦门冬}$w{半升}，$u{麻子仁}$w{半升}，$u{人参}，$u{阿胶}$w{各二两}，$u{大枣}$w{三十枚}，$u{生地黄}$w{一斤}\n	$s{右九味}，以$u{酒}七升，水八升，先煮八味，取三升，去滓，内胶消尽。温服一升，日三服。', 3, '', '甘草,桂枝,生姜,麦门冬,麻子仁,人参,阿胶,大枣,生地黄,酒', 600025557717061, '111C3E69B74BC2F11431DB59B9FBAF68', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:55', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (164, '獭肝散', 50, 1, 10002, '51、$q{《肘后》}$f{獭肝散} $m{1味} 治冷劳，又主鬼疰一门相染。\n	$u{獭肝}$w{一具}，炙干，末之。水服方寸匕，日三服。', 10, '', '獭肝', 600025558106181, 'F402B55ED5BBA6A969655E7379342523', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:55', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (165, '甘草干姜汤', 51, 2, 10002, '52、$f{甘草干姜汤} $m{2味} $u{甘草}$w{四两，炙}，$u{干姜}$w{二两，炮}\n	$s{右㕮咀}，以水三升，煮取一升五合，去滓，分温再服。', 2, '', '甘草,干姜', 600025558491205, '38D41C7D5A4FBF9439B355E41C531422', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:55', NULL, NULL, NULL);
