INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (168, '厚朴麻黄汤', 54, 9, 10002, '55、$f{厚朴麻黄汤} $m{9味} $u{厚朴}$w{五两}，$u{麻黄}$w{四两}，$u{石膏}$w{如鸡子大}，$u{杏仁}$w{半升}，$u{半夏}$w{半升}，$u{干姜}$w{二两}，$u{细辛}$w{二两}，$u{小麦}$w{一升}，$u{五味子}$w{半升}\n	$s{右九味}，以水一斗二升，先煮小麦熟，去滓，内诸药，煮取三升。温服一升，日三服。', 3, '', '厚朴,麻黄,石膏,杏仁,半夏,干姜,细辛,小麦,五味子', 600025559765061, '21C1D49422BDDD58300E4030283720AE', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:56', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (169, '泽漆汤', 55, 9, 10002, '56、$f{泽漆汤} $m{9味} $u{半夏}$w{半升}，$u{紫参}$w{五两。一作紫菀}，$u{泽漆}$w{三斤，以东流水五斗，煮取一斗五升}，$u{生姜}$w{五两}，$u{白前}$w{五两}，$u{甘草}，$u{黄芩}，$u{人参}，$u{桂枝}$w{各三两}\n	$s{右九味}，㕮咀，内泽漆汁中，煮取五升。温服五合，至夜尽。', 10, '', '半夏,紫参,泽漆,生姜,白前,甘草,黄芩,人参,桂枝', 600025560166469, '9A5F477CC4AD910DB6560D23FE7E0DDF', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:56', NULL, NULL, NULL);
