INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (171, '葶苈大枣泻肺汤', 57, 2, 10002, '58、$f{葶苈大枣泻肺汤} $m{2味} $u{葶苈}$w{熬令黄色，捣丸如弹丸大}，$u{大枣}$w{十二枚}\n	$s{右先以水三升}，煮枣取二升，去枣，内葶苈，煮取一升，顿服。', 1, '', '葶苈,大枣', 600025560948805, 'D6E0BC76AB3C12B04DBD4A78CB60A803', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:56', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (172, '桔梗汤', 58, 2, 10002, '59、$f{桔梗汤} $m{2味} $a{亦治血痹。}\n	$u{桔梗}$w{一两}，$u{甘草}$w{二两}\n	$s{右二味}，以水三升，煮取一升。分温再服，则吐脓血也。', 2, '', '桔梗,甘草', 600025561317445, '067EA717A2440CB9EF1F3FC0BF7B1A20', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:56', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (173, '越婢加半夏汤', 59, 6, 10002, '60、$f{越婢加半夏汤} $m{6味} $u{麻黄}$w{六两}，$u{石膏}$w{半斤}，$u{生姜}$w{三两}，$u{大枣}$w{十五枚}，$u{甘草}$w{二两}，$u{半夏}$w{半升}\n	$s{右六味}，以水六升，先煮麻黄，去上沫，内诸药，煮取三升，分温三服。', 3, '', '麻黄,石膏,生姜,大枣,甘草,半夏', 600025561694277, 'FC746141AEE5A63C552DB59D260FA5D8', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:56', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (174, '小青龙加石膏汤', 60, 9, 10002, '61、$f{小青龙加石膏汤} $m{9味} $q{《千金》}$a{证治同，外更加胁下痛引缺盆。}\n	$u{麻黄}，$u{芍药}，$u{桂枝}，$u{细辛}，$u{甘草}，$u{干姜}$w{各三两}，$u{五味子}，$u{半夏}$w{各半升}，$u{石膏}$w{二两}\n	$s{右九味}，以水一斗，先煮麻黄，去上沫，内诸药，煮取三升。强人服一升，羸者减之，日三服，小儿服四合。', 3, '', '麻黄,芍药,桂枝,细辛,甘草,干姜,五味子,半夏,石膏', 600025562050629, 'B95D568C7B123997FA110764738BC531', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:56', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (175, '甘草汤', 61, 1, 10002, '62、$q{《千金》}$f{甘草汤} $m{1味} $a{此方本出于$q{《肘后》}而$q{《千金》}主疗，与$q{《外台》}炙甘草汤同，但唾多下，有出血二字。}\n	$u{甘草}$w{诸本缺铢两，$q{《肘后》}，$q{《千金》}用$w{二两}。}\n	$s{右一味}，以水三升，煮减半，分温三服。', 3, '', '甘草', 600025562402885, '096321413E7AF307CAB1F1F87F4952C6', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:56', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (176, '生姜甘草汤', 62, 4, 10002, '63、$q{《千金》}$f{生姜甘草汤} $m{4味} 治肺痿咳唾涎沫不止，咽燥而渴。\n	$u{生姜}$w{五两}，$u{人参}$w{二两}，$u{甘草}$w{四两}，$u{大枣}$w{十五枚}\n	$s{右四味}，以水七升，煮取三升，分温三服。', 3, '', '生姜,人参,甘草,大枣', 600025562742853, '90117202BDD9CAC67C3609A5BC012334', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:56', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (177, '桂枝去芍药加皂荚汤', 63, 5, 10002, '64、$q{《千金》}$f{桂枝去芍药加皂荚汤} $m{5味} 治肺痿吐涎沫。\n	$u{桂枝}，$u{生姜}$w{各三两}，$u{甘草}$w{二两}，$u{大枣}$w{十枚}，$u{皂荚}$w{一枚，去皮子，炙焦}\n	$s{右五味}，以水七升，微微火煮取三升，分温三服。', 3, '', '桂枝,生姜,甘草,大枣,皂荚', 600025563111493, '2B469E5651278AD4D5F01E2B25E5E5D5', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:56', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (178, '桔梗白散', 64, 3, 10002, '65、$q{《外台》}$f{桔梗白散} $m{3味} 治咳而胸满，振寒，脉数，咽干不渴，时出浊唾腥臭，久久吐脓如米粥者，为肺痈。\n	$u{桔梗}，$u{贝母}$w{各三分}，$u{巴豆}$w{一分，去皮，熬，研如脂}\n	$s{右三味}，为散，强人饮服半钱匕，羸者减之。病在膈上者吐脓血，膈下者泻出。若下多不止，饮冷水一杯则定。', 10, '', '桔梗,贝母,巴豆', 600025563476037, 'A2B5B9A35A04A73DE85DBA07ED2C38D3', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:56', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (179, '苇茎汤', 65, 4, 10002, '66、$q{《千金》}$f{苇茎汤} $m{4味} 治咳有微热烦满，胸中甲错，是为肺痈。\n	$u{苇茎}$w{二升}，$u{薏苡仁}$w{半升}，$u{桃仁}$w{五十枚}，$u{瓜瓣}$w{半升}\n	$s{右四味}，以水一斗，先煮苇茎得五升，去滓，内诸药，煮取二升。服一升，再服，当吐如脓。', 2, '', '苇茎,薏苡仁,桃仁,瓜瓣', 600025563840581, 'C7623F9B12DF9F1C41A52B5937449961', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:56', NULL, NULL, NULL);
