INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (188, '橘枳姜汤', 74, 3, 10002, '75、$f{橘枳姜汤} $m{3味} $u{橘皮}$w{一斤}，$u{枳实}$w{三两}，$u{生姜}$w{半斤}\n	$s{右三味}，以水五升，煮取二升，分温再服。$a{$q{《肘后》}、$q{《千金》}云：治胸痹，胸中愊愊如满，噎塞习习如痒，喉中涩燥，唾沫}', 2, '', '橘皮,枳实,生姜', 600025567121477, '3136EF624EABEE10161F669C0544DD83', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:57', NULL, NULL, NULL);
