INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (191, '乌头赤石脂丸', 77, 6, 10002, '78、$f{乌头赤石脂丸} $m{5味} $u{蜀椒}$w{一两。一法二分}，$u{乌头}$w{一分，炮}，$u{附子}$w{半两，炮。一法一分}，$u{干姜}$w{一两。一法一分}，$u{赤石脂}$w{一两。一法二分}\n	$s{右五味}，末之，$u{蜜}丸如梧子大。先食服一丸，日三服。不知，稍加服。', 100, '', '蜀椒,乌头,附子,干姜,赤石脂,蜜', 600025568358469, '7A396D140E57D1E3768AEF039AF9D626', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:57', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (192, '九痛丸', 78, 8, 10002, '79、$f{九痛丸} $m{6味} 治九种心痛。\n	$u{附子}$w{三两，炮}，$u{生狼牙}$w{一两，炙香}，$u{巴豆}$w{一两，去皮心，熬，研如脂}，$u{人参}，$u{干姜}，$u{吴茱萸}$w{各一两}。\n	$s{上六味}，末之，炼$u{蜜}丸如梧子大，$u{酒}下。强人初服三丸，日三服；弱者，二丸。兼治卒中恶，腹胀痛，口不能言。又治连年积冷，流注，心胸痛并冷冲上气，落马、坠车、血疾等皆主之。忌口如常法。', 50, '', '附子,生狼牙,巴豆,人参,干姜,吴茱萸,蜜,酒', 600025568763973, 'A981BF9E54DF11784228ACFEC9B3115E', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:57', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (193, '厚朴七物汤', 79, 7, 10002, '80、$f{厚朴七物汤} $m{7味} $u{厚朴}$w{半斤}，$u{甘草}，$u{大黄}$w{各三两}，$u{大枣}$w{十枚}，$u{枳实}$w{五枚}，$u{桂枝}$w{二两}，$u{生姜}$w{五两}\n	$s{右七味}，以水一斗，煮取四升，温服八合，日三服。呕者，加$u{半夏}$w{五合}，下利去$u{大黄}；寒多者，加$u{生姜}$w{至半斤}。', 5, '', '厚朴,甘草,大黄,大枣,枳实,桂枝,生姜,半夏', 600025569169477, '9AD65D78F8B59E3122780459B451AD6D', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:57', NULL, NULL, NULL);
