INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (197, '大建中汤', 83, 4, 10002, '84、$f{大建中汤} $m{4味} $u{蜀椒}$w{二合，去汗}，$u{干姜}$w{四两}，$u{人参}$w{二两}，$u{胶饴}$w{一升}\n	$s{右三味}，以水四升，煮取二升，去滓，内胶饴一升，微火煎取一升半。分温再服，如一炊顷，可饮粥二升，后更服，当一日食糜，温覆之。', 2, '', '蜀椒,干姜,人参,胶饴', 600025570910277, '4D6AAA45D600344703DBE2C71CD83154', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:58', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (198, '大黄附子汤', 84, 3, 10002, '85、$f{大黄附子汤} $m{3味} $u{大黄}$w{三两}，$u{附子}$w{三枚，炮}，$u{细辛}$w{二两}\n	$s{右三味}，以水五升，煮取二升，分温三服。若强人煮二升半，分温三服。服后如人行四五里，进一服。', 3, '', '大黄,附子,细辛', 600025571348549, '590B3C312A505892A209FDA7D772CF59', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:58', NULL, NULL, NULL);
