INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (200, '大乌头煎', 86, 1, 10002, '87、$f{大乌头煎} $m{1味} $u{乌头}$w{大者五枚，熬，去皮，不㕮咀}\n	$s{右以水三升}，煮取一升，去滓，内$u{蜜}二升，煎令水气尽，取二升。强人服七合，弱人服五合。不差，明日更服，不可一日再服。', 3, '', '乌头,蜜', 600025572245573, '07076533A02496935D318A7DB3B7FEB5', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:58', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (201, '当归生姜羊肉汤', 87, 5, 10002, '88、$f{当归生姜羊肉汤} $m{3味} $u{当归}$w{三两}，$u{生姜}$w{五两}，$u{羊肉}$w{一斤}\n	$s{右三味}，以水八升，煮取三升，温服七合，日三服。若寒多者，加$u{生姜}$w{成一斤}；痛多而呕者，加$u{橘皮}$w{二两}、$u{白术}$w{一两}。加生姜者，亦加水五升，煮取三升二合，服之。', 4, '', '当归,生姜,羊肉,橘皮,白术', 600025572614213, 'F9D0A79F7DC505B2531AA120248F7400', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:58', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (202, '乌头桂枝汤', 88, 6, 10002, '89、$f{乌头桂枝汤} $m{1味} $u{乌头}\n	$s{右一味}，以$u{蜜}$w{二斤}，煎减半，去滓，以$f{桂枝汤}$w{五合}解之，得一升后，初服二合；不知，即取三合；又不知，复加至五合。其知者，如醉状，得吐者，为中病。', 5, '', '乌头,蜜,桂枝,芍药,甘草,生姜,大枣', 600025572982853, 'A05B5682FED43997B16DCB4BF8AD4321', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:58', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (203, '桂枝汤', 89, 5, 10002, '90、$f{桂枝汤} $m{5味} $u{桂枝}$w{三两，去皮}，$u{芍药}$w{三两}，$u{甘草}$w{二两，炙}，$u{生姜}$w{三两}，$u{大枣}$w{十二枚}\n	$s{右五味}，剉，以水七升，微火煮取三升，去滓。', 3, '', '桂枝,芍药,甘草,生姜,大枣', 600025573351493, 'E2BB37FD0E0A3172E657DA89BB7D9F40', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:58', 1, '超级管理员', '2024-10-22 19:04:20');
