INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (205, '走马汤', 91, 2, 10002, '92、$q{《外台》}$f{走马汤} $m{2味} 治中恶心痛腹胀，大便不通。\n	$u{巴豆}$w{二枚，去皮心，熬}，$u{杏仁}$w{二枚}\n	$s{右二味}，以绵缠，搥令碎，热汤二合，捻取白汁饮之，当下。老小量之。通治飞尸、鬼击病。', 1, '', '巴豆,杏仁', 600025574121541, 'E02F72C3CF050D0F56F3E030B08C91AA', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 08:59:58', NULL, NULL, NULL);
