INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (287, '乌梅丸', 173, 12, 10002, '174、$f{乌梅丸} $m{10味} $u{乌梅}$w{三百个}，$u{细辛}$w{六两}，$u{干姜}$w{十两}，$u{黄连}$w{一斤}，$u{当归}$w{四两}，$u{附子}$w{六两，炮}，$u{川椒}$w{四两，去汗}，$u{桂枝}$w{六两}，$u{人参}$w{六两}，$u{黄柏}$w{六两}\n	$s{右十味}，异捣筛，合治之，以$u{苦酒}渍乌梅一宿，去核，蒸之五升米下，饭熟，捣成泥，和药令相得，内臼中，与$u{蜜}杵二千下，丸如梧子大。先食，饮服十丸，三服，稍加至二十丸。禁生冷滑臭等食。', 30, '', '乌梅,细辛,干姜,黄连,当归,附子,川椒,桂枝,人参,黄柏,苦酒,蜜', 600025608458309, '776F9742DB8F4808C2A65228340DF075', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 09:00:04', NULL, NULL, NULL);
