INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (289, '芎归胶艾汤', 175, 9, 10002, '176、$f{芎归胶艾汤} $m{7味} $a{一方加$u{干姜}$w{一两}。胡氏治妇人胞动，无干姜。}\n	$u{芎䓖}，$u{阿胶}，$u{甘草}$w{各二两}，$u{艾叶}，$u{当归}$w{各三两}，$u{芍药}$w{四两}，$u{干地黄}$w{四两}\n	$s{右七味}，以水五升，$u{清酒}$w{三升}，合煮，取三升，去滓，内胶，令消尽。温服一升，日三服，不差更作。', 3, '', '干姜,芎䓖,阿胶,甘草,艾叶,当归,芍药,干地黄,清酒', 600025609482309, '51BBFFAA36B718129C0C7E28B6B8B4BA', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 09:00:04', NULL, NULL, NULL);
