INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (294, '当归散', 180, 6, 10002, '181、$f{当归散} $m{5味} $u{当归}，$u{黄芩}，$u{芍药}，$u{芎䓖}$w{各一斤}，$u{白术}$w{半斤}\n	$s{右五味}，杵为散，$u{酒}饮服方寸匕，日再服。妊娠常服即易产，胎无疾苦。产后百病悉主之。', 300, '', '当归,黄芩,芍药,芎䓖,白术,酒', 600025611632709, '45FC64672E781ED6DFE2078826A5007B', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 09:00:05', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (295, '白术散', 181, 4, 10002, '182、$f{白术散} $m{4味} $u{白术}$w{四分}，$u{芎䓖}$w{四分}，$u{蜀椒}$w{三分，去汗}，$u{牡蛎}$w{二分}\n	$s{右四味}，杵为散，$u{酒}服一钱匕，日三服，夜一服。但苦痛，加$u{芍药}；心下毒痛，倍加$u{芎䓖}；心烦吐痛，不能食饮，加$u{细辛}$w{一两}、$u{半夏}$w{大者二十枚}。服之后，更以$u{醋浆水}服之。若呕，以醋浆水服之复不解者，$u{小麦汁}服之；已后渴者，$u{大麦粥}服之。病虽愈，服之勿置。', 15, '', '白术,芎䓖,蜀椒,牡蛎,酒,芍药,细辛,半夏,醋浆水,小麦汁,大麦粥', 600025612062789, '0334DFBE323A6BC57D2258C658B2A5F3', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 09:00:05', NULL, NULL, NULL);
