INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (297, '下瘀血汤', 183, 5, 10002, '184、$f{下瘀血汤} $m{3味} $u{大黄}$w{二两}，$u{桃仁}$w{二十枚}，$u{䗪虫}$w{二十枚，熬，去足}\n	$s{右三味}，末之，炼$u{蜜}和为四丸，以$u{酒}$w{一升}，煎一丸，取八合。顿服之，新血下如豚肝。', 4, '', '大黄,桃仁,䗪虫,蜜,酒', 600025612910661, '79245BC53F80F3B50F3F53063498C21F', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 09:00:05', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (298, '竹叶汤', 184, 11, 10002, '185、$f{竹叶汤} $m{10味} $u{竹叶}$w{一把}，$u{葛根}$w{三两}，$u{防风}，$u{桔梗}，$u{桂枝}，$u{人参}，$u{甘草}$w{各一两}，$u{附子}$w{一枚，炮}，$u{大枣}$w{十五枚}，$u{生姜}$w{五两}\n	$s{右十味}，以水一斗，煮取二升半，分温三服，温覆使汗出。颈项强，用$u{大附子}$w{一枚，破之如豆大}，煎药，扬去沫。呕者，加$u{半夏}$w{半升洗}。', 3, '', '竹叶,葛根,防风,桔梗,桂枝,人参,甘草,附子,大枣,生姜,半夏', 600025613344837, 'A69D4B44F293FF859B9EA55516B55D8E', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 09:00:05', NULL, NULL, NULL);
