INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (300, '白头翁加甘草阿胶汤', 186, 6, 10002, '187、$f{白头翁加甘草阿胶汤} $m{6味} $u{白头翁}$w{二两}，$u{黄连}，$u{柏皮}，$u{秦皮}$w{各三两}，$u{甘草}$w{二两}，$u{阿胶}$w{二两}\n	$s{右六味}，以水七升，煮取二升半，内胶，令消尽，分温三服。', 3, '', '白头翁,黄连,柏皮,秦皮,甘草,阿胶', 600025614159941, '30D6C3A9A5DA6EBD2C99CC577F9B6078', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 09:00:05', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (301, '三物黄芩汤', 187, 3, 10002, '188、$q{附方《千金》}$f{三物黄芩汤} $m{3味} 治妇人在草蓐，自发露得风。四肢苦烦热，头痛者，与$f{小柴胡汤}。头不痛但烦者，此汤主之。\n	$u{黄芩}$w{一两}，$u{苦参}$w{二两}，$u{干地黄}$w{四两}\n	$s{右三味}，以水八升，煮取二升。温服一升，多吐下虫。', 2, '', '黄芩,苦参,干地黄', 600025614585925, '75B151337E7695F61AB336CF829BA954', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 09:00:05', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (302, '当归建中汤', 188, 11, 10002, '189、$q{《千金》}内补$f{当归建中汤} $m{6味} 治妇人产后虚羸不足，腹中刺痛不止，吸吸少气，或苦少腹中急，摩痛引腰者，不能食饮。产后一月，日得四五剂为善，令人强壮，宜。\n	$u{当归}$w{四两}，$u{桂枝}$w{三两}，$u{芍药}$w{六两}，$u{生姜}$w{三两}，$u{甘草}$w{二两}，$u{大枣}$w{十二枚}\n	$s{右六味}，以水一斗，煮取三升。分温三服，一日令尽。若大虚，加$u{饴糖}$w{六两}，汤成，内之于火上暖，令饴消。若去血过多，崩伤内衄不止，加$u{地黄}$w{六两}、$u{阿胶}$w{二两}，合八味，汤成，内阿胶。若无当归，以$u{芎䓖}代之；若无生姜，以$u{干姜}代之。', 3, '', '当归,桂枝,芍药,生姜,甘草,大枣,饴糖,地黄,阿胶,芎䓖,干姜', 600025615016005, '92240DCF8D514E3A07D2D85D19EFB80A', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 09:00:05', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (303, '半夏厚朴汤', 189, 5, 10002, '190、$f{半夏厚朴汤} $m{5味} $a{$q{《千金》}作胸满，心下坚，咽中帖帖，如有炙肉，吐之不出，吞之不下。}\n	$u{半夏}$w{一升}，$u{厚朴}$w{三两}，$u{茯苓}$w{四两}，$u{生姜}$w{五两}，$u{干苏叶}$w{二两}\n	$s{右五味}，以水七升，煮取四升。分温四服，日三、夜一服。', 4, '', '半夏,厚朴,茯苓,生姜,干苏叶', 600025615446085, 'EEBFF35A4FFF3D755B140FE53D42F015', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 09:00:05', NULL, NULL, NULL);
