INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (314, '狼牙汤', 200, 1, 10002, '201、$f{狼牙汤} $m{1味} $u{狼牙}$w{三两}\n	$s{右一味}，以水四升，煮取半升，以绵缠筋如茧，浸汤沥阴中，日四遍。', 1, '', '狼牙', 600025620312133, '12CAAE74CBD5BAD209895626490C40C2', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 09:00:06', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (315, '小儿疳虫蚀齿', 201, 2, 10002, '202、$f{小儿疳虫蚀齿} $m{2味} $u{雄黄}，$u{葶苈}\n	$s{右二味}，末之，取腊月猪脂镕，以槐枝绵裹头四五枚，点药烙之。', 1, '', '雄黄,葶苈', 600025620725829, 'D641A4812D804CA1976D9D10050257A9', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-17 09:00:06', 1, '超级管理员', '2024-10-12 08:47:26');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (316, '桂枝汤', 202, 5, 9040000, ' $u{ 桂枝}$w{三两、去皮}   $u{芍药}$w{三两}   $u{甘草}$w{二两、炙}    $u{生姜}$w{三两、切}    $u{大枣}$w{十二枚、擘}  \n\n       $s{右五味}，㕮咀三味，以水七升，微火煮取三升，去滓，适寒温，服一升。服已须臾，啜热稀粥一升余，以助药力。温覆令一时许，遍身絷絷微似有汗者益佳。不可令如水流漓，病必不除。若一服汗出，病差，停后服，不必尽剂。若不汗，更服依前法。又不汗，服后小促其间，半日许，令三服尽。若病重者，一日一夜服，周时观之，服一剂尽，病证犹在者，更作服。若汗不出，乃服至二三剂。禁生冷、粘滑、肉面、五辛、酒酪、臭恶等物。  \n\n      用七碗水，用大火煮，古时候生柴火煮汤药，柴火的“微火”等于现在瓦斯炉的大火，煮成三碗渣拿掉，等温了再喝，一次服一碗。服了以后，等一下再喝热稀饭一碗，来帮忙药力。然后，被子盖起来，躺一时，差不多二个小时，全身微发汗。最好，把感冒病毒从汗排出来了，但是没有伤到体内的津液，这样最刚好。如果药开太重，一下子大汗出就不好了。汗出了以后，不能当风，也不能烤火，都不好。如果第一碗下去，好了就好了，不要把剩下的药喝掉。如果不流汗，再喝一碗，还不流汗，服后小促其间，就是缩短服的时间，就是三到四小时。  \n\n        半日许，令三服尽，十二小时喝三碗，若病重者，一日一夜服，周时观之，就是每四小时喝一次，日夜都服，服一剂尽，病证犹在者，更作服，再去煮，若汗不出，乃服至二三剂。喝桂枝汤中间禁生冷、粘滑、肉面、五辛、酒酪、臭恶等物，臭恶就是腌制的东西，臭豆腐等等，为什么要禁？桂枝汤是恢复胃阳、脾脏功能的药，就汤剂来看，桂枝壮心让动脉的血流出去，白芍让血流回心脏，所以心脏的力量加强，火生土，土就是脾脏，所以桂枝汤喝下去，脾就充满了血，脾在胃的下方，脾一充血，胃下面很多血管，一充血，胃就开始收缩，就肚子饿，想吃东西，所以桂枝汤是让胃口恢复的药。生冷、粘滑、肉面、五辛、酒酪、臭 恶等物，这些东西都是容易腐败的。吃了肉类，会有浮热产生，对病情恢复有影响；如果吃了生冷的东西，会抵消阳药发汗的效果，因此都要避免。喝完桂枝汤，为什么喝热稀饭？在中医的观念认为稀饭、白饭是最好的营养，肠胃最能吸收的是稀饭。平时吃蕃薯稀饭可以保护脾胃，蕃薯与稀饭各一半，对养生很好。  \n\n      桂枝汤最明显的表证就是有汗，代表皮肤毛孔没病的，是滤过性病毒在肌肉里面，因此桂枝汤是解肌的。如果滤过性病毒在皮肤毛孔，皮肤毛孔就封闭起来了，就会没有汗。  \n\n       红枣：朱雀，就是保护胃的，红枣的加减很重要，红枣是甘饴的东西，很甜，平常肚子（中焦）湿热比较盛的人。如果加了红枣会增甘加腻、遇到这种情形，把红枣拿掉。', 3, '', '桂枝,芍药,甘草,生姜,大枣', 613758796099653, '8825D9578D8BE169A72F2BFE5B0DBC9B', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-19 17:30:58', 1, '超级管理员', '2024-11-20 18:17:30');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (317, '桂枝加葛根汤', 203, 6, 9040000, ' $u{ 桂枝}$w{三两、去皮}    $u{ 芍药}$w{三两}    $u{ 生姜}$w{三两、切}   $u{ 甘草}$w{二两、炙}    $u{ 大枣}$w{十二枚、擘}    $u{ 葛根}$w{四两}  右六味，以水七升，内诸药，煮取三升，去滓，温服一升，不须啜粥，余如桂枝汤将息，及禁忌法。  \n\n         不需要喝稀饭，因为葛根发阳的力量很强，所以就不用稀饭来加强发汗。桂枝和芍药等量，葛根要加重，所以如果桂枝三钱，葛根就要用四钱，如果桂枝五钱，葛根用六钱。如果葛根用的比较轻，葛根就无法发到背部，就被桂枝芍药带到四肢上去了。如果要葛根到脸部就要重用，譬如面部中风、口歪眼邪、在对侧合谷下针先麻醉，再地仓透颊车，矫正后，针人中、承浆定位，再开桂枝加葛根汤给病人服用，如果桂枝三，葛根重用到六，吃下去，第二天全部回正，麻感会全去掉的。  \n\n        临床上，小孩子的感冒，常常都见到桂枝加葛根汤证，因为小孩子很皮、很好动，流汗很多的情况下吹到风，因为津液流失很多，所以也需要用到葛根。还有一种情形，体力劳动工作的人，冬天劳动的时候，汗出的同时伤于寒，到了来年夏至以前，发为温病，可能用到桂枝加葛根汤或是葛根汤。  \n\n       临床上，看到扁桃腺发炎，针灸用少商、商阳放血，扁桃腺点刺放血；配合列缺、照海。汤药可以用桂枝加葛根汤，加上连翘、银花、浮萍、蝉蜕，这里的葛根用到四钱就好。', 3, '', '葛根,大枣,生姜,甘草,芍药,桂枝', 614066128040005, 'CE5F5554E52F8B5E1F9F1C5F4B6C8A41', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-20 14:21:30', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (318, '桂枝加厚朴杏仁汤', 204, 7, 9040000, '$u{桂枝}$w{三两、去皮}    $u{甘草}$w{二两、炙}    $u{生姜}$w{三两、切}    $u{芍药}$w{三两}    $u{大枣}$w{十二枚、擘}    $u{厚朴}$w{二两、炙去皮}    $u{杏仁}$w{五十枚。去皮尖}\n	上七味。以水七升。微火煮取三升。去滓。温服一升。覆取微似汗。', 3, '', '桂枝,甘草,芍药,生姜,大枣,厚朴,杏仁', 614083487191109, 'AAFC53BA3008D00D93471985C8D7316A', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-20 15:32:08', 1, '超级管理员', '2024-11-22 14:47:23');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (319, '桂枝加附子汤', 205, 6, 9040000, '$u{桂枝}$w{三两}    $u{芍药}$w{三两}    $u{甘草}$w{二两、炙}    $u{生姜}$w{三两}    $u{大枣}$w{十二枚、擘 }    $u{附子}$w{一枚，炮}  ，去皮破八片 右六味，以水六升，微火煮取三升，去滓，适寒温，服一升。若一服汗止，停后服。  \n【本云桂枝汤。今加附子。将息如前法。】\n  适寒温。等温了再服，若一服汗止，停后服，吃完一服后，汗停了就不要再喝了。  ', 3, '', '桂枝,芍药,甘草,生姜,大枣,附子', 614085076369477, '9AA845592573FB200B9D21A539991790', '附子一枚 破八片大约三钱，这是救逆的，平常两钱就够了，像十岁小孩五分就够了。炮附子就是生附子皮剥掉切片，直接在铁锅上面干炒。  ', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-20 15:38:36', 1, '超级管理员', '2024-11-20 15:50:22');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (320, '桂枝去芍药汤', 206, 4, 9040000, '$u{桂枝}$w{三两}   $u{甘草}$w{二两、炙}   $u{大枣}$w{十二枚、擘 }    $u{生姜}$w{三两}   右四味，以水七升，微火煮取三升，去滓，适寒温，服一升。  ', 3, '', '桂枝,大枣,生姜,甘草', 614097895718981, 'D04BE8708019053915D3A8C4AAD9F9C9', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-20 16:30:46', 1, '超级管理员', '2024-11-20 16:32:16');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (321, '桂枝去芍药加附子汤', 207, 5, 9040000, '$u{桂枝}$w{三两}      $u{甘草}$w{二两、炙}    $u{生姜}$w{三两}    $u{大枣}$w{十二枚、擘 }    $u{附子}$w{一枚、炮}  ，去皮破八片 右六味，以水六升，微火煮取三升，去滓，适寒温，服一升。若一服汗止，停后服。  \n【本云桂枝汤。今加附子。将息如前法。】\n  适寒温。等温了再服，若一服汗止，停后服，吃完一服后，汗停了就不要再喝了。  ', 3, '', '甘草,生姜,大枣,附子,桂枝', 614100214882373, '88CE2B1721B79709006A3EE67B063770', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-20 16:40:12', 1, '超级管理员', '2024-11-20 17:13:56');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (322, '桂枝麻黄各半汤', 208, 7, 9040000, '      $u{桂枝}$w{一两十六铢。去皮}    $u{芍药}    $u{生姜}$w{切}    $u{甘草}$w{炙}    $u{麻黄}$w{各一两。去节}    $u{大枣}$w{四枚。擘}    $u{杏仁}$w{二十四枚、汤浸，去皮尖}   右七味，以水五升，先煮麻黄一二沸，去上沫，内诸药，煮取一升八合，去滓，温服六合。\n\n    先煮麻黄一二沸，因为麻黄太强了，吃下去会阳亢，把上面的白沫去掉，上面的沫就是安非他命的来源，再把其它药加上去，现在不用先煮去上沫了，白水煮服，取微汗。  \n\n       煮取一升八合，去滓，温服六合，就是分成三次喝。平常我们可以剂量加重一点，然后让病人用九碗水煮成三碗，如果是治疗表证，隔三小时一碗，第一碗还没发汗，才吃第二碗，依此类推。如果内科病，就早晚各一碗。然后第三碗隔天早上喝。  \n\n       这是桂枝汤里面加两味药，麻黄和杏仁，桂枝比芍药多。桂枝三，芍药二。因为要加强心脏动脉喷出的力量，因为要发汗，麻黄和芍药的量是一样的。如果处方开给胖子桂枝用三钱，芍药两钱，麻黄两钱，麻黄和芍药的量相等，杏仁四五钱都无妨。  \n\n        桂枝和芍药是一组，麻黄和杏仁是一组，麻黄入肺，在《本草》上写麻黄可以宣肺，麻黄一下去，肺的气管全部打开，肺是诸阳之会，所以心脏的力量会加强，因此麻黄有兴奋剂的作用。为什么加杏仁，麻黄宣肺，因为肺主皮毛，所以麻黄下去直到毛孔，毛孔打开的动能是靠肺。如果光用麻黄没有杏仁，肺会干掉，太热，所以加杏仁把不足的津液补足。桂枝汤是解肌的，入脾脏的，入肠胃的，所以加生姜大枣来补津液，作为后援部队，所以皮肤没事会痒的人，可用桂枝麻黄各半汤，会微微的发汗。如果反着开，麻黄重，桂枝少，汗会大量出去。  \n\n        有没有汗，在治病的时候很重要，例如治疗肾脏病，我们由五行知道，必须先治心火，再治肺金，肾脏的功能就会渐渐恢复，汗为心之液，由能否正常流汗，可以判断心脏的功能好了没有，所以肾脏出问题的人，因为影响到心脏，所以再怎么走路，天气热的时候，也不会流汗。  ', 3, '', '桂枝,生姜,芍药,生姜,甘草,大枣,麻黄,杏仁', 614115318706245, 'AC5A5A5DD18130FC42C15DE5A1BD3094', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-20 17:41:40', 1, '超级管理员', '2024-12-09 09:53:20');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (323, '桂枝二麻黄一汤', 209, 7, 9040000, '$u{桂枝}$w{一两十七铢、去皮}    $u{芍药}$w{一两六铢}    $u{麻黄}$w{十六铢、去节}    $u{生姜}$w{一两六铢、切}    $u{杏仁}$w{二十六个、去皮尖及双仁}    $u{甘草}$w{一两二铢、炙}    $u{大枣}$w{五枚、擘}\n	右七味。以水五升，先煮麻黄一二沸，去上沫，内诸药，煮取二升，去滓，温服一升，日再服 。  ', 2, '', '大枣,甘草,杏仁,生姜,麻黄,芍药,桂枝', 614429563203653, '060596CE2F3A30F84301C6D8612A475D', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-21 15:00:20', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (324, '白虎加人参汤', 210, 5, 9040000, '$u{知母}$w{六两}    $u{石膏}$w{一斤。碎绵裹}    $u{甘草}$w{炙。二两}    $u{粳米}$w{六合}    $u{人参}$w{三两}\n	上五味。以水一斗。煮米熟汤成。去滓。温服一升。日三服。\n\n        知母在《本草》上写是除烦止渴生津，因为白虎汤证的病人，嘴巴很渴，血里面的水不足的时候，喝水都没用的，这时候用知母来除烦，胸腔里面没有水气的时候，肺就像云，一旦云没了，太阳直射，当然烦，这时肺整个干的，口会很渴，想喝冰水，喝下去的水一下就干了，根本来不及，白虎汤吃下去的时候，有个特殊的现象，烧一退的时候，病人也是流汗，这汗是把病人的病毒排出来的。  \n\n        石膏是非常辛寒的药，寒凉的药一吃下去，马上进入血脉，把血的温度下降下来，当病人怕热、壮热、高热的时候，用到白虎汤时，石膏就是至少一两以上。《本草》石膏微辛而寒，于清热中，具有散热之性，为退热之专品，惟宜生用。  \n\n       炙甘草主要是健脾健胃，当脾阳不足的时候，就是脾脏的蠕动太慢，压迫到胃，胃口就没了，炙甘草能让脾阳恢复的很快。甘草清热消炎滋液。  \n\n       粳米就是平常用的糯米，最主要是为了取它的黏液，肺上面有很多肺泡，在壮热的时候，整个干掉了，取粳米的黏液来保护它，让它清凉下来，肺的津液靠粳米补足，肠胃的津液靠红枣、人参。粳米、甘草滋润各组织之黏膜。知母、石膏、甘草、粳米，四味合用成为清热除烦生津止渴之专剂。  \n\n       张仲景在用人参时，都是肠胃不好的时候，所以人参是最好恢复肠胃功能的药，人参很贵，可用党参、花旗参取代，现在的高丽参不纯，是浇硫磺长大的，张仲景用的是野参，《本草》写人参是甘苦微寒，味道一点甘一点苦一点寒，人参是比较凉的药，所以白虎人参汤是 生津止渴的专剂。有一种糖尿病，渴饮千杯不能止渴就是白虎人参汤证。所以上消糖尿病用白虎人参汤，所以大汗、大烦渴、脉洪大，方书称为阳明经病；谓阳明主里，阳明病即主病在里，且主实热。故以白虎汤清高热为主治，加人参防心脏之衰弱，补助津液之消耗，当小肠火足够，将大肠里的水气化上去到肺，才能够生津止渴，否则光是喝很多水不够的，这就是人参与粳米的作用。病人发高烧的时候，但热不寒，大便正常，我们用白虎汤退烧，不用人参。  \n\n       石膏胖子五到六钱，重用的时候用到一两以上，石膏若用五钱，知母用三钱。粳米一汤匙，也就是两三钱就可以，因为有粳米，所以白虎汤容易酸坏，所以一次开的份量，三碗熬一碗，每次喝每次熬，人参一二钱即可，党参可用到五六钱。  \n\n      北派有个说法：麻不过三，桂不过五，那是以前的药，以前的药很纯，现在的药都不纯了，所以有的时候麻黄会开到五六钱。  \n\n      麻黄是青龙，石膏是白虎，附子是玄武，大枣是朱雀，容后详述。  ', 3, '', '人参,粳米,甘草人参,粳米,甘草人参,粳米,甘草,知母,石膏', 614433459994693, '294E10FA9E398EAEF68EBD5231B0E26D', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-21 15:16:11', 1, '超级管理员', '2024-11-21 15:22:06');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (325, '桂枝二越婢一汤', 211, 7, 9040000, '$u{桂枝}$w{去皮}    $u{芍药}    $u{麻黄}    $u{甘草}$w{各十八铢、炙}    $u{大枣}$w{四枚、擘}    $u{生姜}$w{一两二铢、切}    $u{石膏}$w{二十四铢、碎绵裹}\n	上七味。以水五升。煮麻黄一二沸。去上沫。内诸药。煮取二升。去滓。温服一升。本方当裁为越婢汤，桂枝汤，合饮一升;今合为一方，桂枝二越婢一。', 2, '', '石膏,生姜,大枣,甘草,麻黄,芍药,桂枝', 614442486886469, 'B81F55D3A17F322D970EFC6FB61A01CF', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-21 15:52:55', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (326, '桂枝去桂加茯苓白术汤', 212, 6, 9040000, '$u{芍药}$w{三两}    $u{甘草}$w{二两、炙}    $u{生姜}$w{切}    $u{白术}    $u{茯苓}$w{各三两}    $u{大枣}$w{十二枚、擘}\n	上六味。以水八升。煮取三升。去滓。温服一升。小便利则愈。', 3, '', '芍药,甘草,生姜,白术,茯苓,大枣', 614448656625733, '1FB000A24720C85013FC991406A0CE2F', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-21 16:18:01', 1, '超级管理员', '2024-11-21 16:30:05');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (327, '甘草干姜汤', 213, 2, 9040000, '$u{甘草}$w{四两、炙}    $u{干姜}$w{二两}\n	上二味。以水三升。煮取一升五合。去滓。分温再服。\n       干姜就是生姜炒干，或生姜晒干后再炒过，炙甘草在这里可以壮胸阳，胸阳包括肺和心脏都能壮起来，肺的功能一恢复，就能将津液运到四肢，甘草干姜汤也是吐血的神剂，大量吐出血的时候，就开阳药，就是很热的药，就是甘草干姜汤，甘草干姜汤又名二神汤，中医的观念脾胃的功能一恢复，血会回到经络里面来，现在外面的医生，以为吐血是热，开寒凉的药，犀角、生地、菊花下去，病人吐得更厉害，胃穿孔、胃溃疡、会胃吐血的，都是胃家素有寒证的，所以用热药，就是甘草干姜汤。  \n\n  《直指方》曰：甘草干姜汤治男女诸虚出血，胃寒不能行气归元，无力收约其血。', 2, '', '干姜,甘草', 614464279105605, '10B873EC0CF793A15B03EB05F063D70A', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-21 17:21:35', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (328, '芍药甘草汤', 214, 2, 9040000, '$u{白芍药}$w{四两}    $u{甘草}$w{各四两、炙}\n     右二味，㕮咀，以水三升，微火煮取一升半，去滓，分温再服之。  \n\n        又名去杖汤治脚弱无力。行步艰难，芍药甘草汤可以止腹痛，痛代表有东西堵到，\n例：妇科的瘀血，还有肠子的表面有很多微血管，肠子的蠕动能源来自血，如果肠子上的血堵塞到了，这时候，肠子会套叠在一起，血液循环不好，病人会觉得绞痛。白芍破血，活血的力量很强。  \n\n     《古今医统》曰：芍药甘草汤治小儿热腹痛，小便不通，及痘、疹之腹痛。所以小孩没 事会肚子痛的，可用芍药甘草汤。  ', 2, '', '芍药,甘草', 614465020706885, '25656B5C8D31B90A6C046D77A449A9A8', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-21 17:24:36', 1, '超级管理员', '2024-11-21 17:27:24');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (329, '调胃承气汤', 215, 3, 9040000, '$u{大黄}$w{四两、去皮$u{清酒}洗}    $u{甘草}$w{二两、炙}    $u{芒硝}$w{半升}\n 右三味，以水三升，煮取一升，去滓，内芒硝，更上火微煮令沸，少少温服之。  \n\n       大黄和炙甘草的比例是二比一，炙甘草不可以用太重，如果用太重，大黄和芒硝会停在肠胃里面不走，因为炙甘草把它固住了，芒硝是破瘀的，先把大黄和炙甘草煮过，再放芒硝，更上火微煮令沸，放在火上面滚一下就好了，芒硝化了就好，如果要药再强一点。芒硝开少些，用冲服的。芒硝在市面上买的时候像盐巴。上牙是手阳明大肠经，下牙是足阳明胃经，所以上下牙都是阳明证，阳明讲的是消化系统，所以消化系统堵到的话，牙齿开始牙周病，牙龈红肿烂掉，如果牙龈红肿烂掉就是肠胃太热了，有大便，只是没有大小承气汤证，有调胃承气汤证，所以用调胃承气汤把上面的东西轻轻的清出来，一清出来就是消炎，所以大黄是消炎的药，芒硝是攻坚的药。大黄用酒洗，使其具有升提之性，就不会攻下得太快，把小 肠大肠的东西都清光了就不好。  \n\n《活人书》曰：大抵发斑不可用表药，表虚里实者，若发汗开泄，则更斑烂，宜用调胃承气汤下之。  \n\n《证治准绳》曰：破棺丹治疔疮之气入腹而危者。有时候肠胃化脓了，梗在十二指肠的地方，调胃承气汤下去可解。  \n\n《玉机微义》曰：调胃丸止齿痛，血出不止，用调胃承气汤为末，作蜜丸服之。  \n\n《类聚方广义》本方条曰：痘疮，麻疹，痈疽，疔毒，内攻冲心而大热谵语，躁烦闷乱，舌上燥裂，不大便，或下利，或大便绿色者宜此方。为什么大便绿色的，因为人身上的胆汁是绿色的，有时候小孩受到惊吓，肠胃就冻结住了，小肠不会蠕动，所以胆汁就往外流，这时候就用调胃承气汤。  ', 1, '', '大黄,甘草,芒硝', 614467124895813, '01509B85BCEC24427B343198FDC74A08', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-21 17:33:10', 1, '超级管理员', '2024-11-22 08:40:10');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (330, '四逆汤', 216, 3, 9040000, '$u{甘草}$w{二两、炙}    $u{干姜}$w{一两半}    $u{附子}$w{一枚、生用去皮破八片}\n	上三味。以水三升。煮取一升二合。去滓。分温再服。强人可$u{大附子}$w{一枚}    $u{干姜}$w{三两}。\n\n        真正在救逆的时候，是用生附，霍乱、疟疾、上吐下泄都是四逆汤证。一颗生的附子，还没有晒干之前，大约五钱；晒干或烘干以后，大约三钱。生附于表面纤维很多，必须用棉  \n\n       布包起来煮，纤维才不会刺激到喉咙。生附子专门去里寒，炮附子专治表虚。病人表虚而汗 流不止，我们用炮附子，这时用生附子反而没用，因为生附子不走表。如果是开刀或意外车祸，病人失血过多而且怕冷，有里寒的时候，我们用生附子让阳气回头。喝到生附子，嘴唇舌头会麻，虽然是一种中毒现象，但是因为病人需要这个药，所以病人觉得很舒服。四逆汤又称为回阳汤，麻黄汤称为返魂汤。  \n\n       东洞翁曰：本方治四肢厥逆，身体疼痛，下利清谷，或小便清利者。  \n\n      《勿误药室方函口诀》本方条曰：于此方中加乌梅、蜀椒，名温中汤，治虫蚘厥。经方很多治疗打虫的药，乌梅、蜀椒都是，蜀椒就是花椒巴椒，蜀椒取开口的才没有毒。  \n\n       《医林集要》曰：干姜附子汤治伤寒阴证，唇青面黑，身背强痛，四肢厥冷及诸虚沉寒，这就是溺水，在水里面昏迷了，救溺的时候，扎公孙、内关、中脘，然后趴过来，扎会阴，让心脏跳起来，水排出来了，可是体温还是很冷，用四逆汤下去，让体温回复。', 2, '', '附子,干姜,甘草', 614689095901253, '13B2F6333D1B9FDC1A8A10E15C41EB1D', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 08:36:22', 1, '超级管理员', '2024-11-22 08:37:39');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (331, '葛根汤', 217, 7, 9040000, '$u{葛根}$w{四两}，$u{麻黄}$w{三两、去节}，$u{桂枝}$w{二两、去皮}，$u{芍药}$w{二两}，$u{甘草}$w{二两、炙}，$u{生姜}$w{三两}，$u{大枣}$w{十二枚、擘}\n 右七味，㕮咀，以水一斗，先煮麻黄、葛根，减二升，去沫，内诸药，煮取三升，去滓，温服一升，覆取微似汗，不须啜粥。馀如桂枝汤法将息及禁忌。  \n\n       葛根是桂枝的两倍，处方的时候葛根用四钱，麻黄用三钱，桂枝用二钱，芍药用二钱，以下是桂枝汤的方子。为什么用葛根汤?因为桂枝汤的时候，本身没有失掉很多津液，体能很好，葛根汤的时候，表就很虚了，尤其是小孩子，常常跑来跑去，汗流很多，风一吹，就得了葛根汤证，因为他在运动的时候，毛孔开着的，汗就流出去了，流汗的同时，滤过性病毒进来，一进来就很深了，刚开始从背后进来，造成部分的水已离开汗腺但又不出毛孔，所以项强，水渗在肌肉里面，会很痛，所以背部强硬。原本津液就不够了，如果光靠桂枝汤把肠的津液发表发出来，因为津液不够，力量会不够，这时候重用葛根，葛根原本就是提升津液的，把水分发散到皮肤表面上来，为什么加麻黄?麻黄用的比葛根少，不能太多，皮肤表面没有汗，代表有中寒的现象，如果有汗，光是桂枝加葛根就可以了，没有汗，就是被表寒束到了，要发表发出来，但是光靠桂枝没力量，这时候加麻黄在桂枝上面。  \n\n       张仲景在写处方的时候，先写葛根，麻黄，桂枝，麻黄走表，很轻。张仲景在用麻黄的时候，一定先把麻黄煮一下，白沫拿掉再用，如果不先煮一下，麻黄的性轻而且性往上升，它一下子就进入脑部，就是安非他命，所以先煮一下，把它的轻去掉，让它不要走太快，光吃麻黄不会走到皮肤表面，所以单味吃麻黄，不会流汗的，要靠桂枝把它推到肌肉，然后麻黄再到皮肤表面，把病毒排出体外。葛根是升水的，感冒喉咙痛，咽干，就是葛根汤证，葛根是生津止渴的，所以重用葛根，葛根可以用到四钱，不需要喝粥，光靠葛根的力量就够了。肠胃因为有炙甘草、大枣，所以津液很足，葛根直接把津液从肠胃带到皮肤表面去，到头上、喉咙去了。  \n\n        葛根发散的力量很强，譬如小孩发水痘，水痘就是胎毒，小孩在妈妈的肚子里，喝了羊水，到大的时候会发水痘，发起来是一颗小小的一粒，表面上是一粒，结果小孩发高烧，小孩的肠胃的壁表面全部是一片水痘在上面，这就是胎毒，服葛根汤，葛根汤能把所有脏的水排到皮肤表面，喝了葛根汤后，小孩早上起来，会发的满脸全身都是水痘，但是小孩很有精神，不要刺破，让它慢慢消掉就好了，一剂就够了。  \n\n       朮附汤，白朮附子等量，能够发痈脓，在身体里面的瘤，在很深的地方，在子宫或淋巴结里面，一直无法发到表面上，如果能发到皮肤表面，变成大的脓疮，像青春痘、疖子，把脓头去掉就好了，但是在很深的地方或在骨边出不来，就靠白朮附子。为什么加附子，因为深的地方一定接近骨边，所以加附子，附子壮里阳，把里面的脓疮往外推，白朮有干燥的作用，所以把葛根汤里面加这两味药下去的时候，可以发全身性的脓疮。须知如果身上的硬块表面上是平滑的，就没关系，粗糙的是癌，赤小豆当归散也称为排脓汤，那是排痔疮的脓，用法不一样，在金匮中会介绍。  \n\n        举例来说，如果遇到一个病人，糖尿病足、脚上有伤口化脓，偏偏又得到葛根汤证，我们就要灵活运用，可以用葛根汤加上白朮附子排脓，因为在脚上，所以加重白芍，把脚的血液循环加速。经方是绝对处方，比例是黄金比例，运用之妙存乎—心。  \n\n       《方机》曰：鼻渊、脑漏、鼻痈、鼻中息肉等之臭脓滴沥，或浊涕不止，不闻香臭等，皆由同中郁毒之所致，脑漏尤为恶证，若不早治之，则或至不起，俱宜本方加朮附汤，痈疽 初起，壮热憎寒，脉数者，以葛根汤发汗后，转以加朮附汤而促其酿脓，脓成者，速可刺破。脑漏，肾主脑，鼻子不好的头定痛，这时候加强肾，让排脓的力量加强，所以加附子，加白朮。这样鼻黏膜就会越来越干。鼻涕如果说是黄、黏稠的，这是湿热，就改成加些黄芩等去热的药在里面。  ', 3, '', '大枣,生姜,甘草,芍药,桂枝,麻黄,葛根', 614719095214149, 'C011857E3003DD36E767FF71B373E20D', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 10:38:26', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (332, '葛根加半夏汤', 218, 8, 9040000, '$u{葛根}$w{四两}    $u{麻黄}$w{三两、去节}    $u{甘草}$w{二两、炙}    $u{芍药}$w{二两}    $u{桂枝}$w{二两、去皮}    $u{生姜}$w{二两、切}    $u{半夏}$w{半升(洗)}    $u{大枣}$w{十二枚、擘}\n\n       生半夏半斤洗 右八味，以水一斗，先煮麻黄，葛根，减二升，去白沫，内诸药，煮取三升，去滓，温服一升，覆取微似汗。  \n\n     《勿误药室方函口诀》本方条曰：此方不仅治合病之呕，平素有停饮〈胃内停水也〉，服本方，为什么有停饮?平常运动后，很口渴，拿水灌，一次两次没关系，多次后就会造成停饮，水灌太快，因为胃火来不及烧，水就停在胃中间，在胃胸中间的横膈膜上，就像海绵充满了水。又云：葛根汤，动则害胃，往往食机不振、致恶心、呕吐等，故若胃不健全，有恶心，呕吐之倾向，或认为有胃内停水，则不宜单用葛根汤，而用葛根汤，小半夏汤合方之本方，可预防服葛根汤之弊。实际上葛根对胃没有影响的，是桂枝。  ', 3, '', '葛根,麻黄,甘草,芍药,桂枝,生姜,半夏,大枣', 614723758874693, '3CA18D4D9DBF496B5BBEF5E1F4DCB6BC', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 10:57:25', 1, '超级管理员', '2024-11-22 10:59:32');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (333, '葛根黄芩黄连汤', 219, 4, 9040000, '$u{葛根}$w{半斤}    $u{甘草}$w{二两、炙}    $u{黄芩}$w{三两}    $u{黄连}$w{三两}\n	上四味。以水八升。先煮葛根。减二升。内诸药。煮取二升。去滓。分温再服。\n\n       阿米巴痢疾的时候，大剂的用，葛根可以用到六七钱，如果不大量的用葛根，病人下利不止会脱水，如果没有葛根黄芩黄连汤，寒利可以灸肚脐，热利的时候针曲池、合谷、天枢、关元、三阴交。有临床上的案例西医所谓的肠病毒的案例，其实就是表邪下陷，到了肠子变成热利，所以有葛芩连汤证的时候，结果病人喝到葛芩连汤，病人觉得不苦，反而觉得很甜很好喝。 ', 2, '', '黄芩,黄连,甘草,葛根', 614727120068677, '9C564594C3DA9C84C9AFF833CC29628E', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 11:11:05', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (334, '麻黄汤', 220, 4, 9040000, '$u{麻黄}$w{三两、去节}    $u{桂枝}$w{二两、去皮}    $u{甘草}$w{一两、炙}    $u{杏仁}$w{七十个、去皮尖}\n	右四味、以水九升、先煮麻黄、减二升、去上沫。内诸药、煮取二升半、去滓、温服八合、覆取微似汗、不须啜粥、余如桂枝法将息。 麻黄用三钱，杏仁等量用三钱，桂枝少些二钱，炙甘草再少些一钱。  \n\n        伤寒论里面还有在少阴证的时候用到麻黄，就是麻黄附子细辛汤。一般人认为吃了麻黄就会发汗，所以不能乱吃，所有的药典都讲麻黄会解表，而实际上在用的时候，麻黄是发阳的药，把阳气发出来，壮里阳用的，所以不只是太阳证可能用到麻黄，在少阴证与厥阴证都可能用到麻黄。经方的观念是，把阳强起来以后，阴就会自己回头，因此张仲景的观念是，当病人很虚弱的时候，我们用阳药恢复病人的胃气，病人自己会从食物中摄取营养，然后自己痊愈，这才是真正恢复健康。  \n\n        张仲景在用麻黄汤的时候，要让病人流汗并把病毒排出去，桂枝汤能解肌，所以桂枝汤是入脾脏的，而麻黄汤入肺的，把肺解表，所以如果麻黄汤的病人，开成桂枝汤，结果发汗发在肌肉上，还是发不到皮肤表面上的，结果病人会更增腻、更烦躁，所以麻黄汤里面为什么要有桂枝、甘草，就是利用桂枝、甘草，把麻黄先推到皮肤表面上，后面桂枝没力了，就靠麻黄了，用麻黄来解表发汗。如果没桂枝、甘草，麻黄就待在里面，所以少阴篇的第一方麻黄附子细辛汤，就看不到桂枝、甘草，其因就是怕麻黄在皮肤表面发散太过，这时候用了麻黄不会发汗，这里麻黄是发阳的效果。加杏仁在里面，杏仁和麻黄是表里，如果只有麻黄、桂枝、甘草也会发汗，但是发完汗后，病人会大渴，所以加杏仁，杏仁润肺，把肺的津液补足，杏仁就像是麻黄的后备部队，所以麻黄汤用来解表解肺的，因为桂枝汤是利用肠胃的津液输送到表面去，而生姜、红枣是生肠的津液，所以桂枝汤用生姜、红枣。如果麻黄用生姜、红枣不用杏仁，结果肠的津液很足，肺干掉了。如果肺的病、气喘、咳嗽不用麻黄，就治不 好的。所以张仲景治疗肺的时候，一定用麻黄，至于是肺发炎、肺积水另外再开了。 ', 3, '', '麻黄,桂枝,甘草,杏仁', 614729522499653, 'AF39142ADDC21691788B7D1AEC9F2DE2', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 11:20:52', 1, '超级管理员', '2024-12-07 11:55:39');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (335, '小柴胡汤', 221, 15, 9040000, '$u{柴胡}$w{半斤}    $u{黄芩}    $u{人参}    $u{甘草}$w{炙}    $u{生姜}$w{各三两、切、}    $u{大枣}$w{十二枚、擘}    $u{半夏}$w{半升、洗}\n	右七味、以水一斗二升。煮取六升、去滓、再煎取三升、温服一升、日三服。\n\n加减法：\n\n   若胸中烦而不呕者。去$u{半夏}、$u{人参}。加$u{栝楼实}$w{一枚}。\n\n   若渴。去$u{半夏}。加$u{人参}。$w{合前成四两半}    $u{栝楼根}$w{四两}。\n\n   若腹中痛者。去$u{黄芩}。加$u{芍药}$w{三两}。\n\n   若胁下痞硬。去$u{大枣}。加$u{牡蛎}$w{四两}。\n\n   若心下悸、小便不利者。去$u{黄芩}。加$u{茯苓}$w{四两}。\n\n   若不渴。外有微热者。去$u{人参}。加$u{桂枝}$w{三两}。温覆微汗愈。\n\n   若咳者。去$u{人参}、$u{大枣}、$u{生姜}。加$u{五味子}$w{半升}    $u{干姜}$w{二两}。\n\n      原本伤寒论里面，张仲景没有加减法，加减法是后人加进去的，若胸中烦而不呕代表胃里面没有停水了，这时候加栝蒌实，为什么加栝蒌实？栝蒌实去胃中、胃的下方的结实，平常胃的下方随时保持着两公升（校对注：疑为“两公分”）的食物在里面，永远有东西停在里面，新的食物就把旧的推出去，所以有时候吃了三四小时后，还会恶出食物的味道，这一段东西坏掉的时候，就要靠栝蒌实，这一段坏掉的时候，会心烦，不是情绪不好，而是胃里面不通，胀闷胀满的感觉，不会恶心呕吐，栝蒌实用的不多，如果用大黄芒硝，会直接下去，不会停留在胃下方，调胃承气汤里面，是在十二指肠的地方，当然也可以重用甘草，但是甘草只能分解食物的毒，并没有把它完全排出来。若渴者，去半夏，加人参合前成四两半，栝蒌四两，这里的栝蒌是栝蒌根，栝蒌根可以生津止渴的。临床上用，栝蒌根可以降血糖，有种痉病，角弓反张，脑膜炎，就是用栝萎根，后面会介绍栝蒌桂枝汤。若腹中痛者，去黄芩，加芍药，为什么肚子痛？寒湿跑到下焦去了，张仲景对腹痛一定会重用芍药，凡胸满一定去芍药加枳实。若胁下痞鞕，在中焦一带，刚好在肝和脾脏的地方，鞕满不通代表肝气不足，没有办法舒松开来，因为少阳讲的就是胆，消化系统，这时候重用牡蛎，牡蛎可以平肝气，而且咸能软坚，能够去除硬块，不只是在胁下，喉咙的硬块、腋下淋巴的肿块，都可以用牡蛎。心下悸，小便不利者，心下悸即水在中焦，才会令小便不利，所以会用到茯苓。一般来说会有咳嗽的时候，药常常把红枣拿掉，红枣何时加何时去看病情，如果病人湿热很盛的，还有酒客，因为红枣太甜，属甘味，吃下去会增腻，舌苔黄、抽烟多的，就把红枣拿掉，加五味子，五味子是生津的，五味子加二三钱就够了，咳得重的加重点，五味子没有寒热，只针对咳嗽，有润肺的功能。  \n\n       小柴胡汤治疗西医说的肝炎，由中医来看，就是有湿热，小便黄兼往来寒热、胸胁苦满、默默不欲食、心烦喜呕等等，西医只知道这是肝肿起来，顶到胃了。病人没有胃口，我们加上茯苓、白朮，茯苓稍微比白朮多一点，以去湿来改善胃口，然后加上郁金来行肝气；病人如果全身黄疸，病人的精神还好，用茵陈蒿；虚烦不得眠，加栀子。怎么知道病人好转？晚上一点到三点能睡了，一觉到天亮，胃口好，小便颜色正常，体力恢复，双脚温热起来，就代表肝病好了。西医以为肝癌是无形的杀手，那代表西医不能预先诊断出肝癌；其实正统中医两年前就能知道，在实证发生在肝脏之前，每天晚上一点到三点不能睡，就要赶快治疗了。肝木喜疏达，我们可以由种果树的技巧可以领悟治肝的方法。郁金用来疏散郁气，半夏去除多余的水等等，都是与肝木喜疏达的特性有关。小柴胡汤可以说是预防肝病的第一方。  \n\n       淋巴结、淋巴肿块，这是结实在三焦，我们用黄色去实的药，用小柴胡汤加石硫磺；当脑部有积水时，用小柴胡汤加重生半夏去至高之积水；乳癌的药方，其实也是小柴胡汤的加减，遇到经期来的时候，乳癌的药方中需加上桂枝，利用桂枝降冲逆的特性，把奶水导入子宫里。临床上只要看到小柴胡汤的主证，就可以用小柴胡汤，我们不管西医的病名是肾脏病或是经期生理痛或其它病名。还有，当女性在经期得到感冒，一律使用小柴胡汤来和解。女性经期腹痛用小柴胡汤加白芍，需要的时候，白芍可以加重使用。  \n\n       《古今医统》曰：小柴胡汤治瘰疬，乳痈，便毒，下疳，及肝经之一切疮疡，发热，潮热，或不思饮食。小柴胡汤进入三焦，所有的淋巴系统、腺体、手少阳三焦经、足少阳胆经、肝，是人身上最主要最大的腺体。  \n\n       《正体类要》曰：小柴胡汤治一切扑伤等证。打架，身体表面很好，可是心口很痛，皮肤表面又没有瘀血，所以他是伤在半表半里中间，大便如果是黑色的，就是有内出血，小便不通了，代表血堵在膀胱了，一般性伤科是小柴胡汤证，但是小柴胡汤下去只能清热消炎，并不能把瘀清出来，所以用桃仁，不一定是桃子的仁，杏子的仁也可以，桃仁这药专门攻瘀破血，打架内伤在胃的位置，这血已经离开血管，跑到淋巴系统里面去了，在三焦油网中间，经过十几年后，西医打开来看胃没有问题，但是胃壁和淋巴结成一块，纠缠得拿不掉，所以西医叫淋巴癌，如果刚开始有伤的时候，就用小柴胡汤加桃仁，如何查有瘀血，看舌头，舌头上有一块青一块黑的，旁边有齿痕，他可能没有感觉，这时候用小柴胡汤加桃仁，桃仁加一钱半，胖子用五六钱都可以。包括女孩子的妇科也可以用，子宫在半里半表中间，子宫是腺体，所以子宫拿掉，内分泌会不平衡，内分泌系统全部属于半表半里。  \n\n       脑受伤瘀血，在脚上然谷放血，下针涌泉人中百会，处方小柴胡汤的加减，加些破瘀的桃仁、红花。三焦、血脉、神经、脑细胞都属于少阳，所以眼睛、鼻子、耳朵、头部都是属于少阳。  \n\n《保命集》曰：产后日久，虽日久而脉浮疾者，宜服[二元汤]，即本方合四物汤（又名柴胡四物汤）。就是小柴胡汤里面加$m{四物汤}$n{（当归 川芦 白芍 生地）}。  \n\n        真正滋补的时候用生地不是熟地，而且大剂的用，瘦子当归用五钱，生地用一两，当归和生地专门补血的，补到脊椎骨上面去，脊椎骨生血的力量会很强，熟地就是生地炒熟，炒过炮制过的比较热，虚热的人补药下去会更热，用熟地嘴会破，用生地就不会了，所以生用；女孩子月经肚子痛，白芍专门止腹痛，能破瘀，所以产后或流产过，肚子会痛可以用芍药甘草汤，重用白芍到一两，平常三二钱就很强了，让血流回心脏比较强就可以了，如果是静脉瘤那二三钱就不够了，一定比例，如果要让怀孕很好的话，一定加重川芎，如果是月经来的时候吃的，可以使她的子宫排干净，把瘀血清出来，西医之子宫内膜异位，一定会加重川芎，如果眼睛黑黑的，舌头胖胖的，生地可以重用到二三两都可以。  \n\n        $g{乳房硬块}，小柴胡汤可以去掉胸胁苦满，如果硬块比较严重的时候，同样是小柴胡汤就要加一些或减一些药，如果要让胸部的满去掉，桃仁是很好的破瘀的药，也可以加牡蛎，牡蛎也是攻坚的，牡蛎的攻坚和芒硝不一样，中药里面有很多攻坚的药，像桃仁、附子也是攻坚的药，什么时候用到附子？只有在腹膜炎的时候才用附子，已经发热了，非用附子把它清 出来，这时候附子就不是补阳的药而是攻坚的药。要让胸阳旺起来，重用炙甘草，炙甘草平常用一二钱是对肠胃的，加重到五钱一两的时候，炙甘草很热，土会生金，这时候上焦就热起来，所以后面有炙甘草汤，炙甘草重用到四五钱以上后，马上热在胸阳，所以有一救逆的汤方甘草干姜汤，炙甘草用到四，干姜用二，炙甘草加重，让胸阳热起来，才有血在上焦，血在上焦的时候，乳房开始运作了，运作就是生奶的过程，西医打退奶针，奶没有喂完，后遗症就是造成$g{乳房硬块}，治疗$g{乳房硬块}，就是让它再生化一次，就用小柴胡汤里面炙甘草加重。让它充满上来，上来以后胸阳热起来，会充奶，怕会太热，小柴胡汤里可多用黄芩，再把这热导出来，让它变成月经排出去，让胸部的硬块生化或月经排出来，要让上焦的血进入冲脉达到子宫就要靠桂枝，《本草》写桂枝能够通血路，经方家来看桂枝能够通利冲脉，因 为桂枝壮心阳，会把奶水蒸化掉变成血进入子宫，所以治疗的时间要利用月经来的时间，利用月经排的中间再生化一次，生化的时候，胸部乳房会挺起来，然后从月经排出去。  \n\n以上方为主力处方来做加减  \n\n       当病人进入乳癌末期气血两虚时，可以用八珍汤来做加减，主要观念在行气，破瘀，用咸味攻坚，开气去郁，令三焦气机流畅。同时必须以强固胃气，增加命门火维持生命的延伸为主。  \n\n       汤本氏曰：小柴胡汤应用之主目的为胸胁苦满。所谓胸胁苦满者，令病人仰卧，医用指头，自肋骨弓下始，沿胸壁里面，向胸腔按抚轻压而上，触之有一种抵抗物，同时觉压痛者是也。治以小柴胡汤，则之随脑、咽喉、气管、支气管、肺、肋膜、心脏、胃、肠、肝、脾、膵（胰脏）、肾、子宫等病证之治愈，而此抵抗物亦渐次缩消。是故余谓胸胁苦满之腹证，概不外前胸壁里面所有淋巴腺之肿胀硬结也。师之创立小柴胡汤，即欲治此续发的淋巴腺之肿胀硬结与原发的病变耳。又以此淋巴腺之肿胀硬结为其应用主目的者，夫亦以其续发的病变不仅易于触知，且常确定不变也。  \n\n', 3, '', '黄芩,黄连,人参,甘草,生姜,大枣,半夏', 614737479491653, 'B0975201D33BB2F31B4B7F0ED362481A', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 11:53:15', 1, '超级管理员', '2024-12-07 14:25:35');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (336, '大青龙汤', 222, 7, 9040000, '$u{麻黄}$w{六两、去节}    $u{桂枝}$w{二两、去皮}    $u{甘草}$w{二两、炙}    $u{杏仁}$w{五十枚、去皮尖}    $u{生姜}$w{二两、切}    $u{大枣}$w{十二枚、擘}    $u{石膏}$w{如鸡子大(碎)}\n\n     右七味，以水九升，先煮麻黄，减二升，去上沫，内诸药，煮取三升，去滓，温服八合，取微似汗。汗出多者，温粉扑之，一服汗者，停后服。  \n\n      石膏一般四到五钱，杏仁一般二钱多到五钱都没关系。标准的黄金比例是，麻黄用六钱，石膏用四钱，杏仁用二钱，那么杏仁加石膏等于麻黄的六钱，这样子就不会伤到津液。当然临床上要看病人的症状作加减，如果病人高烧与烦躁明显的时候，我们石膏可以用到一两，如果咳嗽频繁或痰多，就多加杏仁。  \n\n     如果喝完大青龙汤，汗出太多，药开太过了或运动流汗太多，用温粉擦擦。如何预防发汗太过，就是慢慢喝大青龙汤，喝第一碗的时候，可以让病人先喝两口，看看如果没有什么感觉，再继续喝两口，慢慢地把第一碗喝完，感觉到快要发汗，就不要再喝，然后保暖帮助发汗。\n', 3, '', '麻黄,桂枝,甘草,杏仁,生姜,大枣,石膏', 614768051204165, 'E2FEC47E122B2B26B09F576529396BC6', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 13:57:38', 1, '超级管理员', '2024-11-22 14:25:24');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (337, '温粉', 223, 3, 9040000, '$u{牡蛎}、$u{龙骨}$n{(马骨)}、$n{糯米}，三味磨粉等量。  \n\n临床上，气喘的病人，冬天喘夏天不喘，就是小青龙汤证，也就是寒喘；天气热才开始喘，天气冷就不喘，就是大青龙汤证，表寒里热，里热想出去出不去，外面的热进不来，被寒束到了，就是热喘。  \n\n大青龙汤是治疗疫病的药方，疫病就是气候不正常的情况下，例如春行冬令，所发生的流行传染病。现代的，只要是症状与大青龙汤证相同，就是用大青龙汤，因为中医是同证同治。如果是四季分明，节气交替正常的时候，就不会用到大青龙汤；只会用到麻黄汤、桂枝汤、葛根汤等等。  ', 3, '', '龙骨,牡蛎', 614769961365573, '293D587D13E8F10412DA6EF817A49C05', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 14:05:25', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (338, '干姜附子汤', 224, 2, 9040000, '$u{干姜}$w{一两}    $u{附子}$w{一枚(生用、去皮、切八片)}\n	上二味。以水三升。煮取一升。去滓。顿服。\n\n        真正在救逆的时候，干姜真正用到一两都没关系，阳没有虚到那程度的时候，像胖子的体格用三钱就可以了，中等的用二钱，小孩用一钱。在救逆的时候，人昏迷过去的时候，大剂的煮浓一点下去，病人只吃了一点，可能就三钱了。生附子用两钱，生附子如果没有去皮，必须用棉布包起来，以免纤维刺激到喉咙；如果已经去皮，就不用搞布包裹。生附子是温心阳、补命门火；肾藏的阳不够用炮附子。用了生附子温心阳之后，心跳不会加快，但心脏搏动的力量会加强；与麻黄发阳不一样，麻黄会使心脏搏动的速度加快。  ', 1, '', '附子,干姜', 614821420191813, '1015591A49F7721B02CC86387CCFB97F', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 17:34:48', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (339, '新加汤', 225, 6, 9040000, '$u{桂枝}$w{三两、去皮}    $u{芍药}$w{四两}    $u{甘草}$w{二两、炙}    $u{人参}$w{三两}    $u{大枣}$w{十二枚、擘}    $u{生姜}$w{四两}\n	上六味，以水一斗二升，煮取三升，去滓，分温服一升，余依桂枝汤法。  \n桂枝三钱，芍药四钱，原本桂枝芍药等量，这时候重用芍药所以用四钱，人参的量可以多加一些以补气。  ', 3, '', '桂枝,芍药,甘草,生姜,大枣,人参', 615044964446277, '95F48E0CAFCCA5CD7031DF5EC3FFB289', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 08:44:24', 1, '超级管理员', '2024-11-23 08:44:36');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (340, '麻黄杏仁甘草石膏汤', 226, 4, 9040000, '$u{麻黄}$w{四两、去节}    $u{杏仁}$w{五十个、去皮尖}    $u{甘草}$w{二两、炙}    $u{石膏}$w{半斤(碎、绵裹)}\n	上四味。以水七升。煮麻黄。减二升。去上沫。内诸药。煮取二升。去滓。温服一升。\n\n       开麻黄的时候，如果有石膏在，不用担心太重，要让石膏达到肺的每一个血管里面。麻黄去节，麻黄的节能够止汗，所以要剪掉，麻黄用三钱，杏仁差不多用两钱最多可以到五钱，石膏也是四钱到六钱，和麻黄量相等就可以，甘草二钱或少一点，石膏一般用棉布包起来，先煮麻黄减二升，就是先去掉麻黄的气，留麻黄的味，不要麻黄跑到头部去了。开大青龙汤的时候，麻黄开六钱，杏仁开两钱，石膏开四钱，如此一来，杏仁加石膏与麻黄的六钱相等，就不会伤到津液。石膏的目的是去热，杏仁是去痰、润肺。因为麻杏甘石汤的病人没有大热，没有发高烧，所以麻黄的剂量不用很多，麻杏甘石汤不是用来退烧的。  \n\n   《类聚方广义》曰：哮喘胸中如火，气逆涎潮，太息呻吟，声如拽锯，鼻流清涕，心下鞕塞，虚里动如奔马者，宜此方。  \n\n     大青龙汤就是麻杏甘石汤加三味药，就是麻杏甘石汤加桂、姜、枣就变成大青龙汤，所以大青龙汤有表证，用桂枝和麻黄把它发表，所以麻黄用到六钱；除了清里热还要解表，麻杏甘石汤和大青龙汤的分辨，同样是气喘也是热，问病人胃口好不好？胃口好就吃麻杏甘石汤，胃口不好的吃大青龙汤，因为甘姜枣就是开胃的药，药吃下去，为什么会流汗？就是靠肠胃的津液去流汗的，胃功能没有了，那还有津液流汗，就是这样分类的。  \n\n气喘的治疗：  \n\n        一、热喘：就是病人虚汗很多，阳虚了，舌苔黄黄的，气喘到你的手上的时候，大都是虚证了，一定喘很久了，小孩用单剌不留针，呼吸痰的声音很大，只针不灸：下公孙内关〈胃心胸〉，三里太白〈土生金〉，临泣太白〈合化土〉，正面的云门背后的肺俞，一般来说气喘的病人胃口一定不好，再加中脘。处方用大青龙汤和麻杏甘石汤的变方，视胃口好不好而定，如果病人喜欢喝酒就用桂枝汤加厚朴杏仁。  \n\n        二、寒喘：看到最多的就是寒喘，每到冬天的时候都不能睡觉，都要坐着睡，吐出来的是白痰，肺寅大卯胃辰宫，每天晚上三点到五点的时候就开始喘，很准时，确定病人是寒喘，除了针之外还可以灸，针灸的穴道还是一样的，也是虚证的治疗，背后的肺俞、脾俞、胃俞，其它的穴道一样，用土生金的方法来治疗。寒喘的时候一定要加灸，灸的效果很快的，处方用小青龙汤来加减。  \n', 2, '', '石膏,甘草,杏仁,麻黄', 615057075920965, 'D7B911996FC9458C6D6786B14361C243', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 09:33:41', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (341, '桂枝甘草汤', 227, 2, 9040000, '$u{桂枝}$w{四两、去皮}    $u{甘草}$w{二两、炙}\n	上二味、以水三升、煮取一升、去滓、顿服。\n\n       桂枝如果四钱，甘草就用二钱，桂枝是甘草的两倍，因为发汗发太过了，甘草到胃里面去，把胃的津液补足，为什么只用桂枝不用白芍?为什么会动悸?平常喝水下去的时候，胃很热，水到胃里面的时候是气化上来的，是成蒸气不是水，今水停在中脘这里，桂枝很热。桂枝下去会蒸发水往上走，还有，心脏的外膜，有很多神经血脉在纵膈膜、横膈膜，在血管里面的是血，在神经淋巴系统的是水，桂枝下去让心脏喷射的力量很强，把停在心下的水很快的就气化了，会动悸就是因为原本应该是水气上来就好了，结果是水上来，这个水是冷水，所以会动悸，这时候桂枝甘草下去，马上就把水气化。打到四肢上去，症状就会去掉。这和小青龙汤证的心下悸很像，小青龙汤证的心下有水气一定有咳喘，今这汤剂没有咳症。所以桂枝甘草汤是心下动悸的时候用的，因为发阳发太多了是阳虚，所以阳虚产生的心悸就是桂枝甘草汤。桂枝可以降冲逆，所以这里会重用桂枝。后面会用到桂枝加桂汤，也是利用桂枝降冲逆的效果。  \n\n桂枝和甘草如果再加上了茯苓和大枣就是更进一层了，汗透发的时候，把肠胃津液都发出去了，下焦的水又往上冲。结果就是脐下悸，奔豚的力量很强，都是水的问题，水在下焦的时候，要靠茯苓把水排出去，再靠大枣把肠胃的津液补回去，所以七十条是桂枝汤吃太多了。平常不会有这种现象，大部分是下焦有停饮的人，水气比较重停在下焦的人才会有。  \n\n六十九条的情形，会发生在如果吃麻黄汤太过，把肺中的津液伤到，就会产生心下悸；而七十条的情形，会发生在如果吃桂枝汤太过，把肠胃的津液伤到了，就会有脐下悸的现象。', 1, '', '甘草,桂枝甘草,桂枝,', 615060191309893, 'EC3189DB81E2DCA5E25D5D7C5307FE5B', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 09:46:22', 1, '超级管理员', '2024-11-23 10:44:46');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (342, '茯苓桂枝甘草大枣汤', 228, 4, 9040000, '$u{茯苓}$w{半斤}    $u{桂枝}$w{四两。去皮}    $u{甘草}$w{二两。炙}    $u{大枣}$w{十五枚。擘}\n\n	上四味。以$u{甘澜水}$w{一斗}，先煮茯苓，减二升，内诸药，煮取三升，去滓，温服一升，日三服。\n\n     作甘澜水法，取水二斗，置大盆内以杓扬之，水上有珠子五六千颗相逐，取用之。  \n\n     甘澜水就是把水弄出水泡，把水泡拿来用，实际上不用如此，水直接拿来用就可以了。为什么用甘澜水?因为取水的性，最轻飘飘的在上面的水，因为怕桂枝下去的时候，病人会再发汗，因为汗发太过了，希望这津液刚好发在皮肤表面上，不要再发出去了。', 3, '', '茯苓,桂枝,甘草,大枣', 615061776105541, 'F52EEFD0793EF4C9D742DC9CC3931D61', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 09:52:48', 1, '超级管理员', '2024-11-23 11:34:49');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (343, '厚朴生姜半夏甘草人参汤', 229, 5, 9040000, '$u{厚朴}$w{半斤(炙、去皮)}    $u{生姜}$w{半斤、切}    $u{半夏}$w{半升(洗)}    $u{甘草}$w{二两}    $u{人参}$w{一两}\n	上五味、以水一斗、煮取三升、去滓、温服一升、日三服。\n       厚朴用三四钱，就不得了了，生姜开三片就好了，生半夏胖子开三钱，普通开二钱，害他的话，半夏拿掉；人参一钱；平常炙甘草不开多，一二钱就够了，后面的炙甘草汤开到五钱一两都有，那是需要，这里不用开太重，因为炙甘草很甜，会增腻。  ', 3, '', '人参,半夏,甘草,生姜,厚朴', 615063099215941, '6BE472F871B45A5D8D6C9771159C472D', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 09:58:11', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (344, '茯苓桂枝白术甘草汤', 230, 4, 9040000, '$u{茯苓}$w{四两}     $u{桂枝}$w{三两、去皮}    $u{白术} $w{二两}   $u{甘草}$w{二两、炙}\n\n  右四味，以水六升，煮取三升，去滓，分温三服。  \n\n    苓桂朮甘汤是治疗水饮的，因为水已经太多，造成水患了，所以一定重用茯苓，再来是桂枝，再来是白朮。  \n\n  《勿误药室方函口诀》本方条曰：足或腰仍动剧者，卧时则脊骨仍战动，或一身体中经脉跳动，有耳鸣逆上之候者，都可以用此方。平常感觉肌肉跳两下，面皮在跳，这是因为水饮，这时候就可以用苓桂朮甘汤，因为脾主肌肉，也主四肢。  ', 3, '', '茯苓,桂枝,白术,甘草', 615066636804165, '263833A12ABAE01AAE76CEBBE803C0FD', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 10:12:35', 1, '超级管理员', '2024-11-23 11:34:45');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (345, '芍药甘草附子汤', 231, 3, 9040000, '$u{芍药}$w{三两}    $u{甘草}$w{三两、炙}    $u{附子}$w{二枚炮、去皮、破八片}\n	上三味。以水五升。煮取一升五合。去滓。分温三服\n\n      芍药甘草附子汤大多用在素虚的人，平常身体虚缺血的人会用到，平常用白芍两钱，炙甘草两钱，炮附子四钱。临床在用来治疗静脉瘤的时候，芍药用一两，炙甘草也是一两，如果静脉瘤有改善，但还不够快的时候，继续加重白芍，但炙甘草保持二两就好，如果脚是冷的，就加重炮附子，如此同时可以预防心脏病；如果是单纯的脚没有力，原来的芍药甘草附子汤就好了。发汗，病不解，反恶寒，这恶寒的现象，和麻黄汤的现象不一样，麻黄汤是摸病人的身体很烫，但是病人感觉冷，脉很浮，这个恶寒是摸病人身体冷的，病人还怕冷，人在很虚的时候，血不足的时候都会怕冷，这时候用附子去壮阳，因为他阳虚，人在阳虚的时候，阳就是人身上的津液，阴就是血，阳占了百分之六十，阴占了百分之四十，所以发汗发太多的时候，阳虚了，水不足了，水不够了血量也就少了，所以用附子去壮肾，因为肾主水，芍药让血流回心脏的力量加速，炙甘草把肠胃的津液补足，临床上用在脚无力的时候，年纪大的人，常常把附子加在里面，附子用三钱，除非寒很盛，寒很盛的时候，三钱四钱加重上去，如果是膝盖的问题，就可用芍药甘草附子汤，此汤亦名去杖汤。  \n\n       《勿误药室方函口诀》本方条曰：此方不仅治发汗后之恶寒，且治芍药甘草汤证而属于阴位者。又以附子代草乌头，善治虫积痛。有活用于治疝或痛风、鹤膝风等，自痛风以至鹤膝等，有所谓以绵包足之冷者，皆有效。凡下部之冷专在腰者，用苓姜朮甘治之；其专在脚者，用此方治之。腰部和脚的不一样，湿在中焦，腰部用茯苓白朮，所以带脉证，就是带脉 腰酸，下针下临泣，处方就是茯苓白朮甘草生姜，一般性的用生姜，寒比较盛的用干姜，中焦的湿堵在腰间，就用利水的利掉，如果腰好了，膝盖脚踝还有痛，就用芍药甘草附子汤，所以单在脚部的用芍药甘草附子汤就可以了。  \n\n        汤本氏曰：本方可治腰部神经痛、坐骨神经痛、关节强直等。所以此方也可以用在腰椎上，要注意，在腰部以上要加茯苓、白朮，在腿部要重芍药和炙甘草，此方不是用在痛风，是脚冰冷的，血液循环不是很好，妇人病，平常女孩脚冰冷的很多，月经来的时候肚子痛，就是标准的芍药甘草附子汤证，芍药甘草附子汤下去，重用芍药不但止她的腹痛，还让她血从脚底下热起来，再加附子更好。  \n\n          案例：心脏动脉血管堵塞，作心导管，就是气球扩张术，扎三次针好了，气球扩张术，比开刀受伤的程度来的大。两人扎第一次针后，眼翳就都退掉了，所以要靠针。五六十岁以上的人，年龄大的人血管容易破裂，如果破在心脏上方，血会被心脏外面的网膜包住，这很危险的，西医碰到的时侯要病人不要动，五十岁以下的人，遇到血管破裂大多在腹腔里面，防己就可以把血管的膜加固起来，用芍药把血导回去。  ', 3, '', '甘草,芍药,附子', 615070871527493, '7E5EB5797802E94739857A099A6D77FC', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 10:29:49', 1, '超级管理员', '2024-11-23 10:43:45');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (346, '茯苓四逆汤', 232, 5, 9040000, '$u{茯苓}$w{六两}    $u{人参}$w{一两}    $u{附子}$w{一枚(生用。去皮。破八片)}    $u{甘草}$w{二两。炙}    $u{干姜}$w{一两半}\n\n	 右五味，以水五升，煮取三升，去滓，温服七合，日三服。 \n\n    附子、炙甘草、干姜这三味是四逆汤，四逆汤加茯苓人参就是茯苓四逆汤，什么时候用到茯苓四逆汤?发汗或汗下，有使其阴虚者，有使其阳虚者，有使其阴阳两虚者。阴虚者可任其自复，阳虚者用干姜附子汤，阴阳两虚者，用人参四逆汤。发汗以后，表阳很足而里面津液不足的时候，就慢慢等他恢复，伤寒家开的是阳药，很少用补阴的药，如果阴虚阳足的，就是肠胃功能很好，就慢慢等它恢复就好了，如果是阳虚了，用干姜附子汤，如果是阴阳两虚，人参四逆汤，发汗了以后，手脚冰冷脉微弱的就用四逆汤，如果病人有烦躁的现象，烦躁为什么?就是水气往上冲了，人身体虚了，虚热在上面，上焦太热了，津液没有了，下焦的水往上冒，身体又不受，所以就用人参四逆汤加茯苓，把水往下消导，小便排掉就可以了，经方中用药常常补泻兼施，例如金匮肾气丸也是如此；所以张仲景在用四逆汤救逆的时候，病人只要阳在，就不会有事，阳足代表身体肠胃功能还好，吃一吃就补回来了，阳虚了就很 危险，阳不足就代表脏腑的吸收功能不行了，这时候就要用药去控制他，阴阳两虚的时候也需要用，阴阳两虚开四逆汤加人参，也是壮里阳的药，阴的部分用人参去补。  \n\n        在《本草》上写茯苓可以能够利水除烦健脾，常常吃茯苓的话，寿过百岁，用到茯苓  \n\n       四逆汤的时候，病人的手脚都是冰冷的，手冰冷的部位从手指到手肘，脚冰冷的部位从脚指到膝盖，这才叫四逆，如果只冷到手腕与脚踝，只能算是手足冷，还不算四逆；脉都快要断掉了，吐出来的气都是冷的，就是标准的四逆汤证，看嘴巴，嘴巴津液还很足，四逆汤就好了，嘴巴干掉了，也是四逆汤，很烦躁才是茯苓四逆汤。  \n\n       《勿误药室方函口诀》本方条曰：此方以茯苓为君药，以烦躁为目的也。《本草》云茯苓主治烦躁，可谓古义。四逆汤证，汗出而烦躁不止者，非此方不能救。如果没有烦躁，就是人参四逆汤证。  ', 5, '', '干姜,甘草,人参,茯苓,附子', 615074247262277, '5F6F9E1B728D84E1F29C3D4BEDD6B416', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 10:43:33', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (347, '五苓散', 233, 5, 9040000, '$u{猪苓}$w{十八铢、去皮}    $u{泽泻}$w{一两六铢}    $u{白术}$w{十八铢}    $u{茯苓}$w{十八铢}    $u{桂枝}$w{半两、去皮}\n	上五味。捣为末。以白饮和服方寸匕。日三服。多饮煖水。汗出愈。如法将息。\n\n       为末就是打成粉，一次吃一平汤匙，白饮就是很稀的米汤，一天吃三次，吃完后多喝温热水，汗出愈，还有小便会很多。常见病人开中焦肠胃的手术后，病人就会有湿的现象，所以，手术完后病人会有小便不利的现象，这就是五苓散证。  \n\n        小孩脑积水也是靠五苓散来利水，西医讲的视网膜有停水，水在上焦，湿疹，都必须用五苓散来利掉的。晕车的时候，横膈膜的积水，用五苓散也很好用，与苓桂朮甘汤主要的不同，是五苓散没有炙甘草，而且一个用散剂，一个是用汤剂。  \n\n       《伤寒百问经络图》曰：五苓散又治瘴气温疟，不服水土，黄疸或泻；又治中酒恶心，或呕吐痰水，水入便吐，心下痞闷者；所以过去五苓散用在瘟疟，水土不服就是因为脾脏太湿了，所以身体运化系统受到影响。如果吃当地产的东西，就不会水土不服。  \n\n      《三因方》曰：己未年，京师大疫，汗之死，下之死，服五苓散遂愈。此无它，温疫也。  \n\n又：五苓散治伏暑饮热，暑气流入经络，壅溢发衄，或胃气虚，血渗入胃，停饮不散， 吐出一二升许。  \n\n     《直指》曰：五苓散治湿证小便不利，经曰：治湿之法，不利小便，则非其治。所以湿在中焦以下小便解，中焦以上用吐的，吐了还没有口渴，就表示还有湿在里面，吐了口渴就表示不再用吐法了。  ', 3, '', '桂枝,茯苓,白术,泽泻,猪苓', 615080982601797, '8E1859476908EE744093F18EA2013A6E', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 11:10:58', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (348, '茯苓甘草汤', 234, 4, 9040000, '$u{茯苓}$w{二两}    $u{桂枝}$w{二两、去皮}    $u{甘草}$w{一两、炙}    $u{生姜}$w{三两、切}\n	上四味、以水四升、煮取二升、去滓、分温三服。', 3, '', '茯苓,生姜,甘草,桂枝', 615086797094981, 'ED1724CB2DFD577FBB4495585CDC0376', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 11:34:37', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (349, '栀子生姜豉汤', 235, 3, 9040000, '$u{栀子}$w{十四个、擘}    $u{生姜}$w{五两}    $u{香豉}$w{四合(绵裹)}\n	上三味、以水四升、先煮栀子生姜、取二升半、内豉、煮取一升半、去滓、分二服、温进一服、得吐者止后服。', 2, '', '香豉,生姜,栀子', 615092006318149, '718CE8F2A7C313FFCEBF067DE550A955', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 11:55:49', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (350, '栀子豉汤', 236, 2, 9040000, '$u{栀子}$w{十四个、擘}    $u{香豉}$w{四合(绵裹)}\n	上二味、以水四升、先煮栀子、得二升半、内豉煮取一升半、去滓、分为二服。温进一服、得吐者止后服。\n栀子一般五钱，豆豉也是五钱，不要把豆豉煮烂掉了，所以先煮栀子。  ', 2, '', '豉,栀子', 615092617191493, '9516C588B96C80B71E5326F2436B6EF8', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 11:58:18', 1, '超级管理员', '2024-11-23 14:15:50');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (351, '栀子甘草豉汤', 237, 3, 9040000, '$u{栀子}$w{十四个、擘}    $u{甘草}$w{二两、炙}    $u{香豉}$w{四合(绵裹)}\n	右三味，以水四升，先煮栀子、甘草得二升半，内豉，煮取一升半，去滓，分温二服。  \n\n栀子用五钱，甘草二钱，豆豉也是五钱。  \n\n     这汤剂是用在病人食物中毒，吃坏肚子了以后，造成的胃肠不适，造成吐，如果因为食物引起的问题，只有吐没有下利的时候，就用栀子甘草豉汤，如果有下利，这汤剂就没有效了，就应该用葛芩连汤。一般来说上吐下泻，一定是热证，也就发炎了。  \n\n    《千金方》本方条曰：栀子甘草豉汤方，治食宿饭、陈羹、臭肉、宿菜而发者。  \n', 2, '', '栀子,甘草,豉', 615093428678725, '21EF8A34AE24823C6BFEE56C3C1CDDE1', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 12:01:36', 1, '超级管理员', '2024-11-23 14:15:45');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (352, '栀子厚朴枳实汤', 238, 3, 9040000, '$u{栀子}$w{十四个、擘}    $u{厚朴}$w{四两(炙、去皮)}    $u{枳实}$w{四合}\n        右三味，以水三升半，煮取一升半，去滓，分二服。  \n       枳实厚朴的量一样，栀子用五六钱，枳实用四钱，厚朴也用四钱。本方的主证是虚烦腹满。\n       厚朴生姜半夏甘草人参汤和承气汤是表里，一个是虚满，一个是实满；此条还有卧起不安的现象，这是属于病后调理的药，会用到这药都是生完病或生的中间，因为肠胃的吸收力不是很强，造成有虚但是又看到部分的实的状况下用的汤剂。  ', 2, '', '枳实,厚朴,栀子', 615126369960005, '064101F63F9F37C7B3A5EB4B8D01CEB4', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 14:15:38', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (353, '栀子干姜豉汤', 239, 3, 9040000, '$u{栀子}$w{十四枚、擘}    $u{干姜}$w{二两}  $u{香豉}$w{四合} \n      右三味，以水三升，煮取一升半，去滓，分二服。', 2, '', '豉,干姜,栀子', 615128744296517, '182BED595A2DEE536A479CF975A47A67', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 14:25:18', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (354, '真武汤', 240, 5, 9040000, '$u{茯苓}    $u{芍药}    $u{生姜}$w{各三两(切)}    $u{白术}$w{二两}    $u{附子}$w{一枚(炮。去皮。破八片)}\n\n	右五味。以水八升。煮取三升。去滓。温服七合。日三服。\n\n        白朮和附子和桂枝汤的关系，桂枝汤喝下去，能够壮脾阳，加上白朮能够健脾去湿，附子能够收阳，能够壮阳同时收它的浮阳，阳浮在表面上，要收它的浮阳靠附子，让阳归根，所以在四逆汤的时候用附子，会用到四逆汤的时候，是很危急的，人都冰冷掉了，快绝了，身体的动能快没了，附子一下去，能把它全收回来，附子就是这功能，所以脑中风，头部、脑出血的时候，常常用到这药；因为白朮这药能够收敛，让血跑回血管里面，附子一下去能把血降下来；有的时候，白朮附子单两味在用，这是发脓疡，如果脓疮生在皮肤表面上，把脓挤掉就好了；脓疮如果生在很里面，在淋巴结的下方很深的地方，如果不去掉，它可能会扩散或烂上来，这时候的汤剂，看它那个位置上，都会加白朮附子在里面，这两味能把很深的脓发到表面上来，所以过去治疗癌症，初期硬块，加白朮附子在里面，因为附子的力量很强，一吃我们的体能就会变得很强，把不干净的往皮肤表面上推，怕里面化脓发炎，所以利用白朮把湿去掉，露出来的只是一个头而已，不会扩散，伤口黏黏稠稠的会化脓，所以要加去湿的药，因此癌症的时候，常常用到白朮附子。  \n\n        真武汤为什么用白芍?因为身瞤动的时候，肌肉组织四肢上面的血的力量已经不够了，循环力量不够了，没有办法完全滋润四肢肌肉，用白芍把血流回心脏，所以靠白芍把全身的血脉打通，《本草》里面写白芍能通血痹，何谓通血痹?就是血液循环不好，靠白芍把它加强，所以妇人的腹痛、月经痛都是用白芍，所以当归芍药散在经方里面很有名。子宫瘀血，西医叫子宫内膜异位，其实是血块在里面而已，芍药能通血痹，就是血瘀积到的地方。芍药能够破瘀，救逆的时候用芍药甘草附子汤，靠附子发散的力量，让芍药把它往回收来。为什么加生姜?因为有心下悸，中间有水饮在里面，加生姜茯苓让它散开来，然后利小便出来。真武汤是镇水用的，为什么叫真武?是个神明的名字，玄武就是真武，是镇水的名称。真武平常用在老人利尿，年龄大的人晚上小便次数多，给西医检查说摄护腺肥大，所以老人夜尿多，肾脏功能不足的时候，可以用此汤方。  \n\n茯苓用的比白朮多，所以真武汤是利尿剂，加重茯苓的量，茯苓要比白朮多，才能把水排出去，平常茯苓白朮等量在用的。附子用炮附子，炮附子可以温阳化水，用来把水的温度增加，然后用芍药生姜来补虚，如此就能利尿。这里因为要排水，所以不用甘草。治疗水肿病的时候，尽量不用甘草。  \n\n        茯苓桂枝白朮甘草汤所谓发汗则动经，身振振而摇是也，治疗中焦胸膈间的水饮。此表里上下俱虚之候，故与真武汤以复其阳，以行其水也。这是上下表里通通虚掉了，所以真武汤证在人很虚弱的，年纪大的人可以看到。  \n\n       仲师心法，阳虚者必先救阳。故以附子回阳，则振振欲擗地者可已；以茯苓化水，则心 下悸、头眩可已；以白朮助吸收水饮，协同茯苓化水气，协同附子以温中达四肢，以芍药、生姜温通血痹，则身瞤可已。脑中风瘀血的时候，常常桂枝用三，芍药用到六，因为血离开了血脉，加重芍药的量让血马上回到心脏；所谓附子能收阳，就是附子能把血管的破洞愈合得很快。  \n\n      《伤寒绪论》曰：凡不得眠者，皆为阳盛，切忌温药，惟汗吐下后，虚烦、脉浮弱者，因津液内竭，则当从权，用真武汤温之。平常不得眠都不用热药，用寒凉的药，有的人是津液虚掉了，才可以用真武汤。  \n\n    《易简方》曰：真武汤不惟阴证伤寒为当服，若虚劳之人，憎寒壮热，咳嗽下利，皆宜服之。  \n\n      如果露营的时候，晚上吹山风，又喝冷的，一下子剧冷，出来就是真武汤证，体能好的不会得到真武汤证，体虚的人早上起来，头很重，就是得到真武汤证，这时候阳虚掉了，真武汤本身很热，所以开真武汤吃。大部分的年轻人得到真武汤证，都是行房事太多，行完房事之后冷浴，又喝冷的，又吹冷气，第二天就变成真武汤证，桂枝汤都来不及，马上变成少阴证，平常看到的多是老年人，男女都可以用。  \n\n        体质素为中湿之人，常自汗出，常晕眩，此时用苓桂朮甘汤无法利水出去的，这时候也要用真武汤；肌肉常瞤动也是用真武汤。遇到晕眩的人，如果只是中膈有水，用苓桂朮甘汤；遇到寒湿的人，就是用真武汤。怎么知道病人有寒湿，脉比较细小而迟，口不渴、没胃口，因为湿伤于下，所以脚冷而无力，而且膝盖骨可能会痛；我们由黄帝外经的骨阴论可知，膝盖骨、囟骨、耳后完骨都属于阴气所生，所以当湿伤于下的时候，下方的阴骨也就是膝盖骨会被伤到。\n', 3, '', '附子,白术,生姜,芍药,茯苓', 615134292865093, 'F2D3560DD77A77106D2893457823F714', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 14:47:53', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (355, '禹余粮丸', 241, 6, 9040000, '$m{禹余粮丸方已失传} (佚)$n{以下内容有待考证}\n$u{禹余粮}$w{四两|  $u{人参}$w{三两}    $u{附子}$w{二枚}   $u{五味子}$w{三合}   $u{茯苓}$w{三两}   $u{干姜}$w{三两} \n右六味,蜜为丸,如梧子大,每服二十丸。 ', 1, '', '干姜,茯苓,五味子,附子,人参,禹余粮干姜,茯苓,五味子,附子,人参,禹余粮干姜,茯苓,五味子,附子,人参,禹余粮干姜,茯苓,五味子,附子,人参,禹余粮干姜,茯苓,五味子,附子,人参,禹余粮干姜,茯苓,五味子,附子,人参,禹余粮,', 615142359507013, '3AEF2901E9E201223364316840034528', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 15:20:42', 1, '超级管理员', '2024-11-23 15:28:18');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (356, '小建中汤', 242, 6, 9040000, '$u{桂枝}$w{三两、去皮}    $u{甘草}$w{二两、炙}    $u{大枣}$w{十二枚、擘}    $u{芍药}$w{六两}    $u{生姜}$w{三两、切}    $u{胶饴}$w{一升}\n	右六味、以水七升、煮取三升、去滓、内饴、更上微火消解、温服一升、日三服、呕家不可用建中汤、以甜故也。\n\n       呕家不可用建中汤，因为太甜了，桂枝汤里面加炙甘草已经够甜了，再加饴糖更甜，平常喜呕的人、抽烟的人、喝酒的人，小建中汤喝下去，他不收的，因为肠胃太虚寒了，小建中汤下去马上吐，因为如果胃是寒的，甜的东西停在胃里面，甜的马上变成酸的，甘的东西很容易变酸的，所以他不喜欢。  \n\n      《苏沉良方》本方条曰：此药治腹痛如神，然腹痛，按之欲便痛，重按之却不甚痛，此为气痛；重按则欲痛而坚者，当自有积也。气腹痛不可下，下之则愈甚，此虚寒证也。此方偏治腹中虚寒，补血，尤治腹痛。如果是实证有东西堵到，绝不可用小建中汤，所以小建中汤是专门治虚寒的腹痛。\n', 3, '', '胶饴,生姜,大枣,甘草,芍药,桂枝', 615163349323845, '4DA404BB43D828CC02005AFB299A533F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 16:46:07', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (357, '大柴胡汤', 243, 8, 9040000, '$u{柴胡}$w{半斤}    $u{黄芩}$w{三两}    $u{芍药}$w{三两}    $u{半夏}$w{半升(洗)}    $u{生姜}$w{五两、切}    $u{枳实}$w{四两、炙}    $u{大枣}$w{十二枚、擘} $u{大黄}$w{二钱}\n	右八味，以水一斗二升，煮取六升，去滓，再煎，取三升，温服一升，日三服。  \n\n       大黄，胖子用二钱，瘦的人用一钱就好了，柴胡、黄芩、半夏、生姜、大枣这是小柴胡汤的方子，少了人参甘草，再放芍药、枳实、大黄就大柴胡汤，枳实这药也是能宽肠的药，和厚朴一样，枳实比较重于宽大肠，厚朴比较重于滋润小肠，大肠和肺是表里，所以大肠堵到的时候用枳实，胸腔堵到、心脏积水也用枳实，枳实这药专门能去结毒，结到的毒、硬块它能把它排掉，实际在用的时候发现到，当大肠的肠壁和大便黏在一起的时候，枳实可把肠壁推开，但只能让它们分开，如果枳实把它清出来就不需要加大黄芒硝了，所以枳实本身并没有攻下的功能，它能把结分开来，必须要靠别的药把它通出来，所以心脏的动脉血管堵塞的时候，用枳实，但是枳实只是把动脉血管里面堵塞的东西与血管壁分开来，所以张仲景还加桂枝，桂枝让心脏动脉血管往外冲的力量加强，喷射的力量加大；怕胃受不了再加生姜在里面，让胃热力散一点，不要太集中在心脏，怕心脏受不了，血管会破裂；因为腹满，肚子胀满，少腹会痛，所以加芍药；大柴胡汤里面如果没有加大黄，就不叫大柴胡汤，因为病已经进入少阳、阳明了，又不是纯阳明证，所以用不到芒硝这样强的药，用大黄把阳明热清出来就好了；大柴胡汤即小柴胡汤去参、草加枳实、大黄、芍药也。以阳明实热不适用参、草补虚之品，因为阳明证已经进入肠子了，不要用甘草再把药停在胃中间，阳明实热，胃火已经很大了，所以不可能加人参；胃中热结，则非枳实不能破其结，非大黄不能下其热，芍药则舒心下之急；但阳明虽结而少阳未罢，柴胡汤又不可不用，故在此方为双解少阳、阳明之剂。所以常常问病人恶不恶心，会恶心就是少阳，恶心加胀满就是大柴胡，肚子不满会恶心就是小柴胡；黄芩、芍药是等量的，枳实要重用，大黄开的比枳实少，如果没有加枳实，只用大黄，肚子会绞痛，因为大黄会硬把肠壁拉开来，因为肠壁没有津液了，枳实下去会产生津液。  \n\n王叔和曰：若不用大黄，恐不名大柴胡汤。  \n\n《类聚方广义》本方条曰：平日心思郁塞，胸满少食，大便二三日或四五日一行，心下时时作痛，吐宿水者，其心大多胸胁烦胀，肩项强急，脐旁大筋坚韧，上入胸肋上，下连小腹，或痛或否按则挛痛，或兼吞酸、嘈杂等症者，俗称疝积留饮痛，宜长服此方，隔五日或十日，常用大陷胸汤或十枣汤攻之；眼目云翳，或赤眼疼痛，胸胁苦满，所以眼睛是属于少阳证，开白内障的处方的时候，用大柴胡汤来作加减；如果眼睛是赤痛红肿，是太阳证，葛根汤来作加减；如果眼睛生翳就是靠柴胡来作加减。大便燥结者，加芒硝为佳，如果大便攻不出来，就要靠芒硝把它打散，大肠比较大，到直肠的时候比较小，大便到直肠如果硬会堵到，吃了大柴胡没有大便，就加点芒硝把硬的大便打散掉，一般会有这种现象的，大多是年龄大的人，身体虚弱的人会看到。遇到对证的时候，用到大黄芒硝来攻下，对病人来说大黄芒硝就是补药，应该攻坚的时候，不能手软，这就是急下存阴的概念。  \n\n    百疢一贯曰：龟胸龟背，大多原由于毒，这毒就是浊痰，凡龟胸后必成龟背，用大柴胡汤治之。重者用大陷胸汤之类，随证不同。  \n\n       《伤寒绪论》曰：潮热，而胁下汗出者为胆实，用大柴胡汤；手足心汗出者为胃实，用大承气汤。这是分辨纯阳明证跟兼有少阳证的时候，腋下一直流汗流很多，就是三焦系统，也就是大柴胡汤证，如果手掌汗流很多的，手上的止汗点，背后的第五椎外开五分的地方华佗夹脊，直针下针可以止汗；如果病人是阳明热，大便正常，舌头伸出来苔是黄的，就是白虎汤，如果大便不通，就用承气汤攻。  ', 3, '', '大黄,大枣,枳实,生姜,半夏,芍药,黄芩,柴胡', 615167477493829, '97D64F2770CA5481A958B446E4C752A8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 17:02:54', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (358, '柴胡加芒硝汤', 244, 8, 9040000, '$u{柴胡}$w{二两十六铢}    $u{黄芩}$w{一两}    $u{人参}$w{一两}    $u{甘草}$w{一两。炙}    $u{生姜}$w{一两。切}    $u{半夏}$w{二十铢、洗}    $u{大枣}$w{十二枚、擘}    $u{芒硝}$w{二两}\n	右八味、以水四升、煮取二升、去滓、纳芒硝。更微煮沸、分温再服、不解更作。\n\n       芒硝使用的时候，是生用，一次一钱就够了；汤药煮好了以后，芒硝冲服，不用再煮；严重的时候，一次用到两钱都可以。病人小便颜色有深黄变成淡黄色的时候，就不要再攻下了。', 2, '', '大枣,芒硝,半夏,生姜,甘草,人参,黄芩,柴胡', 615174153834565, 'A948D8CF316840F4ED3566063C15AA50', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-23 17:30:04', 1, '超级管理员', '2024-11-23 17:30:49');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (359, '桃核承气汤', 245, 5, 9040000, '$u{桃仁}$w{五十个、去皮尖}    $u{大黄}$w{四两}    $u{桂枝}$w{二两、去皮}    $u{甘草}$w{二两、炙}    $u{芒硝}$w{二两}\n	右五味。以水七升。煮取二升半。去滓。内芒硝。更上火。微沸下火。先食。温服五合。日三服。当微利。\n脉当为沉涩，或弦细；舌则红中带紫，苔或白或黄。脉以涩细，舌以紫青，为瘀血之候。  ', 5, '', '芒硝,甘草,桂枝,大黄,桃仁', 615771152941125, '4F0FC297FB1469A21FBD07B4D40793FA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-25 09:59:16', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (360, '柴胡加龙骨牡蛎汤', 246, 11, 9040000, '$u{半夏}$w{二合、洗}  $u{大枣}$w{六枚}  $u{柴胡}$w{四两 } $u{生姜}$w{一两半}  $u{人参}$w{一两半}  $u{龙骨}$w{一两半} $u{铅丹}$w{一两半}  $u{桂枝}$w{一两半、去皮}      $u{茯苓}$w{一两半}  $u{大黄}$w{二两}    $u{牡蛎}$w{一两半} \n	右十一味、以水八升、煮取四升、纳大黄、切如碁（棋）子大、更煮一两沸、去滓、温服一升。\n\n      除了大黄、半夏、红枣以外，其它都等重，因为是半表半里都有，解表攻里同时并进的，一剂药同时把它去掉，过去有些书上写柴胡加龙骨牡蛎汤有加黄芩在里面，有开$m{黄芩}就是$n{嘴巴里面有燥苦，口苦的时候，兼有少阳证的时候，会用黄芩}；柴胡加龙骨牡蛎汤是很好治疗失眠的汤剂，是虚的人吃的；如果失眠是到了晚上但头汗出，常常五六天不大便，舌头又干 又燥，这人是阳明燥屎，不可以吃柴胡加龙骨牡蛎汤；所谓$m{阴虚}的人是$n{肠胃津液不足}，兼有下利而引起；现在买的柴胡加龙骨牡蛎汤的药粉，里面没有铅丹的，都用茯苓代替了，所以开的时候，没有加铅丹也没有关系。  \n\n        龙骨牡蛎有潜阳的功用，常人阳气足的时候，手脚是温热的、额头冷的，手掌、脚掌是热的，手背脚背比较凉，四肢是胃气反映的地方。如果手脚温热而且出汗、大便秘结，这是阳气过盛，我们用承气汤攻下就好了；但如果是虚热的体质，没有便秘，手脚常出汗，就是用龙骨牡蛎。所谓的阳要潜在阴里面，就是说人体的皮表乃太阳寒水所主，把热包在里面，也就是皮表是凉的，里面是热的，不怕冷，这是正常。龙骨与牡蛎潜阳收敛的作用有小差异，当失津的时候，我们用龙骨；如果是失精的时候，我们用牡蛎。所以小朋友夜尿多的时候，因为夜尿是失津，所以用到龙骨牡蛎的时候，龙骨可以多一点；反之如果是大人有遗精的症状，我们用龙骨牡蛎的时候，牡蛎要加重一点。  ', 4, '', '半夏,大枣,柴胡,生姜,人参,龙骨,铅丹,桂枝,茯苓,大黄,牡蛎', 615779363188805, '01B051302B6DD95BE6A27A4111182862', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-25 10:32:41', 1, '超级管理员', '2024-11-25 10:32:52');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (361, '桂枝去芍药加蜀漆龙骨牡蛎救逆汤', 247, 7, 9040000, ' $u{桂枝}$w{三两、去皮}，$u{甘草}$w{二两、炙}，$u{生姜}$w{三两}，$u{牡蛎}$w{五两，熬}，$u{龙骨}$w{四两}，$u{大枣}$w{十二枚}，$u{蜀漆}$w{三两、洗去腥}\n	右为末，以水一斗二升，先煮蜀漆，减二升，纳诸药，煮取三升，去滓，温服一升。  \n\n      现在蜀漆用常山苗代替，其实蜀漆和常山苗是不一样的，因为市面上买不到蜀漆，蜀漆就是一种长在四川的漆树其皮的内层，蜀漆在白铁板上烧，烟有毒，把烟去掉才能入药。蜀漆去痰的力量很强，受惊吓的时候，容易有痰涎壅塞，我们用蜀漆把痰去掉。  \n\n      勿误药室方函口诀本方条曰：此方主火邪，故烫火伤之疼痛烦闷者及灸疮发热者有效。以牡蛎一味，麻油调涂烫火伤，则火毒忽去，其效可推之矣。一般只是热可以，有湿化脓发炎的时候就没有办法了。 \n\n       外敷：过去用牡蛎打粉，磨得很细，加麻油，更好的用硫磺、大黄，硫磺就是在火山口的东西，硫磺本身外用时非常的寒凉，西医就把硫磺跟膏药一起用，变成硫磺膏、中医把硫磺、大黄、麻油配在一起用，如果是皮肤红肿这药就可以了，起水泡的时候要加菖蒲在里面，菖蒲是皮肤表面利水的大剂，菖蒲就是灌木类的水草，把这草晒干烧成灰，这灰敷在皮肤表面上，一敷上去，就开始去水，病人会小便，如果化脓了，就是变成湿了，就要加白朮；如果已经发炎了，就加黄芩，这就是加减；西医的硫磺膏只能去热，不能去水去湿。为什么要赶快去水?因为水绷久了，皮肤就会皱掉，会有疤难看。  \n', 3, '', '蜀漆,龙骨,大枣,生姜,甘草,桂枝,牡蛎', 615790236577861, 'A8C796927FED2938CC5A8AAEA251618D', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-25 11:16:55', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (362, '桂枝加桂汤', 248, 5, 9040000, '$u{桂枝}$w{五两、去皮}    $u{芍药}$w{三两}    $u{生姜}$w{三两。切}    $u{甘草}$w{二两、炙}    $u{大枣}$w{十二枚、擘}\n	右五味。以水七升。煮取三升。去滓。温服一升。【本云桂枝汤。今加桂满五两所以加桂者。以能泄奔豚气也。】\n\n即桂枝汤加桂枝二两  \n这汤剂争议很多，有的赞成桂枝，有的赞成肉桂，但临床上看，肉桂极有效，用桂枝汤加肉桂，肉桂用五分，严重的用八分，不需要用到一钱，因为会太辣了\n', 5, '', '大枣,生姜,甘草,芍药,桂枝', 615798159966277, '76B110C99D9A5B3C02728BD38A8A3A27', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-25 11:49:10', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (363, '桂苓甘草龙骨牡蛎汤', 249, 5, 9040000, '$u{桂枝}$w{一两、去皮}    $u{甘草}$w{二两、炙}    $u{牡蛎}$w{一两(熬)}    $u{龙骨}$w{二两}  $u{茯苓}$w{四两}\n右五味为末,以水五升,煮取二升半,去滓,温服八合,日三服。 \n        像一般发烦、悸、伯金森氏病，都会用到桂枝茯苓甘草龙骨牡蛎汤，像心悸、动悸、手抖心颤、盗汗，都要想到腺体的问题，但是不要和小柴胡汤证弄错了，小柴胡汤药一定有恶心，呕，什么症状都没有，只要有恶心就是小柴胡汤证，上吐就用小柴胡汤，下泻就加一些止泻的药在里面，小柴胡汤证往来寒热现象比较明显。晚上燥热得很厉害，因为血太旺了，血里面的热太高了，津液没了，因为津液一直丧失，血里面的水越来越少，血的温度就越来越高，所以大脖子的人，晚上睡觉的时候，不用盖被子就会很热，这是身体体能一直在丧失的现象。临床上最主要的是津液，技巧就在剂量的加减。  ', 3, '', '茯苓,龙骨,牡蛎,甘草,桂枝', 615834697601093, '553D2407A38A70A6B3CC6D49F3B36364', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-25 14:17:50', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (364, '抵当汤', 250, 4, 9040000, '$u{水蛭}$w{(熬)}    $u{虻虫}$w{各三十个(去翅足。熬)}    $u{桃仁}$w{二十个。去皮尖}    $u{大黄}$w{三两($u{酒}洗)}\n   右四味，以水五升，煮取三升，去滓，温服一升，不下再服。  ', 3, '', '大黄,桃仁,水蛭,虻虫', 615858390286405, 'FF58F0EC87AA373B1A46CE8CE6D876B6', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-25 15:54:14', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (365, '抵当丸', 251, 4, 9040000, '$u{水蛭}$w{二十个(熬)}    $u{虻虫}$w{二十五个(去翅足。熬)}    $u{桃仁}$w{二十个。去皮尖}    $u{大黄}$w{三两、酒浸}\n\n       右四味，杵分为四丸，以水一升，煮一丸，取七合服之，晬时当下血，若不下者，更服。  \n\n      桃仁很黏，水蛭捣碎也是很黏，分成四个丸，一般水蛭二十个大约二钱，虻虫二十五个差不多两钱半，桃仁二十个两钱，大黄三钱。$m{晬时}$n{(即一周时。指一天的某一时辰至次日的同一时辰)}就是今天吃下去后，最少二十四个小时，当下血，如果没有下血再吃，有下血就不用吃了，一次吃一丸就好了。每个人瘀血的量不一样，吃的处方一样，但是剂量不一样，吃到了就停下来。  \n\n         《类聚方广义》本方条曰：余家用此方，取右四味为末，炼蜜为丸，用生蜂蜜就会加强效果，又曰：产后恶漏不尽，凝结为块，成宿患者，平素虽服药，然当难收效，其后再有分娩，用此方服之，不过十日，块可尽消。  ', 4, '', '水蛭,虻虫,桃仁,大黄', 616114803896389, '31904B504A59647152A8A1C4B6196A4C', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 09:17:35', 1, '超级管理员', '2024-11-26 09:17:57');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (366, '大陷胸丸', 252, 6, 9040000, '$u{大黄}$w{半斤}    $u{葶苈子}$w{半升(熬)}    $u{芒硝}$w{半升}    $u{杏仁}$w{半升(去皮尖、熬黑)}\n	右四味。捣筛二味。内杏仁。芒硝。合研如脂。和散。取如弹丸一枚。别捣$u{甘遂末}$w{末一钱匕}    $u{白蜜}$w{二合}。水二升。煮取一升。温顿服之。一宿乃下。如不下。更服。取下为效。禁如药法。\n\n        杏仁放在锅里面炒一下就黑了，表皮黑了，一点焦无妨，放磁碗内一磨成霜，把大黄、葶苈子倒下去，成弹丸大；别捣甘遂末一钱匕，本草里面最强的排水的药有甘遂、芫花、大戟，拿甘遂放蜂蜜下去，两碗水煮一碗，温服，下的时候病人有吐也有下，大便出来的都看不到便，都是痰。  \n\n      大陷胸汤和大陷胸丸的区分：如果病人有壮热，像乳痈、肺癌到末期的时候，肺里面长东西，有壮热的时候用大陷胸汤，无大热的时候用大陷胸丸。如山田氏云：凡结胸有热者，用大陷胸汤下之；其无热者，宜用大陷胸丸下之。  \n\n    《金鉴》曰：大陷胸丸治水肿、肠澼初起，形气俱实者。  \n\n    《类聚方广义》本方条曰：东洞先生晚年，以大陷胸汤为丸用之，一如理中、抵当二丸，泻下之力颇峻。然若毒聚胸背，喘鸣咳嗽，项背共痛者，则以此方为胜。如龟背、鸡胸，胸部突然凸起来，其实里面全部都是痰堵在里面，像桔梗、半夏都是去痰的药，这时候都不够力了，水混在痰里面，热又梗在一起，所以一定要用葶苈。', 3, '', '大黄,葶苈子,芒硝,杏仁', 616128993783877, 'B1134A811C1F8759865B5C92243A1A84', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 10:15:20', 1, '超级管理员', '2024-11-26 10:17:32');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (367, '大陷胸汤', 253, 3, 9040000, '$u{大黄}$w{六两。去皮}    $u{芒硝}$w{一升}    $u{甘遂}$w{一钱}\n	上三味，以水六升，先煮大黄，取二升，去滓，纳芒硝，煮一二沸，纳甘遂末，温服一升，得快利，止后服。  \n\n       大陷胸汤的方剂比大陷胸丸更少了，大黄三钱，芒硝五钱，甘遂五分生用，五分剂量差不多是小塑料勺一勺，如果结得很厉害的时候要加重，有时候加到二勺三勺，平常大部分二勺就到了，很少用到三勺，像西医讲的急性肺扩张，肺突然的膨胀起来，或是肠梗到，麻痹 性的肠梗阻，都是中医讲的大陷胸汤证，所以是热实结胸，如果热实结在肠中，就是大承气汤证，现在梗在上焦就是大陷胸汤，大陷胸汤与大陷胸丸有一个明显差异，大陷胸汤的痞硬而痛是从心下往下到少腹的关元穴附近；而大陷胸丸的痞硬而痛是从心下往上走，所以用丸剂，不然汤药走太快，一下子跑到下焦去了。  \n\n用六碗水先煮大黄，煮成二碗，大黄的滓去掉，纳芒硝滚一二下就好了，再拿甘遂粉倒进去，所以甘遂生用的，先喝一碗，如果喝一碗没有上吐下泻再喝，一般来说差不多隔六小时，如果又吐又泻就不用再喝了，如果光吃大黄芒硝，一下子就里急后重，但是如果加甘遂下去，就是喝大陷胸汤的感觉，喝到胃里面就不走了，药往上走，里面好像打仗一样，等到你感觉药力往下走，大出来的全部是痰没有大便，因为肺和大肠是表里的，为什么加了甘遂，痰全部从大肠出来，而不是从肺出来?因为痰渗入膈膜，再进入三焦，再渗入大肠出来，渗出来的。药力大约持续三小时，泻下的时候是从大便出来，好像水龙头打开一样泄出来，病人家属很紧张，但是病人本身拉出来以后精神变好，觉得很舒服。  \n\n     《类聚方广义》本方条曰：小儿急惊风，胸满心下石鞕，心下就是胃的地方硬硬的，咽喉痰潮，痰潮壅塞，直视惊挛，像脑膜炎眼睛都瞪直了，胸动如奔马者，呼吸就很痛很快。  \n\n   《古方便览》曰：胸高起，或背曲成痀瘘之状，或腹内陷下濡而牵引及背，脚细软羸瘦而不能步行，手臂不遂者，皆治之。过去陷胸汤临床上看的时候，包括小儿麻痹发壮热的时候都是大陷胸汤证，壮热来的时候，整个水痰热积在肺上面的时候，结果脑神经烧坏掉了，这都是大陷胸汤证。  \n\n     《勿误药室方函口诀》本方条曰：此方治热实结胸之主药，其它凡胸痛剧者，尤有特效。凡医者临死地，不可无此手段。又因留饮而肩背凝痛者，有速效。小儿患龟背等，亦有用此方者；小孩背弯起来，其实里面都是痰，全部梗在那地方，有时候梗在胸口，有时候绷起来一块，其轻者，宜用大陷胸丸。又小儿将成鸡胸时，宜及早用此方，以收速效。  ', 2, '', '大黄,芒硝,甘遂', 616133402157125, '6D2B84D9DD7825B6147BF946BAA2ED29', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 10:33:16', 1, '超级管理员', '2024-11-26 10:33:27');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (368, '小陷胸汤', 254, 3, 9040000, '$u{黄连}$w{一两}    $u{半夏}$w{半升(洗)}    $u{栝楼实}$w{大者一枚}\n	右三味，以水六升，先煮栝楼，取三升去滓，纳诸药，煮取二升，去滓，分温三服． \n \n       黄连用一钱，半夏、栝蒌实的量相等用五钱，小陷胸汤专门去痰结在胸中有呕者，病人很恶心，恶出来的是痰，病人并不会咳嗽，痰梗在胸里面，中医叫痰积。临床上看到最多的是抽烟的人常常得到这种病，只要一得到感冒后．再误下马上就梗到了。临床上不一定结胸的病人才用到小陷胸汤，遇到胃不舒服的病人，舌苔黄而厚，确定胃是热的，吐痰很多，就可以用了。  \n\n      内经提过，肾欲坚，急食苦以坚之临床上遇到尿毒的病人，我们也会用到黄连来解毒，所以黄连可以坚肾，预防毒素入心。 ', 3, '', '栝楼实,黄连,半夏', 616141134766149, 'ABE15581FA424D1567EC5C6ADC667D58', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 11:04:44', 1, '超级管理员', '2024-11-26 11:05:45');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (369, '文蛤散', 255, 1, 9040000, '$u{文蛤}$w{五两}\n	右一味，为散，以沸汤和一钱匕服，汤用五合。  \n\n      文蛤用五钱就好了，到菜场的时候买海水的文蛤，黄黄的上面有黑条纹的比较大的、打粉，平常小便不是很好的吃一吃没关系，打碎后磨成细末，一钱匕就是喝汤的汤匙一平匙、用滚水冲，汤用五合。为什么要喝这么多水？就是把水利出来。病重一点的文蛤散就不行了，所以文蛤散用得不多，大多用五苓散。  \n\n        与文蛤类似的还有牡蛎和瓦楞子，因为咸能软坚，所以这两味药也是攻坚用的，像牡蛎可以用在甲状腺肿或是淋巴肿大；至于瓦楞子就是菜市场能看到的血蚶的外壳，形状表面象旧式瓦房屋顶的瓦垄，所以称为瓦楞子，因为形状也像乳房，所以用来攻乳房附近的肿块。 ', 3, '', '文蛤', 616148958859333, '559110018C0E030BE834E7D47A61ED41', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 11:36:34', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (370, '三物小白散', 256, 3, 9040000, '$u{桔梗}$w{三分}    $u{巴豆}$w{一分(去皮心、熬黑、研如脂)}    $u{贝母}$w{三分}\n	右三味、为散、纳巴豆。更于臼中杵之。以白饮和服。强人半钱匕。羸者减之。病在膈上必吐。在膈下必利。不利。进热粥一杯。利过不止。进冷粥一杯。身热皮粟不解。欲引衣自覆。若以水潠之、洗之。益令热却不得出。当汗而不汗则烦。假令汗出已。腹中痛。与$u{芍药}$w{三两}。如上法。\n\n        白饮就是米汤，强人半钱匕，就是半个汤匙，三味药加起来半汤匙，差不多三比一比三，桔梗三、巴豆一、贝母三，羸者减之，瘦的人还要减半。病在膈上必吐，病在膈下必利。如果不利，再吃热稀饭就好了，不要再吃药，如果利不止，吃冷稀饭就好了，或者是黄连也可以、冷豆浆也可以。如果病人感觉身冷鸡皮疙瘩，这时候不要用水去喷他，休息就好了。如果病人吃了巴豆后肚子痛，重用芍药三两，这时候不要用三钱，用三两，单味的芍药去熬汤吃，就能把巴豆的毒解掉。  \n\n        《类聚方广义》本条曰：此方不仅治肺痈，就是肺里面化脓疡，且治痈疽，看不到的脓肿、肿块、硬块，胃酸；胃里面化脓长瘤，及胸膈中有顽痰，胸背牵痛者。又咳家胶痰缠扰，咽喉不利，气息有臭者，皆有效。就是结得很盛的时候可以用，但是要确定是寒实，才可以用。卒中风，马脾风，痰潮息迫，牙关紧闭，药汁不入者，取少许吹鼻中，则吐痰涎而咽喉立适。突然中风的时候，痰上来很多，西医在天突的地方开一个洞，牙关紧闭药都进不去，所以药要用喷的，痰从嘴巴、鼻子出来，一下去人就醒过来了，所以三物小白散在用的时候，如果病在胸膈以上一定是吐出来的，如果病在胸膈以下一定是下利的，就是胃以上、食道里面的一定会吐出来，已经下去的全都会排出来。  ', 1, '', '贝母,巴豆,桔梗', 616152787284037, '0C4E51513C8A975B3A1293032DE1E64D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 11:52:09', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (371, '柴胡桂枝汤', 257, 9, 9040000, '$u{桂枝}$w{去皮}    $u{芍药}$w{一两半}    $u{黄芩}$w{一两半}    $u{人参}$w{一两半}    $u{甘草}$w{一两。炙}    $u{半夏}$w{二合半(洗)}    $u{生姜}$w{一两半。切}    $u{大枣}$w{六枚。擘}    $u{柴胡}$w{四两}\n      右九味,以水七升,煮取三升,去滓,温服。\n\n       有太阳少阳证的时候,不能把太阳的药开太重,而少阳的药要加重,所以柴胡四钱以上,桂枝一钱半,芍药也用一钱半,如果桂枝开得重,药一下去,马上就到肌肉去了,太快了,所以柴胡加重,少阳的热靠柴胡推出去,把少阳的热推到太阳再出去,柴胡加重让桂枝跟着柴胡走,如果桂枝开重,柴胡就跟着桂枝走,桂枝走了柴胡还在后面,就太快了,如果这时候开的是小柴胡汤,吃完还要再吃桂枝汤的。', 3, '', '柴胡,大枣,生姜,半夏,甘草,人参,黄芩,芍药,桂枝', 616184030859333, 'E5B218F7E4005691A9CACCCA092F00E6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 13:59:16', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (372, '柴胡桂枝干姜汤', 258, 7, 9040000, '$u{柴胡}$w{半斤}    $u{桂枝}$w{三两、去皮}    $u{干姜}$w{二两}    $u{栝楼根}$w{四两}    $u{黄芩}$w{三两}    $u{牡蛎}$w{二两(熬)}    $u{甘草}$w{二两、炙}\n        右七味，以水一斗二升，煮取六升，去滓，再煎取三升，温服一升，日三服。初服微烦，复服汗出，便愈。  \n\n     有外证所以重用柴胡，柴胡用五钱六钱，桂枝用三钱，干姜用二钱，栝蒌根用四钱，黄芩用三钱，牡蛎用二钱，炙甘草用二钱。  \n\n     《类聚方广义》本条方曰：痨瘵、肺萎、肺痈、痈疽、痔漏、结毒、癥毒等，经久不愈，渐就衰惫，胸满，干呕，寒热交作，动悸，烦闷，盗汗，自汗，痰咳，干咳，咽干，口燥， 大便溏泄，大便不利，面无血色，精神乏困，不耐厚药者，宜此方。只要是长久不愈的人，就会慢慢消弱下来，所以张仲景出痨瘵的第一个方就是柴胡桂枝干姜汤，为什么叫作痨?他不能动，一动就一天起不来，为什么会造成痨?因为工作上的关系，大部分是劳心才会有，劳力的人得到的是疲劳，痨症的人吃什么药都没有用，吃什么食物都不会胖，摸脉很洪大，但是脉是中空的，遇到这种情形的时候，张仲景开的第一方就是柴胡桂枝干姜汤。明明是桂枝汤的病人，桂枝汤下去没感觉，再开强一点还是没感觉，开麻黄汤下去，汗都不流一滴，这就是痨。  \n\n       以中医的观念，平常人的湿在中焦。就是内湿，如果湿在关节就是风湿，如果湿在血管里面就是痨，血液的新陈代谢有一定的量，如果血管有湿沉在里面，会造成一动就来不及补充能量，桂枝能让动脉的血液循环加速，血管的外壁就是淋巴系统，这是三焦网络就要靠柴胡，血管里面的血比较多?水比较少，脉洪大，所以用大剂的栝蒌根把水补足，因为血里面长年津液不足产生的燥热，用黄芩下去把它去掉，但是推动的力量不够，用干姜、炙甘草来建中，一下去把脾胃的功能加强起来，配合在一起，这时候就能把血管里面的湿推上皮肤表面上去，所以柴胡桂枝干姜汤吃下去后，病人所得到的汗是湿汗，所流出来的汗粘答答的。  \n\n        初服微烦，复服汗出，便愈，这汗出来的时候，湿答答的出来?有湿为什么不用白朮？知果湿在关节、肌肉、脾脏上面可以用白朮，但湿在血管里面则不能用白朮，因为白朮收敛的力量很强，白朮可以止利，如用于此，反而不利发散血中之湿。  ', 3, '', '甘草,牡蛎,黄芩,栝楼根,干姜,桂枝,柴胡', 616190270226501, '6CD387A2C0EE11E496B9928FD8A74656', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 14:24:40', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (373, '半夏泻心汤', 259, 7, 9040000, '$u{半夏}$w{半升(洗)}    $u{黄芩}    $u{干姜}    $u{人参}    $u{甘草}$w{炙各三两}    $u{黄连}$w{一两}    $u{大枣}$w{十二枚、擘}\n        右七味,以水一斗,煮取六升,去滓,再煮取三升,温服一升,日三服。\n\n    这半夏泻心汤为什么用干姜?因为胃旁边有水，造成胃寒掉了，所以用干姜，如果胃中有水的话用生姜，干姜是温中的药；\n张仲景需要用到肠胃的津液的时候，一定会开到人参、干姜、甘草、大枣、生姜，所以肠胃的津液要补足，就一定会用到甘草、大枣、人参。\n    有寒证的时候、需要$m{强心的时候我们用炙甘草}，要$n{解毒的时候用生甘草}，生甘草还有蓄水的功能，也就是用了人参补津液之后，以生甘草把津液留在肠胃中。人参在经方家的观念是治疗心下痞，胃里面不舒服、胃痛的，人参是最好的药，不是拿来当茶喝，不需要如此用；因为胃里面坏死的食物，产生了沼气往上走，黄芩、黄连把坏死的食物分解掉，这胃病的肇因是水没有去掉，所以用半夏把水利掉。\n\n        临床上看的时候，有一点感冒自己不知道。知道的时候叫伤寒，不知道的叫中风，然后病人吃坏肚子的上吐下泻，拉出来的都是水，肚子咕咕的肠鸣，就是半夏泻心汤证，用半夏止呕利水，黄连、黄芩去把肠子食物分解掉。黄连解血分中热毒，黄芩解肝胆三焦的热毒，因为上吐下泄所以胃的津液都伤到了，所以把人参、干姜、甘草、大枣混在里面用，张仲景的方剂就是这意思，所有的痞都是肠胃科的问题。这个方剂用汤剂或散剂都可以。  \n\n      舌苔代表胃的津液，如果舌苔黄，代表有热，如果舌苔黄但不是非常干燥，就是用黄芩黄连；如果是舌苔黄而且非常干燥，就是用石膏。  \n\n\n《金鉴》曰：结胸兼阳明里实者，大陷胸汤证也；结胸证病人一定没有下利的，所以有结胸的现象兼有大便堵到的现象，一定是大陷胸汤证；兼阳明不成实者，小陷胸汤证也；结胸证，但是大便还是通的就是小陷胸汤证，都是结胸的症状，就是胃里面很难过，绷得很紧，筋挛的现象。痞鞕兼少阳里实证者，是大柴胡汤证，胃里面很难过，硬硬的，然后大便稍微不通，没有结胸那么厉害，就是大柴胡汤证，兼少阳里不成实者，半夏泻心汤也，里不成实者，就是下利拉很多水出来，这时候靠半夏泻心汤。这种虚症的现象常常在食物中毒、误食  \n不干净的东西的时候，开半夏泻心汤给病人吃，半夏泻心汤的时候病人一定有呕吐、下利兼有肠鸣，所以有呕吐就是半夏泻心汤。  \n\n《芳翁医谈》曰：休息痢，世皆以为难治，盖亦秽物不尽，宜服笃落丸，（笃落丸为大黄一味之丸方。）光吃大黄一味药，会拉的很难过，笃落丸就是笃定会落下来，这样吃不好。又：下利如休息痢，无脓血，惟水泻，时或自止，止则腹胀，泻如爽然，然日羸惫，面色萎 黄，恶心吞酸，有时腹自痛，当与半夏泻心汤，没有拉血，拉出来都是水，停止没拉，肚于就胀起来，拉完后肚子就舒服了，面色就越来越疲惫，又恶心又吐酸，东西吃不下去。  ', 3, '', '大枣,黄连,人参,干姜,黄芩,半夏,甘草', 616196872220741, '9D292E43BC42734170E90438FB461C92', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 14:51:32', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (374, '十枣汤', 260, 4, 9040000, '$u{芫花}$w{(熬)}    $u{甘遂}    $u{大戟}    $u{大枣}$w{十枚(先煮)}\n	上三味等分、各别捣为散、以水一升半、先煮大枣肥大者十枚、取八合、去滓、纳药末、$a{强人服一钱匕、羸人服半钱、}温服之、$a{平旦服。}若下少病不除者。明日更服。$a{加半钱、}得快下利后、糜粥自养。\n\n       能把胸腔下方、横膈膜、肺的下方的水利出来，完全靠甘遂，所以大陷胸汤和大陷胸丸都是对结胸，如果结胸从胃的痞鞕一路往下走，因为比较下面就是大陷胸汤把它攻掉，如同样的结胸在这里但是病往上走，顶到喉咙，脖子都不能弯下来，如果用大陷胸汤就跑太快了，结胸会没有去掉，这时候要改用大陷胸丸，因为丸剂本身是药缓力重，吃大陷胸丸可以因势利导，把它导下来，所以结胸有两种症状，一个从心下往上升的用大陷胸丸，一个从心下往下走的用大陷胸汤，都是以胸膈为主，所以半夏、甘遂一定会用到，甘遂利水利痰的力量非常强。  \n\n      如果水渗到脏腑中间的三焦油网的时候，一定要靠大戟才能打通。甘遂利水利痰，去肺中的积水与子宫中的积水，但甘遂还有涤痰的效果，所以大陷胸汤用甘遂。  \n\n       肺泡里面都是水的时候用芫花，芫花去除胸腹的积水，所以会用到芫花的病人一定到了但坐不得卧的阶段，就是肺积水不能躺，一躺下去就要喘就再坐起来，吃完十枣汤，三小时就好了。  \n\n         这三味药磨粉等量的用，各l／3 钱，一次只给病人一剂，因为这三味药都是碱性的药，胃里面有胃酸，如果光吃这三味药到胃里面，胃就会难过了，所以要靠红枣，过去拿十个红枣去熬，现在大枣比较小，用二三十个浓一点无所谓，红枣汤能中和碱性，且让药发散的力 量很强。  \n\n         强人服一钱匕，胖的人用一汤匙，就是喝汤的汤匙一平匙，羸人服半钱，瘦的人用半匙，$m{平旦服}，这就是吃十枣汤的技巧了，一定要早上六点钟吃，五点到七点都可以，因为肺寅大卯胃辰宫，大肠开卯时，肺和大肠相表里，水在上焦的时候，用十枣汤攻下去的时候，病人会上吐下泻，如果有痰，上面吐出来的是痰，如果没有痰，只有水，这水是泻出来的，全部从大便排。病人吃十枣汤后约半小时，开始跑厕所，连续约三小时，中间大概上六七次水才排完，这三味药都是毒药，但是三小时后通通排掉了，若下少者，病不除者，明日更服，加半钱，如果大便三四次，应该下六七次才够，病没有除的，第二天再吃，再加半匙，得快下利后，标准是六次，糜粥自养，这时候喝稀饭，用红枣下去熬稀饭，不能吃油腻食物或肉类，否则会有余热；因为吐了很多，用红枣把胃的津液补足，临床上看到肝病的腹水、脾脏病腹水的时候，也是一样用十枣汤；不可以每天用十枣汤，吃完十枣汤后要调理病人的肠胃，北派的观念只要病人的肠胃功能非常好，吸收的功能非常好病人就不会死。肝病腹水的时候，肚子里面有很多水停在三焦油网脏腑中间，所以大戟加重；如果积水在肺的上方，三剂等量，如果肺积水甘遂多一点；攻出来的水，其实就是人体内的高蛋白的东西，这营养应该给脏腑，结果被水堵到了，这营养一段时间后会坏掉，所以必须把它排掉。  \n\n        看到十枣汤的病人，确定没有表证的时候要速攻，不要等到胃气已经没有才攻，十枣汤喝下去结果病人死了，以为是吃到毒药死的。所以要小心麻黄汤证没好变成小青龙汤证，小青龙汤证没好变成十枣汤证。  \n\n      《勿误药室方函口诀》本方条曰：据前田长奄之经验，一人之手肿，余处不肿，元气饮食如故，用此方，经水泻而速愈，亦别开生面法也。其实只有手肿用不到十枣汤的，此说过于牵强。  \n', 2, '', '大戟,甘遂,芫花,大枣', 616210136985669, '9872E20C310673E57AB5A893C20A3BA0', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 15:45:30', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (375, '大黄黄连泻心汤', 261, 2, 9040000, '$u{大黄}$w{二两}    $u{黄连}$w{一两(麻过滤绞之)}\n	右二味。以麻沸汤二升渍之。须臾绞去滓。分温再服。\n\n      过去这汤剂曾经用在肺结核、出血，大黄、黄连这两味药本身是气厚味重的药，这两味在临床上消炎的力量非常强，所谓麻沸汤，就是滚水泡大黄、黄连。象茶一样喝，还有一种就是把大黄、黄连包在棉布里，放在水里浸，喝挤出来的汁也可以，这样药比较浓，汁比较少些，因为黄连很苦，麻沸汤这样取药就是取气，取气轻往上升，所以要让药往上走的时候，一定要用泡的，如果是汤剂，取它的味重，因为汤剂会越熬越浓，所以让药往下走的时候用煮的。  \n\n       那么时候吃药？伤寒论里面只有两个地方讲出血，甘草干姜汤是胃大量出血，里寒时候在用；也有里热出血的，从嘴巴鼻子喷血出来，或眼睛微血管出血，这时候用麻沸汤，用泡的不用煮的，因为出血在上焦，鼻子出血是因为胃里面太热了，胸阳太热往上走热太盛的时候血管破裂掉了，所以出嘴巴或鼻子出血；如果是痔疮，就要用煮的，因为在下焦。  \n\n       临床上看病人，按之濡，按胃软绵绵的，结果病人其脉关上浮者、上焦的肺、心脏的地方很热，肺结核就是这样，结核就是里面发炎了，中医没有这名词，中医叫痨瘵，病人三黄，就是病人脸黄、小便黄、全身黄，病人瘦瘦干干的、焦黄的，肺里面发炎了，有的肺里面都是脓痰，肺都萎缩掉了，所以知道是上焦热，处方的时候大黄二、黄连一，药量用两计没关系，因为用泡的，一次泡可以吃好几次，譬如眼睛出血，会出血就是血离经了，血会离经就是热才会离经，所以是上热，这时候用大黄黄连汤的时候用滚水泡，一下就消掉了。  \n\n华佗给病人吃的麻醉汤，羊踯躅三钱，茉莉花根一钱，当归一两，菖蒲三分，照这比率三碗水煮成一碗，病人一喝下去就会人事不知了，大概持续三个小时，若还要久一点，在病人快醒前再喝一碗，这汤大多用在伤科，趁病人昏迷的时候，把骨头接好，伤口表面涂三黄泻心汤，就是大黄、黄连、黄芩磨粉撤在伤口上，如果伤口化脓就再加去湿的药。  \n\n      方与輗曰：经血错出口鼻，曰逆经，又名错经，初吐衄，后眼耳十指尖皆出血，甚至形体麻木，手足强直，为错经中之最剧者也。这是错经中最严重的，严重到最后七窍都出血，  手指指甲都渗血出来，一般来说错经的时候，血从鼻子、嘴巴出来。  \n\n    又：此方不仅治吐血、衄血。凡下血、尿血、齿衄、舌衄、耳衄等一身九窍者，无一不 治，真治血之玉液金丹也。从高压的深海里面出来的都可以用。  \n\n    又：跌打损伤，昏眩不醒人事，及血出不已者，大宜此汤。患金疮者，惟用此汤可治。刀伤的大多用外敷，平常做外用的时候三黄里面加些细红砂糖，砂糖粘可以去湿，所以砂糖可以预防化脓。  \n\n    《餐英馆治疗杂记》本方诀曰：此方以心下痞，大便秘，上气为目的；并一切上焦有蓄热，或口舌生疮，或逆上而眼目赤者，皆当以大便秘为目的。这时候的用法大黄、黄连煮成汤。  \n\n     《类聚方广义》本方条曰：酒客郁热下血者，肠痔肿痛下血者，痘疮发热炽盛而七孔出血者，产后血晕郁冒或如狂者。  \n\n     《肘后百一方》曰：患恶疮三十年不愈者，以大黄、黄芩、黄连，各三两为散，将疮洗净为止、每日三次敷之，无不瘥。所以脓疮的时候，把伤口清洗干净再敷三黄泻心汤，加白朮可以去湿，三十年没好就是湿很盛，粘答答的就是湿，所以光去热不够的，还要去湿，所以才会三十年没好。可以加乳香、没药可以收敛伤口排脓，加三七帮助排脓。  \n\n    《和剂局方》曰：上焦有热攻冲眼目赤肿，口舌生疮，中焦有热，心膈烦躁，饮食不美，下焦有热，小便赤涩，大便秘结；五脏俱热，即生疮痍。及之五般痔疾，粪门肿痛，或下鲜血。小儿积热，亦宜服之。中焦有热的时候，病人的感觉是心膈烦躁，饮食不美，吃东西没有味道，如果是下焦有热，小便是黄的，大便便秘，这一段就是如果去判断热在中焦还是在下焦：痔疮的时候，不要管它痔疮长什么样子，三黄泻心汤煮汤剂，外痔可以表面放血，下针下孔最、承山，痛马上去掉，外敷用枯痔散，还有肛门用烟熏，把雄黄放在瓦罐里烧，把肚子包起来，肛门对着瓦罐熏，痔疮马上收口，也可以做成粉敷在外面，七天左右会剥落，内痔，用汤剂把直肠脱出来，然候敷枯痔散，再下针，痔疮好了再吃汤剂把肠子收回去。  \n\n 戒烟涤痰方  \n\n     皂荚三钱  红枣适量  痰多加天南星三钱 口不渴者加半夏   戒烟后胃口太盛加石膏一两以上  \n\n      去肺中之湿气加知母五钱  \n\n      如果戒烟以后失眠、烦躁，加柴胡三钱  黄芩三钱  郁金五钱 疏散肝郁以后，抽烟的欲望就少了。  \n', 2, '', '黄连,大黄', 616213203869765, 'F61B87950F87B9A6AA49F15943CD5AC8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 15:57:59', 1, '超级管理员', '2024-11-26 16:00:05');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (376, '附子泻心汤', 262, 4, 9040000, '$u{大黄}$w{二两}    $u{黄连}$w{一两}    $u{黄芩}$w{一两}    $u{附子}$w{一枚、炮、去皮、破、别煮取汁}\n	右四味，切三味，以麻沸汤二升渍之，须臾，纳附子汁，分温再服。\n  \n    同样用泡的，大黄、黄连、黄芩用泡的，附子煮汁，附子如果用泡的，会只有头不流汗，身体还在流汗；会用到三黄一定是里面很热，除了肺外，还有肠胃热也可以用。 \n', 2, '', '附子,大黄,黄连,黄芩', 616214968135749, 'F6ED6E3F68CFD782063CE7343E8B49E5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 16:05:09', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (377, '生姜泻心汤', 263, 8, 9040000, '$u{生姜}$w{四两、切}    $u{甘草}$w{三两、炙}    $u{人参}$w{三两}    $u{干姜}$w{一两}    $u{黄芩}$w{三两}    $u{半夏}$w{半升(洗)}    $u{黄连}$w{一两}    $u{大枣}$w{十二枚、擘}\n	右八味,以水一斗,煮取六升,去滓,再煎,取三升,温服一升,日三服。\n\n       把生姜拿掉后就是半夏泻心汤，所以半夏泻心汤可以止呕，病人肠胃不舒服呕酸的时候，用半夏泻心汤，如果有下利的现象的时候，就是半夏泻心汤重用生姜，这里生姜干姜并用，干姜是温中，热，让肠胃蠕动功能恢复，生姜能散水，把肠胃里面的水散掉，这是寒热并结，所以寒药热药并在里面，因为嘴巴呕气，肠胃里面有宿食，所以用黄连、黄芩解肠里面的病毒，因为下利，把水都排掉，肠里面的津液就不足了，所以用甘草、大枣、人参把里面的津液补足。生姜用来散胃中的水，半夏用来散胃外面的水。  \n\n        胃病好了以后，最好是平常吃饭不要过饱，让微饿的感觉来强化我们的胃气；人工的食物、咖啡等等少吃，吃清淡一点。  \n\n       《类聚方广义》本方条曰：凡患噫气干呕，或嘈杂吞酸，或平日饮食每觉恶心烦满，胁下有水饮升降者，其人大多心下痞鞕，或脐上有块，长服此方。所以肠胃不好的人，常常在下利的人，肚子常鸣叫的人都是生姜泻心汤证，常常呕酸的就是半夏泻心汤证，早上起来嘴巴很苦的是小柴胡汤证，胆汁上逆，小柴胡汤治少阳热，所以要重用黄芩。  \n\n     《方伎杂志》曰：凡患此等之人，多属嗜食酒肉食者或喜食咸辛甜食者，治此等人必徒劳无功焉。  \n', 3, '', '大枣,黄芩,黄连,半夏,干姜,人参,甘草,生姜', 616225465806917, '9D23A3D73A0EEA0D3FA5E38B0BA26CD0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 16:47:52', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (378, '甘草泻心汤', 264, 6, 9040000, '$u{甘草}$w{四两、炙}    $u{干姜}$w{三两}    $u{黄芩}$w{三两}    $u{半夏}$w{半升(洗)}    $u{黄连}$w{一两}    $u{大枣}$w{十二枚、擘}\n   右六味，以水一斗，煮取六升，去滓。再煮，取三升，温服一升，日三服。  \n\n      这时候重用甘草就可以了，不用炙甘草，所有的泻心汤都有半夏、黄芩、黄连，这三味药，因为里面都有水，半夏来利水降逆，里面有发炎的现象，黄芩、黄连来处理，胃里面寒掉了用干姜让胃热起来。例如狐惑，女人的性病，在阴部有红肿或起一小块发炎，不会传染，但会痒、痛，严重的影响到喉咙也发炎，有的女人有白带喉咙也不好，因为喉咙和妇科是连到的，平常看的时候又是甘草泻心汤证，所以中医辨症论治，是同证同治。  \n\n      案例：一位纽约客，心脏动脉血管堵塞，开刀两次，心脏动脉血管堵塞的人，左眼有严 重红血丝，扎针：天突、巨阙、关元、肠关、心阙、厉兑，阳明经的井穴，井主心下满，病人主述心下痞，胃里面难过，所以处方甘草泻心汤加防己，当天病人回去上了七次厕所，因为心和小肠相表里，所以心脏动脉血管的堵塞，就是堵在小肠里面，扎一次针，第三天就好了，第三天复诊，舌苔黄，上焦发炎，因为开刀的时候，经脉都错接了，所以处方栀子豆豉等，来打通经络。  \n', 3, '', '甘草,干姜,黄芩,半夏,黄连,大枣', 616228377849925, '703D12294F3103D6D75D0F9CB1D54995', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 16:59:43', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (379, '赤石脂禹余粮汤', 265, 2, 9040000, '$u{赤石脂}$w{一斤(碎)}    $u{太一禹余粮}$w{一斤(碎)}\n	上二味。以水六升。煮取二升。去滓。分温三服。', 3, '', '禹余粮,赤石脂', 616231028117573, '6B0D5F9E0987AE1A00C97C6C24DC07EA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 17:10:30', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (380, '旋覆代赭石汤', 266, 7, 9040000, '64、$f{旋覆代赭汤} 7味 \n$u{旋覆花}$w{三两}    $u{人参}$w{二两}    $u{生姜}$w{五两}    $u{代赭石}$w{一两}    $u{甘草}$w{三两、炙}    $u{半夏}$w{半升(洗)}    $u{大枣}$w{十二枚、擘}\n        右七味，以水一斗，煮取六升，去滓，再煎，取三升，温服一升，日三服。  \n\n    旋覆花用三，代赭石用一。  \n\n        旋覆代赭石汤通常在肠胃科里面，旋覆花和代赭石是中医去热痰的药，发汗、吐、下都没有把痰去掉，痰还是梗在中间，这噫气和甘草泻心汤的噫气不一样，甘草泻心汤完全是虚噫，这旋覆代赭石汤是有痰饮在里面，以旋覆花软坚化结，就是软化痰的硬块，以代赭石降逆止噫；旋覆代赭石汤用在病人常常感到反胃恶心，里面有痰吐不出来，肠胃又虚掉了。现 在说的胃酸逆流、火烧心的症状，只要用旋覆代赭石汤，往往是一剂就好了。起因是因为精制糖做成甜食吃太多了，所以开了药方之后，还要吩咐病人戒绝由精制糖类所做成的甜食。  \n\n       《餐英馆治疗杂话》曰：周扬俊曰：治反胃噫气，气逆不降者，有神效，谓已用生姜泻心汤而噫气不除者，为虚气之逆，宜用此方镇压之意。旋覆代赭石汤就是经方里面镇逆用的，这时候里面恶心反胃的感觉很强，光靠半夏都不能止呕，就要靠旋覆花和代赭石下去，半夏止呕最重要是在水呕，对痰呕力量嫌不足，所以这时候要用旋覆花和代赭石。  \n\n 结胸证、痞证与其类证辨析：  \n             寒实结胸为脓胸或肺脓疡，三物小白散可以排除脓毒；结胸证为心下鞕满而痛，痞则按之不鞕而濡。如心下痞鞕满，引胁下痛，呕即短气，汗不出恶寒者，为胸膜间有水毒，犯胃则 呕，迫肺则短气，故以十枣汤峻攻其水。结胸则以大小陷胸汤。心下痞则用泻心汤。泻心汤 有生姜、附子、甘草、半夏等之分别，各有主治证之不同。误下而邪陷下焦者，宜赤石脂禹余粮汤。误犯吐下，重则成痿，轻则以旋覆代赭汤。  ', 3, '', '大枣,半夏,甘草,赭石,生姜,人参,旋覆花', 616234542972997, '7998586337DF539C9BD032246FE25459', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 17:24:48', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (381, '桂枝人参汤', 267, 5, 9040000, '$u{桂枝}$w{四两、切}    $u{甘草}$w{四两、炙}    $u{白术}$w{三两}    $u{人参}$w{三两}    $u{干姜}$w{三两}\n	右五味，以水九升，先煮四味，取五升，纳桂更煮，去滓，取三升，温服一升，日再服，夜一服。  \n\n       把炙甘草和干姜拿出来就是甘草干姜汤，肠胃虚寒的时候一定会用到甘草干姜汤，如果因为吐下，肠胃津液伤到的时候，一定会用到人参，可用党参代替。为什么用白朮?白朮能健脾整胃去湿，一般用黄土炒过的比较好，能够让肠胃的津液恢复得很好，三焦油网中黄黄的东西，如果不够了就要用白朮，靠白朮增加它的油质，所以白朮吃下去的时候，会让肠胃的蠕动很正常，肠胃的黏液会增加，西医就是不懂得用白朮，所以便秘也治不好。  \n\n        38条太阳病，桂枝证，医反下之，利遂不止，用葛根黄芩黄连，此则同为下利不止，而用桂枝人参汤者，何也 ? 彼为热利，此为寒利，彼无心下痞鞕，此则有心下痞鞕也。 葛芩连汤用的时候是里热，因为表面的滤过性病毒跑到里面，所以葛芩连汤专门是清里热用的，同样是利下不止，葛芩连汤是热利，桂枝人参汤是寒利，葛芩连汤没有心下痞鞕，桂枝人参汤有心下痞鞕，因为肠胃虚寒掉了，肠胃被攻下以后，里面没有东西，津液也被攻掉。胃壁黏在一起了，这时候用桂枝人参汤让它解开来，所以会兼用到人参、白朮、甘草、干姜。  \n\n       寒利和热利怎么分辨?大便很臭就是热利，热就是脓所以会臭，大便没有味道的就是寒利，用问的就好了，不用去闻；看看舌头也可以，摸摸脉也可以，所有的热脉是数，数就是跳得很快，热在下焦，所以摸到尺脉部分一定是很快；胃发炎的候，关的地方一定跳得很快，如果是寒利，摸到的脉一定很微细很微弱，所以桂枝人参汤和葛根黄芩黄连汤刚好互为表里剂，一寒一热。  ', 3, '', '桂枝,甘草,白术,人参,干姜', 616236948471877, '995918E6E02459AAB7C973D2ABDDEFA3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 17:34:36', 1, '超级管理员', '2024-11-26 17:59:57');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (382, '瓜蒂散', 268, 3, 9040000, ' $u{瓜蒂}$w{一枚、熬黄}，$u{赤小豆}$w{一分、煮}\n右二味，各别捣筛，为散已，合治之，取一钱匕，以$u{香豉}$w{一合}，用热汤$w{七合}，煮作稀糜，去滓，取汁，合散顿服之。不吐者少少加，得快者吐乃止，诸亡血虚家，不可与瓜蒂散。  ', 1, '', '香豉,赤小豆,瓜蒂', 616477613338693, '64C1468EEE84F3ECE93B5840E169E3F4', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 09:53:52', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (383, '黄芩汤', 269, 4, 9040000, '$u{黄芩}$w{三两}    $u{芍药}$w{二两}    $u{甘草}$w{二两、炙}    $u{大枣}$w{十二枚、擘}\n     右四味，以水一斗，煮取三升，去滓，温服一升，日再服，夜一服。  ', 3, '', '大枣,甘草,芍药,黄芩', 616487324692549, 'A03BD799378CC7E9737166BA7C96B362', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 10:33:23', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (384, '黄芩加半夏生姜汤', 270, 6, 9040000, '$u{黄芩}$w{三两}    $u{芍药}$w{二两}    $u{甘草}$w{二两。炙}    $u{大枣}$w{十二枚。擘}    $u{半夏}$w{半升(洗)}    $u{生姜}$w{一两半。一方三两。切}\n      右六味，以水一斗，煮取三升，去滓，温服一升，日再服，夜一服。  \n\n       水一斗约十碗水，黄芩三钱，芍药二钱，炙甘草二钱，红枣十二枚，半夏五钱，生姜二三片，温服一升，日再服，夜一服，白天服，晚上服，半夜起来再服，下利、肠胃科的药大多是六小时吃一次，吃药时间到了，半夜也要叫起来吃，二十四小时连续，三碗吃下去大概就好了。  \n\n      热利如果有兼有一点表证，或纯热利没有表证也没有腹痛，用葛芩连汤;如果热利而且兼有小腹痛，用黄芩汤；如果热利有小腹痛兼有呕吐，用黄芩加半夏生姜汤。  \n\n     这里的芍药是用来止腹痛的，之前讲过芍药也是补阴的药，可以活静脉的血来治疗静脉瘤与静脉曲张；经方里面有胸满就不用白芍，改用枳实，所以一般在治疗心脏病的时候，也不用到白芍。', 3, '', '大枣,生姜,甘草,芍药,黄芩,半夏', 616488984903749, '6C8E7CE5DF5C2BAC997DB9D1285C24B9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 10:40:08', 1, '超级管理员', '2024-11-27 11:04:48');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (385, '黄连汤', 271, 7, 9040000, '$u{黄连}$w{三两}    $u{甘草}$w{三两。炙}    $u{干姜}$w{二两}    $u{桂枝}$w{三两。去皮}    $u{人参}$w{三两}    $u{半夏}$w{半升(洗)}    $u{大枣}$w{十二枚。擘}\n\n      以水一斗，煮取六升，去滓，温服一升，旦三服，夜二服。  \n\n      甘草、干姜、人参、大枣，上吐下泄的时候，这四味药一定要在里面，胸满、胸口燥满、恶心、吐的时候一定把白芍拿掉，用桂枝把胸阳往下降，半夏止呕，黄连消炎，上焦的热靠黄连去掉，肠胃里面的寒靠炙甘草、干姜，炙甘草、干姜就是下焦腹寒所用的甘草干姜汤，能够让肠子蠕动起来，上焦的热靠黄连、半夏，桂枝把上面的虚热往下导，人参、大枣就是来补充因为吐下所丧失的津液。当胃热有吐血的时候，我们就不用桂枝；但是胃炎而胃痛的时候，桂枝还是可以配合黄连使用。  \n\n      温服一升，日三服，夜二服，白天吃三次，晚上吃二次，连续的吃，大约一天二十四小时就好了。  \n\n      霍乱的时候，针委中穴、外关穴，内服黄连汤，针加药，大约二天就好了。  \n', 5, '', '大枣,半夏,人参,桂枝,干姜,甘草,黄连', 616491661697093, 'B92C76D73CE9B6FCF3DF2E12206203CF', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 10:51:02', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (386, '去桂加白术汤', 272, 5, 9040000, '$u{附子}$w{三枚、炮、去皮、破}    $u{白术}$w{四两}    $u{生姜}$w{三两、切}    $u{大枣}$w{十二枚、擘}    $u{甘草}$w{二两、炙}\n\n    右五味，以水六升，煮取二升，去滓，分温三服。初服其人身如痹，半日许，复服之，三服尽，其人如冒状，勿怪；此以附子、术并走皮内，逐水气未得除，故使之尔，法当加桂枝四两，$n{此本一方二法：以大便硬。小便自利。去桂也。以大不便硬。小便不利。当加桂。附子三枚恐多也。虚弱及产妇宜减之。}\n\n     桂枝附子汤和去桂枝加白朮汤同样有生姜、炙甘草、大枣，其余的桂枝附子汤有桂枝和附子，去桂枝加白朮汤有白朮和附子，桂枝附子汤是用在病人有伤寒表证兼有湿证的时候用，所以他浑身关节痛，这时候用桂枝去风，靠附子去湿，附子行走速度很快；如果病人没有表证，只是全身关节酸痛，没有浮脉，就没有表证，大便比较稀，小便很正常，就是湿往大肠走了，这就是脾脏太湿了，肠子的黏液很多是从脾来的，湿很盛的时候，就顺着肠壁出来了，和小便没关系，所以不管排尿系统，管肠就好了，这时候用白朮，因为白朮专门去脾湿的，如果这药没有加附子的话，就光把脾脏的湿去掉了，不能去掉关节的湿，因为附子走表，附子把白朮带到四肢关节，把四肢关节的湿去掉。  \n\n       初服其人身如痹，刚开始服的时候，全身关节麻痹，因为附子走表，半日许，差不多十二小时以后再吃一碗，其人如冒状，头有昏眩的现象，勿怪；此以附子、朮并走皮内，不用生姜、甘草、大枣，光用附子、白朮就是朮附汤，  \n\n        朮附汤发脓急救用的，把身体里面的脓疮发出来的，现在加生姜、甘草、大枣，就是让它从脾脏到肌肉到关节，脾主四肢。顺着脾经走到关节里面把湿去掉，如果逐水气未得除，故使之尔，因为水气还没有办法完全去，所以附子在皮肤上走的时候，慢慢吸收水气，病人会头昏，当加桂枝四两，此本一方两法也，可以加桂枝，加不加都可以，这是一个处方、两个方法；一般性的风湿就可以用这二个方子，有表证的用桂枝附子汤，没表证的用白朮附子汤。第三个方子就是治疗痛风。  \n\n', 3, '', '附子,白术,生姜,甘草,大枣', 616494967160901, 'F53A39F6E5E89FAFF6EBDBE058380038', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 11:04:29', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (387, '桂枝附子汤', 273, 5, 9040000, '$u{桂枝}$w{四两、去皮}，$u{生姜}$w{三两、切}，$u{附子}$w{二枚、炮、去皮、破八片}，$u{甘草}$w{二两、炙}，$u{大枣}$w{十二枚、擘}\n	$s{右五味}，以水六升，煮取二升，去滓，分温三服。', 3, NULL, '附子,桂枝,生姜,甘草,大枣', 616497169125445, 'BA2830AAB5E768361065CF632E03EB72', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 11:13:26', 1, 'admin', '2025-03-01 14:34:45');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (388, '甘草附子汤', 274, 4, 9040000, ' $u{甘草}$w{二两、炙}，$u{附子}$w{二枚、炮、去皮}，$u{白术}$w{二两}，$u{桂枝}$w{四两、去皮}\n	$s{右四味}，以水六升，煮取三升，去滓，温服一升，日三服。初服得微汗则解，能食，汗止，复烦者，服五合；恐一升多者，宜服六七合为始。  \n\n      桂枝重用，譬如桂枝四钱，其它全部都用二钱，桂枝去风，白朮去湿，靠附子带到皮肤表面去，光这三味的时候，跑得最快的是桂枝。因为桂枝去风的力量很强，湿比较慢，所以如果没有加甘草，风去了，湿还留在关节里面，所以桂枝四，炙甘草二，附子二，白朮二，如果是胖子桂枝可以用到六钱。  \n\n       为什么会有风湿相搏？脾主四肢、主肌肉，脾脏运转不是很好的时候，湿会停下来，如果湿停在上焦，当得到桂枝汤证或麻黄汤证的时候，又刚好下利。就变成结胸了，因为工作环境的关系，湿停在不同的地方，有的人湿停在肌肉，有的人湿停在关节，虽然看起来表面有红肿，其实里面是寒湿。  \n\n       膝盖风湿，下针膝五针，扎完针后摸摸脉，如果没有表证就是白朮附子汤，如果是痛风，风吹得很难过，不可以碰，用衣服盖着比较好，整个红肿的，这是标准的痛风，扎针开四关、合谷、太冲、大杼，骨会大杼，脾俞脾主四肢主肌肉，肾俞把湿从小便利出来，曲池、膝五针，全身差不多都好了，再开甘草附子汤吃。  \n\n       东洞翁本方定义曰：治骨节烦疼，不得屈伸、上冲，汗出，恶寒，小便不利者。日三服，一天吃三次，初服得微汗则解，刚开始服的时候，会得微汗，一层黏黏的汗，那是湿不是好的津液，恐一升多者，可以分五六次吃，二小时吃一次，或三小时吃一次，看病况而定。  ', 3, '', '桂枝,白术,附子,甘草', 616499533033541, '4BA272CD8050AF97B15658010202EF86', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 11:23:03', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (389, '白虎汤', 275, 4, 9040000, '$u{知母}$w{六两}    $u{石膏}$w{一斤、碎}    $u{甘草}$w{二两}    $u{粳米}$w{六合}\n    右四味,以水一斗,煮米熟,汤成,去滓,温服一升。日三服。\n\n       白虎汤是一个生津去热的方子，热除了发炎以外，还有高温的壮热，像脑膜炎的壮热，肺炎的高热。  \n\n       白虎汤里的石膏可以用到一两，用棉布包起来煮。平常不要随便吃石膏，石膏非常寒凉，目的是去胃热，知母可以去上焦的湿，因为都是寒凉的药，所以不用炙甘草，因为炙过的药比较热，所以用生的甘草，粳米用糯米就可以了，煮米熟，汤成，米不要太多，不要把它煮成干饭，要煮成很稀的稀饭，所以米大约用两茶匙，为什么用糯米?因为糯米比较黏， 胃液肠液都是黏黏的，白虎汤证就是肠胃的津液没有了，因为红枣下去胃还要消化，所以红枣没有糯米好，五谷是胃最能吸收的东西，所以糯米汤本身就是胃的津液，这时候用石膏去退热，用知母去湿除烦，心烦的时候用知母在里面，知母能去肺热的湿；白朮是去中焦的湿 所以不用。  ', 3, '', '粳米,甘草,石膏,知母', 616501272219717, '6065C2E77161C2982FC7B3099F43AEE6', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 11:30:08', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (390, '炙甘草汤', 276, 10, 9040000, '	$u{甘草}$w{四两、炙}，$u{桂枝}，$u{生姜}$w{各三两}，$u{麦门冬}$w{半升}，$u{麻子仁}$w{半升}，$u{人参}，$u{阿胶}$w{各二两}，$u{大枣}$w{三十枚}，$u{生地黄}$w{一斤}\n	$s{右九味}，以$u{酒}七升，水八升，先煮八味，取三升，去滓，纳胶烊消尽。温服一升，日三服，一名复脉汤。 。\n\n      炙甘草用一两，生姜三片，桂枝三钱，人参二钱，生地黄一两，阿胶二钱，麦门各五钱，麻子仁五钱，大枣十二到十五枚、麦门冬和麻子仁是表里药，一个润肺，一个清肠，常常并用所以等量。  \n\n       清酒，白的酒，米酒就可以了，用三碗酒四碗水煮成三碗，去滓，一碗撒一钱阿胶，吃之前热过后再撒阿胶，所以阿胶生用，药生用的时候，药力锐且迅，煮熟的药比较纯但缓走下，生用阿胶，可以马上到心脏去，心血马上补足。因为知道病人的身体虚掉了，所以生地用一两，北派说生地不用到两根本补不到的，因为知道病人需要，所以开到一两。如果纯用酒去熬，喝两付就好了，如果纯用水去熬，要三付，如果要一剂就好，把药剂加重，汤煮浓点，两碗当一碗喝。  \n\n       临床上，只要摸到结代脉，不管外证是什么，要先把结代脉治好，因为中医的观念，心主神，别的病是慢慢的死，但是心脏病一发就死了，所以要先治疗结代脉。停药的时机，必须等到睡眠正常、大便正常、手足温热、无胸满心痛的症状，才可以停药。  \n\n       在内经灵枢决气第三十篇中提到：何谓津?岐伯曰：腠理发泄，汗出溱溱，是谓津。何谓液?岐伯曰：谷入气满，淖泽注于骨，骨属屈伸，泄泽补益脑髓，皮肤润泽，是谓液。若以津液二者来分阴阳，则津为阳、液为阴。津不足的时候我们用人参来补之；若液不足的时候，我们用生地来补之。由此我们就可以知道炙甘草汤中用到人参与生地的药理所在。  \n\n        方与輗本方条曰：此为仲景伤寒，脉结代，心动悸之圣方也；孙真人用以治虚劳，王刺始利用以利肺痿，凡仲景之诸方，其通变如此。故虽云通变如此，而此方之妙，在脉结、代，故一名复脉汤。无论何病，凡脉结代者，概当先用此方。  ', 3, '', '地黄,大枣,阿胶,人参,麻子仁,麦门冬,生姜,桂枝,甘草', 616504700268613, '5D989AA715530460A80BA9B867643BF6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 11:44:05', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (391, '大承气汤', 277, 4, 9040000, '$u{大黄}$w{四两($u{酒}洗)}    $u{厚朴}$w{半斤(炙、去皮)}    $u{枳实}$w{五枚、炙}    $u{芒硝}$w{三合}\n	右四味、以水一斗、先煮二物、取五升、去滓、纳大黄、更煮取二升、去滓、纳芒硝、更上微火一两沸、分温再服、$n{得下。余勿服。}\n\n       以中医的解释，调胃承气汤的症状是实而不满，里面有堵到但是没有胀满的感觉，小承气汤的症状是小腹胀满，是没有结硬块的少腹胀满，大承气汤的症状是满而实，三个承气汤都是攻实的。实但没有胀满，只是消化不好而已，调胃承气汤顺顺气就好了，如果是满而不实，少腹胀满，但是并没有结成大便干燥，病人有发热但是没有潮热，给小承气汤就好了，如果到了胀满又实，整个堵在大肠里面，就是大承气汤，因为大承气汤多了芒硝，芒硝善攻坚，把大便打散掉，大黄只能去实无法攻坚，如果只用大黄，没有用芒硝的时候，通出来时病人肚子会绞痛，因为没有用芒硝把燥屎打散，所以芒硝是攻坚用的。  \n\n       厚朴枳实在大小承气汤中都有，枳实最主要的功能就是可以增加肠子的津液，厚朴能够宽肠，把肠子打开来，能把肠壁和干燥的大便分开来，大便为什么会干掉？就是肠胃的津液没了才会干掉，肠胃的津液没了造成大便也干了，这互相有关联的，所以用厚朴把肠壁打开来，用枳实润泽肠子；如果处方只有大黄、芒硝，没有厚朴、枳实，会把大便硬打下来，很痛的，有加厚朴、枳实两味的大便会很顺的下来，没有感觉的。  \n\n        张仲景在用大黄的时候，只有两个地方用酒洗，调胃承气汤和大承气汤的大黄用酒洗，小承气汤的大黄没有用酒洗，直接入药，因为调胃承气汤和大承气汤都有芒硝，芒硝又咸又寒，怕芒硝伤到胃，所以大黄用酒洗蒸过，来对付芒硝，大承气汤的煮法，右四味，以水一斗，煮取二物，就是光煮厚朴、枳实，药先煮的就是取它的味重力缓，剂量用法像胖子的体格，大黄四钱，厚朴五钱，枳实五钱，芒硝二钱，一剂就去掉了，十碗煮成五碗，先煮厚朴、枳实，去滓再加大黄，再五碗煮成二碗，纳芒硝，更上火微煮一二沸，撒芒硝上去，微火稍 微滚一下就好，所以芒硝几乎是生用，生用的药性非常的急速，药进到肚子里面去的时候，跑最前面的就是芒硝，芒硝把大便打散掉，然后大黄去推它，一扯开来的时候，肠子会痛，厚朴、枳实就上来了，如果同时煮的时候，药性就没有了，芒硝煮烂了变成盐巴，性就没有那么强，平常吃的粉剂，只是中承气，大黄如果用酒泡过再入药，拉出来很舒服的，大黄如果没有用酒洗，拉完还会出很多水，肠胃的津液会伤到。  \n得下，余勿服，下了就不要再吃了，不要可惜它。  \n\n       《类聚方广义》本方条曰：凡痼毒滞症，其人腹中坚实，或鞕满而大便难，胸腹动悸，或喜怒无常，或不寐警惕，健忘怔忡，或身体不仁，或战曳瘫痪，筋挛骨痛，或言语蹇涩， 缄默如偶人，饮啖倍常，或数十日不食不饥，变态百出，不可名状，例如梅毒，外面的中医用土茯苓汤，病人的症状，每天下午燥热难忍，大便五六天不通，要靠甘油锭去通，嘴巴很臭，味道很浓，舌苔黑的，外病是梅毒，结果是大承气汤医好的，大便通之后，胃口大开，免疫系统恢复，病毒都被赶出去。  \n\n      《伤寒蕴要》曰：大抵下药，必切脉沉实、沉滑、沉疾有力者，可下也。再以手按脐腹，硬者或叫痛不可按者，则下之无疑也。沉代表病在里，疾代表里热结实到了，如果手按着而感觉很舒服，就是虚，不可以攻。  \n\n       《小青囊》曰：大承气汤治舌四边微红，中央见灰黑色，此由失下所致，可用本方退之。又治舌现黄色而黑点乱生者，其证必渴而谵语。失下就是应该下而不攻，谵语就是胡言乱语了，有的女人发谵语，结果是小柴胡汤，因为她刚好热入血室，所以要注意辨症。  \n\n        舌黄就代表热，舌黄且厚，病人是湿而且热，如果舌干且深黄就是壮热，如果是里黑且燥就是热极了，最热了，壮热就已经进入阳明了，舌黑掉的时候，再不攻就死了，粉剂没有汤剂厉害，吃了五六包粉剂没用，不如熬汤剂，如果连汤剂都不下，就是大肠癌了，大肠癌可以用巴豆、附子、吴茱萸，巴豆用在腹中结到，属寒结，用巴豆加附子和吴茱萸可以通结，如果光用巴豆，胃打穿了，小肠也打穿了，结到的还是结到。  \n\n       平常最常用的是小承气汤，大承气汤是救急的时候在用，不大便的时候，舌苔黄的，问有没有放屁?大小承气汤最明显的区分就是，有放屁就是小承气汤，屁没有了就是大承气汤。但是服小承气汤后，放屁连连的则属大承气汤证。  \n\n      《医学纲目》曰：顺利散（即本方），凡消谷而善饥，曰中消者，怎么吃都吃不饱，就是胃的蠕动太快了，中医讲的就是中消，治热在胃而能食，热在胃里面而能吃，小便赤黄，微利，稍微有点下利，至不欲食有效，多不可利。小承气汤用在这，是因为肠胃的东西消化太快了，热全部集中在小肠里面，所以下焦的热都会出来，所以小便都会黄，渴饮千杯不能止渴，则属上消症，用白虎汤，中消糖尿病不是都开小承气汤，必须要是大便便实才用小承气汤，张仲景于中消未出方，中消症状也是用白虎汤加减，下消糖尿病就是桂附八味丸，下消糖尿病就是不能行房事了。\n', 2, '', '大黄,厚朴,枳实,芒硝', 616589191995461, '3940D781C9E69F53721B46713D52E64F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 17:27:53', 1, '超级管理员', '2024-11-27 17:33:59');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (392, '小承气汤', 278, 3, 9040000, '$u{大黄}$w{四两($u{酒}洗)}    $u{厚朴}$w{二两(炙、去皮)}    $u{枳实}$w{三枚(大者、炙)}\n	右三味、以水四升、煮取一升二合、去滓、分温二服、$n{初服汤当更衣、不尔者、尽饮之、若更衣者、勿服之。}\n\n       以中医的解释，调胃承气汤的症状是实而不满，里面有堵到但是没有胀满的感觉，小承气汤的症状是小腹胀满，是没有结硬块的少腹胀满，大承气汤的症状是满而实，三个承气汤都是攻实的。实但没有胀满，只是消化不好而已，调胃承气汤顺顺气就好了，如果是满而不实，少腹胀满，但是并没有结成大便干燥，病人有发热但是没有潮热，给小承气汤就好了，如果到了胀满又实，整个堵在大肠里面，就是大承气汤，因为大承气汤多了芒硝，芒硝善攻坚，把大便打散掉，大黄只能去实无法攻坚，如果只用大黄，没有用芒硝的时候，通出来时病人肚子会绞痛，因为没有用芒硝把燥屎打散，所以芒硝是攻坚用的。  \n\n       厚朴枳实在大小承气汤中都有，枳实最主要的功能就是可以增加肠子的津液，厚朴能够宽肠，把肠子打开来，能把肠壁和干燥的大便分开来，大便为什么会干掉？就是肠胃的津液没了才会干掉，肠胃的津液没了造成大便也干了，这互相有关联的，所以用厚朴把肠壁打开来，用枳实润泽肠子；如果处方只有大黄、芒硝，没有厚朴、枳实，会把大便硬打下来，很痛的，有加厚朴、枳实两味的大便会很顺的下来，没有感觉的。  \n\n        张仲景在用大黄的时候，只有两个地方用酒洗，调胃承气汤和大承气汤的大黄用酒洗，小承气汤的大黄没有用酒洗，直接入药，因为调胃承气汤和大承气汤都有芒硝，芒硝又咸又寒，怕芒硝伤到胃，所以大黄用酒洗蒸过，来对付芒硝，大承气汤的煮法，右四味，以水一斗，煮取二物，就是光煮厚朴、枳实，药先煮的就是取它的味重力缓，剂量用法像胖子的体格，大黄四钱，厚朴五钱，枳实五钱，芒硝二钱，一剂就去掉了，十碗煮成五碗，先煮厚朴、枳实，去滓再加大黄，再五碗煮成二碗，纳芒硝，更上火微煮一二沸，撒芒硝上去，微火稍 微滚一下就好，所以芒硝几乎是生用，生用的药性非常的急速，药进到肚子里面去的时候，跑最前面的就是芒硝，芒硝把大便打散掉，然后大黄去推它，一扯开来的时候，肠子会痛，厚朴、枳实就上来了，如果同时煮的时候，药性就没有了，芒硝煮烂了变成盐巴，性就没有那么强，平常吃的粉剂，只是中承气，大黄如果用酒泡过再入药，拉出来很舒服的，大黄如果没有用酒洗，拉完还会出很多水，肠胃的津液会伤到。  \n得下，余勿服，下了就不要再吃了，不要可惜它。  \n\n       《类聚方广义》本方条曰：凡痼毒滞症，其人腹中坚实，或鞕满而大便难，胸腹动悸，或喜怒无常，或不寐警惕，健忘怔忡，或身体不仁，或战曳瘫痪，筋挛骨痛，或言语蹇涩， 缄默如偶人，饮啖倍常，或数十日不食不饥，变态百出，不可名状，例如梅毒，外面的中医用土茯苓汤，病人的症状，每天下午燥热难忍，大便五六天不通，要靠甘油锭去通，嘴巴很臭，味道很浓，舌苔黑的，外病是梅毒，结果是大承气汤医好的，大便通之后，胃口大开，免疫系统恢复，病毒都被赶出去。  \n\n      《伤寒蕴要》曰：大抵下药，必切脉沉实、沉滑、沉疾有力者，可下也。再以手按脐腹，硬者或叫痛不可按者，则下之无疑也。沉代表病在里，疾代表里热结实到了，如果手按着而感觉很舒服，就是虚，不可以攻。  \n\n       《小青囊》曰：大承气汤治舌四边微红，中央见灰黑色，此由失下所致，可用本方退之。又治舌现黄色而黑点乱生者，其证必渴而谵语。失下就是应该下而不攻，谵语就是胡言乱语了，有的女人发谵语，结果是小柴胡汤，因为她刚好热入血室，所以要注意辨症。  \n\n        舌黄就代表热，舌黄且厚，病人是湿而且热，如果舌干且深黄就是壮热，如果是里黑且燥就是热极了，最热了，壮热就已经进入阳明了，舌黑掉的时候，再不攻就死了，粉剂没有汤剂厉害，吃了五六包粉剂没用，不如熬汤剂，如果连汤剂都不下，就是大肠癌了，大肠癌可以用巴豆、附子、吴茱萸，巴豆用在腹中结到，属寒结，用巴豆加附子和吴茱萸可以通结，如果光用巴豆，胃打穿了，小肠也打穿了，结到的还是结到。  \n\n       平常最常用的是小承气汤，大承气汤是救急的时候在用，不大便的时候，舌苔黄的，问有没有放屁?大小承气汤最明显的区分就是，有放屁就是小承气汤，屁没有了就是大承气汤。但是服小承气汤后，放屁连连的则属大承气汤证。  \n\n      《医学纲目》曰：顺利散（即本方），凡消谷而善饥，曰中消者，怎么吃都吃不饱，就是胃的蠕动太快了，中医讲的就是中消，治热在胃而能食，热在胃里面而能吃，小便赤黄，微利，稍微有点下利，至不欲食有效，多不可利。小承气汤用在这，是因为肠胃的东西消化太快了，热全部集中在小肠里面，所以下焦的热都会出来，所以小便都会黄，渴饮千杯不能止渴，则属上消症，用白虎汤，中消糖尿病不是都开小承气汤，必须要是大便便实才用小承气汤，张仲景于中消未出方，中消症状也是用白虎汤加减，下消糖尿病就是桂附八味丸，下消糖尿病就是不能行房事了。\n', 2, '', '枳实,厚朴,大黄', 616590648066117, '4F7B7CE50FDC419E050DAE2E4E245425', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 17:33:48', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (393, '猪苓汤', 279, 5, 9040000, '$u{猪苓}$w{去皮}，$u{茯苓}，$u{阿胶}，$u{滑石}，$u{泽泻}$w{各一两}\n	$s{右五味}，以水四升，先煮四味，取二升，去滓，内阿胶烊消，温服七合，日三服。  \n\n     胖子各三钱，普通人各二钱就可以了，先煮四味，就是把阿胶拿出来，阿胶都是后下的，一天吃三次，中药没有记饭前或饭后服，则一律饭前吃。  \n\n  《类聚方广义》本方条曰：治淋病点滴不通，阴头肿痛，少腹膨胀而痛者，若茎中痛，出脓血者，都可以用猪苓汤。  \n\n       又：妊妇七八月后，有牝护焮热肿痛，不能起卧，小便淋沥者，以三棱针轻轻刺肿处，放出瘀水后，再用此方，则肿痛立消，小便快利。怀孕中间小便不通，要用到猪苓汤，还有若一身悉肿者，宜越婢加朮汤，怀孕的时候水肿，就是越婢加朮汤，越婢再加白朮，所以孕妇水肿是越婢加朮汤，小便不通是猪苓汤。  \n\n      《尊水琐言》曰：满身洪肿，以手力按其肿，放手则按处忽复起胀，肿胀虽如是其甚，然未曾有碍呼吸，气息亦如平日，是猪苓汤证也。更有肿势如前，腰以下虽满肿，臂、肩、胸、背无恙，呼吸仍如寻常者，是亦可用猪苓汤，勿必问其渴之有无。所以下半肿也可以用猪苓汤，水肿的时候，有些水要用发汗发掉，不发汗则喘满，就要用越婢加朮汤。  ', 3, '', '猪苓,茯苓,阿胶,滑石,泽泻', 616856743944261, '4B9ECA0B220EB48F2096FCD9699673D5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-28 11:36:33', 1, '超级管理员', '2024-11-28 11:37:10');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (394, '蜜煎导', 280, 3, 9040000, '$u{蜜}$w{七合}\n	一味。纳铜器中，微火煎之，稍凝似饴状，搅之勿令焦着。欲可丸，并手捻作梃，令头锐，大如指，长二寸许。 当热时急作，冷则硬。以纳谷道中，以手急抱，欲大便时乃去之。 又$u{大猪胆}$w{一枚。泻汁}。和少许$u{醋}。以灌谷道内。如一食顷。当大便出宿食恶物。甚效。\n\n       把蜂蜜熬到感觉黏的程度如麦牙糖一样就关火，等稍微温一点的时候，并手捻作梃，令头锐，大如指，长二寸许，用手搓成一条一头大一头尖的，趁温的时候做好，等凉了以后插到肛门去，大头先进，肠子蠕动会让它往里面跑，以手急抱，欲大便时乃去之，用手抱到，有要大便感觉的时候再放手。  ', 1, '', '蜜', 616941846040645, 'DFF381F250AC35F7A5898C7E477635C0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-28 17:22:50', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (395, '土瓜根', 281, 0, 9040000, '方缺', 0, '', NULL, 616943151439941, '29B5EC5E93B83D7311CC58263F4B071F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-28 17:28:09', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (396, '大猪胆汁', 282, 1, 9040000, 'u{大猪胆}$w{一枚、泻汁}，和少许$u{法醋}，以灌谷道内，如一食顷，当大便出宿食恶物，甚效。', 1, '', '猪胆汁', 616943458758725, '476DEBD521915503D8382A3D5EB4685F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-28 17:29:24', 1, '超级管理员', '2024-11-29 09:45:59');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (397, '茵陈蒿汤', 283, 3, 9040000, '$u{茵陈蒿}$w{六两}    $u{栀子}$w{十四枚、擘}    $u{大黄}$w{二两、去皮}\n	 右三味,以水一斗,先煮茵陈,减六升,纳二味,煮取三升,去滓,分温三服,小便当利,尿如皂角汁,色正赤,一宿腹减,黄从小便去也。 \n\n   先煮茵陈蒿，再煮其它两味。茵陈蒿在胖子或刚发病黄很盛的时候，可以开到五六钱，瘦人三钱就够了，栀子的量和茵陈蒿差不多，大黄约茵陈蒿的三分之一即可。 \n    \n 《勿误药室方函口诀》本方条曰：此方为治发黄之圣剂；茵陈蒿专治发黄，盖有解湿热及利水之效。  ', 3, '', '大黄,栀子,茵陈蒿', 617184637898821, '763B2D526F1EA2D44DEE5B7948E884C6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 09:50:45', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (398, '吴茱萸汤', 284, 4, 9040000, '$u{吴茱萸}$w{一升}，$u{人参}$w{三两}，$u{生姜}$w{六两}，$u{大枣}$w{十二枚}\n	$s{右四味}，以水五升，煮取三升。温服七合，日三服。\n\n  吴茱萸用三钱，重证的时候可以用到五钱，人参、生姜、大枣酌量的用。\n\n《肘后方》曰：一方（即本方）治人食毕噫醋及醋心（即食后吞酸嘈杂也）。  \n\n 张元素曰：吴茱萸汤其用有三：去胸中之逆气满塞，止心腹寒感疼痛，及消宿酒。早上宿醉未醒，可以用吴茱萸汤，吴茱萸汤对酒客病非常的好。\n', 3, '', '大枣,生姜,人参,吴茱萸', 617197769121861, '904D92C55A0876E37E26B2B1E6FB6BE5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 10:44:11', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (399, '麻仁丸', 285, 6, 9040000, '$u{麻子仁}$w{二升}，$u{芍药}$w{半斤}，$u{枳实}$w{半斤、炙}，$u{大黄}$w{一斤}，$u{厚朴}$w{一斤、炙、去皮}，$u{杏仁}$w{一斤、去皮尖，研作脂}\n\n    右六味，为末，炼蜜为丸，桐子大。每服十丸，旦三服，渐加，以知为度。  \n\n    开处方的时候照比例开，麻子仁二，白芍六，枳实六，大黄十二，厚朴十二，杏仁十二。  \n\n     《方函口诀》引闲斋曰：治老人之秘结最佳。然本方虽和缓，究属攻破之剂，尝见有误用致死者。老人血液枯燥而便秘者，得大剂肉苁蓉辄通利；若用本方，虽取快一时，不旋踵而秘结益甚，不可不知。常常看到老年人大便像羊大便一样，一颗一颗的，肉苁蓉是补肾，是男人壮精的药，把精力壮起来，体能恢复以后，肠胃蠕动功能恢复，自然而然把大便排出来。年龄大的人身体很虚，没有体力承受承气汤的威力，所以紧急时可用猪胆汁导法和蜜煎导法，从肛门把大便清出来，  ', 3, '', '麻子仁,芍药,枳实,大黄,厚朴,杏仁', 617203947024453, 'FEC5706F98F6A7DACC596C76A3F10D0A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 11:09:19', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (400, '栀子蘗皮汤', 286, 3, 9040000, '$u{栀子}$w{十五个、擘}    $u{甘草}$w{一两、炙}    $u{黄柏}$w{二两}\n\n右三味，以水四升，煮取一升半，去滓，分温再服  \n\n栀子用二、三钱，炙甘草一钱，黄柏二钱，胖子用栀子用到三、五钱没关系，栀子和黄柏的剂量相等，为什么甘草要炙过?因为药下去，要同时能够停在上焦、中焦、下焦，如果炙甘草没炙过，上焦还没清，栀子已经跑到下焦去了，所以用炙甘草在中间的时候，让栀子停在上焦，黄柏清利下焦。  ', 2, '', '黄柏,甘草,栀子', 617214152740933, '4C7C1A9CDF58CBEA9F5B1E9F34966DAA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 11:50:51', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (401, '麻黄连轺赤小豆汤', 287, 8, 9040000, '$u{麻黄}$w{二两。去节}    $u{ 连轺}$w{（连翘）二两}    $u{杏仁}$w{四十个、去皮尖}    $u{赤小豆}$w{一升}    $u{大枣}$w{十二枚、擘}    $u{生梓白皮}$w{一升、切}    $u{生姜}$w{二两、切}    $u{甘草}$w{二两、炙}\n', 3, '', '甘草,生姜,生梓白皮,大枣,赤小豆,杏仁,连轺,麻黄', 617216463597637, '05B4222BF24E6ECC7D5AD653BCF448C7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 12:00:15', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (402, '桂枝加大黄汤', 288, 6, 9040000, '$u{桂枝}$w{三两、去皮}    $u{大黄}$w{一两}    $u{芍药}$w{三两}    $u{甘草}$w{二两、炙}    $u{生姜}$w{三两、切}    $u{大枣}$w{十二枚、擘}\n右六味,以水七升,煮取三升,去滓,温服一升,日三服。 \n 桂枝加大黄汤里面桂枝三钱、芍药三钱,再加大黄,大黄去实。  ', 3, '', '大黄,大枣,生姜,芍药,桂枝,甘草', 617563378458693, '8533F9D50A1E747F2741E0FCBC3EE865', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 11:31:51', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (403, '桂枝加芍药汤', 289, 5, 9040000, '$u{桂枝}$w{三两、去皮}    $u{芍药}$w{六两}    $u{甘草}$w{二两、炙}    $u{生姜}$w{三两、切}    $u{大枣}$w{十二枚、擘}\n	右五味,以水七升,煮取三升,去滓,分温三服。 \n桂枝加芍药汤里面桂枝三钱,芍药六钱', 3, '', '桂枝,芍药,甘草,生姜,大枣', 617564194377797, '1D6BEE191BBE3EB14F59D38F7CD4FAEE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 11:35:10', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (404, '麻黄附子细辛汤', 290, 3, 9040000, '$u{麻黄}$w{二两、去节}    $u{细辛}$w{二两}    $u{附子}$w{一枚(炮、去皮、破八片)}\n     右三味，以水一升，先煮麻黄，减二升，去上沫，纳诸药，煮取三升，去滓，温服一升，日三服。\n     一般处方的时候,麻黄细辛等量,譬如二钱,附子是加重的,三钱或四钱,\n 因为附子要配合细辛,又要配合麻黄,一药双用,\n 如果附子和细辛等量,附子配细辛,麻黄吃下去,照样没有小便,把附子加重,一部份配合麻黄,一部份配合细辛大黄也是一样的功能,\n 因为要通大便,所以把麻黄换大黄,舌苔白的,跳脉一息二下,代表蠕动很慢,这就是寒实。', 3, '', '麻黄,细辛,附子', 617618070921285, '0FD640F7B0CD198EE9B62C0FA645E967', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 15:14:24', 1, '超级管理员', '2024-11-30 15:31:03');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (405, '大黄附子细辛汤', 291, 3, 9040000, '$u{大黄}$w{二两}    $u{细辛}$w{二两}    $u{附子}$w{一枚(炮、去皮、破八片)}\n     一般处方的时候,麻黄细辛等量,譬如二钱,附子是加重的,三钱或四钱,\n 因为附子要配合细辛,又要配合麻黄,一药双用,\n 如果附子和细辛等量,附子配细辛,麻黄吃下去,照样没有小便,把附子加重,一部份配合麻黄,一部份配合细辛大黄也是一样的功能,\n 因为要通大便,所以把麻黄换大黄,舌苔白的,跳脉一息二下,代表蠕动很慢,这就是寒实。', 3, '', '大黄,细辛,附子大黄,细辛,附子大黄,细辛,附子,', 617622123651141, 'E07ED7B94FB9503CE00EC07ABBB8781F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 15:30:53', 1, '超级管理员', '2024-11-30 15:32:20');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (406, '麻黄附子甘草汤', 292, 3, 9040000, '$u{麻黄}$w{二两。去节}    $u{甘草}$w{二两。炙}    $u{附子}$w{一枚(炮。去皮。破八片)}\n      右三味，以水七升，先煮麻黄一二沸，去上沫，纳诸药，煮取三升，去渣，温服一升，日三服。  \n\n      麻黄附子细辛汤和麻黄附子甘草汤的不一样就是细辛和甘草，细辛是升阳，升里阳的，里阳下陷的时候，寒在里面，就是阳升不上来，肾脏下焦的阳应该要往上升，上焦的阳要往下降，才能够交会起来，肾脏的水，到膀胱以后，在胞室，就是精宫，阳火很热很大，把膀胱的水蒸化，蒸化了以后，废水由小便出来，还有部分水，水生木，进入肝胆，然后变成胆汁再分泌出来，这段就是下焦的火，如果这一段的火没了，细辛有这功能让它提升上来。  \n\n张仲景的甘草用炙的时候，用在两个地方\n\n       一个目的是补他的津液的不足，所以有麻黄附子甘草汤，是少阴病得到二三天以后用的；少阴病，如果刚开始的时候是麻黄附子甘草汤，因为免疫系统要跟滤过性病毒相抗，津液会伤到，所以少阴病得到二三天的以后，津液伤到的时候，用炙甘草下去补他，所以要取他的微发其汗，315条的少阴病，始得之，反发热，这刚开始得到少阴病的时候，津液还没有伤到，就是麻黄附子细辛汤，\n\n       第二在经方里面，复脉，凡是脉不正常，心律不整的时候，不管是跳的太快，或怎样，一定会用到炙甘草，炙甘草的力量很强，所以炙甘草汤实际上是让脉恢复正常最有力的方子，所以炙甘草汤，芍药甘草附子汤，麻黄附子甘草汤，都重用炙甘草。  \n\n        如果不用炙过的甘草，用一般的生甘草，张仲景的想法是，第一津液不够了，第二肠里还有一些食物腐坏掉了，用甘草去解毒，这就是一般《本草纲目》写的，甘草可以解百毒，实际上像滤过性病毒，毒蛇咬的，吃甘草都不会好的，所谓解百毒，是把肠胃里面坏掉的食物中和掉，好的留为己用，桂枝汤里面用炙甘草不用生甘草的原因是担心发表以后，胃肠中津液丧失，所以做预先防范的动作。  ', 3, '', '附子,甘草,麻黄', 617624568123461, 'D9E729E65D9B47E0BF8F90F9E12C75A3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 15:40:50', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (407, '黄连阿胶汤', 293, 5, 9040000, '$u{黄连}$w{四两}    $u{黄芩}$w{二两}    $u{芍药}$w{二两}    $u{鸡子黄}$w{二枚}    $u{阿胶}$w{三两}\n 右五味，以水五升，先煮三物，取二升，去渣，内胶烊尽，小冷，纳鸡子黄，搅令相得，温服七合，日三服。  \n\n        先煮三物，就是黄连、黄芩、芍药先煮，五碗水煮成二碗，去渣，再用小微火，阿胶放进，让阿胶化掉后。把火关掉，等它冷了后，纳鸡子黄，搅令相得，不要汤很烫的时候放鸡子黄，那会变成蛋花汤，这地方鸡蛋要生用，叫鸡子黄就是生用，鸡子黄是补心血，鸡蛋生用和熟用不一样，所以小冷，也不要太冷，因此粉剂就没用了。  \n\n      《类聚方广义》本方条曰：诸失血证，胸悸，身热，腹痛微利，舌干唇燥，烦悸不能寐，身体困惑，面无血色，或面热潮红者均效。\n\n      临床上，黄连阿胶汤大部分用在手术以后的烦躁，因为很虚没有办法入眠，年龄大的人，气血两虚的状况下，没有办法入眠，这时候用安眠药没有用，灸三毛稍微睡一下，或睡得不是很深，可以用黄连阿胶汤下去当安眠剂。 ', 3, '', '鸡子黄,阿胶,芍药,黄芩,黄连', 617631504343109, 'B2929B09368778BA2F2DC7EDD252F0B3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 16:09:04', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (408, '附子汤', 294, 5, 9040000, '$u{附子}$w{二枚(炮、去皮、破八片)}    $u{茯苓}$w{三两}    $u{人参}$w{二两}    $u{白术}$w{四两}    $u{芍药}$w{三两}\n\n   右五味，以水八升，煮取三升，去渣，温服一升，日二服。  \n\n     这附子汤里面如果把人参换成生姜，就是真武汤，真武汤的时候，白朮和茯苓的剂量不一样，附子汤里面，白朮如果是四，茯苓就是三，白朮比茯苓重，所以重在健脾上面，真武汤里面茯苓重用，白朮比较少，因为真武汤是小便不利，所以真武汤是水结下焦，这水在走的时候要靠生姜，附子把胃里面的水排掉，因为生姜能散水，然后茯苓把水利出去，所以把人参拿掉。  \n\n     虚寒疼痛，全身骨节疼痛的时候用附子汤。  ', 2, '', '芍药,白术,茯苓,人参,附子', 617633713471557, '67EA2ED9E4CE851B1D65B4B37C2DAFEC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 16:18:03', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (409, '桃花汤', 295, 5, 9040000, '$u{赤石脂}$w{一斤，一半全用，一半筛末}，$u{干姜}$w{一两}，$u{粳米}$w{一升}\n	$s{右三味}，以水七升，煮米令熟，去渣，温服七合，纳赤石脂末，方寸匕，日三服，若愈，余勿服。  \n\n      赤石脂胖子用五钱，因为里寒所以用干姜，干姜温中，为什么不用人参?因为人参是补津液的。用人参时，肠里面的病毒会不出来，所以用糯米，能生津就好了，不要把它固住，粳米放一勺就好了，不要煮成糯米饭，赤石脂一半打碎生用，一半跟着药一起煮，汤煮好了再放赤石脂的粉末，赤石脂生用就是要把药整个固涩在胃里，让肠子固住，不再下利，消炎的力量很强，一剂下去就不再下利了。', 3, '', '粳米,干姜,赤石脂', 617635145957445, '8A20F15C7AEA36C15BFAD8629F89D104', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 16:23:53', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (410, '猪肤汤', 296, 3, 9040000, '$u{猪肤}$w{一斤}    $u{白蜜}、$u{白粉}$w{(即大米粉)}\n  右一味，以水一斗，煮取五升，去渣，加$u{白蜜}$w{一升}    $u{白粉}$w{五合}，熬香，和令相得，温分六服。  \n\n      单味的药去煮，加蜂蜜，再加白粉，就是米粉。猪皮加白蜜，都是能增补我们的胰液，米粉能助胃消化，米已经打碎成粉了，如果再不能消化，此人就差不多了，加蜂蜜就是健脾胃，甜的入脾，脾包含了胰。  \n\n      像少阴证会有下利，咽痛，心烦的现象，就是阴虚掉了，里面功能没有了，肺里热往上跑，跑到上面来就是喉咙痛，跑到下面就是下利，但是又不象桃花汤全部在下面，又不象黄连阿胶汤全部在上面，病毒分开来的，所以并没有便脓血，因为热往两边跑，所以用猪肤汤主之。  \n  ', 6, '', '猪肤', 617637558530117, '94DE0994E7772858B5C1B6873EC6A0A0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 16:33:42', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (411, '甘草汤', 297, 1, 9040000, '$u{甘草}$w{二两}\n\n右一味，以水三升，煮取一升半，去渣，温服七合，日一服。  \n\n如果单味药，开一两二两没有关系，甘草二，桔梗一。  \n\n      为什么喉咙痛会伴随着痰饮?因为喉咙是肺的开口，也是胃的开口，所以喉咙和气管和食道都结在一起。如果喉咙痛就是肿起来了，肿起来气行就不是很顺畅，很多热气就慢慢囤积在这里，如果热堵到了，就会生很多黏液，就会造成痰，有痰的时候靠桔梗，桔梗汤能宣肺化痰，\n      金匮里面只有两个排脓汤方，其一就是甘草桔梗汤，所以这脓肯定是肺里面化脓，肺里面痰太多了；\n              第二当归赤小豆散，用来治痔疮化脓；另外是薏苡附子败酱散，这汤方是已经转化成腹膜炎，盲肠炎，大黄牡丹皮汤来不及煮，转成腹膜炎的时候用的。  ', 3, '', '甘草', 617639444516933, '897A219B82E098C489A619811DACA894', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 16:41:22', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (412, '桔梗汤', 298, 2, 9040000, '$u{桔梗}$w{一两}    $u{甘草}$w{二两}\n	右二味、以水三升、煮取一升、去滓、温分再服。\n\n    甘草二，桔梗一。  \n    为什么喉咙痛会伴随着痰饮?因为喉咙是肺的开口，也是胃的开口，所以喉咙和气管和食道都结在一起。如果喉咙痛就是肿起来了，肿起来气行就不是很顺畅，很多热气就慢慢囤积在这里，如果热堵到了，就会生很多黏液，就会造成痰，有痰的时候靠桔梗，桔梗汤能宣肺化痰，金匮里面只有两个排脓汤方，其一就是甘草桔梗汤，所以这脓肯定是肺里面化脓，肺里面痰太多了；第二当归赤小豆散，用来治痔疮化脓；另外是薏苡附子败酱散，这汤方是已经转化成腹膜炎，盲肠炎，大黄牡丹皮汤来不及煮，转成腹膜炎的时候用的。  ', 2, '', '桔梗,甘草', 617640823869509, '7AB400797C16373B2AF6423671544FFE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 16:46:59', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (413, '苦酒汤', 299, 3, 9040000, '$u{半夏}$w{十四枚(洗、破如枣核)}    $u{鸡子}$w{一枚、去黄} 内上 $u{苦酒}$w{着鸡子壳中}\n    右二味，内半夏，著苦酒中，以鸡子壳，置刀环中，安火上，令三沸，去滓，少少含咽之，不差，更作三剂。  \n\n          半夏用生半夏，拿一颗两颗，严重的拿二颗，熟半夏没有用，洗生半夏的时候把生半夏戳破，鸡子就是鸡蛋，用铁架子架着蛋壳，在火面上烧，蛋壳里面留一点蛋白，再倒些苦酒汤在里面，然后生半夏放进去，用打火机在下面烧，烧的时候要看，看蛋壳中蛋清表面起一二个泡泡出来就关火，不要煮太熟，滚一二下，先喝一口，慢慢的喝下去，很冲的，喉咙开了就好了，针灸的时候，在扁桃腺上放血，还有过去有医生用巴豆与贝母做成巴豆霜，把巴豆霜用管子吹到喉咙上去，巴豆不要用吃的，用吃的舌头会破个洞，结果喉咙还是没好，临床上，喉咙都闭到了，吞不下东西的时候，像木舌证，也是用这苦酒来让喉咙打开，含在嘴巴里面，没有吞下去没关系，针灸的话，在舌头下方的金津玉液放血。  \n\n    《金鉴》曰：半夏涤涎，蛋清敛疮，苦酒消肿，则咽清而生出矣。用半夏来去痰，蛋清来收敛疮，利用蛋清的润滑收他的疮，因为苦酒汤攻下去的时候，喉咙会破掉，所以火不能太热，太热就变成蛋白了，苦酒来消肿。 ', 1, '', '鸡子,半夏', 617642419077189, '919EE17F46516245D8CB6409578A2EAA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 16:53:28', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (414, '半夏散及汤', 300, 3, 9040000, '$u{半夏}$w{(洗)}    $u{桂枝}$w{去皮}    $u{甘草}$w{炙}   以上各等分  \n 以上三味，各别捣筛已，合治之，白饮和，服方寸匕，日三服，若不能散服者，以水一升，煎七沸，内散两方寸匕，更煎三沸，下火令小冷，少少咽之。  \n\n      这就是少阴证的喉痛，少阴证的时候本身又有中风，本来少阴证得到了一段时间，津液本来就不足了，因为里面阴虚很盛，没有办法有正常的津液给喉咙，这时候用桂枝来去风，用甘草、半夏，这就是有少阴证的同时得到有表证的时候用的，就是带有伤寒感冒的时候用的，这三味等分，白饮就是米汤，不能服散用汤剂也可以。  \n\n      《勿误药室方函口诀》本方条曰：此方宜于冬时中寒，咽喉疼痛者，虽有发热、恶寒、可治。然此证冬时为多。又后世所谓火喉癣证，上焦有虚热，而喉头烂，痛苦不堪，饮食不能下咽，用甘桔汤及其它诸治喉痛药无寸效者，用之一旦而有效；临证上，严重到吞不下去了用苦酒汤，如果本身是少阴证还兼有伤寒的表证，所以摸脉很重要，少阴证的人脉很虚弱，就是这人里虚了，里虚就是肠胃功能没有吸收，病人很虚弱，这时候得到的喉咙痛，一定是虚火，不是实火，实火用黄连、黄芩等消炎的药，虚火就不能用。', 1, '', '甘草,桂枝,半夏', 617643459616837, 'EA0FD3DFC0574CFA11B6DA3D7D072BBC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 16:57:42', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (415, '白通汤', 301, 3, 9040000, '$u{葱白}$w{四茎}    $u{干姜}$w{一两}    $u{附子}$w{一枚(生。去皮。破八片)}\n右三味，以水三升，煮取一升，去滓，分温再服。  \n\n       白通汤用葱白、干姜、附子，附子生用，用生附的时候，一定是和干姜并用的，炮附一定是和生姜并用，生附和干姜能温经散寒，力量能达到表上面去，从神经血脉一直到四肢末稍，炮附和生姜能去里寒，尤其是中焦、下焦里面的寒水，所以生姜有利水的功能，炮附能去寒，所以现在白通汤的目的就是要温经散寒。  \n\n    少阴病，下利，少阴病的人会下利就是里虚掉了，什么时机用白通汤?  \n\n    第一四逆汤，会用到四逆汤一定是手脚冰冷了，可是四逆汤的主证，是肠胃里面的热能没有办法达到四肢，简单讲就是中阳不振，中焦的阳，脾胃的功能不好，或味口不好，舌苔白白的，里寒很盛，脾胃没有热度，所以造成手脚冰冷的就是用四逆汤。  \n\n    第二附子汤，附子汤在用的时候，表里皆寒且虚，连阳都不足了，所以附子汤可以补阳的不足，如果是表寒里虚，阳气很足的时候都是小青龙汤证。  \n\n     第三就是白汤通，是阴盛在下，虚阳在上，白通汤的目的是让上下通达，所以少阴证下利的时候，因为里寒太盛了，上焦的胸阳、心阳没有办法往下走，结果下焦的阳不足，上面的阳下不来，变成上面是热，下面是寒，下面的肠胃没有蠕动，东西就坏死掉，造成不断的下利，这时候就要用白通汤。  \n\n     白通汤里面的葱白，只用葱的白茎，和干姜、附子一起煮，因为没有炙甘草，所以药一下去的时候，没有阻碍，一下去就能把上焦的阳往下带，干姜来温中，生附能行到表面上，能把肠胃的蠕动加速，让血行到四肢上去。  \n\n      通脉四逆汤，就是阴盛于内，阳隔于外，摸病人微发热，可是舌苔伸出来全部是白的，就是表热里寒，如果前面是太阳证的话，要开解表的药，也要开去里寒的药，如果少阴证的时候，就不一样，少阴证的表热是假像的热，病人的体能快被阴赶出去了，所以脉已经很微细了，很危险了，这时候要开通脉四逆汤，能打通他全身的血脉，所以通脉就是通达内外。通脉四逆汤和四逆汤的区别，病人的脉都是微细的，但是四逆汤只胃阳虚而已，所以四逆汤  \n的病人手脚冰冷，通脉四逆汤的病人手脚热的，但是脉都快没了。  \n\n所以上下不能通的时候用白通汤，全身都虚寒的时候靠附子汤，内外阴阳不能协和的时候用通脉四逆汤。  \n', 2, '', '葱白,附子,干姜', 617645865730117, 'D1A3F093184C1ACC6E7988D3DD82917D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 17:07:30', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (416, '白通加猪胆汁汤', 302, 5, 9040000, '$u{葱白}$w{四茎}    $u{干姜}$w{一两}    $u{附子}$w{一枚(生、去皮、破八片)}   $u{猪胆汁}$w{一合}\n右三味，以水三升，煮取一升，去滓，纳胆汁、   $u{人尿}$w{五合}  ，和令相得，分温再服，若无胆亦可用。  ', 2, '', '猪胆汁,附子,干姜,葱', 617649430237253, 'A73AE6FC60D70E4359C960EA1396A87C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 17:22:00', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (417, '真武汤', 303, 8, 9040000, '$u{茯苓}    $u{芍药}    $u{生姜}$w{各三两、切}    $u{白术}$w{二两}    $u{附子}$w{一枚(炮、去皮、破八片)}\n	右五味，以水八升，煮取三升，去滓，温服七合，日三服。 \n\n真武汤方加减法  \n\n      若咳者。加$u{五味子}$w{半升}    $u{细辛}$w{一两}    $u{干姜}$w{一两}。\n      若小便利者。去$u{茯苓}。\n      若下利者。去$u{芍药}。加$u{干姜}$w{二两}。\n      若呕者。去$u{附子}。加$u{生姜}。$w{足前为半斤。}\n\n      张仲景常常在咳嗽的时候加细辛、五味子，加干姜，代表这是水饮的咳，水气往上冲的时候，所以加细辛、五味子，下来再遇到干姜，水气就去掉了。如果小便很正常，茯苓就不用了。张仲景在寒利的时候一定会用干姜，所以如果下利很重，加干姜。呕吐的很厉害，代表水饮很重，胃里面有一定的水，过量的时候就会恶心，所以靠生姜，生姜能散胃里面的水，胃的蠕动不好的时候要靠干姜，所以生姜、干姜不一样。  \n', 4, '', '干姜,细辛,五味子,附子,白术,芍药,生姜,茯苓', 617651411988549, '76AB3F87BA99A445027F3C4CA2577258', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 17:30:04', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (418, '通脉四逆汤', 334, 3, 9040000, ' $u{附子}$w{大者一枚，生用}，$u{干姜}$w{三两，强人可四两}，$u{甘草}$w{二两，炙}\n	$s{右三味}，以水三升，煮取一升二合，去滓，分温再服，其脉即渐出者愈。\n \n     非若暴出者之自无而忽有，既有而仍无，如灯火之回焰也。\n\n     面赤色者，加葱九茎。\n     腹中痛者，去葱，加芍药二两。\n     呕者，加生姜二两。\n     若咽痛者，去芍药，加桔梗一两。\n     利止，脉不出者，去桔梗，加人参二两。  \n\n       以水三碗煮一碗，若暴出者之自无而忽有，既有而仍无，有时候有，有时候又没有，如灯火之回焰也，面赤色者加葱九茎，这时候通脉四逆汤加葱茎，因为上下相隔，应急的时候，可以通脉四逆汤加白通汤，腹中痛者，这代表肠里面的血停滞，这时候要靠白芍，白芍一下去把血带到肝里面，肝静脉的血再回到心脏再换血；若咽痛者，去芍药，加桔梗一两，喉咙痛的加桔梗；利止，脉不出者，去桔梗，加人参二两，为什么最后加人参?如果病人的胃气能恢复，病人就还有救。  \n', 2, '', '附子,甘草,干姜', 618265699557445, '699F29B1167BC97D5A3E42687A0E88E5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 11:09:36', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (419, '四逆散', 335, 4, 9040000, '$u{甘草}$w{炙}    $u{枳实}$w{(破、水渍、炙干)}    $u{芍药}    $u{柴胡}\n	右四味，各十分，捣筛，白饮合服方寸匕，日三服。\n\n     咳者。加$u{五味子}、$u{干姜}$w{各五分}。并主下利。\n     悸者。加$u{桂枝}$w{五分}。\n     小便不利者。加$u{茯苓}$w{五分}。\n     腹中痛者。加$u{附子}$w{一枚、炮令坼}。\n     泄利下重者。先以水五升。煮$u{薤白}$w{三升}、去滓、以散三方寸匕、内汤中、煮取一升半、分温再服。\n\n       薤白这药，本身能开肺，肺气一开的时候下就通了，因为肺和大肠相表里的，所以有的人便秘吃承气汤没有用，实际上是肺气没有打开来，思能伤脾，忧能伤肺，常担心的人相会改变。眉毛下方会看到白色的，眉底的肉会变成白色的，所以肺病的人可以看到白色，眉毛和肺有关系，眉毛只剩几根的空壳子，外表穿的很华丽，相书里面看眉毛很稀落的人，代表这人里面一无所有，所以掉眉毛和掉头发不一样，头发主肾，所以如果能让忧虑去掉，让肺开开来，就能让眉毛长回来，眉毛很长的代表长寿，所以要保持平常心。  \n\n      如果是肌肉里面血堵到了，被打伤，肌肉里面淤血的时候用桂枝汤加桃仁，如果是打到内部、肠胃的地方、三焦网络的内伤，就用四逆散来作加减。 \n ', 3, '', '柴胡,芍药,枳实,甘草', 618270700793925, '6E04E75517303D04E34ADA7A120F2ACC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 11:29:57', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (420, '乌梅丸', 336, 10, 9040000, '$u{乌梅}$w{三百个}，$u{细辛}$w{六两}，$u{干姜}$w{十两}，$u{黄连}$w{一斤}，$u{当归}$w{四两}，$u{附子}$w{六两，炮}，$u{蜀椒}$w{四两、炒去汁}，$u{桂枝}$w{六两}，$u{人参}$w{六两}，$u{黄柏}$w{六两}\n	$s{右十味}，异捣筛，合治之，以$u{苦酒}渍乌梅一宿，去核，蒸之五升米下，饭熟，捣成泥，和药令相得，内臼中，与$u{蜜}杵二千下，丸如梧子大。先食，饮服十丸，三服，稍加至二十丸。禁生冷滑臭等食。\n\n       乌梅先泡醋泡一个晚上，再用米去蒸，蒸熟后把米跟乌梅捣在一起，和蜜，细辛辣是很辣的，干姜也会辣，蜀椒是专门杀菌的，就是巴椒，蜀椒开口无毒闭口有毒、蜀椒、细辛、干姜都是辛辣的，黄连、黄柏是苦的攻下，炮附、桂枝、干姜是热的，让肠胃热起来，把肠胃的环境改变了，虫才不会生在里面，病人有虫在里面，一定是肠胃虚寒的，所以这时候一定吃人参，把肠胃的虚寒补回来，张仲景在肠胃虚寒的时候一定加人参，本身就已是吸收不好，而食物进去胃里面应该吸收化生成血，结果被虫吃掉了，所以用当归把血再补回去。  \n\n吃乌梅丸的时候，禁生冷、滑物、臭食等，因为肠胃已经不好了，再吃这些会又再造虫出来，先食饮，服十丸，就是饭前吃乌梅丸，如果饭后吃乌梅丸，人吃到的是乌梅丸，虫吃到的是饭，所以先后顺序对了，虫下来后，肠胃的环境改变了，肠胃变热了，虫就不能呆在里面了。  \n\n        乌梅也主久利，这久利指的是寒利。有时候寒到利有带脓血的时候，脓就是炎，这时候用黄连，黄柏、干姜、细辛、炮附就是在寒利的时候用的。中焦过湿无法化除时、也可用此丸剂，其丸苦温，故能去结实之湿。有些病人一紧张就下利，例如遇到考试的时候就下利，也是乌梅丸证。  \n', 30, '', '黄柏,人参,桂枝,蜀椒,附子,当归,黄连,干姜,细辛,乌梅', 618318809968709, '0D2957D23E59EA5F9B965C4140F28CBA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 14:45:43', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (421, '当归四逆汤', 337, 7, 9040000, '$u{当归}$w{三两}    $u{桂枝}$w{三两}    $u{芍药}$w{三两}    $u{细辛}$w{三两}    $u{甘草}$w{二两、炙}    $u{通草}$w{二两}    $u{大枣}$w{二十五枚、擘}\n	右七味，以水八升，煮取三升，去滓。温服一升，日三服。  \n\n     如果遇到病人很危险的时候，就照上面的剂量开，用两计，平常用钱计，晚上睡觉脚冰冷的，就是当归四逆汤证。还有一个地方用当归四逆汤，就是疝气，疝气时可加上升麻来升提阳气。所以只有疝气和冻疮用到当归四逆汤，还有就是急救的时候用。  \n\n       若其人内有久寒者，宜当归四逆加吴茱萸生姜汤主之。  \n\n        这内有久寒，讲的是胃寒，在厥阴篇里面讲的，实际上是肝太寒了，引起的胃的功能不正常，所以用当归四逆加吴茱萸生姜汤主之、吴茱萸是最好止呕的圣剂，寒就是有水，所以加生姜把水排掉。  \n\n     当归四逆加吴茱萸生姜汤方  \n\n  当归三两   桂枝三两   芍药三两   细辛三两   通草二两   甘草二两炙  \n\n  吴茱萸二升 生姜半斤   大枣二十五枚  \n\n 右九味，以水六升，清酒六升，和煮取五升，去滓，分温五服。  \n\n大部分妇人的带下，就是白带，都是阴寒的体质，这种状况就是当归四逆加吴茱萸生姜汤，人的生殖系统，只有肝经络过。所以当归四逆加吴茱萸生姜汤把肝热起来，白带就去掉了，因此在妇科的时候会用到这方子。  ', 3, '', '大枣,通草,甘草,细辛,芍药,桂枝,当归', 618343414198341, '8CECD3F8A678C77A80B3F5225F7C97FB', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 16:25:50', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (422, '当归四逆加吴茱萸生姜汤', 338, 9, 9040000, '$u{当归}$w{三两}    $u{桂枝}$w{三两}    $u{芍药}$w{三两}    $u{细辛}$w{三两}    $u{甘草}$w{二两。炙}    $u{通草}$w{二两}    $u{大枣}$w{二十五枚、擘}    $u{生姜}$w{半斤}    $u{吴茱萸}$w{二升}\n	上九味，以水六升、$u{清酒}$w{六升}和。煮取五升，去滓，温分五服。\n\n       大部分妇人的带下，就是白带，都是阴寒的体质，这种状况就是当归四逆加吴茱萸生姜汤，人的生殖系统，只有肝经络过。所以当归四逆加吴茱萸生姜汤把肝热起来，白带就去掉了，因此在妇科的时候会用到这方子。  ', 5, '', '当归,桂枝,芍药,细辛,甘草,通草,生姜,吴茱萸,大枣', 618346069364805, '4687DC0D48F25BD3F6C6D4312DD32EF3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 16:36:38', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (423, '麻黄升麻汤', 339, 14, 9040000, '$u{麻黄}$w{二两半、去节}    $u{升麻}$w{一两一分}    $u{当归}$w{一两一分}    $u{知母}$w{十八铢}    $u{黄芩}$w{十八铢}    $u{葳蕤}$w{十八铢}    $u{芍药}$w{六铢}    $u{天门冬}$w{六铢(去心)}    $u{桂枝}$w{六铢}    $u{茯苓}$w{六铢}    $u{甘草}$w{六铢、炙}    $u{石膏}$w{六铢(碎、绵裹)}    $u{白术}$w{六铢}    $u{干姜}$w{六铢}\n	右十四味，以水一斗，先煮麻黄一二沸，去上沫，内诸药，煮取三升，去滓，分温三服，相去如炊三斗米顷令尽，汗出愈。  \n\n所以麻黄升麻汤是寒热错杂的处方，由此可见寒热的药可以同时并用。寒热药并用的时候一定要热药冷服，药冷了后再吃。  \n\n本方之主证：为表证无汗，兼咽喉溃烂而肠中虚寒下利者。  \n', 3, '', '干姜,白术,石膏,甘草,茯苓,桂枝,天门冬,芍药,葳蕤,黄芩,知母,当归,升麻,麻黄', 618353548480581, 'A4ABB41539D8D35F932E7F448B80DF61', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 17:07:04', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (424, '干姜黄连黄芩人参汤', 340, 4, 9040000, '$u{干姜}    $u{黄芩}    $u{黄连}    $u{人参}$w{各三两}\n	右四味、以水六升、煮取二升、去滓、分温再服。\n四味药等量，各开三钱，干姜温胃寒，黄连、黄芩清肠热，吐、利以后，津液伤到了，一定加人参。', 3, '', '干姜,黄芩,黄连,人参', 618354878419013, '828C4FC97F37FC1A75F11771D3B86558', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 17:12:29', 1, '超级管理员', '2024-12-02 17:13:05');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (425, '白头翁汤治', 341, 4, 9040000, '$u{白头翁}$w{二两}    $u{黄柏}$w{三两}    $u{黄连}$w{三两}    $u{秦皮}$w{三两}\n	右四味，以水七升，煮取二升，去滓，温服一升，不愈，更服一升。  \n\n      白头翁二钱，白头翁本身有止腹痛，同时能去热，如果光是止腹痛，白芍也可以止腹痛，但是这里是热利，痢疾的原虫把肠子都破坏掉了，肠子里面出血很多，所以靠白头翁和秦皮，秦皮在《本草》写药性苦寒、止涩的功能，味是苦的性是寒的，秦皮有止下利的功能，黄连、黄柏就是清热的药，拉的很厉害的时候，白头翁用五钱都可以。  ', 2, '', '秦皮,黄连,黄柏,白头翁', 618359129698373, '5B7DEFA9EC59B97C32C513955E49F2AA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 17:29:46', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (426, '麻黄汤', 342, 4, 1001000, '$u{麻黄}$w{三两、去节}    $u{桂枝}$w{二两、去皮}    $u{甘草}$w{一两、炙}    $u{杏仁}$w{七十个、去皮尖}\n	右四味，以水九升，先煮麻黄减二升，去上沫，纳诸药，煮取二升半，去滓，温服八合，覆取微似汗，不须粥饮，余如桂枝法将息，桂枝汤见后卷。', 3, '', '杏仁,甘草,桂枝,麻黄', 620047195783237, 'FD1E1E7F35375BF7BF5401957354DFD5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 11:58:32', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (427, '白虎汤', 343, 4, 1001000, '$u{知母}$w{六两}    $u{石膏}$w{一斤、碎}    $u{甘草}$w{二两、炙}    $u{粳米}$w{六合}\n\n     右四味，以水一斗，煮米熟，汤成去滓，温服一升，日三服。\n', 3, '', '知母,石膏,甘草,粳米', 620073246429253, '141F96F0587011722688C5E7B7FD42D9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 13:44:32', 1, '超级管理员', '2024-12-13 21:55:35');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (428, '大承气汤', 344, 4, 1001000, '$u{大黄}$w{四两、 (酒洗)}    $u{厚朴}$w{半斤 (炙去皮)}    $u{枳实}$w{五枚、(炙)}    $u{芒硝}$w{三合}\n\n	右四味，以水一斗，先煮二物，取五升，去滓，纳大黄，更煮取二升，去滓，纳芒硝，更上微火一两沸，分温再服，得下余勿服。\n', 2, '', '大黄,厚朴,枳实,芒硝', 620076255526981, '721EB01EA09AF359EE5A0C3269397BBF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 13:56:47', 1, '超级管理员', '2024-12-16 14:20:42');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (429, '小承气汤', 345, 3, 1001000, '$u{大黄}$w{四两、(酒洗)}    $u{厚朴}$w{二两、(炙去皮)}    $u{枳实}$w{三枚 (炙)}\n\n         右三味，以水四升，煮取一升二合，去滓分温再服，$m{初服更衣者，停后服，不尔者，尽饮之。}', 2, '', '大黄,厚朴,枳实', 620080646508613, '85FB0353D3EEDFB40CC9358AC8187DBA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 14:14:39', 1, '超级管理员', '2024-12-14 17:02:10');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (430, '调胃承气汤', 346, 3, 1001000, '$u{甘草}$w{二两 (炙)}  、$u{ 芒硝}$w{半斤}  、$u{大黄}$w{四两 (酒洗)}   。\n\n         右三味，以水三升，煮二物至一升，去滓，纳芒硝，更上微火一二沸，温顿服之。\n\n$a{桂版。伤寒论}$m{辨阳明病脉证并治}及$m{伤寒例第四} $n{芒硝}用量均为$q{半斤}', 1, '', '大黄,甘草,芒硝', 620081996570693, 'D6F6CA7D516E5D33FF3EC1243E4F0C5B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 14:20:08', 1, '超级管理员', '2024-12-14 16:55:44');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (431, '小柴胡汤', 347, 7, 1001000, '$u{柴胡}$w{半斤}    $u{黄芩}    $u{人参}    $u{甘草}$w{炙}    $u{生姜}$w{各三两、切、}    $u{大枣}$w{十三枚、擘}  $u{半夏}$w{半升、洗、}\n\n       右七味，以水一斗二升，煮取六升，去滓，再煎取三升，温服一升，日三服。另$a{伤寒例第四卷:小柴胡汤方 $m{大枣用量}$w{十二枚、擘} }  \n\n         若胸中烦而不呕者，去 $u{半夏}、 $u{人参}，加 $u{栝蒌实}$w{一枚}。\n         若渴，去 $u{半夏}，加 $u{人参}合前成四两半， $u{栝蒌根}$w{四两}。\n         若腹中痛者，去 $u{黄芩}，加 $u{芍药}$w{三两}。\n         若胁下痞鞕，去 $u{大枣}，加 $u{牡蛎}$w{四两}。\n         若心下悸，小便不利者，去 $u{黄芩}，加 $u{茯苓}$w{四两}。\n         若不渴，外有微热者，去 $u{人参}，加 $u{桂枝}$w{三两}，温覆取微汗愈。\n         若咳者，去 $u{人参}、 $u{大枣}，加 $u{五味子}$w{半升}，去 $u{生姜}，加 $u{干姜}$w{二两}。\n\n', 3, '', '柴胡,黄芩,人参,甘草,生姜,大枣,半夏', 620086219198533, '6702723B1605A370866EA14F10213752', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 14:37:19', 1, '超级管理员', '2024-12-11 15:34:37');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (432, '大柴胡汤', 348, 8, 1001000, '$u{柴胡}$w{半斤}    $u{黄芩}$w{三两}    $u{芍药}$w{三两}    $u{半夏}$w{半升(洗)}    $u{生姜}$w{五两、切}    $u{枳实}$w{四枚、炙}    $u{大枣}$w{十二枚、劈} $u{大黄}$w{二两}\n\n	右八味，以水一斗二升，煮取六升，去滓，再煎，温服二升，日三服。\n', 3, '', '柴胡,黄芩,芍药,半夏,生姜,枳实,大枣,大黄', 620088735297605, '53C67CE989C5049C11F6A4F5D2FFC021', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 14:47:33', 1, '超级管理员', '2024-12-16 09:40:25');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (433, '茯苓白术厚朴石膏黄芩甘草汤', 349, 6, 1001000, '$u{茯苓}$w{四两} $u{白术}$w{三两} $u{ 厚朴}$w{四两} $u{石膏}$w{半斤} $u{ 黄芩}$w{三两} $u{甘草}$w{二两、炙}\n右六味，以水一斗，煮取五升，每服一升五合余，日三服。', 3, '', NULL, 620091272020037, '3DF2E49902E56C2D57CCF15F9EAB516D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 14:57:53', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (434, '附子细辛黄连黄芩汤', 350, 4, 1001000, '$u{附子}$w{大者一枚（炮去皮破八片）} $u{细辛}$w{二两} $u{黄连}$w{四两} $u{黄芩}$w{二两}\n右四味，以水六升，煮取三升，温服一升，日三服。', 3, '', NULL, 620091835031621, '140666F7BC1A2B8CB3002DA8E3DE8EAC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 15:00:10', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (435, '乌梅丸', 351, 10, 1001000, '$u{乌梅}$w{三百枚}，$u{细辛}$w{六两}，$u{干姜}$w{十两}，$u{黄连}$w{十六两}，$u{当归}$w{四两}，$u{附子}$w{六两，炮去皮}，$u{蜀椒}$w{四两、出汗}，$u{桂枝}$w{六两、去皮}，$u{人参}$w{六两}，$u{黄柏}$w{六两}\n\n	$s{右十味}，异捣筛，合治之，以$u{苦酒}渍乌梅一宿，去核，蒸之五升米下，饭熟，捣成泥，和药令相得，内臼中，与$u{蜜}杵二千下，丸如梧子大。先食，饮服十丸，三服，稍加至二十丸。禁生冷，滑物，臭食等。\n', 30, '', '', 620093952835653, '0ECCD2FF4730A8A944A510D00EC01C95', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 15:08:47', 1, '超级管理员', '2024-12-16 14:30:04');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (436, '桂枝当归汤', 352, 6, 1001000, '$u{桂枝}$w{二两} $u{当归}$w{三两} $u{半夏}$w{一升} $u{芍药}$w{三两} $u{黄柏}$w{二两} $u{甘草}$w{二两（炙）}\n    右六味，以水七升，煮取四升，去滓，分温三服。', 3, '', '', 620094636822597, '86DD12059E1B9714AEF0F9A1C83DCD7C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 15:11:34', 1, '超级管理员', '2024-12-07 15:15:53');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (437, '大青龙汤加附子', 353, 8, 1001000, '$u{麻黄}$w{六两（去节）} $u{桂枝}$w{二两（去皮）}$u{ 甘草}$w{二两（炙）} $u{杏仁}$w{四十枚（去皮尖）} $u{生姜}$w{三两（切）} $u{大枣}$w{十枚（劈）} $u{石膏}$w{如鸡子大 }$u{附子}$w{一枚（炮去皮破八片）}\n\n       右八味，以水九升，先煮麻黄减二升，去上沫，纳诸药，煮取三升，去滓，温服一升，取微似汗，汗出多者温粉粉之，一服汗者，停后服；若复服汗多亡阳，遂虚，恶风烦躁不得眠也。', 1, '', '', 620095673098309, '1756F86F45DDB2AF22E3115F851A6850', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 15:15:47', 1, '超级管理员', '2024-12-13 21:49:42');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (438, '大黄石膏茯苓白术枳实甘草汤', 354, 6, 1001000, '$u{大黄}$w{四两} $u{石膏}$w{一斤} $u{茯苓}$w{三两} $u{白术}$w{四两} $u{枳实}$w{三两} $u{甘草}$w{三两（炙）}\n\n      右六味，以水八升，煮取五升，温分三服。', 3, '', NULL, 620096221794373, 'DE1F5742AA169318329E19B15944DDBF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-07 15:18:01', NULL, NULL, NULL);
