INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (473, '桂枝茯苓白术细辛汤', 389, 4, 1001000, '$u{桂枝}$w{三两 }，$u{茯苓}$w{四两 }，$u{白术}$w{三两 }，$u{细辛}$w{二两}\n\n      右四味，以水六升，煮取二升，去滓，温服一升，日再服。', 2, '', NULL, 620722812481605, '1478111E806E9A82E2CA86CB6088A4E8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-09 09:47:37', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (474, '桂枝麻黄各半汤', 390, 1, 1001000, '即$f{桂枝汤}三合，$f{麻黄汤}三合，并为六合，顿服之，将息如$f{桂枝汤}法。', 1, '', NULL, 620724466520133, 'FABF2E91C1847911235804DD1492B482', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-09 09:54:21', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (475, '桂枝汤', 391, 5, 1001000, '$u{桂枝}$w{三两（去皮） }，$u{芍药}$w{三两 }，$u{甘草}$w{二两（炙） }，$u{生姜}$w{三两（切） }，$u{大枣}$w{十二枚（劈）}\n\n        右五味，〖口父〗咀。以水七升，微火煮取三升，去滓，适寒温，服一升。服已须臾，啜热稀粥一升余，以助药力，温覆令一时许，遍身漐漐，微似有汗者益佳，不可令如水流漓，病必不除。若一服汗出病差，停后服，不必尽剂；若不汗，更服依前法；又不汗，后服小促其间，半日许，令三服尽；若病重者，一日一夜服，周时观之。服一剂尽，病证犹在者，更作服；若汗不出，乃服至二三剂。禁生冷、粘滑、肉面、五辛、酒酪、臭恶等物。', 3, '', '', 620725110902853, 'A3EB77D41496ADFE46600E4699D2797D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-09 09:56:59', 1, '超级管理员', '2024-12-18 18:39:29');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (476, '大青龙汤', 392, 7, 1001000, '$u{麻黄}$w{六两（去节） }、$u{桂枝}$w{二两（去皮） }、$u{甘草}$w{二两（炙） }、$u{杏仁}$w{四十枚（去皮尖） }、$u{生姜}$w{三两（切） }、$u{大枣}$w{十二枚（劈） }、$u{石膏}$w{如鸡子大（碎） }。\n\n      右七味，以水九升，先煮麻黄，减二升，去上沫，纳诸药，煮取三升，去滓，温服一升，取微似汗，汗多者，温粉粉之。一服汗出停后服。若复服汗多亡阳，遂虚，恶风烦躁，不得眠也。', 3, '', '', 620725403078725, '9F6F79881CF96014A7895780D7288A75', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-09 09:58:10', 1, '超级管理员', '2024-12-11 13:51:55');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (477, '白术茯苓厚朴汤', 393, 3, 1001000, '$u{白术}$w{三两 }，$u{茯苓}$w{四两 }，$u{厚朴}$w{二两（炙去皮）}，\n      右三味，以水五升，煮取一升五合，去滓，分温再服。', 2, '', NULL, 620726205059141, 'FBEB86BDCBC54E19A43287F8F5568D3B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-09 10:01:26', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (478, '麻黄茯苓汤', 394, 5, 1001000, '$u{麻黄}$w{二两（去节）}，$u{ 茯苓}$w{三两 }，$u{白术}$w{三两 }，$u{防己 }，$u{赤小豆}$w{一升}\n\n       右五味，以水七升，先煮麻黄，再沸，去上沫，纳诸药，煮取三升，去滓，温服一升，日三服。', 3, '', NULL, 620726585811013, 'B29D2290C6B8381B1E9208E488A7BCF5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-09 10:02:59', NULL, NULL, NULL);
