INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (480, '小青龙汤', 396, 8, 1001000, '$u{麻黄}$w{三两（去节） }，$u{ 芍药}$w{三两  }，$u{细辛}$w{三两  }，$u{桂枝}$w{三两（去皮）  }，$u{干姜}$w{三两  }，$u{半夏}$w{半升（洗） }，$u{ 甘草}$w{三两  }，$u{五味子}$w{半升}\n\n      右八味，以水一斗，先煮麻黄，减二升，去上沫，纳诸药，煮取三升，去滓，温服一升。日三服。\n\n       若渴去$u{半夏}，加$u{栝蒌根}$w{三两}；\n       若微利，若噎者，去$u{麻黄}，加$u{附子}$w{一枚}；\n       若小便不利，少服满者，去$u{麻黄}，加$u{茯苓}$w{四两}；\n       若喘者，加$u{杏仁}$w{半升（去皮尖）}。', 3, '', '', 620727372410949, 'C28E3973F3FEDF0E4A36B6558887C153', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-09 10:06:11', 1, '超级管理员', '2024-12-14 15:00:57');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (481, '五苓散', 397, 5, 1001000, '$u{猪苓}$w{十八铢（去皮）  }，$u{泽泻}$w{一两六铢  }，$u{茯苓}$w{十八铢  }，$u{桂枝}$w{半两（去皮）  }，$u{白术}$w{十八铢 }\n\n     右五味，捣为散，以白饮和服方寸匙，日三服，多饮暖水，汗出愈。\n\n    另 $a{伤寒论.桂版-辨太阳病脉证并治下}发黄者，加$u{茵陈蒿}}$w{十分}。\n\n        $a{伤寒论.桂版-辨阳明病脉证并治}诸黄家，但利其小便，五苓散加茵陈蒿主之；$f{五苓散}加$u{茵陈蒿}$w{十分}同末)。\n\n', 3, '', '', 620727910830149, 'E98049ED04B7867D989A3470F8732824', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-09 10:08:22', 1, '超级管理员', '2024-12-16 09:46:56');
