INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (484, '麻黄杏仁薏苡甘草汤', 400, 4, 1001000, '$u{麻黄}$w{一两  }，$u{杏仁}$w{二十枚（去皮尖） }，$u{ 薏苡}$w{一两  }，$u{甘草}$w{一两（炙） }，\n\n      右四味，以水六升，先煮麻黄，减二升，去上沫，纳诸药，煮取三升，去滓，温服一升，日三服。', 3, '', '', 620736015876165, '2145AE7E0D136CD01810C3E373A2BFD8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-09 10:41:21', 1, '超级管理员', '2024-12-09 10:44:21');
