INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (511, '桂枝去芍药加附子汤', 426, 5, 1001000, '$u{桂枝}$w{三两 }、$u{甘草}$w{二两（炙） }、$u{生姜}$w{三两（切） }、$u{大枣}$w{十二枚（劈） }、$u{附子}$w{一枚（炮去皮破八片） }。\n\n       右五味，以水七升，煮取三升，去滓，温服一升，日三服，将息如桂枝汤法。', 3, '', '', 621452631167045, '7FE05D3285941295887037AA2893796E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 11:17:16', 1, '超级管理员', '2024-12-11 13:55:02');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (512, '桂枝二麻黄一汤', 427, 2, 1001000, '即$f{桂枝汤}二升，$f{麻黄汤}一升，合为三升，每服一升，日三服，将息如$f{桂枝汤}法。', 3, '', '', 621453356089413, '5B07F7882EED0D98343F5DAA6ABEFDD9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 11:20:13', 1, '超级管理员', '2024-12-11 13:55:09');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (513, '桂枝二越婢一汤', 428, 7, 1001000, '$u{桂枝}$w{十八铢（去皮）}、$u{芍药}、$u{麻黄}、$u{甘草}$w{各十八铢（炙）}、$u{大枣}$w{四枚（劈）}、$u{生姜}$w{一两二铢（切）}、$u{石膏}$w{二十四铢（碎，绵裹）}。\n\n       右七味，以水六升，煮麻黄，去上沫，纳诸药，煮取三升，去滓，温服一升，日三服。', 3, '', '', 621453990277189, 'CBD375D850E0C58C59B5C1E783357685', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 11:22:48', 1, '超级管理员', '2024-12-11 13:55:14');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (514, '芍药甘草汤', 429, 2, 1001000, '芍药四两、甘草四两（炙）。\n\n    右二味，以水三升，煮取一升五合，去滓，分温再服之。', 2, '', '', 621454672957509, 'D2E6B8CDAEE0F37F5E40973D222BE7FA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 11:25:34', 1, '超级管理员', '2024-12-11 13:55:19');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (515, '四逆汤', 430, 4, 1001000, '$u{人参}$w{二两}、$u{甘草}$w{二两（炙）}、$u{干姜}$w{一两半}、$u{附子}$w{一枚（炮去皮破八片）}。\n\n      右四味，以水三升，煮取一升二合，去滓，分温二服。\n另$a{桂版。伤寒论-辨厥阴病脉证并治}若强可用大附子一枚，干姜二两。', 2, '', '', 621455212306501, '900A6FA69794BEC847CEBEB9E256F3CB', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 11:27:46', 1, '超级管理员', '2024-12-16 14:38:26');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (516, '地黄半夏牡蛎酸枣仁汤', 431, 4, 1001000, '$u{地黄}$w{六两}、$u{半夏}$w{半升}、$u{牡蛎}$w{二两}、$u{酸枣仁}$w{三两}。\n\n       右四味，以水四升，煮取二升，分温再服。', 2, '', '', 621455576428613, '717A27A8A5FE41D4590C4752B17F3C9C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 11:29:15', 1, '超级管理员', '2024-12-11 13:55:38');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (517, '竹叶石膏黄芩泽泻半夏甘草汤', 432, 6, 1001000, '}、$u{竹叶}$w{两把}、$u{石膏}$w{半斤（棉裹）}、$u{黄芩}$w{三两}、$u{泽泻}$w{二两}、$u{半夏}$w{半升}、$u{甘草}$w{二两}。\n\n       右六味，以水五升，煮取三升，去滓，温服一升，日三服。', 3, '', '', 621455902855237, 'BE28805C0BAB35951607379FDA2BBDDF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 11:30:35', 1, '超级管理员', '2024-12-11 13:55:43');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (518, '葛根汤', 433, 7, 1001000, '$u{葛根}$w{四两}、$u{麻黄}$w{三两（去节）}、$u{桂枝}$w{二两（去皮）}、$u{芍药}$w{二两}、$u{甘草}$w{二两（炙）}、$u{生姜}$w{三两（切）}、$u{大枣}$w{十二枚（劈）}。\n\n     右七味，以水一斗，先煮麻黄葛根，减二升，去上沫，纳诸药，煮取三升，去滓，温服一升，复取微似汗，不须啜粥，余如桂枝法将息及禁忌，诸汤皆仿此。', 3, '', '', 621463376150597, '3B6351EC921216DCC2E704E908480C0E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 12:00:59', 1, '超级管理员', '2024-12-16 16:57:29');
