INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (522, '干姜附子汤', 437, 2, 1001000, '$u{干姜}$w{一两（炮） }、$u{附子}$w{一枚（破八片炮） }。\n      右二味，以水三升，煮取一升，去滓，顿服。', 2, '', NULL, 621495830360133, '76C00B2E266C1FF92AF1E877EAB78F80', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 14:13:02', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (523, '桂枝去芍药加人参生姜汤', 438, 5, 1001000, '$u{桂枝}$w{三两（去皮） }、$u{甘草}$w{二两（炙） }、$u{大枣}$w{十二枚（劈） }、$u{人参}$w{三两，生姜}$w{四两（切）}。\n\n       右五味，以水一斗二升，煮取三升，去滓，温服一升，日三服。', 2, '', NULL, 621496481996869, 'E800C46B3D7FDBC60F7F35FD2599CBD9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 14:15:42', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (524, '桂枝甘草汤', 439, 2, 1001000, '$u{桂枝}$w{四两（去皮） }、$u{甘草}$w{二两（炙） }。\n\n    右二味，以水三升，煮取一升，去滓，顿服。', 2, '', NULL, 621503101472837, '4D7490DB31A9B54999A9029C3FA4CD6A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 14:42:38', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (525, '茯苓桂枝甘草大枣汤', 440, 4, 1001000, '$u{茯苓}$w{半斤}、$u{桂枝}$w{四两}、$u{甘草}$w{二两（炙）}、$u{大枣}$w{十五枚（劈）}。\n\n    右四味，以甘澜水一斗，先煮茯苓减二升，纳诸药，煮取三升，去滓，温服一升，日三服。\n\n作甘澜水法，取水二斗，置大盆内，以杓扬之，水上有珠子五六千颗相逐，取用之。', 3, '', NULL, 621503598514245, '8AFDF490C16B4250CC72B34DFA2E4F8D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 14:44:39', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (526, '奔豚汤', 441, 9, 1001000, '$u{甘草}$w{二两（炙）}、$u{芎藭}$w{二两}、$u{当归}$w{二两}、$u{黄芩}$w{二两}、$u{芍药}$w{二两}、$u{半夏}$w{四两}、$u{生姜}$w{四两}、$u{葛根}$w{五两}、$u{桂枝}$w{三两}。\n\n      右九味，以水二斗，煮取五升，温服一升，日三服，夜二服。', 5, '', NULL, 621504197812293, '1FE4241F74DFECA5C6EE99A59A1A3407', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 14:47:05', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (527, '厚朴生姜半夏甘草人参汤', 442, 5, 1001000, '$u{厚朴}$w{半斤（炙去皮） }、$u{生姜}$w{半斤（切） }、$u{半夏}$w{半斤（洗） }、$u{甘草}$w{二两（炙） }、$u{人参}$w{一两 }。\n      右五味，以水一斗，煮取三升，去滓，温服一升，日三服。', 3, '', NULL, 621504626085957, '1F8DCD133413EA29DEBE3623E6DE228E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 14:48:50', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (528, '茯苓桂枝白术甘草汤', 443, 4, 1001000, '$u{茯苓}$w{四两 }、$u{桂枝}$w{三两 }、$u{白术}$w{二两 }、$u{甘草}$w{二两（炙） }。\n\n      右四味，以水六升，煮取三升，去滓，分温三服，小便利则愈。', 3, '', '', 621506150359109, '432C36EC6BF0801D119168938DB6D518', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 14:55:02', 1, '超级管理员', '2024-12-17 10:57:00');
