INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (530, '茯苓四逆汤', 445, 5, 1001000, '$u{茯苓}$w{六两}、$u{人参}$w{二两}、$u{附子}$w{一枚（生用，去皮，破八片）}、$u{甘草}$w{二两（炙）}、$u{干姜}$w{一两半}。\n\n     右五味，以水五升，煮取三升，去滓，温服七合，日三服。', 3, '', NULL, 621506960281669, 'B82B3EA534DE2D47B1031A2A9254A92C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 14:58:20', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (531, '茯苓甘草汤', 446, 4, 1001000, '$u{茯苓}$w{二两}、$u{桂枝}$w{二两}、$u{甘草}$w{一两（炙）}、$u{生姜}$w{三两（切）}。\n\n     右四味，以水四升，煮取二升，去滓，分温三服。', 3, '', NULL, 621507978387525, '349B28EB02C7EEEDB50197840499FA4E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 15:02:28', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (532, '栀子生姜豉汤', 447, 3, 1001000, '$u{栀子}$w{十四枚（劈）}、$u{生姜}$w{五两}、$u{香豉}$w{四合（棉裹）}。\n\n     右三味，以水四升，先煮栀子生姜取二升半，纳豉煮取一升半，去滓，分二服，温进一服，得吐者止后服。', 2, '', NULL, 621508913127493, 'CBE7229773DC88F519E7F9243F3242D5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 15:06:17', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (533, '栀子甘草豉汤', 448, 3, 1001000, '$u{栀子}$w{十四枚（劈）}、$u{甘草}$w{二两（炙）}、$u{香豉}$w{四合（棉裹）}。\n\n      右三味，以水四升，先煮栀子甘草取二升半，纳豉煮取一升半，去滓，分二服，温进一服，得吐者止后服。', 2, '', NULL, 621509398786117, 'F299401BA2AB3C4A7FC1FBFE1DDAEBD0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 15:08:15', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (534, '栀子干姜汤', 449, 2, 1001000, '$u{栀子}$w{十四枚（劈） }、$u{生姜}$w{二两（切）}。\n\n     右二味，以水三升半，煮取一升半，去滓，分温二服，进一服得吐者止后服。\n', 2, '', '', 621509725052997, '8A8D3CFF388293172EB2769979960882', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 15:09:35', 1, '超级管理员', '2024-12-11 15:09:40');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (535, '栀子豉汤', 450, 2, 1001000, '$u{栀子}$w{十四枚（劈） }、$u{香豉}$w{四合（棉裹） }。\n\n    右二味，以水四升，先煮栀子得二升半，纳豉煮取一升半，去滓，分为二服，温进一服，得吐者止后服。', 2, '', '', 621510211682373, '9005303F1B638EDE42894D8B4B674395', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 15:11:34', 1, '超级管理员', '2024-12-11 15:11:38');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (536, '栀子厚朴枳实汤', 451, 3, 1001000, '$u{栀子}$w{十四枚（劈） }、$u{厚朴}$w{四两（炙去皮） }、$u{枳实}$w{四枚（水浸炙令黄） }。\n\n      以上三味，以水三升半，煮取一升半，去滓，分二服。温进一服，得吐者止后服。', 2, '', NULL, 621511194681413, 'BBE37F35EBD7FDC6F3697C20202B3023', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 15:15:34', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (537, '真武汤', 452, 5, 1001000, '$u{茯苓}$w{三两}、$u{芍药}$w{三两}、$u{生姜}$w{三两（切）}、$u{白术}$w{二两}、$u{附子}$w{一枚（炮去皮破八片）}。\n\n    右五味，要以水八升，煮取三升，去滓，温服七合，日三服。\n    若咳者，加$u{五味子}$w{半升}，$u{细辛$u{干姜}$w{各一两}；\n    若小便不利者，加$u{茯苓}$w{一两}；\n    若下利者，去$u{芍药}，加$u{干姜}$w{二两}；\n    若呕者，去$u{附子}，加$u{生姜}$w{足前成半斤}。', 3, '', '', 621511792930885, '6B23C6776F71B9DCDBA4F77CB5C8AAF3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 15:18:00', 1, '超级管理员', '2024-12-16 14:06:19');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (538, '禹余粮丸', 453, 6, 1001000, '$u{禹余粮}$w{四两}、$u{人参}$w{三两}、$u{附子}$w{二枚}、$u{五味子}$w{三合}、$u{茯苓}$w{三两}、$u{干姜}$w{三两}。\n\n     右六味，蜜为丸，如梧子大，每服二十丸。', 20, '', NULL, 621512701849669, '77D871D16ECF008FBE7D9CB0CB8F5FB3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 15:21:41', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (539, '小建中汤', 454, 6, 1001000, '$u{桂枝}$w{三两}、$u{芍药}$w{六两}、$u{甘草}$w{二两 (炙)}、$u{生姜}$w{三两（切）}、$u{大枣}$w{十二枚（劈）}、$u{胶饴}$w{一升}。\n\n      右六味，以水七升，先煮五味取三升，去滓内饴更上微火消解，温服一升，日三服。呕家不可用，以甜故也。\n', 3, '', '', 621517232099397, '2C45A3786B01E3EB604CCF47AA05A435', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 15:40:08', 1, '超级管理员', '2024-12-16 09:50:24');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (540, '小陷胸汤', 455, 3, 1001000, '$u{黄连}$w{一两 }、$u{半夏}$w{半升 }、$u{括蒌实}$w{大者一枚 }\n\n           右三味，以水六升，先煮括蒌取三升，纳诸药，煮取二升，去滓，分温三服。', 3, '', '', 621518028091461, '1A3706CE3809D76538E17CF00AB75EB9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 15:43:22', 1, '超级管理员', '2024-12-14 14:32:01');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (541, '柴胡加芒消汤', 456, 8, 1001000, '$u{柴胡}$w{二两十六铢 }、$u{黄芩}$w{一两 }、$u{人参}$w{一两 }、$u{甘草}$w{一两（炙） }、$u{生姜}$w{一两（切） }、$u{芒硝}$w{二两 }、$u{大枣}$w{四枚 }、$u{半夏}$w{二十铢 }。\n\n     右八味，以水四升，煮取二升，去滓，纳芒硝，更煮微沸，分温再服，不解更作。', 2, '', NULL, 621518673158213, 'EBCE47384F209809DE63A62981AF43C5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 15:45:59', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (542, '桃仁承气汤', 457, 5, 1001000, '$u{桃仁}$w{五十个（去皮尖） }、$u{大黄}$w{四两 }、$u{桂枝}$w{二两 }、$u{甘草}$w{二两（炙） }、$u{芒硝}$w{二两}。\n\n      右五味，以水七升，煮四味，取二升，去滓，纳芒硝，更上火微沸。下火，先食温服五合，日三服，当微利。', 3, '', NULL, 621519277412421, '75C246B0EC863242663840FD0989D0DD', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-11 15:48:27', NULL, NULL, NULL);
