INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (560, '大陷胸汤', 475, 3, 1001000, '$u{大黄}$w{六两}、$u{芒硝}$w{一升}、$u{甘遂}$w{一钱 (匙)}。\n\n         右三味，以水六升，先煮大黄，取二升，去滓，纳$u{芒硝}，煮二沸，纳$u{甘遂}末，温服一升，得快利，止后服。', 2, '', NULL, 622556198535237, '99E0B2FC1BDF8C97C34CCB090AC83428', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-14 14:07:41', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (561, '文蛤散', 477, 7, 1001000, '$u{文蛤}$w{五两}、$u{麻黄}$w{三两}、$u{甘草}$w{三两}、$u{生姜}$w{三两}、$u{石膏}$w{五两}、$u{杏仁}$w{五十粒 (去皮尖)}、$u{大枣}$w{十二枚 (劈)}。\n\n        右七味，为散，以沸汤和一方寸匙，汤用五合，调服，假令汗出已，腹中痛者，与$u{芍药}$w{三两}。', 1, '', NULL, 622564982030405, 'ECD5FAFCD984014C7B06918A27BDE2A6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-14 14:43:26', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (562, '白散', 478, 3, 1001000, '$u{桔梗}$w{三分}、$u{巴豆}$w{一分}、$u{贝母}$w{三分}。\n\n        右三味为散，更于臼中杵之，以白饮和服，强人$m{半钱匙}，羸者减之。病在膈上必吐，在膈下必利；不利$m{进热粥一杯}，利不止$n{进冷粥一杯}。', 1, '', NULL, 622565593514053, '5BC27AD6C68EBDA12B91B2AE7176D66D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-14 14:45:55', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (563, '柴胡桂枝干姜汤', 479, 7, 1001000, '$u{柴胡}$w{半斤}、$u{桂枝}$w{三两}、$u{干姜}$w{二两}、$u{括蒌根}$w{四两}、$u{黄芩}$w{三两}、$u{牡蛎}$w{二两 (熬)}、$u{甘草}$w{二两 (炙)}。\n\n         右七味，以水一斗二升，煮取六升，去滓，再煎取三升，温服一升，日三服。初服微烦，复服，汗出便愈。', 3, '', NULL, 622567195979845, '83F9A11C596D1AEFFD38BA45EC634E34', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-14 14:52:26', NULL, NULL, NULL);
