INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (565, '十枣汤', 481, 4, 1001000, '$u{芫花 (熬)}、$u{甘遂}、$u{大戟}。\n          \n        右三味，各$w{等分}，别捣为散，以水一升半，先煮$u{大枣}$w{肥者十枚}，取八合，去滓，纳药末，强人服一钱匙，羸人服半钱，温服之，平旦服，若下少，病不除者，明日更服，加半钱，得快下利后，糜粥自养。', 2, '', NULL, 622570224992325, '723C14F3934055C5B5F607DF4AB6C907', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-14 15:04:46', NULL, NULL, NULL);
