INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (571, '桂枝人参汤', 487, 5, 1001000, '$u{桂枝}$w{四两}、$u{甘草}$w{四两 (炙)}、$u{白术}$w{三两}、$u{人参}$w{三两}、$u{干姜}$w{三两}。\n\n         右五味，以水九升，先煮四味，取五升，纳桂枝，更煮取三升，去滓，温服一升，日再服，夜一服。', 4, '', NULL, 622575232778309, '15433C9F9C9BCCEDF61662E84E84326D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-14 15:25:08', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (572, '瓜蒂散', 488, 3, 1001000, '$u{瓜蒂}$w{一分 (熬)}、$u{赤小豆}$w{一分}。\n\n         右二味，各别捣筛，为散已，合治之，取一钱匙，以$u{香豉}$w{一合}，用热汤七合，煮作稀糜，去津，取汁，和散温顿服之，不吐者，少少加，得快吐乃止。诸亡血，虚家，不可与也。\n', 1, '', '', 622576114958405, '3D575B159296EAD395BE9DAFC35A42CF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-14 15:28:44', 1, '超级管理员', '2024-12-16 14:40:36');
