INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (575, '黄连汤', 491, 7, 1001000, '$u{黄连}$w{三两}、$u{甘草}$w{三两 (炙)}、$u{干姜}$w{三两}、$u{桂枝}$w{三两}、$u{人参}$w{二两}、$u{半夏}$w{半升 (洗)}、$u{大枣}$w{十二枚 (劈)}。\n\n        右七味，以水一斗，煮取六升，去滓，温服一升，日三服，夜三服。', 6, '', NULL, 622577977098309, '115B65E1C679D6709B4B2253A941127A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-14 15:36:18', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (576, '炙甘草汤', 492, 9, 1001000, '$u{甘草}$w{四两 (炙)}、$u{生姜}$w{三两 (切)}、$u{人参}$w{二两}、$u{地黄}$w{半斤}、$u{桂枝}$w{三两}、$u{麦门冬}$w{半升}、$u{阿胶}$w{二两}、$u{麻仁}$w{半升}、$u{大枣}$w{十二枚 (劈)}。\n\n        右九味，以清酒七升，先煮八味，取三升，去滓，纳胶烊消尽，温服一升，日三服。\n\n另:$a{桂版。伤寒论-辨咳嗽水饮黄汗历节病脉证并治【炙甘草汤】} $u{地黄}$w{一斤}、$u{大枣}$w{三十枚}。\n', 3, '', '', 622578611478597, '0E7FA3EC7177C45C01FB29DE69BA77DE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-14 15:38:53', 1, '超级管理员', '2024-12-17 10:51:12');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (577, '猪苓汤', 493, 5, 1001000, '$u{猪苓}$w{一两 (去皮)}、$u{茯苓}$w{一两}、$u{泽泻}$w{一两}、$u{阿胶}$w{一两}、$u{滑石}$w{一两 (碎)}。\n\n         右五味，以水四升，先煮四味，取二升，去滓，纳阿胶烊消，温服七合，日三服。', 3, '', NULL, 622602932981829, '342A351D7F944E44175F293E505B2490', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-14 17:17:51', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (578, '白蜜煎', 494, 4, 1001000, '$u{人参}$w{一两}、$u{地黄}$w{六两}、$u{麻仁}$w{一升}、$u{白蜜}$w{八合}。\n\n         右四味，以水一斗，先煎三味，取五升，去滓，纳蜜，再煎一二沸，每服一升，日三夜二。', 5, '', NULL, 622605125009477, '81D979E388CADACC3B81C2EFDD551BA6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-14 17:26:46', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (579, '大猪胆汁', 495, 1, 1001000, '$u{大猪胆}$w{一枚}。右一味，泄汁，和醋少许，灌谷道中，如一食顷，当大便出宿食甚多。', 1, NULL, '', 623186570125381, '7059671DC3F8AF95E52E6F371F3A14C7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 08:52:41', 1, '超级管理员', '2024-12-20 10:25:17');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (580, '蜜煎导', 496, 1, 1001000, '$u{食蜜}$w{七合}。右一味，纳铜器中，微火煎之，稍凝如饴状，搅之勿令焦着，可丸时，并手捻作挺，令头锐，大如指，长二寸许，当热时急作，冷则鞕，纳谷道中，以手紧抱，欲大便时乃去之。', 1, '', '', 623187695489093, '9E34E3D9477E29C10F355F1BF5173A4C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 08:57:15', 1, '超级管理员', '2024-12-16 08:59:56');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (581, '茵陈蒿汤', 497, 3, 1001000, '$u{茵陈蒿}$w{六两}、$u{栀子}$w{十四枚 (劈)}、$u{大黄}$w{二两 (去皮)}。\n\n         右三味，以水一斗二升，先煮茵陈，减六升，纳二味，煮取三升，去滓，分温三服，小便当利，尿如皂荚汁状，色正赤，一宿病减，黄从小便去也。', 3, '', NULL, 623188665339973, 'C3B8E58F63A0222CF757DA208CB59853', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 09:01:12', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (582, '小半夏汤', 498, 2, 1001000, '$u{半夏}$w{一升}、$u{生姜}$w{半斤}。\n\n        右二味，以水七升，煮取一升半，去滓，分温再服。', 2, '', NULL, 623191871356997, '68F1C4899C7FD57748773A575CCB3CC1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 09:14:15', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (583, '麻子仁丸', 499, 6, 1001000, '$u{麻子仁}$w{二升}、$u{芍药}$w{半斤}、$u{枳实}$w{半斤 (炙)}、$u{大黄}$w{一斤 (去皮)}、$u{厚朴}$w{一只 (炙)}、$u{杏仁}$w{一升 (去皮尖)}。\n\n            右六味，蜜为丸，如梧桐子大，饮服十丸，日三服，渐加，以知为度。', 3, '', NULL, 623192843550789, 'ED3CD89B1248033BCA04856AAA70DD7F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 09:18:12', NULL, NULL, NULL);
