INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (586, '栀子大黄汤', 502, 4, 1001000, '$u{栀子}$w{十四枚}、$u{大黄}$w{一两}、$u{枳实}$w{五枚}、$u{豉}$w{一升}。\n\n        右四味，以水六升，煮取三升，去滓，温服一升，日三服。', 3, '', NULL, 623196718719045, 'D60AE9DE7DF8CE11C734CEE97B9BAFB1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 09:33:58', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (587, '猪膏发煎', 503, 2, 1001000, '$u{猪膏}$w{半斤}、$u{乱发}$w{如鸡子大三枚}。\n\n        右二味，和膏煎之，发消药成，分再服，病从小便出。', 2, NULL, NULL, 623197336551493, '987C73AC0A789FF5FF263F7083C4350D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 09:36:29', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (588, '大黄硝石汤', 504, 4, 1001000, '$u{大黄}$w{四两}、$u{黄柏}$w{四两}、$u{芒硝}$w{四两}、$u{栀子}$w{十五枚}。\n\n        右四味，以水六升，先煮三味，取二升，去滓，纳硝，更煮取一升，顿服。', 2, '', NULL, 623197758210117, '9EE20437125AFFCB70B24B58E19A3CD4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 09:38:12', NULL, NULL, NULL);
