INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (610, '桃花汤', 526, 3, 1001000, '$u{赤石脂}$w{一斤 (一半全用一半筛末)}、$u{干姜}$w{一两}、$u{粳米}$w{一升}。\n\n       右三味，以水七升，煮米令熟，去滓，温服七合，纳赤石脂末方寸匙，日三服，若一服愈，余勿服。', 3, '', NULL, 623258473648197, '2973A2961792AE150936C58EE53A0AE8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 13:45:15', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (611, '猪肤汤', 527, 2, 1001000, '$u{猪肤}$w{一斤}。\n \n         右一味，以水一斗，煮取五升，去滓，加$u{白蜜}$w{一升}，$n{白粉}$w{五合}，熬香，和令相得，分温六服。(白粉即米粉)', 6, '', '', 623259439755333, '965F27B47A1FA1E24E6DFB893487CE4B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 13:49:11', 1, '超级管理员', '2024-12-16 13:49:57');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (612, '甘草汤', 528, 1, 1001000, '$u{甘草}$w{二两}。\n\n         右一味，以水三升，煮取一升半，去滓，温服七合，日二服。', 2, '', NULL, 623260165754949, '64AC3C27F3186EA0B4B30E22DE62FBDB', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 13:52:08', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (613, '桔梗汤', 529, 2, 1001000, '$u{桔梗}$w{一两}、$u{甘草}$w{二两}。\n\n       右二味，以水三升，煮取一升，去滓，温分再服。', 2, '', NULL, 623260440973381, '2FFEA22EB7955B96068382640DE7C2E4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 13:53:16', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (614, '苦酒汤', 530, 3, 1001000, '$u{半夏}$w{十四枚 (洗破如枣核)}、$u{鸡子}$w{一枚 (去黄纳上$u{苦酒}着鸡子壳中)}。\n\n        右二味，纳半夏，着苦酒中，以鸡子壳，置刀环中，安火上，令三沸，去滓，少少含咽之，不差，更作三剂。', 3, '', NULL, 623261268455493, 'CCB7BFF3FF7728934B97B8D783B3C39C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 13:56:38', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (615, '半夏散', 531, 3, 1001000, '$u{半夏} }$w{(洗)}、$u{桂枝}、$u{甘草} }$w{(炙)}。\n\n       右三味，$w{等分}，各别捣筛已，合治之，白饮和服方寸匙，日三服，若不能散服者，以水一升煎七沸，纳散两方寸匙，更煎三沸，下火令小冷，少少咽之。', 3, '', NULL, 623261992726597, 'C688F56DBFB4002705D3CA604B5ED476', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 13:59:34', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (616, '白通汤', 532, 3, 1001000, '$u{葱白}$w{四茎}、$u{干姜}$w{一两}、$u{附子}$w{一枚 (生用去皮破八片)}。\n\n          右三味，以水三升，煮取一升，去滓，分温再服。', 2, '', NULL, 623262430675013, 'C8B0850BA4B9FD7D7DC818737C97E148', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 14:01:21', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (617, '白通加猪胆汁汤', 533, 5, 1001000, '$u{葱白}$w{四茎}、$u{干姜}$w{一两}、$u{附子}$w{一枚 (生用去皮破八片)}、$u{人尿}$w{五合}、$u{猪胆汁}$w{一合}。\n\n           右五味，以水三升，先煮三物，取一升，去滓，纳人尿，猪胆汁，和令相得，分温再服，若无胆汁亦可用。', 2, '', NULL, 623263001698373, '44BE292A1B992EB1DB009992E9B0A11B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 14:03:41', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (618, '四逆散', 534, 4, 1001000, '$u{甘草}$w{二两 (炙)}、$u{附子}$w{大者一枚}、$u{干姜}$w{一两半}、$u{人参}$w{二两}。\n\n       右四味，捣筛，白饮和服方寸匙，\n            咳者去$u{人参}加、$u{五味子}、$u{干姜}$w{各五分}，\n            并主下利；悸者，加$u{桂枝}$w{五分}；\n            小便不利者，加$u{茯苓}$w{五分}；\n            泄利下重者，先以水五升，煮$u{薤白}$w{三两}，取三升，去滓，以散三方寸匙纳汤中，煮取一升半，分温再服。', 2, '', NULL, 623266213122117, '90A3793649B123468FC76A625F624008', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 14:16:45', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (619, '当归四逆加人参附子汤', 535, 9, 1001000, '$u{当归}$w{三两}、$u{桂枝}$w{三两 (去皮)}、$u{芍药}$w{三两}、$u{细辛}$w{三两}、$u{甘草}$w{二两 (炙)}、$u{木通}$w{二两}、$u{大枣}$w{二十五枚 (劈)}、$u{人参}$w{三两}、$u{附子}$w{一枚 (炮去皮破八片)}。\n\n         右九味，以水八升，煮取三升，去滓，温服一升，日三服。', 3, '', '', 623270614896709, '136FD10C7C49343988AA6B18E89931C1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 14:34:39', 1, '超级管理员', '2024-12-16 14:34:46');
