INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (623, '麻黄升麻汤', 539, 7, 1001000, '$u{麻黄}$w{二两半 (去节)}、$u{升麻}$w{一两}、$u{知母}$w{一两}、$u{黄芩}$w{一两半}、$u{桂枝}$w{二两}、$u{白术}$w{一两}、$u{甘草}$w{一两 (炙)}。\n\n         右七味，以水一斗，先煮麻黄去上沫，纳诸药，煮取三升，去滓，温服一升，日三服。', 3, '', NULL, 623274218528837, '45BB66DBAAFC9EE119892E8E5AF55A62', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 14:49:19', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (624, '干姜黄芩黄连人参汤', 540, 4, 1001000, '$u{干姜}$w{三两}、$u{黄芩}$w{三两}、$u{黄连}$w{三两}、$u{人参}$w{三两}。\n\n        右四味，以水六升，煮取二升，去滓，分温再服。', 2, '', NULL, 623274598084677, '2D63C2940FC17DFB434DF4469E02B2E4', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 14:50:52', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (625, '柏叶阿胶汤', 541, 4, 1001000, '$u{柏叶}$w{三两}、$u{阿胶}$w{二两}、$u{干姜}$w{二两 (炮)}、$u{牡丹}$w{三两}。\n\n       右四味，以水三升，先煮三味，取二升，去滓，纳胶烊消，温服一升，日再服。', 2, '', NULL, 623275127345221, 'CA8B6F4CE3F2A2FB7EBAEF53EC6F92FE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 14:53:01', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (626, '白头翁汤', 542, 4, 1001000, '$u{白头翁}$w{二两}、$u{黄连}、$u{黄柏}、$u{秦皮}$w{各三两}。\n\n       右四味，以水七升，煮取二升，去滓，温服一升，不愈更服一升。', 2, '', NULL, 623276290871365, '6C42C66F807C93B655E38D520CB2CD43', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 14:57:45', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (627, '白头翁加阿胶甘草汤', 543, 3, 1001000, '$u{白头翁}$w{二两}、$u{甘草}$w{二两}、$u{阿胶}$w{二两}、$u{黄连}$w{三两}、$u{黄柏}$w{三两}、$u{秦皮}$w{三两}。\n\n        右六味，以水七升，煮取二升半，去滓，纳胶烊消，分温三服。', NULL, '', NULL, 623276686344261, 'DA1DC3335A93CC937AE2AFBD2F6C08E3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 14:59:22', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (628, '紫参汤', 544, 2, 1001000, '$u{紫参}$w{半斤}、$u{甘草}$w{三两}。\n\n          右二味，以水五升，先煮紫参取二升，纳甘草，煮取一升半，去滓，分温再服。', 2, '', NULL, 623278029180997, 'F737C8EA419B87249BAF2F34DFC0DBB9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 15:04:50', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (629, '诃黎勒散', 545, 1, 1001000, '$u{诃黎勒}$w{十枚 (煨)}。右一味为散，粥饮和，顿服之。', 2, '', NULL, 623278349283397, 'AFBD43B78BCAC2F6255D429AD15B12F1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 15:06:08', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (630, '半夏干姜散', 546, 2, 1001000, '$u{半夏}、$u{干姜}$w{各等分}。右二味，杵为散，取方寸匙，浆水一升半，煮取七合，顿服之。', 2, '', NULL, 623279279398981, '840841051D9998DCFAB5A0B30ACC9E87', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 15:09:55', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (631, '生姜半夏汤', 547, 2, 1001000, '$u{生姜}$w{一斤}、$u{半夏}$w{半升}。\n\n        右二味，以水三升，先煮半夏，取二升，纳生姜汁，煮取一升，去滓，小冷，分四服，日三，夜一，呕止，停后服。', 4, '', NULL, 623279712194629, 'C5887481FE84D5A3F2F4A354018BFDD2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 15:11:41', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (632, '橘皮汤', 548, 2, 1001000, '$u{橘皮}$w{四两}、$u{生姜}$w{半斤}。\n\n          右二味，以水七升，煮取三升，去滓，温服一升，下咽即愈。', 2, '', NULL, 623280065499205, 'BFED4B9ED473A681562DE78B80306C3F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 15:13:07', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (633, '橘皮竹茹汤', 549, 6, 1001000, '$u{橘皮}$w{二斤}、$u{竹茹}$w{二升}、$u{人参}$w{一两}、$u{甘草}$w{五两}、$u{生姜}$w{半斤}、$u{大枣}$w{三十枚}。\n\n        右六味，以水一斗，煮取三升，去滓，温服一升，日三服。', 3, '', NULL, 623280380407877, '9FCFDBE6E0DFCEC62BD7951C4817A526', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 15:14:24', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (634, '黄连茯苓汤', 550, 6, 1001000, '$u{黄连}$w{二两}、$u{茯苓}$w{三两}、$u{阿胶}$w{一两半}、$u{芍药}$w{三两}、$u{黄芩}$w{三两}、$u{半夏}$w{一升}。\n\n        右六味，以水一斗，先煮五味，取三升，去滓，纳胶烊消，分温三服。\n\n            若胸中热甚者，加$u黄连}$w{一两}，合前成$m{三两}；\n            腹满者，加$u厚朴}$w{二两}；\n            人虚者，加$u甘草}$w{二两}，\n            渴者，去$u半夏}，加$u括蒌根}$w{二两}。', 3, '', NULL, 623281695641669, 'F836403405503BC124BF08D1460A6DAC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 15:19:45', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (635, '甘草粉蜜汤', 551, 3, 1001000, '$u{甘草}$w{二两}、$u{白粉}$w{一两 (即铅粉)}、$u{蜜}$w{四两}。\n\n       右三味，以水三升，先煮甘草，取二升，去滓，纳粉蜜搅令和，煎如薄粥，温服一升，差，止后服。\n\n注：$a{“白粉”：会通本注“即铅粉”（另有猪肤汤亦用白粉，却注为米粉）。宋文清通过南阳风土习惯考证认为“小麦粉”。附：《成都中医学院学报》(1986.11.18)报道，四川省某县1970年7月发生一起应用甘草粉蜜汤集体驱蛔，因使用铅粉，致使接受该方的74人全部中毒，无一幸免。中毒者在服药时曾觉药有铅臭，数小时后心烦，轻微呕吐，胃中嘈杂不适。2～9天内先后不同程度出现头昏头痛，身软无力，懒言嗜睡，口臭流涎，口腔糜烂，食欲逐渐下降，胸腹胀满，四肢及眼胞浮肿。部分病例在牙龈边缘可见蓝灰色铅线。中毒者初起面色灰白少华，大便秘结；3～5天后部分病人面色发黄，甚至全身发黄；大便由秘结转溏泻，小便深黄量少。舌质：中毒初中期淡红，苔白滑或厚腻；中后期有少数患者出现舌绛少苔；脉象多虚弦、滑数无力或见有濡弱之脉。经用昆布、海藻、金钱草、板蓝根等加减治疗，除1例死亡外，全部治愈。据此，作者认为原方“粉”，应为米粉。}', 2, '', '', 623282345422917, '980D1EECDE90AA06E4A450E26D0A75E5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 15:22:23', 1, '超级管理员', '2024-12-16 15:26:43');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (636, '当归生姜羊肉汤', 552, 3, 1001000, '$u{当归}$w{三两}、$u{生姜}$w{五两}、$u{羊肉}$w{一斤}。\n\n          右三味，以水八升，煮取三升，温服七合，日三眼。\n               寒多者加$u{生姜}$w{成一斤}；痛多而呕者，加$u{橘皮}$w{二两}、$u{白术}$w{一两}；加$u{生姜}者，亦加水五升，煮取三升二合，分温三服。', 3, '', NULL, 623284319199301, '221BDCF0B8AC0762829C77789E179C14', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 15:30:25', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (637, '乌头桂枝汤', 553, 1, 1001000, '$u{乌头}$w{五枚}。\n\n         右一味，以$u{蜜}二升，煮减半，去滓，以$f{桂枝汤}$w{五合}，解之，令得一升，初服二合，不知即服三合，又不知加至五合，其知者如醉状，得吐者为中病。', 2, '', NULL, 623285086789701, 'E38CE83126142F2660A58D014A38FD40', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 15:33:33', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (638, '蜘蛛散', 554, 2, 1001000, '$u{蜘蛛}$w{十四枚 (熬)}、$u{桂枝}$w{一两}。\n\n         右二味，为散，以白饮和服方寸匙，日再服，蜜丸亦可。', 2, '', NULL, 623285602357317, '8FDC9E471330379CDCB35B873EED8EBB', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 15:35:39', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (639, '肾气丸', 555, 8, 1001000, '$u{地黄}$w{八两}、$u{薯蓣}$w{四两}、$u{山茱萸}$w{四两}、$u{泽泻}$w{三两}、$u{牡丹皮}$w{三两}、$u{茯苓}$w{三两}、$u{桂枝}$w{一两}、$u{附子}$w{一枚 (炮)}。\n\n          右八味，末之，炼蜜和丸，如梧子大，$n{酒}下十五丸，渐加至二十五丸，日再服，白饮下亦可。', 15, '', NULL, 623286233473093, 'DF1BB67C392BE64F55B3ACEBC1F6E499', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 15:38:13', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (640, '文蛤汤', 556, 7, 1001000, '$u{文蛤}$w{五两}、$u{麻黄}$w{三两}、$u{甘草}$w{三两}、$u{生姜}$w{三两}、$u{石膏}$w{五两}、$u{杏仁}$w{五十枚}、$u{大枣}$w{十二枚}。\n\n           右七味，以水六升，煮取二升，去滓，温服一升，汗出即愈，若不汗，再服。', 2, '', '', 623286861025349, '1E3A73A57A00FE8D6B0E576D232C127D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 15:40:46', 1, '超级管理员', '2024-12-16 15:40:51');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (641, '小柴胡加茯苓汤', 557, 8, 1001000, '$u{柴胡}$w{半斤}、$u{黄芩}$w{三两}、$u{人参}$w{二两}、$u{半夏}$w{半升 (洗)}、$u{甘草}$w{三两}、$u{生姜}$w{二两 (切)}、$u{大枣}$w{十二枚 (劈)}、$u{茯苓}$w{四两}。\n\n         右八味，以水一斗二升，煮取六升，去滓，再煎，取三升，温服一升，日三服。', 3, '', NULL, 623287344672837, 'ED8E47BD2D9AD1CE08545F929C4DE181', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 15:42:44', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (642, '白术茯苓半夏枳实汤', 558, 4, 1001000, '$u{白术}$w{三两}、$u{茯苓}$w{四两}、$u{半夏}$w{一升}、$u{枳实}$w{一两半}。\n\n          右四味，以水六升，煮取三升，去滓，分温三服。', 3, '', '', 623288866103365, '625364600A32577132277AC524425038', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 15:48:55', 1, '超级管理员', '2024-12-16 15:52:50');
