INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (645, '理中加人参括蒌根汤', 561, 5, 1001000, '$u{人参}$w{四两}、$u{白术}$w{三两}、$u{甘草}$w{三两}、$u{干姜}$w{三两}、$u{括蒌根}$w{二两}。\n\n        右五味，以水八升，煮取三升，去滓，温服一升，日三服。', 3, '', '', 623290759405637, '80F3A0C813A196561FB07412372ADFB6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 15:56:38', 1, '超级管理员', '2024-12-16 15:59:09');
