INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (647, '理中丸', 563, 4, 1001000, '$u{人参}$w{三两}、$u{干姜}$w{三两}、$u{甘草}$w{三两}、$u{白术}$w{三两}。\n\n         右四味，捣筛，蜜和为丸，如鸡子黄大，以沸汤数合和一丸，研碎温眼，日三服，夜二服，腹中未热，可益至三四丸。', 5, '', NULL, 623292965969989, '79AE6A9BD0956DB91D1C499CE6BD707A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 16:05:36', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (648, '四逆加人参汤', 564, 4, 1001000, '$u{甘草}$w{二两 (炙)}、$u{附子}$w{一枚 (生用去皮破八片)}、$u{干姜}$w{一两半}、$u{人参}$w{三两}。\n\n       右四味，以水三升，煮取一升二合，去滓，分温再服。', 2, '', NULL, 623294246232133, '71C83164538650C277DAC14E89294A69', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 16:10:49', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (649, '通脉四逆加猪胆汁汤', 565, 5, 1001000, '$u{甘草}$w{二两 (炙)}、$u{干姜}$w{三两}、$u{附子}$w{大者一枚 (生用)}、$u{猪胆汁}$w{半合}、$u{人参}$w{二两}。\n\n         右五味，以水三升，先煮四味，取一升，去滓，纳猪胆汁搅匀，分温再服。', 3, '', NULL, 623295006318661, '893BA46171D03402CDCA745A7881AF68', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 16:13:54', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (650, '栝蒌桂枝汤', 566, 6, 1001000, '$u{栝蒌根}$w{三两}、$u{桂枝}$w{三两（去皮）}、$u{甘草}$w{二两（炙）}、$u{芍药}$w{三两}、$u{生姜}$w{二两（切）}、$u{大枣}$w{十二枚（劈）}。\n\n         右六味，以水七升，微火煮取三升，去滓，适寒温服一升，日三服。', 3, '', NULL, 623305529561157, 'FFF80F2DC2E9074D636543736024F122', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 16:56:44', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (651, '桂枝加附子当归细辛人参干姜汤', 567, 10, 1001000, '$u{桂枝}$w{三两}、$u{芍药}$w{三两}、$u{甘草}$w{二两（炙）}、$u{当归}$w{四两}、$u{细辛}$w{一两}、$u{附子}$w{一枚（炮）}、$u{人参}$w{二两}、$u{干姜}$w{一两半}、$u{生姜}$w{三两（切）}、$u{大枣}$w{十二枚（劈）}。\n\n          右十味，以水一斗二升，煮取四升，去滓，温服一升，日三服，夜一服。', 4, '', NULL, 623307141656645, 'E41B2C79DED56B2540A8A7791C6CF160', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 17:03:17', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (652, '烧裩散', 568, 1, 1001000, '右剪取妇人中裩，近隐处，烧灰，以水和服方寸匙，日三服，小便即利，阴头微肿则愈，妇人病取男子裩裆烧，和服如法。', 3, '', NULL, 623308082380869, 'C6372A707350100112445F3377B16106', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 17:07:07', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (653, '枳实栀子豉汤', 569, 3, 1001000, '$u{枳实}$w{三枚（炙）}、$u{栀子}$w{十四枚（劈）}、$u{香豉}$w{一升（棉襄）}。\n\n         右三味，以清浆水七升，空煮取四升，纳枳实、栀子煮取二升，纳香豉更煮五六沸，去滓，温分再服，覆令微似汗。', 2, '', NULL, 623308588970053, 'EE5ED8D2AC8194D086D4864C222041A8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 17:09:11', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (654, '牡蛎泽泻散', 570, 7, 1001000, '$u{牡蛎}、$u{泽泻}、$u{栝蒌根}、$u{蜀漆（洗去腥）}、$u{葶历（熬）}、$u{商陆根（熬）}、$u{海藻（洗去腥）}。\n\n            右七味$w{等分}，异捣，下筛为散，更入臼中治之，白饮和服方寸匙，日三服，小便利止后服。', 3, '', NULL, 623309175554117, '5DA1FCD010FBE19556084A2DF4845D9E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 17:11:34', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (655, '百合知母汤', 571, 2, 1001000, '$u{百合$w{七枚}、$u{知母$w{三两}。\n\n         右二味，先以水洗百合，渍一宿，当白沫出，去其水，另以泉水二升，煮取一升，去滓，别以泉水二升，煮知母取一升，去滓，后合煎取一升五合，分温再服。', 2, '', NULL, 623310316396613, '7E8F779CD8F6D7796FB38C94B1118FF6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 17:16:12', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (656, '百合滑石代赭汤', 572, 3, 1001000, '$u{百合}$w{七枚}、$u{滑石}$w{三两}、$u{代赭石}$w{如弹丸大 (碎棉裹)}。\n\n右三味，以水先洗，煮百合如前法，别以泉水二升，煮二味，取一升，去滓，合和，重煎，取一升五合，分温再服。', 2, '', NULL, 623310685859909, 'C2C790C48F505B4E62C9C466D2F48B7D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 17:17:42', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (657, '百合鸡子黄汤', 573, 2, 1001000, '$u{百合}$w{七枚}、$u{鸡子黄}$w{一枚}。\n\n       右二味，先洗煮百合如前法，去滓，纳鸡子黄，搅匀，顿服之。', 2, '', NULL, 623311021727813, 'A089B080E2ADA22C2A6861AD47C5A0E1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 17:19:04', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (658, '百合地黄汤', 574, 2, 1001000, '$u{百合}$w{七枚}、$u{地黄汁}$w{一升}。\n\n        右二味，先洗煮百合如上法，去滓，纳地黄汁，煎取一升五合，分温再服，中病勿更服，大便当如漆。', 2, '', NULL, 623311388102725, '2233203F67F2FED58664652B3D28D19E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 17:20:34', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (659, '百合洗方主', 575, 1, 1001000, '$u{百合}$w{一升}。\n\n         右一味，以水一斗，渍之一宿，以洗身，洗已，食煮饼，勿以$m{盐豉}也。', 1, '', NULL, 623311849676869, '0132639B777B539B4D9E75953A151EFF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 17:22:27', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (660, '括蒌牡蛎散', 576, 2, 1001000, '$u{括蒌根}、$u{牡蛎 (熬) }$w{各等分}。\n\n            右二味，捣为散，白饮和服方寸匙，日三服。', 3, '', NULL, 623312180273221, '4E0A20C6D9EE350C9530491D32E45646', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 17:23:47', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (661, '百合滑石散', 577, 2, 1001000, '$u{百合$w{一两 (炙)}、$u{滑石$w{二两}。\n\n        右二味，为散，饮服方寸匙，日三服，当微利，热除则止后服。', 3, '', NULL, 623312510537797, 'F4B64E5BF6A62961C84B10E58DBC603D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 17:25:08', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (662, '苦参汤', 579, 1, 1001000, '$u{苦参}$w{一斤}。\n\n          右一味，以水一斗，煮取七升，去滓，薰洗，日三次。', 3, '', NULL, 623313390055493, '3A9D2A5CF0DBD17ECF788BEC3793380D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 17:28:43', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (663, '雄黄散', 580, 1, 1001000, '$u{雄黄}$w{一两}。\n\n         右一味，为末，筒瓦二枚合之，纳药于中，以火烧烟，向肛薰之。', 1, '', NULL, 623313798643781, '9DACAECF814AD5506A11E30AFFE7BCB8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 17:30:22', NULL, NULL, NULL);
