INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (665, '升麻鳖甲汤', 582, 6, 1001000, '$u{升麻}$w{二两}、$u{蜀椒}$w{一两 (去汁)}、$u{雄黄}$w{五钱 (研)}、$u{当归}$w{一两}、$u{甘草}$w{二两}、$u{鳖甲}$w{一片 (炙)}。\n\n        右六味，以水四升，煮取一升，顿服之，不差，再服，取汗。', 2, '', NULL, 623314717888581, '9759DEDF32C3246FBF151CBFE9752965', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-16 17:34:07', NULL, NULL, NULL);
