INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (667, '白虎加桂枝人参汤', 584, 6, 1001000, '$u{知母}$w{六两}、$u{石膏}$w{一斤}、$u{甘草}$w{二两(炙)}、$u{粳米}$w{二合}、$u{桂枝}$w{三两}、$u{人参}$w{三两}。\n\n         右六味，以水一斗，煮米熟，汤成去滓，温服一升，日三服。', 3, '', NULL, 623531905249349, '404021AB71AFC10E1829B21061AFE2D1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 08:17:51', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (668, '鳖甲煎丸', 585, 7, 1001000, '$u{鳖甲}、$u{柴胡}、$u{黄芩}、$u{大黄}、$u{牡丹}、$u{（庶/虫）虫}、$u{阿胶}。\n\n          右七味，$w{各等分}，捣筛，炼蜜为丸，如梧桐子大，每服七丸，日三服，清酒下，不能饮者，白饮亦可。', 3, '', NULL, 623532676038725, 'CF956C7D78AAE054A4EB4993E70B0318', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 08:20:59', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (669, '白虎加桂枝汤', 586, 5, 1001000, '$u{知母$w{六两}、$u{石膏$w{一斤}、$u{甘草$w{二两(炙)}、$u{粳米$w{二合}、$u{桂枝$w{三两}\n\n         右五味，以水一斗，煮米熟，汤成去滓，温服一升，日三服。', 3, '', NULL, 623539041378373, '75C04E0190793676B4255899617D7BCA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 08:46:53', NULL, NULL, NULL);
