INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (672, '黄芪桂枝五物汤', 589, 5, 1001000, '$u{黄芪}$w{三两}、$u{桂枝}$w{三两}、$u{芍药}$w{三两}、$u{生姜}$w{六两}、$u{大枣}$w{十二枚}。\n\n       右五味，以水六升，煮取二升，温服七合，日三服。', 3, '', NULL, 623541289984069, '0C535BFECB675321FB1D0900F26C510F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 08:56:02', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (673, '桂枝龙骨牡蛎汤', 590, 7, 1001000, '$u{桂枝}$w{三两}、$u{芍药}$w{三两}、$u{甘草}$w{二两（炙）}、$u{生姜}$w{三两}、$u{大枣}$w{十二枚}、$u{龙骨}$w{三两}、$u{牡蛎}$w{三两}。\n\n        右七味，以水七升，煮取三升，去滓，分温三服。', 3, '', NULL, 623542288552005, 'EB05549927B8150B8D46EC927D770A95', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 09:00:06', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (674, '天雄散', 591, 4, 1001000, '$u{天雄}$w{三两（炮）}、$u{白术}$w{八两}、$u{桂枝}$w{六两}、$u{龙骨}$w{三两}。\n\n        右四味，杵为散，酒服半钱匙，日三服，不知稍增，以知为度。', 3, '', NULL, 623547880489029, '7256BB659E7BB590F4B885B033A8716C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 09:22:51', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (675, '黄芪建中汤', 592, 7, 1001000, '$u{桂枝}$w{三两}、$u{芍药}$w{六两}、$u{甘草}$w{二两 (炙)}、$u{生姜}$w{三两（切）}、$u{大枣}$w{十二枚（劈）}、$u{胶饴}$w{一升}}、$u{黄芪}$w{一两半}。\n\n      右七味，以水七升，煮取三升，去滓，内胶饴，更上微火消解，温服一升，日三服。\n\n     气短，胸满者，加生姜一两；\n     腹满者，去大枣，加茯苓一两半；\n     大便秘结者，去大枣，加枳实一两半；\n     肺气虚损者，加半夏三两。\n', 3, '', NULL, 623556954742853, '40D572F353FCA6418DEDA162C9E986C8', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 09:59:47', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (676, '蛇床子散', 593, 1, 1001000, '$u{蛇床子}$w{一两}。\n\n         右一味，末之，以白粉少许，和合相得，如枣大，棉裹纳阴中，自温。', 1, '', '', 623557423611973, 'F5A98446DF70424DC314337510B5C2F5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 10:01:41', 1, '超级管理员', '2024-12-17 17:03:05');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (677, '酸枣仁汤', 594, 5, 1001000, '$u{酸枣仁}$w{二升}、$u{甘草}$w{一两}、$u{知母}$w{二两}、$u{茯苓}$w{二两}、$u{川芎}$w{一两}。\n\n       右五味，以水八升，煮酸枣仁，得六升，纳诸药，煮取三升，去滓，温服一升，日三服。', 3, '', NULL, 623558178590789, '196CE6EB80801702B8AF618848E124DA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 10:04:45', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (678, '大黄䗪虫丸', 595, 12, 1001000, '$u{大黄}$w{十两}、$u{黄芩}$w{二两}、$u{甘草}$w{三两}、$u{桃仁}$w{一升}、$u{杏仁}$w{一升}、$u{芍药}$w{四两}、$u{地黄}$w{十两}、$u{干漆}$w{一两}、$u{虻虫}$w{一升}、$u{水蛭}$w{百枚}、$u{蛴螬}$w{一升}、$u{䗪虫}$w{半升}\n\n           右十二味，末之，炼蜜和丸，如小豆大，酒饮服五丸，日三服。', 3, '', '', 623559325270085, 'CEE1643CF611615E04E9CAFA84C5AEAB', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 10:09:25', 1, '超级管理员', '2024-12-17 10:09:41');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (679, '硝石矾石散', 596, 2, 1001000, '$u{硝石（熬黄）}、$u{矾石（烧）}$w{各等分}。\n\n       右二味，为散，大麦粥汁和服方寸匙，日三服，大便黑，小便黄，是其候也。', 3, '', NULL, 623560158875717, 'A010F1F023D9C346E836077A89776607', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 10:12:49', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (680, '十枣汤', 597, 3, 1001000, '$u{芜花 (熬)}、$u{甘遂}、$u{大戟}$w{各等分}。\n右三味，捣筛，以水一升五合，先煮肥大枣十枚，取八合，去滓，纳药末，强人服一钱匙，赢人服半钱匙，平旦温服之，不下，明日更加半钱，得快利后，糜粥自养。', 1, '', NULL, 623563701350469, '23CC6E6EE83D49D6702BC39268BE3BF5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 10:27:14', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (681, '射干麻黄汤', 598, 7, 1001000, '$u{射干}$w{三两}、$u{麻黄}$w{三两}、$u{半夏}$w{半升}、$u{五味子}$w{半升}、$u{生姜}$w{四两}、$u{细辛}$w{三两}、$u{大枣}$w{七枚}。\n\n          右七味，以水一斗二升，先煮麻黄，去上沫，纳诸药，煮取三升，分温三服。', 3, '', NULL, 623564108128325, 'F2A0B3E832459430628A245D167557DC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 10:28:53', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (682, '皂荚丸', 599, 1, 1001000, '$u{皂荚}$w{八两 (刮去皮酥炙)}。\n右一味，末之，蜜丸如梧桐子大，以枣膏和汤，服三丸，日三服，夜一服。', 4, '', NULL, 623564467859525, 'CEF0D44085C086FBBAC0388309767E74', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 10:30:21', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (683, '厚朴麻黄汤', 600, 6, 1001000, '$u{厚朴}$w{五两}、$u{麻黄}$w{四两}、$u{石膏}$w{如鸡子大}、$u{杏仁}$w{半升}、$u{半夏}$w{半升}、$u{五味子}$w{半升}。\n\n       右六味，以水一斗，先煮麻黄，去沫，纳诸药，煮取三升，去滓，分温三服。', 3, '', NULL, 623564855738437, 'CC9330B65E8BCCB012F6381994F86992', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 10:31:56', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (684, '泽漆汤', 601, 6, 1001000, '$u{半夏}$w{半升}、$u{紫参}$w{五两}、$u{泽漆}$w{三升}、$u{生姜}$w{五两}、$u{人参}$w{三两}、$u{甘草}$w{三两 (炙)}。\n\n          右六味，以东流水五斗，先煮泽漆，取一斗五升，纳诸药，煮取五升，温服五合，日夜服尽。', 10, '', NULL, 623565479166021, 'AF583298E01E2BC8FBDA7C2F040EA560', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 10:34:28', NULL, NULL, NULL);
