INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (688, '葶苈大枣泻肺汤', 605, 2, 1001000, '$u{葶苈}$w{ (熬令黄色捣丸如弹子大)}、$u{大枣}$w{十二枚}。\n\n     右二味，以水三升，先煮大枣取二升，去枣，纳葶苈，煮取一升，去滓，顿服。', 2, '', NULL, 623568143003717, '7D8F27A7838E4681BA95D37E437BEDB5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 10:45:18', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (689, '甘遂半夏汤', 606, 4, 1001000, '$u{甘遂}$w{大者三枚}、$u{半夏}$w{十二枚}、$u{芍药}$w{五枚}、$u{甘草}$w{如指大一枚 (炙)}。\n\n         右四味，以水二升，煮取半升，去滓，以蜜半升和药汁，煎取八合，顿服。', 2, '', NULL, 623570500059205, '069A1A322FECDD63F92889CE2413817D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 10:54:54', NULL, NULL, NULL);
