INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (694, '防已椒目葶苈大黄丸', 611, 4, 1001000, '$u{防已}、$u{椒目}、$u{葶苈}、$u{大黄}$w{各一两}。\n\n       右四味，捣筛，炼蜜为丸，如梧桐子大，先食，饮服一丸，日三服，不知稍增。', 3, '', NULL, 623573545607237, '9A104BD6FD441626341FD9E28B53884D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 11:07:17', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (695, '小半夏加茯苓汤', 612, 3, 1001000, '$u{半夏}$w{一升}、$u{生姜}$w{半斤}、$u{茯苓}$w{四两}。\n\n      右三味，以水七升，煮取二升，去滓，分温再服。', 2, '', NULL, 623574236708933, '3D43F5258287F10955A7CD05C0EEDAA7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 11:10:06', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (696, '防已黄芪汤', 613, 6, 1001000, '$u{防已}$w{一两}、$u{甘草}$w{五钱 (炙)}、$u{白术}$w{七钱半}、$u{黄芪}$w{一两}。\n\n       右四味，剉如麻豆大，每抄五钱匙，$u{生姜}$w{四片}、$u{大枣}$w{一枚}、水一升半，煮取八合，去滓，温服；\n   \n      喘者，加$u{麻黄}$w{五钱}，\n      胃中不和者，加$u{芍药}$w{三分}；\n      气上冲者，加$u{桂枝}$w{三分}；\n     下有陈寒者，加$u{细辛}$w{三分}；服后当如虫行皮中，从腰下如冰，后坐被上，又以一被绕腰下，温令有微汗差。', 1, '', '', 623581082177605, '7EB97B2464F7DDFB2DE5098F4DDF26C0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 11:37:57', 1, '超级管理员', '2024-12-17 11:38:21');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (697, '越婢汤', 614, 5, 1001000, '$u{麻黄}$w{六两}、$u{石膏}$w{半斤}、$u{甘草}$w{二两}、$u{生姜}$w{三两}、$u{大枣}$w{十二枚}。\n\n       右五味，以水六升，先煮麻黄，去上沫，纳诸药，煮取三升，去滓，分温三服。', 3, '', NULL, 623581617242181, '4DC144D608FB5E2770798DAD104DC756', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 11:40:08', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (698, '防已茯苓汤', 615, 5, 1001000, '$u{防已}$w{三两}、$u{黄芪}$w{三两}、$u{桂枝}$w{三两}、$u{茯苓}$w{六两}、$u{甘草}$w{二两 (炙)}。\n\n       右五味，以水六升，煮取三升，分温三服。', 3, '', NULL, 623582240084037, 'A58376C1A8DCD007BB29446FA7811272', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 11:42:40', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (699, '甘草麻黄汤', 616, 2, 1001000, '甘草二两、麻黄四两。\n\n    右二味，以水五升，先煮麻黄，去上沫，纳甘草，煮取三升，去滓，温服一升，复令汗出，不汗再服。', 3, '', NULL, 623584404152389, 'DDB50A1D95A3818A273C756AF9C2D05A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 11:51:28', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (700, '越婢加术汤', 617, 6, 1001000, '$u{麻黄}$w{六两}、$u{石膏}$w{半斤}、$u{甘草}$w{二两 (炙)}、$u{生姜}$w{三两}、$u{大枣}$w{十五枚}、$u{白术}$w{四两}。\n\n         右六味，以水六升，先煮麻黄，去上沫，纳诸药，煮取三升，分温三服。', 3, '', NULL, 623584816824389, '60A1A29CFE68B5667AC3BFEBC764A433', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 11:53:09', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (701, '黄芪芍药桂枝汤', 618, 4, 1001000, '$u{黄芪}$w{五两}、$u{芍药}$w{三两}、$u{桂枝}$w{三两}。\n\n       右三味，以$u{苦酒}$w{一升}，水七升，相合，煮取三升，去滓，温服一升，当心烦，服至六七日乃解；若心烦不止者，以苦酒阻故也，以美酒醢易之。', 3, '', '', 623585345638469, '6AF916DF928467FC20249CE845BAE84D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 11:55:18', 1, '超级管理员', '2024-12-17 11:55:25');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (702, '桂枝加黄芪汤', 619, 6, 1001000, '$u{桂枝}$w{三两}、$u{芍药}$w{三两}、$u{甘草}$w{二两 (炙)}、$u{生姜}$w{三两 (切)}、$u{大枣}$w{十五枚}、$u{黄芪}$w{二两}。\n\n      右六味，以水八升，煮取三升，去滓，温服一升，日三服。', 3, '', NULL, 623587048001605, '64F4C77142EE85D53C3678AC091FD922', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 12:02:14', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (703, '桂枝芍药知母甘草汤', 620, 4, 1001000, '$u{桂枝}$w{三两}、$u{芍药}$w{三两}、$u{知母}$w{二两}、$u{甘草}$w{二两}。\n\n       右四味，以水六升，煮取三升，去滓，温服一升，日三眼。', 3, '', NULL, 623625143779397, '10B9D96C273671F6946EE47398D59AF7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 14:37:14', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (704, '乌头麻黄黄芪芍药甘草汤', 621, 5, 1001000, '}、$u{乌头}$w{五枚 (切)}、$u{麻黄}$w{三两}、$u{黄芪}$w{三两}、$u{芍药}$w{三两}、$u{甘草}$w{三两}。\n\n           右五味，先以蜜二升煮乌头，取一升，去滓，别以水三升煮四味，取一升，去滓，纳蜜再煮一二沸，服七合，不知尽服之。', 2, '', NULL, 623625924960325, 'DF7EC97B8846085A0BDBC8E6E770E0D7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 14:40:25', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (705, '桂枝甘草麻黄生姜大枣细辛附子汤', 622, 7, 1001000, '$u{桂枝}$w{三两}、$u{甘草}$w{二两 (炙)}、$u{麻黄}$w{二两}、$u{生姜}$w{二两 (切)}、$u{大枣}$w{十二枚}、$u{细辛}$w{三两}、$u{附子}$w{一枚 (炮)}。\n\n      右七味，以水七升，先煮麻黄去沫，纳诸药，煮取三升，分温三服，汗出即愈。', 3, '', NULL, 623626851033157, '38EE1CB4C663FD06F7BFFA2A208A0FA6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 14:44:11', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (706, '枳实白术汤', 623, 2, 1001000, '$u{枳实}$w{七枚}、$u{白术}$w{二两}。\n\n       右二味，以水五升，煮取三升，去滓，分温三服。', 3, '', NULL, 623627203977285, '474A6BBBC2165619AFB619F98E5533F6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 14:45:37', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (707, '括蒌瞿麦薯蓣丸', 624, 5, 1001000, '$u{括蒌根}$w{二两}、$u{瞿麦}$w{一两}、$u{薯蓣}$w{二两}、$u{附子}$w{一枚 (炮)}、$u{茯苓}$w{三两}。\n\n           右五味，末之，炼蜜为丸，如梧桐子大，饮服二丸，日三服，不知可增至七八丸，以小便利，腹中温为知。', 3, '', NULL, 623627586424901, 'CE90C19EB747719D0B9FACA2905A537D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 14:47:11', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (708, '茯苓白术戎盐汤', 625, 3, 1001000, '$u{滑石}$w{一斤}、$u{乱发}$w{一斤 (烧)}、$u{白鱼}$w{一斤}。\n\n       右三味杵为散，饮服方寸匙，日三服。', 3, '', NULL, 623628338348101, '6F2304D45B86CCE7FA5572BD03DB03A5', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 14:50:14', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (709, '茯苓白术戎盐汤', 626, 3, 1001000, '$u{茯苓}$w{半斤}、$u{白术}$w{二两}、$u{戎盐}$w{二枚 (弹丸大)}。\n\n        右三味，先以水一斗，煮二味，取三升，去滓，纳戎盐，更上微火一二沸化之，分温三服。', 3, '', NULL, 623628654719045, '0612056544D3CC2E1E68A5F41735062A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 14:51:32', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (710, '下瘀血汤', 627, 3, 1001000, '$u{大黄}$w{三两}、$u{桃仁}$w{二十枚}、$u{䗪虫}$w{二十枚 (去足)}。 \n\n      右三味，末之，炼蜜和丸，以酒一升，水一升，煮取八合，顿服之，血下如豚肝愈。', 2, '', NULL, 623629890654277, 'C31E2CFAE4BF6DC98823E4D4D65CE965', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 14:56:33', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (711, '柏叶汤', 628, 3, 1001000, '$u{柏叶}$w{三两}、$u{干姜}$w{三两}、$u{艾叶}$w{三把}。\n\n      右三味，以水五升，取马通汁一升，合煮取一升，去滓，分温再服。', 2, '', NULL, 623630434721861, '9603A73C00BDB02DFA406E3C5799B440', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 14:58:46', NULL, NULL, NULL);
