INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (713, '泻心汤', 630, 2, 1001000, '$u{大黄}$w{二两}、$u{黄连}$w{一两}。\n\n       右二味，以水三升，煮取一升，去滓，顿服之。', 2, '', '', 623631187333189, 'B654C5F4E539698E641EC462ED6D754F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 15:01:50', 1, '超级管理员', '2024-12-17 16:48:08');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (714, '王不留行散', 631, 9, 1001000, '$u{王不留行}$w{十分 (烧)}、$u{蒴藿}$w{细叶十分 (烧)}、$u{桑根白皮}$w{十分 (烧)}、$u{甘草}$w{十八分}、$u{黄芩}$w{二分}、$u{蜀椒}$w{三分 (去目)}、$u{厚朴}$w{二分}、$u{干姜}$w{二分}、$u{芍药}$w{二分}。\n\n        右九味，为散，饮服方寸匙，小疮即粉之，大疮但服之，产后亦可服。', 1, '', NULL, 623632530780229, '096CB72210B6665DC7D31D7D663BFB80', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 15:07:18', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (715, '排脓散', 632, 3, 1001000, '$u{枳实}$w{十六枚}、$u{芍药}$w{六分}、$u{桔梗}$w{二分}。\n\n       右三味，杵为散，取鸡子黄一枚，以药散与鸡黄相等，揉和令相得，饮和服之，日一服。', 1, '', NULL, 623632777297989, 'C42C85D78987797D0B0CF2976CA8C1BD', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 15:08:18', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (716, '排脓汤', 633, 4, 1001000, '$u{甘草}$w{二两}、$u{桔梗}$w{三两}、$u{生姜}$w{一两}、$u{大枣}$w{十枚}。\n\n       右四味，以水三升，煮取一升，去滓，温服五合，日再服。', 1, '', NULL, 623633081540677, '9C51D4F0296EEC906F270134A5A4E361', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 15:09:32', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (717, '黄连粉', 634, 2, 1001000, '$u{黄连}$w{十分}、$u{甘草}$w{十分}。\n\n        右二味，捣为末，饮服方寸匙，并粉其疮上。', 1, '', NULL, 623633786245189, 'B812CD85183981AD212FA9CC436385C0', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 15:12:24', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (718, '薏苡附子败酱散', 635, 3, 1001000, '$u{薏苡}$w{十分}、$u{附子}$w{二分}、$u{败酱}$w{五分}。\n\n         右三味，杵为末，取方寸匙，以水二升，煮减半，去滓，顿服，小便当下血。', 2, '', NULL, 623634239164485, '8533131BFD5BAEEB2AE4A49460A20F92', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 15:14:15', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (719, '大黄牡丹汤', 636, 5, 1001000, '$u{大黄}$w{四两}、$u{牡丹}$w{一两}、$u{桃仁五}$w{十个}、$u{冬瓜子}$w{半升}、$u{芒硝}$w{三合}。\n\n         右五味，以水六升，煮取一升，去滓，顿服之，有脓者当下脓，无脓者当下血。', 2, '', NULL, 623634617233477, '6995146BB719FA58CF9EDF865D2F39E9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 15:15:47', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (720, '括蒌薤白白酒汤', 637, 3, 1001000, '$u{括蒌实}$w{一枚 (捣)}、$u{薤白}$w{半斤}、$u{白酒}$w{七升}。\n\n        右三味，同煮取二升，分温再服。', 2, '', NULL, 623635475013701, '0D7BD1F41316B573E8C0BA92A11AC90B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 15:19:17', NULL, NULL, NULL);
