INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (727, '乌头赤石脂丸', 644, 5, 1001000, '$u{乌头}$w{一两}、$u{蜀椒}$w{一两}、$u{附子}$w{五钱}、$u{干姜}$w{一两}、$u{赤石脂}$w{一两}。\n\n        右五味，末之，蜜为丸，如梧桐子大，先食，服一丸，日三服，不知稍增，以知为度。', 3, '', NULL, 623638387646533, '8F06FF931E0FDA9EE062FD5997A39734', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 15:31:08', NULL, NULL, NULL);
