INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (729, '半夏麻黄丸', 646, 2, 1001000, '$u{半夏}、$u{麻黄}$w{各等分}。\n\n        右二味，末之，炼蜜和丸，如小豆大，饮服三丸，日三服。', 3, '', NULL, 623639162597445, 'ECA87CE8E27C0515114362B9F336F1D2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 15:34:17', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (730, '九痛丸', 647, 6, 1001000, '$u{附子}$w{三两}、$u{狼毒}$w{四两}、$u{巴豆}$w{一两 (去皮心熬研如脂)}、$u{人参}$w{一两}、$u{干姜}$w{一两}、$u{吴茱萸}$w{一两}。\n\n           右六味，末之，蜜丸如梧桐子大，酒下，强人初服三丸，日三服，弱者二二丸。兼治卒中恶，腹胀痛，口不能言，又治连年积冷，流注，心胸痛，冷气上冲，落马，坠车，血疾等，皆主之；忌口如常法。', 3, '', NULL, 623639627931717, '75C9EB6CED5FB8589B26959ADD9DB34A', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 15:36:11', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (731, '桂枝茯苓丸', 648, 5, 1001000, '$u{桂枝}、$u{茯苓}、$u{牡丹}、$u{桃仁}、$u{芍药}$w{各等分}。\n\n         右五味，末之，炼蜜为丸，如兔屎大，每日食前服一丸，不知可渐加至三丸。', 1, '', NULL, 623641523556421, '383E718E66849629B0868A9F7F550B15', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 15:43:53', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (732, '胶艾汤', 650, 7, 1001000, '$u{地黄}$w{六两}、$u{川芎}$w{二两}、$u{阿胶}$w{二两}、$u{艾叶}$w{三两}、$u{当归}$w{三两}、$u{芍药}$w{四两}、$u{甘草}$w{二两}。\n\n            右七味，以水五升，清酒三升，煮六味，取三升，去滓，纳胶烊消，温服一升，日三服。', 3, '', NULL, 623642807177285, 'C37C1DDD86354DB7C31E85C770B856EF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 15:49:07', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (733, '当归芍药散', 651, 6, 1001000, '$u{当归}$w{三两}、$u{芍药}$w{一斤}、$u{茯苓}$w{四两}、$u{白术}$w{四两}、$u{泽泻}$w{半斤}、$u{川芎}$w{三两}。\n\n          右六味，杵为散，取方寸匙，温酒和，日三服。', 3, '', NULL, 623643636957253, '28BABEF524CF0C46E5A1713CB3693131', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 15:52:29', NULL, NULL, NULL);
