INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (748, '王瓜根散', 667, 4, 1001000, '$u{王瓜根}$w{三分}、$u{芍药}$w{三分}、$u{桂枝}$w{三分}、$u{䗪虫}$w{三枚}\n\n        右四味，杵为散，酒服方寸匙，日三服。', 3, '', NULL, 623652532076613, 'F20E67146CDFC6F99A58BCEEACF38145', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 16:28:41', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (749, '黄芪当归汤', 668, 2, 1001000, '$u{黄芪}$w{三两}、$u{当归}$w{半两}。\n\n       右二味，以水五升，煮取三升，去滓，温服一升，日三服。', 3, '', NULL, 623657625006149, '863EECC5FC607BD99171CA28C7634998', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 16:49:24', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (750, '胶姜汤', 669, 7, 1001000, '$u{阿胶}$w{三两}、$u{地黄}$w{六两}、$u{川芎二两}、$u{生姜}$w{三两 (切)}、$u{当归}$w{三两}、$u{芍药}$w{三两}、$u{甘草}$w{二两 (炙)}。\n\n        右七味，以水五升，清酒三升，先煮六味，取三升，去滓，纳胶烊消，温服一升，日三服。', 3, '', NULL, 623658221273157, '48959B28B8E285B729B64E68A2AB4DEB', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 16:51:50', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (751, '大黄甘遂阿胶汤', 670, 3, 1001000, '$u{大黄}$w{四两}、$u{甘遂}$w{二两}、$u{阿胶}$w{二两}。\n\n       右三味，以水三升，煮二味，取一升，去滓，纳胶烊消，温顿服之。', 2, '', NULL, 623658574217285, 'A04D20A066C029DFDCC798BED512B21D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 16:53:16', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (752, '矾石丸', 671, 2, 1001000, '$u{矾石}$w{三分 (烧)}、$u{杏仁}$w{一分}。\n\n         右二味，末之，炼蜜为丸，枣核大，纳脏中，剧者再纳之。', 1, '', NULL, 623659336200261, 'A74DE27F08264AABD10827D83DBAF2FB', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 16:56:22', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (753, '红蓝花酒', 682, 1, 1001000, '$u{红蓝花}$w{一两}。\n\n         右一味，以酒一斗，煎减半，去滓，分温再服。', 2, '', NULL, 623659707818053, '565D850628404DDEFB3CC2659AB5C227', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 16:57:53', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (754, '狼牙汤', 683, 1, 1001000, '$u{狼牙}$w{三两}。\n\n         右一味，以水四升，煮取半升，去滓，以绵缠箸如茧大，浸汤沥阴中，洗之，日四遍。', 4, '', '', 623661293957189, '536FD53A6FF0FCDAF1D8B53553F5DDFD', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 17:04:20', 1, '超级管理员', '2024-12-18 19:58:55');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (755, '小青龙汤', 684, 13, 9040000, '21、$f{小青龙汤} 8味 \n$u{麻黄}$w{去节}    $u{芍药}    $u{细辛}    $u{干姜}    $u{甘草}$w{炙}    $u{桂枝}$w{各三两。去皮}    $u{五味子}$w{半升}    $u{半夏}$w{半升(洗)}\n	上八味。以水一斗。先煮麻黄。减二升。去上沫。内诸药。煮取三升。去滓。温服一升。若渴。去$u{半夏}。加$u{栝楼根}$w{三两}。若微利。去$u{麻黄}。加$u{荛花}。$w{如一鸡子。熬令赤色}。若噎者。去$u{麻黄}。加$u{附子}$w{一枚。炮}。若小便不利。少腹满者。去$u{麻黄}。加$u{茯苓}$w{四两}。若喘。去$u{麻黄}。加$u{杏仁}$w{半升。去皮尖。}【且荛花不治利。麻黄主喘。今此语反之。疑非仲景意。】$a{臣亿等谨按小青龙汤。大要治水。又按本草荛花下十二水。若水去。利则止也。又按千金。形肿者应内麻黄。乃内杏仁者。以麻黄发其阳故也。以此证之。岂非仲景意也。}', 3, NULL, NULL, 643808106459205, '6F31A5C30F3CE21754F96B150C83A308', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-12 15:21:56', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (756, '四逆加人参汤', 685, 4, 9050000, '$u{甘草}$w{二两 (炙)}、$u{附子}$w{一枚 (生用去皮破八片)}、$u{干姜}$w{一两半}、$u{人参}$w{三两}。\n\n       右四味，以水三升，煮取一升二合，去滓，分温再服。\n\n四逆汤内加人参一两，余依四逆汤服法（上三味，呚咀，微火煮取一升二合，去滓，分温再服。强人可大附子一枚，干姜三两。）  ', 2, NULL, '', 648718903623749, '8DADD61C2DAC28126D632076D4174711', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-26 12:24:01', 1, 'admin', '2025-02-28 16:31:46');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (758, '理中丸', 686, 4, 9050000, '$u{人参}    $u{干姜}    $u{甘草}$w{炙}    $u{白术}$w{各三两}\n\n    上四味，捣筛为末，蜜和为丸，如鸡子黄大，以沸汤数合，和一丸研碎，温服之。日三四服，夜一服，腹中未热，益至三四丸，然不及汤，汤法以四物依两数切，用水八升，煮取三升，去渣，温服一升，日三服，\n\n     若脐上筑者，肾气动也，去术加桂四两。\n\n     吐多者，去术 加生姜三两。\n\n     下多者，还用术。\n\n     悸者，加茯苓二两。\n\n      渴欲得水者，加术，足前成四两半。\n\n       腹中痛者，加人参，足前成四两半。\n\n       寒者，加干姜，足前成四两半。\n\n       腹满者，去术加附子一枚。\n\n    服汤后如食顷，饮热粥一升许，微自温，勿揭衣被。  ', 3, NULL, NULL, 648720643379269, 'B42863415C94EAD94ECFA2A21B548CE1', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-26 12:31:05', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (761, '通脉四逆加猪胆汁汤', 687, 4, 9050000, '$u{甘草}$w{二两、炙}    $u{干姜}$w{一两半}    $u{附子}$w{一枚、生用去皮破八片}  $u{猪胆汁}$w{半合}\n\n    上四味，以水三升，煮取一升二合，去滓，内猪胆汁，分温再服，其脉即来，无猪胆，以羊胆代之。', 2, NULL, '', 648751619280965, '272687F3655A5FDC2E98C1B488B36377', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-26 14:37:08', 1, 'admin', '2025-02-28 16:31:56');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (764, '栝篓桂枝汤', 688, 6, 9050000, '$u{栝蒌根}$w{二两}，$u{桂枝}$w{三两}，$u{芍药}$w{三两}，$u{甘草}$w{二两}，$u{生姜}$w{三两}，$u{大枣}$w{十二枚}\n\n        上六味，以水九升，煮取三升，分温三服，取微汗。汗不出，食顷，啜热粥发之。', 3, NULL, NULL, 649741163307077, '69573E3E38D6251A8DBA87C378071BCD', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-01 09:43:36', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (765, '麻黄加术汤', 689, 5, 9050000, '$u{麻黄}$w{三两（去节） }，$u{桂枝}$w{二两 }，$u{甘草}$w{一两  }，$u{白术}$w{四两  }，$u{杏仁}$w{七十个（去皮尖）}\n\n      右五味，以水九升，先煮麻黄，减二升，去上沫，内诸药，煮取二升半，去滓，温服八合，覆取微汗', 3, NULL, '', 649768537399365, '5FF57FF229A238421C78163137CA6575', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-01 11:34:59', 1, 'admin', '2025-03-01 16:53:43');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (766, '麻黄杏仁薏苡甘草汤', 690, 4, 9050000, '$u{麻黄}$w{半两}，$u{甘草}$w{一两，炙}，$u{薏苡仁}$w{半两}，$u{杏仁}$w{十个，去皮尖}\n\n	上锉麻豆大，每服四钱匕， 匕者茶匙也，四钱匕者四茶匙也。水一盏半，煮八分，去滓，温服，有微汗，避风。', 1, NULL, '', 649771265654853, '84A539866F0ED20B8C8E579194C4E562', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-01 11:46:05', 1, 'admin', '2025-03-01 11:46:16');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (767, '防己黄耆汤', 691, 4, 9050000, '$u{ 防己}$w{一两 }，$u{ 甘草}$w{半两（炙）  }，$u{白术}$w{七钱半 }，$u{黄芪}$w{一两一分  }\n\n       上锉麻豆大，每抄五钱匕，生姜四片，大枣一枚，水盏半，煎八分，去滓温服，\n\n      喘者 加$u{麻黄}$w{半两}，\n     胃中不和者，加$u{芍药}$w{三分}，\n     气上冲者，加$u{桂枝}$w{三分}，\n    下有陈寒者，加$u{细辛}$w{三分}。 \n\n    服后当如虫行皮中， 自腰下如冰，后坐被上，又以一被绕腰下，温令微汗差。', 1, NULL, NULL, 649773634834501, '46A2960FF7091ABB80F009C831EACCF2', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-01 11:55:43', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (768, '去桂枝加白术汤', 692, 5, 9050000, '$u{附子}$w{一枚、炮、去皮、破}    $u{白术}$w{二两}    $u{生姜}$w{一两半、切}    $u{大枣}$w{六枚、擘}    $u{甘草}$w{二两、炙}\n\n上五味，以水三升，煮取一升，去滓，分温三服。一服觉身痺，半日许再服，三服都 尽，其人如冒状，勿怪即是术附并走皮中，逐水气，未得除故耳。', 3, NULL, NULL, 649829412732997, 'FCAD84EA35AEDA4A8F92C60138D0BE40', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-01 15:42:41', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (769, '瓜蒂汤', 693, 1, 9050000, '$u{瓜蒂}$w{二十个}\n\n     右剉，以水一升，煮取五合，去滓，顿服。', 1, NULL, '瓜蒂', 649844359151685, '614ACBD2E0CDC9DED5EA04689DF2B630', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-01 16:43:30', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (770, '百合地黄汤', 694, 2, 9050000, '       $u{百合}$w{七枚}、$u{地黄汁}$w{一升}。\n\n       上先煎百合如前法，内地黄汁，煎取一升五合，分温再服。中病勿更服。大便当如漆。\n\n        仲师用生地黄汁，大家看『先煎百合如前法，内地黄汁』地黄汁 再煮一下，不要煮太久。我们既然要生用，地黄汁用一两或二两都没 有关系，平常百合我们用一两二两也没有关系，我一般开这个处方时 剂量都是上两的。如果是『分温再服』，差不多两个是等量。\n\n       如果『中病』就是喝到了、头昏了、嘴巴麻了，就停药。\n\n     『大便当如漆』有时候排出颜色黑黑的大便来，这就是虚热，伏热在里面被排出来。这种病人，你给他下法、吐法、汗法都不对症，此时就用百合，百合最好 消化，跟生地黄在一起。生地黄取汁的时候是先泡过，我们把它泡在滚水里面，泡透了以后，再挤汁出来，生用。\n\n       因为生地黄本身入肾， 肾阴不足的时候，要用生地黄。我们的六味地黄丸就是使用生地黄， 它入肾阴，滋肾阴，肾阴足的话肝就足了，水就会生木。水可以生木 后，就不会但卧，就是想卧下却又睡不着。当百合入肺后，就不会如见神灵状。因为百合下去后肺的津液就会被补的很充足，病人的魄就 会很快的安静下来。', 2, NULL, '', 650506836000837, '573CED34621D42B2474215E1ECEBC5A9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-03 13:39:08', 1, 'admin', '2025-03-03 13:41:35');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (771, '百合知母汤', 695, 2, 9050000, '$u{百合}$w{七枚}、$u{知母}$w{三两}。\n\n     上先以水洗百合，渍一宿当白沫出，去其水，别以泉水二升，煎取一升，去滓；别以泉水二升煎知母，取一升；后合煎一升五合，分温再服。\n', 2, NULL, '百合,知母', 650508469366853, '8D8FCC6B62DFC7D7D1A1391E7742C143', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-03 13:45:46', 1, 'admin', '2025-03-05 17:25:55');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (772, '百合滑石代赭汤', 696, 3, 9050000, '$u{百合}$w{七枚}、$u{滑石}$w{三两}、$u{代赭石}$w{如弹丸大 (碎棉裹)}。\n\n上先煎百合如前法，别以泉水二升，滑石代赭取一升，去滓后合和重煎，取一升五合， 分温再服。', 2, NULL, NULL, 651267949666373, 'C01D10269F0034D9D162E07688EE62AE', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-05 17:16:06', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (773, '百合鸡子汤', 697, 2, 9050000, '$f{百合鸡子汤} $m{2味} $u{百合}$w{七枚，擘}，$u{鸡子黄}$w{一枚}\n	$s{右先以水洗百合}，渍一宿，当白沫出，去其水，更以泉水二升，煎取一升，去滓，内鸡子黄，搅匀，煎五分，温服。', 2, NULL, NULL, 651534932897861, '798CCA070769FF8F6617A0EE16A66117', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-06 11:22:28', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (774, '百合洗方', 698, 1, 9050000, '$u{百合}$w{一升}。\n\n         右一味，以水一斗，渍之一宿，以洗身，洗已，食煮饼，勿以$m{盐豉}也。', 1, NULL, NULL, 651536128434245, '0132639B777B539B4D9E75953A151EFF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-06 11:27:20', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (775, '栝蒌牡蛎散', 699, 2, 9050000, '$u{括蒌根}、$u{牡蛎 (熬) }$w{各等分}。\n\n            右二味，捣为散，白饮和服方寸匙，日三服。', 3, NULL, NULL, 651536493879365, '4E0A20C6D9EE350C9530491D32E45646', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-06 11:28:49', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (776, '百合滑石散', 700, 2, 9050000, '$u{百合$w{一两 (炙)}、$u{滑石$w{二两}。\n\n        右二味，为散，饮服方寸匙，日三服，当微利，热除则止后服。\n\n     百合用炙过，就是用火烧过，或是在锅子里面干炒过。 比例是用百合一两，滑石就要用三两，将这两味药捣成散剂来服。『方 寸匕』就是一个汤匙而已，一天吃三次。如果吃了百合滑石散后有点 下利时就可以停药，因为表示药到了。', 3, NULL, '', 651537176817733, '8119B5ECEF1BD748A8A2AB6844BC30FB', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-06 11:31:36', 1, 'admin', '2025-03-06 11:33:17');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (777, '苦参汤', 701, 1, 9050000, '$u{苦参}$w{一斤}。\n\n          右一味，以水一斗，煮取七升，去滓，薰洗，日三次。', 3, NULL, NULL, 651540367003717, '3A9D2A5CF0DBD17ECF788BEC3793380D', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-06 11:44:34', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (778, '赤小豆当归散', 702, 2, 9050000, '$u{赤小豆}$w{三升 (浸令毛出曝干)}、$u{当归}$w{十两}。\n\n          右二味，杵为散，浆水服方寸匙，日三服。', 3, NULL, NULL, 651543721422917, 'A643DAAC2D02D12485DDD928EA02F152', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-06 11:58:13', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (779, '升麻鳖甲汤', 703, 6, 9050000, '$u{升麻}$w{二两}、$u{蜀椒}$w{一两 (炒去汗)}、$u{雄黄}$w{半两 (研)}、$u{当归}$w{二两}、$u{甘草}$w{二两}、$u{鳖甲}$w{手指大一片 (炙)}。\n\n       上六味，以水四升，煮取一升，顿服之，老小再服，取汗。肘后千金方阳毒用升麻汤， 无鳖甲有桂；阴毒用甘草汤，无雄黄。', 2, NULL, NULL, 651573206970437, '355CB3937E43AEE8FEDF63D5DC0DB33B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-06 13:58:12', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (780, '升麻鳖甲汤去雄黄蜀椒', 704, 4, 9050000, '$u{升麻}$w{二两}、$u{当归}$w{二两}、$u{甘草}$w{二两}、$u{鳖甲}$w{手指大一片 (炙)}。\n\n       上四味，以水四升，煮取一升，顿服之，老小再服，取汗。肘后千金方阳毒用升麻汤， 无鳖甲有桂；阴毒用甘草汤，无雄黄。', 2, NULL, '', 651573606805573, 'E4DA3C0A57E1FEE4590CF3FDA8F8B996', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-06 13:59:50', 1, 'admin', '2025-03-06 14:00:05');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (781, '鳖甲煎丸', 705, 23, 9050000, '$u{鳖甲}$w{十二分，炙}，$u{乌扇}$w{三分，烧、即 射干}，$u{黄芩}$w{三分}，$u{柴胡}$w{六分}，$u{鼠妇}$w{三分，熬}，$u{干姜}$w{三分}，$u{大黄}$w{三分}，$u{桂枝}$w{三分}，$u{石苇}$w{三分，去毛}，$u{厚朴}$w{三分}，$u{紫葳}$w{三分 即凌霄 }，$u{半夏}$w{三分}，$u{阿胶}$w{三分，炙}，$u{葶苈}$w{一分，熬}，$u{人参}$w{一分}，$u{瞿麦}$w{二分}，$u{䗪虫}$w{五分，熬}，$u{牡丹}$w{五分，去心}，$u{芍药}$w{五分}，$u{蜂窠}$w{四分，熬}，$u{赤硝}$w{十二分}，$u{蜣螂}$w{六分，熬}，$u{桃仁}$w{二分，去皮尖， 研}\n	$s{上二十三味为末}，取$u{煅灶下灰}$w{一斗}，$u{清酒}$w{一斛五斗}，浸灰，候酒尽一半，着鳖甲于中，煮令泛烂如胶漆，绞取汁，内诸药，煎为丸，如梧子大。空心服七丸，日三服。$a{$q{《千金方》}鳖甲片十二片，又有海藻三分，大戟一分，䗪虫五分，无鼠妇、赤硝二味，以鳖甲和诸药为丸。}', 50, NULL, NULL, 651618373013573, '2C939A2551B2DD7CE827A48AB7E4A4E3', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-06 17:01:59', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (782, '白虎加桂枝汤', 706, 5, 9050000, '$u{知母$w{六两}、$u{石膏$w{一斤}、$u{甘草$w{二两(炙)}、$u{粳米$w{二合}、$u{桂枝$w{三两}\n\n         上五味，以水一斗，煮米熟，汤成去滓，温服一升，日三服。', 3, NULL, NULL, 651623642656837, '881F312100F19668687B995204BDBD75', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-06 17:23:25', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (783, '蜀漆散', 707, 3, 9050000, '$u{蜀漆}$w{烧去腥}，$u{云母}$w{烧二日夜}，$u{龙骨}$w{等分}\n\n	$s{上三味}，杵为散，未发前，以浆水服半钱。温疟加$u{蜀漆}$w{半分}，临发时，服一钱匕。$a{一方云母作云实。}', 1, NULL, NULL, 651624546123845, '0A5167A32A9CD60B9499185AFFF80BB6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-06 17:27:06', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (784, '牡蛎汤', 708, 4, 9050000, '$u{牡蛎}$w{四两，熬}，$u{麻黄}$w{四两，去节}，$u{甘草}$w{二两}，$u{蜀漆}$w{三两}\n\n上四味，以水八升，先煮蜀漆、麻黄，去上沫，得六升，内诸药，煮取二升，温服一升。若吐，则勿更服。', 2, NULL, NULL, 651867859562565, '558B52584C2861814E94C164DCB486C9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-07 09:57:09', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (785, '柴胡去半夏加栝蒌汤', 709, 7, 9050000, '$u{柴胡}$w{八两}，$u{人参}，$u{黄芩}，$u{甘草}$w{各三两}，$u{栝蒌根}$w{四两}，$u{生姜}$w{二两}，$u{大枣}$w{十二枚}\n\n	上七味，以水一斗二升，煮取六升，去滓，再煎取三升。温服一升，日二服。', 3, NULL, NULL, 651868227633221, '0D8DFAC3BB7E03A5C2F77A279D9879EB', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-07 09:58:39', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (786, '柴胡桂姜汤', 710, 7, 9050000, '$u{柴胡}$w{半斤}、$u{桂枝}$w{三两、去皮}、$u{干姜}$w{二两}、$u{括蒌根}$w{四两}、$u{黄芩}$w{三两}、$u{甘草}$w{三两(炙)}、$u{牡蛎}$w{三两(熬)}。\n\n           上七味，以水一斗，煮取六升，去滓，再煎取三升，温服一升，日三服，初服微烦，再服，汗出便愈。', 3, NULL, NULL, 651868923334725, 'F819C887C0E10979654DDB6940258E0F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-07 10:01:28', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (787, '防己地黄汤', 711, 6, 9050000, '$u{防己}$w{一分}，$u{桂枝}$w{三分}，$u{防风}$w{三分}，$u{甘草}$w{一分}。\n	$s{上四味}，以$u{酒}$w{一杯}，渍之一宿，绞取汁。$u{生地黄}$w{二斤}，㕮咀，蒸之如斗米饭久，以铜器盛其汁，更绞地黄汁，和分再服。\n\n      防己、甘草、桂枝、防风这些药的比例，防己、甘 草是一，桂枝是三。你不要开一分、三分，这种轻剂量治疗牙齿中风可以用，治疗中风的人需要大剂的药，使用三钱五钱一剂都不为过， 比例要知道。同时像防己本身能够去湿，中气不足的时候用甘草。桂枝和甘草补中，都能够补中阳不足，让脾脏开始运化。防己和防风， 都能够去风。这处方是遇到病人的风邪直接进在皮表，停在经上面的 时候使用的，是最浅的处方。这四味药先用酒泡过，泡完以后再绞它的汁用，汁里面就有药跟酒在里面。生地黄，也要大剂的用，剂量用两，差不多用到二两到三两才够量。\n\n        遇到体格比较大的病人，使用四两以上都没关系。地黄生的时候是黏答答的、黑黑的，你把它放在锅里蒸熟，好像蒸米一样，隔水蒸， 不要浸水。蒸熟了以后把它拿起来绞汁。把生地黄绞成生地黄汁，然后跟刚刚前面已经绞成汁的四味药，混合在一起，喝下这个汁，才是 真正的防己地黄汤。地黄汁必须是绞汁的，把它蒸熟的，不是煮熟的， 利用地黄来补病家的血不足。靠桂枝甘草来健中，来加强病人的肠胃功能，然后开一点防己防风去风。', 2, NULL, NULL, 651946043437125, '5FA2FB11F92BC73B78A5F25E0331F5D7', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-07 15:15:17', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (788, '侯氏黑散', 712, 15, 9050000, '$u{菊花}$w{四十分}，$u{白术}$w{十分}，$u{细辛}$w{三分}，$u{茯苓}$w{三分}，$u{牡蛎}$w{三分}，$u{桔梗}$w{八分}，$u{防风}$w{十分}，$u{人参}$w{三分}，$u{矾石}$w{三分}，$u{黄芩}$w{五分}，$u{当归}$w{三分}，$u{干姜}$w{三分}，$u{芎䓖}$w{三分}，$u{桂枝}$w{三分}。\n\n	$s{上十四味}，杵为散，$u{酒}服方寸匕，日一服。初服二十日，温酒调服，禁一切鱼、肉、大蒜，常宜冷食，六十日止，即药积在腹中不下也，热食即下矣，冷食自能助药力。', 60, NULL, NULL, 651948909150277, '35987453D09C152AA7EAEA4E96253915', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-07 15:26:56', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (789, '风引汤', 713, 12, 9050000, '$u{大黄}，$u{干姜}，$u{龙骨}$w{各四两}，$u{桂枝}$w{三两}，$u{甘草}，$u{牡蛎}$w{各二两}，$u{寒水石}，$u{滑石}，$u{赤石脂}，$u{白石脂}，$u{紫石英}，$u{石膏}$w{各六两}。\n	$s{上十二味}，杵，粗筛，以韦囊盛之。取三指撮，井花水三升，煮三沸，温服一升。$a{治大人风引，少小惊痫瘈疭，日数十发，医所不能疗，除热方。巢氏云：脚气宜风引汤。}', 60, NULL, NULL, 651949439926341, '7D65FBB49D61C11525DD74AFF45F0A82', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-07 15:29:06', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (790, '头风摩散方', 714, 2, 9050000, '$u{大附子}$w{一枚，炮}，$u{盐}$w{等分}\n	$s{上二味}，为散，沐了，以方寸匕，摩疾上，令药力行。', 10, NULL, NULL, 651950541905989, '532CE38F052E0AD9DFD173C20FD1B334', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-07 15:33:35', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (791, '桂枝芍药知母汤', 715, 9, 9050000, '$u{桂枝}$w{四两}，$u{芍药}$w{三两}，$u{甘草}$w{二两}，$u{麻黄}$w{二两}，$u{生姜}$w{五两}，$u{白术}$w{四两,炮}，$u{知母}$w{四两}，$u{防风}$w{四两}，$u{附子}$w{二枚，炮}\n	$s{右九味}，以水七升，煮取二升，温服七合，日三服。', 3, NULL, NULL, 652213851217989, '06524ACAF59A0FEBA58517F7CBF98CF6', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-08 09:24:59', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (792, '乌头汤', 716, 2, 9050000, '$m{5味} 治脚气疼痛，不可屈伸。\n	$u{麻黄}，$u{芍药}，$u{黄芪}$w{各三两}，$u{甘草}$w{三两，炙}，$u{川乌}$w{五枚，㕮咀，以$u{蜜}二升，煎取一升，即出乌头}\n\n	$s{上五味}，㕮咀四味，以水三升，煮取一升，去滓，内$u{蜜}煎中，更煎之。服七合，不知，尽服之。', 3, NULL, NULL, 652217539424325, '5C68E48A8AE56BBDBE0BC6F9A652E680', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-08 09:40:00', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (793, '矾石汤', 717, 1, 9050000, '$u{矾石}$w{二两}\n	$s{上一味}，以浆水一斗五升，煎三、五沸，浸脚良。', 1, NULL, NULL, 652220010750021, 'BFC82AD7BC8EB76528BA032AC3C34299', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-08 09:50:03', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (794, '黄耆桂枝五物汤', 718, 5, 9050000, '$u{黄耆}$w{三两}、$u{桂枝}$w{三两}、$u{芍药}$w{三两}、$u{生姜}$w{六两}、$u{大枣}$w{十二枚}。\n\n       上五味，以水六升，煮取二升，温服七合，日三服。', 3, NULL, NULL, 652329439670341, 'F8782050CA5FBA8EB342C55E6658BE3B', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-08 17:15:19', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (795, '桂枝龙骨牡蛎汤', 719, 7, 9050000, '$u{桂枝}$w{三两}、$u{芍药}$w{三两}、$u{甘草}$w{二两（炙）}、$u{生姜}$w{三两}、$u{大枣}$w{十二枚}、$u{龙骨}$w{三两}、$u{牡蛎}$w{三两}。\n\n        右七味，以水七升，煮取三升，去滓，分温三服。', 3, NULL, NULL, 653030748602437, 'EB05549927B8150B8D46EC927D770A95', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-10 16:48:57', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (796, '天雄散', 720, 4, 9050000, '$u{天雄}$w{三两（炮）}、$u{白术}$w{八两}、$u{桂枝}$w{六两}、$u{龙骨}$w{三两}。\n\n        右四味，杵为散，酒服半钱匙，日三服，不知稍增，以知为度。\n\n     天雄散是治疗阳虚的，不是治阴虚。阳虚就是代表身体里面阴寒很盛，这时是看不到热症的，如果是阴虚的话，就可以看到热症，但是看到的是虚热。如果病人是失精家，再遇到这种表里都寒的时候， 就是要用天雄散的时机。\n\n      天雄的意思就是吃下去天天都雄壮威武，故名叫天雄，天雄药力比附子强很多，附子是三年收成，而它是五年才 收成。你到药房去买天雄，药房会告诉你天雄就是附子，一定会得到 这个答案的。按照神农本草经，三年、四年、五年都不一样，第五年 采收才是天雄。\n\n      天雄散就是用散剂，『天雄三两炮』如果散剂的话我 们可以用这个比例，三两就三两没有关系，白术八两、桂枝六两、龙骨三两。经方里面写的是龙骨，但实际用的是牡蛎，牡蛎可能比龙骨还更恰当一点。如果你将龙骨牡蛎都放进去用，也没有关系，原文上 有一点失去方义，其实是可以用牡蛎的。\n\n      将这四味药杵为散，用酒服， 半个汤匙，『半钱匕』就是我们平常喝汤的汤匙平匙量。一天吃三次， 饭前空腹吃。吃完了以后，如果没感觉到改变，就是还有亡血失精， 这个时候就要增加剂量。\n\n       这个药在经方里面，是属于很强的补阳药， 主治症状还包含阳不举，如果服了天雄散后仍然不举，表示天雄散没 有用了，此时我们就需要用到像阳起石，肉蓰蓉等，还可以再加一些 鹿茸，这几味都是我们中药里面一般的壮阳的药。但是如果你光吃这 种药，结果就是全身汗毛都举起来了，就是那个地方不举，所以要靠 一些药把它带到它该去的地方。\n\n       你如果将这壮阳复方放在天雄散里面一起吃，效果就非常的好，还可以放到桂枝龙骨牡蛎汤里面也可以。 这类药千万不要单味的用，要用复方，它才会进入到我们肾脏去。这 几个药都是等量的比例在用的，也可以把鹿茸拿去泡酒，然后一边喝鹿茸酒，一边服天雄散也可以，这些都是中药里面比较强的壮阳药， 一般是阳虚时才会用到。\n\n        如果阳没有虚而是阴虚，吃这类壮阳药，就会越吃越热，反而没有用。阴虚的话，病人一定会看到阳亢的症状， 所谓阳亢就是上焦热下面是寒的，也是属于失精家。\n\n        阳虚和阴虚治法 不一样，阳虚是看不到阳症，只看到阴症，比如你问病人说会不会口 渴？病人回答说不渴时，就是阳虚了。如果是阴虚，就会很渴，因为 上面的阳热是虚热，所以只要问病人口渴不渴大概就晓得了。', 3, NULL, NULL, 653312933322821, '16A5E643C03AA6BDF8E37EA44E644D16', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-11 11:57:10', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (797, '黄耆建中汤', 721, 7, 9050000, '$u{桂枝}$w{三两}、$u{芍药}$w{六两}、$u{甘草}$w{二两 (炙)}、$u{生姜}$w{三两（切）}、$u{大枣}$w{十二枚（劈）}、$u{胶饴}$w{一升}}、$u{黄芪}$w{一两半}。\n\n      右七味，以水七升，煮取三升，去滓，内胶饴，更上微火消解，温服一升，日三服。\n\n     气短，胸满者，加生姜一两；\n     腹满者，去大枣，加茯苓一两半；\n     大便秘结者，去大枣，加枳实一两半；\n    疗肺虚 损不足 ，补气加半夏三两。', 3, NULL, NULL, 653640521424965, '623D6D76EDB3112AC29CE4D07729615C', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-12 10:10:07', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (798, '八味肾气丸', 722, 8, 9050000, '$u{干地黄}$w{八两}、$u{山药}$w{四两}、$u{山茱萸}$w{四两}、$u{泽泻}$w{三两}、$u{牡丹皮}$w{三两}、$u{茯苓}$w{三两}、$u{桂枝}$w{一两}、$u{附子}$w{一枚 (炮)}。\n\n          上八味，末之，炼蜜和丸，如梧子大，$n{酒}下十五丸，渐加至二十五丸，日再服，白饮下亦可。', 15, NULL, NULL, 653655193079877, '0236C53491F846F7619AD76C5FD95C63', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-12 11:09:49', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (799, '薯蓣丸', 723, 23, 9050000, '$u{薯蓣}$w{三十分}，$u{人参}$w{七分}，$u{白术}$w{六分}，$u{茯苓}$w{五分}，$u{甘草}$w{二十八分}，$u{当归}$w{十分}，$u{干地黄}$w{十分}，$u{芍药}$w{六分}，\n$u{芎藭}$w{六分}，$u{麦门冬}$w{六分}，$u{阿胶}$w{七分}，$u{干姜}$w{三分}，$u{大枣}$w{百枚为膏}，$u{桔梗}$w{五分}，$u{杏仁}$w{六分}，$u{桂枝}$w{十分}，\n$u{防风}$w{六分}，$u{神曲}$w{十分}，$u{豆黄}$w{卷十分}，$u{柴胡}$w{五分}，$u{白蔹}$w{二分}\n\n	$s{上二十一味}，末之，炼$u{蜜}和丸，如弹子大。空腹$u{酒}服一丸，一百丸为剂。', 100, NULL, NULL, 653662088769605, 'E142E2110BF0035C3F083753B9A23CD9', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-12 11:37:53', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (800, '酸枣仁汤', 724, 5, 9050000, '$u{酸枣仁}$w{二升}，$u{甘草}$w{一两}，$u{知母}$w{二两}，$u{茯苓}$w{二两}，$u{芎䓖}$w{二两} \n\n	$s{上五味}，以水八升，煮酸枣仁，得六升，内诸药，煮取三升，分温三服。', 3, NULL, NULL, 653662668976197, '3FA775994AACE76F0AD13CB292B54A7F', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-12 11:40:15', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (801, '灸甘草汤', 725, 9, 9050000, '  $u{甘草}$w{四两，炙}，$u{桂枝}，$u{生姜}$w{各三两}，$u{麦门冬}$w{半升}，$u{麻仁}$w{半升}，$u{人参}，$u{阿胶}$w{各二两}，\n$u{大枣}$w{三十枚}，$u{生地黄}$w{一斤}\n\n上九味，以酒七升，水八升，先煮八味，取三升，去滓，内胶消尽，温服一升， 日三服。', 3, NULL, '', 653677728792645, '41ED8E60F940E889254C61BB093F9072', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-12 12:41:31', 1, 'admin', '2025-03-12 12:42:55');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (802, '獭肝散', 726, 1, 9050000, '《肘后》獭肝散\n\n	      獭肝一具		\n\n炙干末之，水服方寸匕， 日三服。', 3, NULL, NULL, 653678365655109, '3035BC9492D6FB0A0136B860C1CCA204', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-12 12:44:07', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (803, '射干麻黄汤', 727, 9, 9050000, ' $u{射干}$w{三两}，$u{麻黄}$w{四两}，$u{生姜}$w{四两}，$u{细辛}，$u{紫菀}，$u{款冬花}$w{各三两}，$u{五味子}$w{半升}，$u{大枣}$w{七枚}，$u{半夏}$w{半升}\n	$s{上九味}，以水一斗二升，先煮麻黄两沸，去上沫，内诸药，煮取三升，分温三服。', 3, NULL, NULL, 653748042600517, 'AB53F408B38E9A047A27D4ACA2BD3A60', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-12 17:27:38', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (804, '皂荚丸', 728, 3, 9050000, '$u{皂荚}$w{八两，刮去皮，用酥炙}\n	$s{上一味}，末之，$u{蜜}丸梧子大。以枣膏和汤服三丸，日三、夜一服。', 4, NULL, '', 654079119441989, 'D6FF1410A007DC669C2BBC1A7B9FCCAC', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-13 15:54:47', 1, 'admin', '2025-03-13 15:55:11');
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (805, '泽漆汤', 729, 9, 9050000, '$u{半夏}$w{半升}，$u{紫参}$w{五两。一本紫菀}，$u{生姜}$w{五两}，$u{白前}$w{五两}，$u{甘草}，$u{黄芩}，$u{人参}，$u{桂枝}$w{各三两},\n$u{泽漆}$w{三斤，以东流水五斗，煮取一斗五升}，\n	$s{右九味}，㕮咀，内泽漆汁中，煮取五升。温服五合，至夜尽。', 5, NULL, NULL, 654081667072069, 'B87AEC8582B1FD81C68719B06E641899', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-13 16:05:09', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (806, '厚朴麻黄汤', 730, 9, 9050000, '$u{厚朴}$w{五两}，$u{麻黄}$w{四两}，$u{石膏}$w{如鸡子大}，$u{杏仁}$w{半升}，$u{半夏}$w{半升}，$u{干姜}$w{二两}，$u{细辛}$w{二两}，$u{小麦}$w{一升}，$u{五味子}$w{半升}\n\n	$s{上九味}，以水一斗二升，先煮小麦熟，去滓，内诸药，煮取三升。温服一升，日三服。', 3, NULL, NULL, 654082161307717, '1092B95B91C0BA3B4AB81B09568A0A32', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-13 16:07:10', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (807, '麦门冬汤', 731, 6, 9050000, '$u{麦门冬}$w{七升}，$u{半夏}$w{一升}，$u{人参}$w{二两}，$u{甘草}$w{二两}，$u{粳米}$w{三合}，$u{大枣}$w{十二枚}\n	$s{上六味}，以水一斗二升，煮取六升。温服一升，日三、夜一服。', 4, NULL, NULL, 654086729125957, '0D6DCF18D05FEA13D0606DD5D030A9CF', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-13 16:25:45', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (808, '葶苈大枣泻肺汤', 732, 2, 9050000, '$u{葶苈}$w{熬令黄色，捣丸如弹丸大}，$u{大枣}$w{十二枚}\n	$s{右先以水三升}，煮枣取二升，去枣，内葶苈，煮取一升，顿服。', 1, NULL, NULL, 654092681449541, '91AC40726272F2C352AE56A9581E8D9E', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-13 16:49:58', NULL, NULL, NULL);
INSERT INTO `Fang` (`FangId`, `FangName`, `FangNo`, `YaoCount`, `FangSourceBookId`, `FangText`, `FangdrinkNum`, `FangList`, `YaoList`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (809, '桂枝去芍药加皂荚汤', 733, 5, 9050000, '	$u{桂枝}，$u{生姜}$w{各三两}，$u{甘草}$w{二两}，$u{大枣}$w{十枚}，$u{皂荚}$w{一枚，去皮子，炙焦}\n	$s{上五味}，以水七升，微微火煮取三升，分温三服。', 3, NULL, NULL, 654099458617413, 'B5F3E07B9CC021BCFF2EFE34B4A01136', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-03-13 17:17:33', NULL, NULL, NULL);
